function createPostShareState(seed = {}) {
  const pickerSeed =
    seed.roomPicker && typeof seed.roomPicker === "object"
      ? seed.roomPicker
      : {};
  return {
    open: seed.open === true,
    postId: normalizeString(seed.postId),
    preview: seed.preview || null,
    loading: seed.loading === true,
    sendingConversationId: normalizeString(seed.sendingConversationId),
    roomPicker: {
      open: pickerSeed.open === true,
      loading: pickerSeed.loading === true,
      error: normalizeString(pickerSeed.error),
      scopeType: normalizeString(pickerSeed.scopeType).toLowerCase(),
      scopeId: normalizeString(pickerSeed.scopeId),
      title: normalizeString(pickerSeed.title),
      avatarUrl: normalizeUrl(pickerSeed.avatarUrl),
      scopeBadge: normalizeString(pickerSeed.scopeBadge),
      canManage: pickerSeed.canManage === true,
      channels: Array.isArray(pickerSeed.channels) ? pickerSeed.channels : [],
    },
    error: normalizeString(seed.error),
    notice: normalizeString(seed.notice),
  };
}

function createPostComposerSaveExportState(seed = {}) {
  return {
    status: normalizeString(seed.status),
    label: normalizeString(seed.label),
    progress: Number.isFinite(Number(seed.progress))
      ? Math.max(0, Math.min(1, Number(seed.progress)))
      : null,
    url: normalizeUrl(seed.url),
    fileName: normalizeString(seed.fileName),
    error: normalizeString(seed.error),
  };
}

function createPostComposerEditState(seed = {}) {
  const styleId = normalizeString(seed.captionStyleId || seed.styleId).toLowerCase();
  const textCase = normalizeString(seed.captionTextCase || seed.textCase).toLowerCase();
  const mode = normalizeString(seed.captionMode || seed.mode).toLowerCase();
  return {
    trimEnabled: seed.trimEnabled === true,
    trimStartMs: Math.max(0, Number(seed.trimStartMs) || 0),
    trimEndMs: Math.max(0, Number(seed.trimEndMs) || 0),
    captionsEnabled: seed.captionsEnabled === true,
    captionMode: ["transcript", "style", "format"].includes(mode)
      ? mode
      : "transcript",
    captionText: normalizeString(seed.captionText).slice(0, 5000),
    captionSegments: Array.isArray(seed.captionSegments)
      ? seed.captionSegments
          .map((segment, index) =>
            normalizePostComposerCaptionSegment(segment, index),
          )
          .filter((segment) => segment.text)
      : [],
    captionGenerating: seed.captionGenerating === true,
    captionGenerationStage: normalizeString(seed.captionGenerationStage),
    captionGenerationError: normalizeString(seed.captionGenerationError),
    captionGenerationModel: normalizeString(seed.captionGenerationModel),
    captionStyleId: POST_COMPOSER_CAPTION_STYLE_PRESETS.some(
      (preset) => preset.id === styleId,
    )
      ? styleId
      : "tiktok",
    captionTextCase: POST_COMPOSER_CAPTION_CASES.includes(textCase)
      ? textCase
      : "uppercase",
    captionX: Math.max(0.08, Math.min(0.92, Number(seed.captionX) || 0.5)),
    captionY: Math.max(0.12, Math.min(0.92, Number(seed.captionY) || 0.78)),
    captionScale: Math.max(0.7, Math.min(1.8, Number(seed.captionScale) || 1)),
    captionWidthFactor: Math.max(
      0.24,
      Math.min(0.96, Number(seed.captionWidthFactor) || 0.86),
    ),
    captionColor: normalizePostComposerCoverColor(seed.captionColor, "#FFFFFF"),
    captionBackgroundColor: normalizePostComposerCoverColor(
      seed.captionBackgroundColor,
      "#000000",
    ),
    textOverlayEnabled: seed.textOverlayEnabled === true,
    overlayText: normalizeString(seed.overlayText || seed.text).slice(0, 160),
    overlayX: Math.max(0.08, Math.min(0.92, Number(seed.overlayX) || 0.5)),
    overlayY: Math.max(0.12, Math.min(0.9, Number(seed.overlayY) || 0.5)),
    overlayScale: Math.max(0.5, Math.min(3, Number(seed.overlayScale) || 1)),
    overlayRotationDeg: Math.max(
      -45,
      Math.min(45, Number(seed.overlayRotationDeg) || 0),
    ),
    overlayStartMs: Math.max(0, Number(seed.overlayStartMs) || 0),
    overlayEndMs: Math.max(0, Number(seed.overlayEndMs) || 0),
    overlayColor: normalizePostComposerCoverColor(seed.overlayColor, "#FFFFFF"),
    overlayBackgroundEnabled: seed.overlayBackgroundEnabled === true,
    overlayBackgroundColor: normalizePostComposerCoverColor(
      seed.overlayBackgroundColor,
      "#000000",
    ),
  };
}

