function closeConfirmationSheet(confirmed = false) {
  const resolver = confirmationResolver;
  confirmationResolver = null;
  state.ui.confirmation = createConfirmationState();
  scheduleRender();
  if (typeof resolver === "function") {
    resolver(confirmed === true);
  }
}

function requestConfirmation(options = {}) {
  const normalized =
    typeof options === "string" ? { message: options } : { ...options };
  const fallbackMessage =
    normalizeString(normalized.message || normalized.copy || normalized.title) ||
    "Continue?";
  if (!root || typeof scheduleRender !== "function") {
    return Promise.resolve(
      typeof window.confirm === "function"
        ? window.confirm(fallbackMessage)
        : false,
    );
  }
  if (typeof confirmationResolver === "function") {
    confirmationResolver(false);
  }
  return new Promise((resolve) => {
    confirmationResolver = resolve;
    state.ui.confirmation = createConfirmationState({
      ...normalized,
      message: fallbackMessage,
      open: true,
    });
    scheduleRender();
  });
}

function confirmDestructiveAction(options = {}) {
  return requestConfirmation({
    eyebrow: "Confirm change",
    tone: "danger",
    icon: "trash",
    confirmLabel: "Confirm",
    ...options,
  });
}

function closeTextPrompt(value = null) {
  const resolver = textPromptResolver;
  textPromptResolver = null;
  state.ui.textPrompt = createTextPromptState();
  scheduleRender();
  if (typeof resolver === "function") {
    resolver(value);
  }
}

function requestTextPrompt(options = {}) {
  if (!root || typeof scheduleRender !== "function") {
    return Promise.resolve(null);
  }
  if (typeof textPromptResolver === "function") {
    textPromptResolver(null);
  }
  return new Promise((resolve) => {
    textPromptResolver = resolve;
    state.ui.textPrompt = createTextPromptState({ ...options, open: true });
    scheduleRender();
  });
}

const messagingDevice = createMessagingBrowserDevice();
const messagingSocket = createMessagingSocketClient({
  async getAuthToken() {
    return normalizeString(
      state.auth.session?.idToken || state.auth.session?.accessToken,
    );
  },
  async getDeviceId() {
    return messagingDevice.currentDeviceId();
  },
  onEvent(event) {
    handleMessagingSocketEvent(event);
  },
  onStateChange(snapshot) {
    state.pages.messaging.socket = {
      connectionState:
        normalizeString(snapshot.connectionState) || "disconnected",
      disconnectedAt: snapshot.disconnectedAt || null,
      reconnectAttemptCount: Number(snapshot.reconnectAttemptCount) || 0,
    };
    scheduleRender();
  },
});

function messagingTypingIndicatorsEnabled() {
  return normalizeMessagingAccountSettings(state.pages.messaging.settings)
    .typingIndicatorsEnabled !== false;
}

function stopMessagingTyping(conversationId = "") {
  const activeConversationId = normalizeString(messagingTypingConversationId);
  const targetConversationId = normalizeString(conversationId) || activeConversationId;
  window.clearTimeout(messagingTypingStopTimer);
  messagingTypingStopTimer = null;
  if (
    activeConversationId &&
    (!targetConversationId || targetConversationId === activeConversationId)
  ) {
    messagingSocket.typingStop(activeConversationId);
    messagingTypingConversationId = "";
  }
}

function handleMessagingComposerTyping(conversationId = "", value = "") {
  const normalizedConversationId = normalizeString(conversationId);
  const hasText = Boolean(normalizeString(value));
  if (!normalizedConversationId || !hasText || !messagingTypingIndicatorsEnabled()) {
    stopMessagingTyping(normalizedConversationId);
    return;
  }
  if (
    messagingTypingConversationId &&
    messagingTypingConversationId !== normalizedConversationId
  ) {
    stopMessagingTyping();
  }
  if (!messagingTypingConversationId) {
    messagingSocket.typingStart(normalizedConversationId);
    messagingTypingConversationId = normalizedConversationId;
  }
  window.clearTimeout(messagingTypingStopTimer);
  messagingTypingStopTimer = window.setTimeout(() => {
    stopMessagingTyping(normalizedConversationId);
  }, 3000);
}

function clearMessagingTypingParticipantTimer(userId = "") {
  const normalizedUserId = normalizeString(userId);
  if (!normalizedUserId) {
    return;
  }
  const timer = messagingTypingParticipantTimers.get(normalizedUserId);
  if (timer) {
    window.clearTimeout(timer);
    messagingTypingParticipantTimers.delete(normalizedUserId);
  }
}

function removeMessagingTypingParticipant(userId = "", { render = false } = {}) {
  const normalizedUserId = normalizeString(userId);
  if (!normalizedUserId) {
    return;
  }
  clearMessagingTypingParticipantTimer(normalizedUserId);
  const conversation = state.pages.messaging.conversation;
  const nextParticipants = conversation.typingParticipants.filter(
    (entry) => normalizeString(entry.userId) !== normalizedUserId,
  );
  if (nextParticipants.length !== conversation.typingParticipants.length) {
    conversation.typingParticipants = nextParticipants;
    if (render) {
      scheduleRender();
    }
  }
}

function clearMessagingTypingParticipants({ render = false } = {}) {
  messagingTypingParticipantTimers.forEach((timer) => {
    window.clearTimeout(timer);
  });
  messagingTypingParticipantTimers.clear();
  const conversation = state.pages.messaging.conversation;
  if (conversation.typingParticipants.length) {
    conversation.typingParticipants = [];
    if (render) {
      scheduleRender();
    }
  }
}

function setMessagingTypingParticipant(userId = "", label = "") {
  const normalizedUserId = normalizeString(userId);
  if (!normalizedUserId) {
    return;
  }
  clearMessagingTypingParticipantTimer(normalizedUserId);
  const conversation = state.pages.messaging.conversation;
  const existing = conversation.typingParticipants.filter(
    (entry) => normalizeString(entry.userId) !== normalizedUserId,
  );
  conversation.typingParticipants = existing.concat({
    userId: normalizedUserId,
    label: normalizeString(label) || normalizedUserId,
  });
  messagingTypingParticipantTimers.set(
    normalizedUserId,
    window.setTimeout(() => {
      removeMessagingTypingParticipant(normalizedUserId, { render: true });
    }, MESSAGING_TYPING_PARTICIPANT_TTL_MS),
  );
}

function normalizeString(value) {
  if (value === undefined || value === null) {
    return "";
  }
  return String(value).trim();
}

function normalizeUrl(value) {
  const normalized = normalizeString(value);
  return normalized || "";
}

function resolveSharedAssetUrl(value) {
  const normalized = normalizeUrl(value);
  if (!normalized || typeof window === "undefined") {
    return normalized;
  }
  try {
    return new URL(normalized, window.location.origin).toString();
  } catch {
    return normalized;
  }
}

function parseBoolean(value, fallback = false) {
  if (typeof value === "boolean") {
    return value;
  }
  if (typeof value === "number") {
    return value !== 0;
  }
  const normalized = normalizeString(value).toLowerCase();
  if (["true", "1", "yes", "y"].includes(normalized)) {
    return true;
  }
  if (["false", "0", "no", "n"].includes(normalized)) {
    return false;
  }
  return fallback;
}

function getCurrentRoute() {
  return state.route;
}

function isShareRoute(route = state.route) {
  return normalizeString(route?.routeKey) === ROUTE_KEY_SHARE_POST;
}

function isFeedRoute(route = state.route) {
  const routeKey = normalizeString(route?.routeKey);
  return routeKey === ROUTE_KEY_FEED || routeKey === ROUTE_KEY_SHARE_POST;
}

function isElectionDayRoute(route = state.route) {
  return normalizeString(route?.routeKey) === ROUTE_KEY_ELECTION_DAY;
}

function isCtaInviteRoute(route = state.route) {
  return normalizeString(route?.routeKey) === ROUTE_KEY_CTA_INVITE;
}

function isPublicPetitionRoute(route = state.route) {
  const routeKey = normalizeString(route?.routeKey);
  return (
    routeKey === ROUTE_KEY_PUBLIC_PETITION ||
    routeKey === ROUTE_KEY_PUBLIC_PETITION_RESULTS
  );
}

function isPublicAccountRoute(route = state.route) {
  const routeKey = normalizeString(route?.routeKey);
  return (
    routeKey === ROUTE_KEY_AUTH ||
    routeKey === ROUTE_KEY_BOOTSTRAP ||
    routeKey === ROUTE_KEY_ACCOUNT_DELETION_REQUESTED
  );
}

function isStandalonePostViewRoute(route = state.route) {
  return normalizeString(route?.routeKey) === ROUTE_KEY_POST_VIEW;
}

function isRouteFallbackRoute(route = state.route) {
  return normalizeString(route?.routeKey) === ROUTE_KEY_ROUTE_FALLBACK;
}

function isProtectedRoute(route = state.route) {
  return (
    !isShareRoute(route) &&
    !isStandalonePostViewRoute(route) &&
    !isRouteFallbackRoute(route) &&
    !isElectionDayRoute(route) &&
    !isCtaInviteRoute(route) &&
    !isPublicPetitionRoute(route) &&
    !isPublicAccountRoute(route)
  );
}

function getRouteSection(route = state.route) {
  const routeKey = normalizeString(route?.routeKey);
  if (
    routeKey === ROUTE_KEY_AUTH ||
    routeKey === ROUTE_KEY_BOOTSTRAP ||
    routeKey === ROUTE_KEY_ACCOUNT_DELETION_REQUESTED
  ) {
    return "account";
  }
  if (
    routeKey === ROUTE_KEY_DISCOVER ||
    routeKey === ROUTE_KEY_ACHIEVEMENTS ||
    routeKey === ROUTE_KEY_SEARCH ||
    routeKey === ROUTE_KEY_SEARCH_RESULTS ||
    routeKey === ROUTE_KEY_POLICY_QUESTIONS ||
    routeKey === ROUTE_KEY_POLICY_QUESTION_DETAIL
  ) {
    return "discover";
  }
  if (
    routeKey === ROUTE_KEY_CANDIDATES ||
    routeKey === ROUTE_KEY_ELECTION_DAY ||
    routeKey === ROUTE_KEY_OFFICIAL_DETAIL ||
    routeKey === ROUTE_KEY_CONGRESSIONAL_REPORT_CARD ||
    routeKey === ROUTE_KEY_OFFICIAL_REPORT_CARD ||
    routeKey === ROUTE_KEY_AUTO_CANDIDATE_DETAIL ||
    routeKey === ROUTE_KEY_CANDIDATE_DETAIL ||
    routeKey === ROUTE_KEY_CANDIDATE_EDIT
  ) {
    if (isCandidateSettingsEditRoute(route)) {
      return "settings";
    }
    return routeKey === ROUTE_KEY_ELECTION_DAY ? "elections" : "candidates";
  }
  if (
    routeKey === ROUTE_KEY_CANDIDATE_DASHBOARD ||
    routeKey === ROUTE_KEY_CANDIDATE_DASHBOARD_DETAIL ||
    routeKey === ROUTE_KEY_CANDIDATE_DASHBOARD_SECTION ||
    routeKey === ROUTE_KEY_CANDIDATE_VOTER_MAP ||
    routeKey === ROUTE_KEY_CANDIDATE_VOTER_MAP_SECTION
  ) {
    return "campaigns";
  }
  if (
    routeKey === ROUTE_KEY_COALITIONS ||
    routeKey === ROUTE_KEY_COALITION_START ||
    routeKey === ROUTE_KEY_COALITION_JOIN ||
    routeKey === ROUTE_KEY_COALITION_DETAIL ||
    routeKey === ROUTE_KEY_COALITION_SECTION
  ) {
    return "coalitions";
  }
  if (
    routeKey === ROUTE_KEY_MISSIONS ||
    routeKey === ROUTE_KEY_MISSION_DETAIL
  ) {
    return "missions";
  }
  if (
    routeKey === ROUTE_KEY_EVENTS ||
    routeKey === ROUTE_KEY_CTA_INVITE ||
    routeKey === ROUTE_KEY_PUBLIC_PETITION ||
    routeKey === ROUTE_KEY_PUBLIC_PETITION_RESULTS ||
    routeKey === ROUTE_KEY_EVENT_DETAIL ||
    routeKey === ROUTE_KEY_EVENT_SIGNUP ||
    routeKey === ROUTE_KEY_EVENT_PAYMENT ||
    routeKey === ROUTE_KEY_MANAGE_EVENTS ||
    routeKey === ROUTE_KEY_MANAGE_EVENTS_NEW ||
    routeKey === ROUTE_KEY_MANAGE_EVENTS_EDIT
  ) {
    return "events";
  }
  if (
    routeKey === ROUTE_KEY_PROFILE_SELF ||
    routeKey === ROUTE_KEY_PROFILE_USER ||
    routeKey === ROUTE_KEY_PROFILE_EDIT ||
    routeKey === ROUTE_KEY_PROFILE_CONNECTIONS ||
    routeKey === ROUTE_KEY_PROFILE_NOTIFICATIONS
  ) {
    return "profile";
  }
  if (
    routeKey === ROUTE_KEY_MESSAGES_ROOT ||
    routeKey === ROUTE_KEY_MESSAGES_WILDCARD
  ) {
    return "messages";
  }
  if (
    routeKey === ROUTE_KEY_ADMIN ||
    routeKey === ROUTE_KEY_ADMIN_SECTION
  ) {
    return "admin";
  }
  if (
    routeKey === ROUTE_KEY_TOPICS ||
    routeKey === ROUTE_KEY_ONBOARDING_TOPICS
  ) {
    return "topics";
  }
  if (
    routeKey === ROUTE_KEY_SETTINGS ||
    routeKey === ROUTE_KEY_SETTINGS_SECTION ||
    routeKey === ROUTE_KEY_ONBOARDING_PROFILE ||
    routeKey === ROUTE_KEY_ONBOARDING_PHOTO ||
    routeKey === ROUTE_KEY_ONBOARDING_LOCATION ||
    routeKey === ROUTE_KEY_ONBOARDING_ADDRESS
  ) {
    return "settings";
  }
  return "feed";
}

function getCurrentPathWithQuery() {
  return `${window.location.pathname}${window.location.search}`;
}

function getPathnameFromRouteTarget(value) {
  const normalized = normalizeString(value);
  if (!normalized) {
    return "/";
  }
  try {
    return new URL(normalized, window.location.origin).pathname;
  } catch {
    return normalized.split("?")[0] || "/";
  }
}

function getSettingsDocumentTitle(route = state.route) {
  const settingsPath = getSettingsRoutePath(route).replace(/\/$/u, "");
  if (!settingsPath) {
    return "Settings";
  }
  const exactTitles = {
    "account-security/totp": "Authenticator App",
    "candidate-access/name": "Candidate Access",
    "candidate-access/office": "Candidate Office",
    "preferences/home-location": "Home Location",
    "preferences/home-location/request": "Location Request",
    "preferences/my-districts": "My Districts",
    "security/device-link": "Trusted Devices",
    "security/restore": "Message Recovery",
    "voter-profile/home-location": "Home Location",
    "voter-profile/home-location/request": "Location Request",
  };
  if (exactTitles[settingsPath]) {
    return exactTitles[settingsPath];
  }
  return normalizeString(getSettingsSectionConfig(getSettingsSection(route))?.label) || "Settings";
}

function getAuthDocumentTitle() {
  const mode = authRouteModeFromPath();
  const titles = {
    signup: "Create Account",
    confirm: "Confirm Account",
    reset: "Reset Password",
    "reset-confirm": "Reset Password",
    login: "Sign In",
  };
  return titles[mode] || "Account";
}

function routeTitleFromConfig(configs = [], key = "", fallback = "") {
  const normalizedKey = normalizeString(key);
  const match = configs.find((item) => item.key === normalizedKey);
  return normalizeString(match?.label) || normalizeString(fallback);
}

function prefixRouteTitle(prefix, title, fallback) {
  const normalizedPrefix = normalizeString(prefix);
  const normalizedTitle = normalizeString(title);
  if (!normalizedTitle) {
    return fallback;
  }
  if (!normalizedPrefix) {
    return normalizedTitle;
  }
  return normalizedTitle.toLowerCase().includes(normalizedPrefix.toLowerCase())
    ? normalizedTitle
    : `${normalizedPrefix} ${normalizedTitle}`;
}

function getCandidateDashboardDocumentTitle(route = state.route) {
  const sectionKey = candidateDashboardSectionForRoute(route);
  if (!sectionKey || sectionKey === CANDIDATE_DASHBOARD_DEFAULT_SECTION) {
    return "Candidate Dashboard";
  }
  const label = routeTitleFromConfig(
    CANDIDATE_DASHBOARD_SECTION_CONFIG,
    sectionKey,
    humanizeLabel(sectionKey),
  );
  return prefixRouteTitle("Campaign", label, "Candidate Dashboard");
}

function getCandidateVoterMapDocumentTitle(route = state.route) {
  const sectionKey = candidateVoterMapSectionForRoute(route);
  const exactTitles = {
    menu: "Candidate Voter Map",
    map: "Candidate Voter Map",
    connected: "Connected Voters",
    add: "Add Voters",
    "territories/admin": "Territory Admin",
    scripts: "Outreach Scripts",
    notes: "Voter Notes",
  };
  if (exactTitles[sectionKey]) {
    return exactTitles[sectionKey];
  }
  return routeTitleFromConfig(
    CANDIDATE_VOTER_MAP_SECTION_CONFIG,
    sectionKey,
    "Candidate Voter Map",
  );
}

function getCoalitionDocumentTitle(route = state.route) {
  const routeKey = normalizeString(route?.routeKey);
  if (routeKey === ROUTE_KEY_COALITION_START) {
    return "Start Coalition";
  }
  if (routeKey === ROUTE_KEY_COALITION_JOIN) {
    return "Join Coalition";
  }
  const parts = coalitionRouteKeywordParts(route);
  if (!parts.length) {
    return routeKey === ROUTE_KEY_COALITIONS ? "Coalitions" : "Coalition";
  }
  if (parts[0] === "admin" && parts[1] === "edit") {
    return "Edit Coalition";
  }
  if (parts[0] === "admin") {
    return "Coalition Admin";
  }
  if (parts[0] === "amplify" && parts[1] === "create") {
    return "Create Amplify Request";
  }
  if (parts[0] === "constitution" || parts[0] === "voting") {
    const governance = coalitionGovernanceRouteForRoute(route);
    const governanceTitles = {
      constitution: "Coalition Constitution",
      voting: "Coalition Voting",
      speaker: "Speaker Console",
      "proposal-create": "New Coalition Proposal",
      "vote-detail": "Coalition Vote",
      "vote-results": "Coalition Vote Results",
    };
    return governanceTitles[governance.key] || "Coalition Governance";
  }
  if (parts[0] === "voter-map") {
    const sectionKey = coalitionVoterMapSectionForRoute(route);
    const voterMapTitles = {
      menu: "Coalition Voter Map",
      map: "Coalition Voter Map",
      "federal-districts": "Coalition Districts",
      connected: "Coalition Connected Voters",
      add: "Add Coalition Voters",
      cta: "Coalition CTA",
      "cta/transport": "CTA Transport",
      members: "Coalition Voter Map Members",
      "territories/admin": "Coalition Territories",
      scripts: "Coalition Outreach Scripts",
      notes: "Coalition Voter Notes",
    };
    return (
      voterMapTitles[sectionKey] ||
      prefixRouteTitle(
        "Coalition",
        routeTitleFromConfig(
          COALITION_VOTER_MAP_SECTION_CONFIG,
          sectionKey,
          humanizeLabel(sectionKey),
        ),
        "Coalition Voter Map",
      )
    );
  }
  const sectionKey = coalitionSectionForRoute(route);
  if (!sectionKey || sectionKey === COALITION_DEFAULT_SECTION) {
    return "Coalition";
  }
  const label = routeTitleFromConfig(
    COALITION_SECTION_CONFIG,
    sectionKey,
    humanizeLabel(sectionKey),
  );
  return prefixRouteTitle("Coalition", label, "Coalition");
}

