async function createCandidateDashboardMission(formData) {
  const candidateId = currentCandidateDashboardId();
  const resource = state.pages.candidateDashboard.detail.missionsWorkspace;
  const payload = candidateMissionPayloadFromForm(formData);
  if (!payload) {
    resource.error = "Mission title and lead owner are required.";
    showToast(resource.error);
    scheduleRender();
    return false;
  }
  resource.actionPendingKey = "create";
  resource.error = "";
  scheduleRender();
  try {
    const result = await fetchJson("/api/missions", {
      auth: true,
      method: "POST",
      body: payload,
    });
    const mission = normalizeCandidateDashboardMission(result.mission || result);
    resource.createOpen = false;
    resource.createDraft = null;
    showToast("Mission created.");
    await loadCandidateDashboardMissions(candidateId || payload.scopeId, {
      refresh: true,
    });
    if (mission.missionId) {
      resource.items = [
        mission,
        ...resource.items.filter((item) => item.missionId !== mission.missionId),
      ];
    }
    return true;
  } catch (error) {
    resource.error =
      normalizeString(error?.message) || "Mission could not be created.";
    showToast(resource.error);
    return false;
  } finally {
    resource.actionPendingKey = "";
    scheduleRender();
  }
}

