async function loadOfficialDetail(officialId, { refresh = false } = {}) {
  const detail = state.pages.candidates.officialDetail;
  const normalizedOfficialId = decodeRouteSegment(officialId);
  if (!normalizedOfficialId) {
    return;
  }
  if (detail.loading) {
    return;
  }
  if (
    refresh ||
    normalizeString(detail.item?.officialId) !== normalizedOfficialId
  ) {
    detail.item = null;
    detail.approval = null;
  }
  detail.loading = true;
  detail.approvalLoading = true;
  detail.error = "";
  detail.approvalError = "";
  scheduleRender();

  try {
    const [profileResult, approvalResult] = await Promise.allSettled([
      fetchJson(
        `/api/officials/${encodeURIComponent(normalizedOfficialId)}/profile`,
        {
          auth: true,
        },
      ),
      fetchJson(
        `/api/officials/${encodeURIComponent(normalizedOfficialId)}/approval`,
        {
          auth: true,
        },
      ),
    ]);
    if (profileResult.status === "rejected") {
      throw profileResult.reason;
    }
    detail.item = normalizeOfficialProfile(
      profileResult.value.profile || profileResult.value,
    );
    if (approvalResult.status === "fulfilled") {
      detail.approval = normalizeOfficialApprovalSummary(approvalResult.value);
      detail.approvalError = "";
    } else {
      detail.approval = null;
      detail.approvalError =
        normalizeString(approvalResult.reason?.message) ||
        "Approval summary unavailable.";
    }
  } catch (error) {
    detail.error =
      normalizeString(error?.message) || "Official profile unavailable.";
  } finally {
    detail.loading = false;
    detail.approvalLoading = false;
    scheduleRender();
  }
}

