function coalitionBallotPayloadFromForm(formData, vote) {
  if (vote.proposalType === "YES_NO") {
    const choice = normalizeString(formData.get("choice")).toLowerCase();
    if (!["yes", "no", "abstain"].includes(choice)) {
      throw new Error("Choose a ballot option.");
    }
    return { choice };
  }
  const rankings = vote.options
    .map((option) => ({
      optionId: option.optionId,
      rank: Number(normalizeString(formData.get(`rank:${option.optionId}`))),
    }))
    .filter((entry) => entry.optionId);
  const uniqueRanks = new Set(rankings.map((entry) => entry.rank));
  if (
    rankings.length !== vote.options.length ||
    uniqueRanks.size !== vote.options.length ||
    rankings.some(
      (entry) =>
        !Number.isInteger(entry.rank) ||
        entry.rank < 1 ||
        entry.rank > vote.options.length,
    )
  ) {
    throw new Error("Rank every option exactly once.");
  }
  return {
    rankings: rankings
      .sort((left, right) => left.rank - right.rank)
      .map((entry) => entry.optionId),
  };
}

function refreshCoalitionRankedBallotRanks(form, movedLabel = "") {
  const items = Array.from(
    form?.querySelectorAll("[data-coalition-rank-item]") || [],
  );
  items.forEach((item, index) => {
    const rank = index + 1;
    const input = item.querySelector("[data-coalition-rank-input]");
    const position = item.querySelector("[data-coalition-rank-position]");
    if (input) {
      input.value = String(rank);
    }
    if (position) {
      position.textContent = `#${rank}`;
    }
    const preferenceLabel = item.querySelector("[data-coalition-rank-label]");
    if (preferenceLabel) {
      preferenceLabel.textContent = index === 0 ? "Top preference" : `Preference ${rank}`;
    }
    item.classList.toggle("is-top", index === 0);
    item
      .querySelectorAll('[data-action="coalition-ranked-ballot-move"]')
      .forEach((button) => {
        const direction = Number(button.getAttribute("data-direction"));
        const disabled =
          !Number.isInteger(direction) ||
          (direction < 0 && index === 0) ||
          (direction > 0 && index === items.length - 1);
        button.disabled = disabled;
        button.setAttribute("aria-disabled", disabled ? "true" : "false");
      });
  });
  const status = form?.querySelector("[data-coalition-rank-status]");
  if (status && movedLabel) {
    status.textContent = `${movedLabel} moved. Current order updated.`;
  }
}

function moveCoalitionRankedBallotOption(target) {
  const form = target?.closest('form[data-route-form="coalition-vote-ballot"]');
  const list = target?.closest("[data-coalition-rank-list]");
  const item = target?.closest("[data-coalition-rank-item]");
  const direction = Number(target?.getAttribute("data-direction"));
  if (!form || !list || !item || !Number.isInteger(direction) || direction === 0) {
    return;
  }
  const items = Array.from(list.querySelectorAll("[data-coalition-rank-item]"));
  const index = items.indexOf(item);
  const nextIndex = index + direction;
  if (index < 0 || nextIndex < 0 || nextIndex >= items.length) {
    return;
  }
  if (direction < 0) {
    list.insertBefore(item, items[nextIndex]);
  } else {
    list.insertBefore(items[nextIndex], item);
  }
  refreshCoalitionRankedBallotRanks(
    form,
    normalizeString(item.getAttribute("data-option-label")) || "Option",
  );
}

async function castCoalitionVote(formData) {
  const coalitionId = currentCoalitionDetailId();
  const voteId = normalizeString(formData.get("voteId"));
  const vote = state.pages.coalitions.detail.votes.find(
    (item) => item.voteId === voteId,
  );
  if (!coalitionId || !voteId || !vote) {
    showToast("Ballot could not be submitted.");
    return false;
  }
  const workspace = coalitionGovernanceWorkspace();
  let body;
  try {
    body = coalitionBallotPayloadFromForm(formData, vote);
  } catch (error) {
    workspace.error = normalizeString(error?.message) || "Ballot is invalid.";
    showToast(workspace.error);
    scheduleRender();
    return false;
  }
  const actionKey = `vote:ballot:${voteId}`;
  workspace.actionPendingKey = actionKey;
  workspace.error = "";
  scheduleRender();
  try {
    await fetchJson(
      `/api/coalitions/${encodeURIComponent(coalitionId)}/votes/${encodeURIComponent(voteId)}/ballot`,
      { auth: true, method: "POST", body },
    );
    showToast("Ballot submitted.");
    await loadCoalitionDetail(coalitionId, { refresh: true });
    return true;
  } catch (error) {
    workspace.error = settingsErrorMessage(error, "Ballot could not be submitted.");
    showToast(workspace.error);
    return false;
  } finally {
    if (workspace.actionPendingKey === actionKey) {
      workspace.actionPendingKey = "";
    }
    scheduleRender();
  }
}

