function coalitionAmplifyWorkspace() {
  const detail = state.pages.coalitions.detail;
  if (!detail.amplifyWorkspace) {
    detail.amplifyWorkspace = createCoalitionAmplifyWorkspaceState();
  }
  return detail.amplifyWorkspace;
}

function splitCoalitionAmplifyTokens(value) {
  return normalizeString(value)
    .split(/[\s,]+/u)
    .map((entry) => entry.replace(/^#+/u, "").trim())
    .filter(Boolean);
}

function coalitionAmplifyLinksFromForm(formData) {
  return COALITION_AMPLIFY_PLATFORM_OPTIONS.reduce((acc, [key]) => {
    const value = normalizeUrl(formData.get(`link:${key}`));
    if (value) {
      acc[key] = value;
    }
    return acc;
  }, {});
}

async function refreshCoalitionAmplifyRequests() {
  const coalitionId = currentCoalitionDetailId();
  if (!coalitionId) {
    return;
  }
  await loadCoalitionDetail(coalitionId, { refresh: true });
}

async function copyCoalitionAmplifySuggestedCopy(requestId) {
  const normalizedRequestId = normalizeString(requestId);
  const request = state.pages.coalitions.detail.amplifyRequests.find(
    (item) => item.requestId === normalizedRequestId,
  );
  const text = normalizeString(request?.suggestedCopy);
  if (!text) {
    showToast("No suggested copy available.");
    return;
  }
  if (!navigator.clipboard?.writeText) {
    showToast("Clipboard copy is unavailable in this browser.");
    return;
  }
  try {
    await navigator.clipboard.writeText(text);
    showToast("Suggested copy copied.");
  } catch {
    showToast("Suggested copy could not be copied.");
  }
}

async function createCoalitionAmplifyRequest(formData) {
  const coalitionId = currentCoalitionDetailId();
  const title = normalizeString(formData.get("title"));
  const suggestedCopy = normalizeString(formData.get("suggestedCopy"));
  const description = normalizeString(formData.get("description"));
  const hashtags = splitCoalitionAmplifyTokens(formData.get("hashtags"));
  const links = coalitionAmplifyLinksFromForm(formData);
  if (!coalitionId || !title || !suggestedCopy) {
    showToast("Title and suggested copy are required.");
    return false;
  }
  if (!Object.keys(links).length) {
    showToast("Add at least one link to amplify.");
    return false;
  }
  const workspace = coalitionAmplifyWorkspace();
  workspace.actionPendingKey = "create";
  workspace.error = "";
  scheduleRender();
  try {
    await fetchJson(
      `/api/coalitions/${encodeURIComponent(coalitionId)}/amplify_requests`,
      {
        auth: true,
        method: "POST",
        body: {
          title,
          suggestedCopy,
          links,
          ...(description ? { description } : {}),
          ...(hashtags.length ? { hashtags: hashtags.join(", ") } : {}),
        },
      },
    );
    showToast("Amplify request created.");
    await loadCoalitionDetail(coalitionId, { refresh: true });
    return true;
  } catch (error) {
    workspace.error = settingsErrorMessage(
      error,
      "Amplify request could not be created.",
    );
    showToast(workspace.error);
    return false;
  } finally {
    if (workspace.actionPendingKey === "create") {
      workspace.actionPendingKey = "";
    }
    scheduleRender();
  }
}

