  const contactPrompt = state.pages.candidateDashboard.detail.contactPrompt;
  const fallbackSettings =
    contactPrompt.settings ||
    normalizeCandidateDashboardContactPromptSettings({}, candidateId);
  const nextSettings = {
    ...fallbackSettings,
    feedPromptEnabled: formData.has("feedPromptEnabled"),
    enabledContactTypes: CANDIDATE_CONTACT_TYPE_CONFIG.reduce((next, type) => {
      next[type.key] = formData.has(`contactType:${type.key}`);
      return next;
    }, {}),
  };
  contactPrompt.draft = nextSettings;
  contactPrompt.actionPendingKey = "save";
  contactPrompt.error = "";
