function coalitionVoterRecordsWorkspace() {
  const workspace = coalitionVoterMapWorkspace();
  if (!workspace.voters) {
    workspace.voters = createCoalitionVoterMapWorkspaceState().voters;
  }
  if (!workspace.voters.import) {
    workspace.voters.import =
      createCoalitionVoterMapWorkspaceState().voters.import;
  }
  return workspace.voters;
}

function buildCoalitionVoterRecordsQuery(resource, { cursor = "" } = {}) {
  const query = new URLSearchParams({ limit: "50" });
  const filters = resource.filters || {};
  [
    "q",
    "source",
    "city",
    "state",
    "party",
    "doorKnock",
    "mailPhysical",
    "mailEmail",
    "phoneCall",
    "textMessage",
    "yardSign",
  ].forEach((key) => {
    const value = normalizeString(filters[key]);
    if (value) {
      query.set(key, value);
    }
  });
  const normalizedCursor = normalizeString(cursor);
  if (normalizedCursor) {
    query.set("cursor", normalizedCursor);
  }
  return query;
}

async function loadCoalitionVoterRecords(
  coalitionId,
  { refresh = false, append = false } = {},
) {
  const normalizedCoalitionId = decodeRouteSegment(coalitionId);
  const voters = coalitionVoterRecordsWorkspace();
  if (!normalizedCoalitionId) {
    return;
  }
  if (append ? voters.loadingMore : voters.loading) {
    return;
  }
  if (!append && voters.loaded && !refresh) {
    return;
  }
  if (append && !voters.nextCursor) {
    return;
  }
  if (refresh && !append) {
    voters.items = [];
    voters.nextCursor = null;
    voters.loaded = false;
  }
  if (append) {
    voters.loadingMore = true;
  } else {
    voters.loading = true;
  }
  voters.error = "";
  scheduleRender();
  try {
    const query = buildCoalitionVoterRecordsQuery(voters, {
      cursor: append ? voters.nextCursor : "",
    });
    const payload = await fetchJson(
      `/api/coalitions/${encodeURIComponent(normalizedCoalitionId)}/voters?${query.toString()}`,
      { auth: true },
    );
    const page = normalizeCandidateVoterRegistryPage(payload);
    voters.items = append ? voters.items.concat(page.items) : page.items;
    voters.nextCursor = page.nextCursor;
    voters.loaded = true;
  } catch (error) {
    voters.error = settingsErrorMessage(
      error,
      "Coalition voter records could not be loaded.",
    );
  } finally {
    voters.loading = false;
    voters.loadingMore = false;
    scheduleRender();
  }
}

