function normalizeCoalitionDirectoryCategory(raw = {}, index = 0) {
  const label =
    normalizeString(raw.label || raw.name || raw.category || raw.key) ||
    `Category ${index + 1}`;
  return {
    key: normalizeString(raw.key || raw.id || label) || label,
    label,
    color: normalizeString(raw.color) || "",
    seeded: parseBoolean(raw.seeded, false),
  };
}

function normalizeCoalitionDirectoryTitle(raw = {}, index = 0) {
  const title =
    normalizeString(raw.title || raw.label || raw.name) ||
    `Role title ${index + 1}`;
  return {
    id: normalizeString(raw.id || raw.key || title) || title,
    title,
    category: normalizeString(raw.category || raw.roleCategory),
    titleGroup: normalizeString(raw.titleGroup || raw.title_group || raw.group),
    enabled: raw.enabled !== false,
    seeded: parseBoolean(raw.seeded, false),
  };
}

function normalizeCoalitionDirectoryCapability(raw = {}, index = 0) {
  const label =
    normalizeString(raw.label || raw.name || raw.key || raw.id) ||
    `Capability ${index + 1}`;
  return {
    id: normalizeString(raw.id || raw.key || label) || label,
    key: normalizeString(raw.key || raw.id || label) || label,
    label,
    category: normalizeString(raw.category || raw.roleCategory),
    enabled: raw.enabled !== false,
    seeded: parseBoolean(raw.seeded, false),
  };
}

function normalizeCoalitionDirectoryCatalog(raw = {}) {
  const payload = readObjectPayload(raw?.config || raw);
  return {
    categories: readArrayPayload(payload, ["categories"])
      .map(normalizeCoalitionDirectoryCategory)
      .filter((item) => item.label),
    titles: readArrayPayload(payload, ["titles"])
      .map(normalizeCoalitionDirectoryTitle)
      .filter((item) => item.title && item.enabled),
    capabilities: readArrayPayload(payload, ["capabilities"])
      .map(normalizeCoalitionDirectoryCapability)
      .filter((item) => item.label && item.enabled),
  };
}

function coalitionDirectoryAddressLabel(source = {}) {
  const address = readObjectPayload(source.address);
  const label = normalizeString(source.addressLabel || source.address_label);
  if (label) {
    return label;
  }
  return [
    address.addressLine1 || source.addressLine1,
    address.addressLine2 || source.addressLine2,
    address.city || source.city,
    address.state || source.state,
    address.postalCode || source.postalCode,
  ]
    .map(normalizeString)
    .filter(Boolean)
    .join(", ");
}

function normalizeCoalitionDirectoryMember(raw = {}) {
  const source = readObjectPayload(raw.member || raw.item || raw);
  const firstName = normalizeString(source.firstName || source.first_name);
  const lastName = normalizeString(source.lastName || source.last_name);
  const fullName =
    normalizeString(source.fullName || source.full_name) ||
    [firstName, lastName].filter(Boolean).join(" ") ||
    normalizeString(source.email) ||
    "Coalition member";
  const socialHandles = readObjectPayload(
    source.socialHandles || source.social_handles || source.socials,
  );
  return {
    memberId:
      normalizeString(source.memberId || source.member_id || source.id) ||
      fullName,
    coalitionId: normalizeString(source.coalitionId || source.coalition_id),
    firstName,
    lastName,
    fullName,
    initials:
      [firstName.slice(0, 1), lastName.slice(0, 1)]
        .filter(Boolean)
        .join("")
        .toUpperCase() || fullName.slice(0, 1).toUpperCase() || "M",
    email: normalizeString(source.email),
    phone: normalizeString(source.phone),
    addressLabel: coalitionDirectoryAddressLabel(source),
    lat: Number.isFinite(Number(source.lat ?? source.latitude))
      ? Number(source.lat ?? source.latitude)
      : null,
    lng: Number.isFinite(Number(source.lng ?? source.longitude))
      ? Number(source.lng ?? source.longitude)
      : null,
    roleCategory: normalizeString(source.roleCategory || source.role_category),
    roleTitle: normalizeString(source.roleTitle || source.role_title),
    roleLevel: normalizeString(source.roleLevel || source.role_level),
    territoryType: normalizeString(source.territoryType || source.territory_type),
    territoryValue: normalizeString(
      source.territoryValue || source.territory_value,
    ),
    organizationName: normalizeString(
      source.organizationName || source.organization_name,
    ),
    capabilities: normalizeStringList(source.capabilities),
    notes: normalizeString(source.notes),
    socialHandles,
    linkStatus:
      normalizeString(source.linkStatus || source.link_status) || "unlinked",
    linkedUserId: normalizeString(source.linkedUserId || source.linked_user_id),
    linkedUsername: normalizeString(
      source.linkedUsername || source.linked_username,
    ),
    avatarUrl: normalizeUrl(source.avatarUrl || source.avatar_url),
    categoryColor: normalizeString(source.categoryColor || source.category_color),
    locationStateId: normalizeString(
      source.locationStateId || source.location_state_id,
    ),
    locationDistrictId: normalizeString(
      source.locationDistrictId || source.location_district_id,
    ),
    locationCountyId: normalizeString(
      source.locationCountyId || source.location_county_id,
    ),
    createdAt:
      Number(source.createdAt ?? source.created_at) ||
      Date.parse(source.createdAt || source.created_at || "") ||
      null,
    updatedAt:
      Number(source.updatedAt ?? source.updated_at) ||
      Date.parse(source.updatedAt || source.updated_at || "") ||
      null,
    archivedAt:
      Number(source.archivedAt ?? source.archived_at) ||
      Date.parse(source.archivedAt || source.archived_at || "") ||
      null,
    raw: source,
  };
}

function normalizeCoalitionDirectoryImportPreview(raw = {}) {
  const payload = readObjectPayload(raw);
  const summary = readObjectPayload(payload.summary);
  return {
    uploadId: normalizeString(payload.uploadId || payload.upload_id),
    summary: {
      totalRows: Number(summary.totalRows || summary.total || 0) || 0,
      validRows: Number(summary.validRows || summary.valid || 0) || 0,
      invalidRows: Number(summary.invalidRows || summary.invalid || 0) || 0,
      duplicateRows:
        Number(
          summary.duplicateRows ||
            summary.duplicateExistingRows ||
            summary.duplicates ||
            0,
        ) || 0,
    },
    items: readArrayPayload(payload, ["items", "rows"]).map((row, index) => {
      const firstName = normalizeString(row.firstName || row.first_name);
      const lastName = normalizeString(row.lastName || row.last_name);
      const fullName =
        normalizeString(row.fullName || row.full_name) ||
        [firstName, lastName].filter(Boolean).join(" ") ||
        normalizeString(row.email) ||
        `Row ${index + 1}`;
      return {
        rowNumber: Number(row.rowNumber || row.row || index + 1) || index + 1,
        fullName,
        email: normalizeString(row.email),
        roleCategory: normalizeString(row.roleCategory || row.role_category),
        roleTitle: normalizeString(row.roleTitle || row.role_title),
        organizationName: normalizeString(
          row.organizationName || row.organization_name,
        ),
        duplicate: parseBoolean(row.duplicate, false),
        error: normalizeString(row.error || row.reason),
      };
    }),
  };
}

function normalizeCoalitionDirectoryImportStatus(raw = {}) {
  const payload = readObjectPayload(raw);
  const job = readObjectPayload(payload.job || payload);
  const importedCount =
    Number(job.importedCount || job.successCount || job.success_count || 0) ||
    0;
  const skippedCount =
    Number(
      job.skippedCount ||
        job.skippedDuplicateCount ||
        job.skipped_duplicate_count ||
        0,
    ) || 0;
  const failedCount =
    Number(job.failedCount || job.errorCount || job.error_count || 0) || 0;
  return {
    importId: normalizeString(job.importId || job.import_id),
    status: normalizeString(job.status) || "unknown",
    processedRows:
      Number(job.processedRows || job.processed_rows || job.totalRows || 0) ||
      importedCount + skippedCount + failedCount,
    importedCount,
    skippedCount,
    failedCount,
    errorMessage: normalizeString(job.errorMessage || job.error_message),
  };
}

function coalitionDirectoryWorkspace() {
  const workspace = coalitionVoterMapWorkspace();
  if (!workspace.directory) {
    workspace.directory = createCoalitionVoterMapWorkspaceState().directory;
  }
  if (!workspace.directory.catalog) {
    workspace.directory.catalog =
      createCoalitionVoterMapWorkspaceState().directory.catalog;
  }
  if (!workspace.directory.import) {
    workspace.directory.import =
      createCoalitionVoterMapWorkspaceState().directory.import;
  }
  return workspace.directory;
}

function buildCoalitionDirectoryMembersQuery(directory) {
  const query = new URLSearchParams();
  const filters = directory.filters || {};
  const search = normalizeString(filters.search);
  const category = normalizeString(filters.category);
  if (search) {
    query.set("search", search);
  }
  if (category) {
    query.set("category", category);
  }
  return query;
}

function normalizeCoalitionDirectorySort(value = "") {
  const normalized = normalizeString(value).toLowerCase();
  return ["name", "role", "linked", "updated"].includes(normalized)
    ? normalized
    : "name";
}

async function loadCoalitionDirectory(
  coalitionId,
  { refresh = false } = {},
) {
  const normalizedCoalitionId = decodeRouteSegment(coalitionId);
  const directory = coalitionDirectoryWorkspace();
  if (!normalizedCoalitionId || directory.loading) {
    return;
  }
  if (directory.loaded && !refresh) {
    return;
  }
  if (refresh) {
    directory.members = [];
    directory.loaded = false;
  }
  directory.loading = true;
  directory.error = "";
  scheduleRender();
  try {
    const query = buildCoalitionDirectoryMembersQuery(directory);
    const [catalogResult, membersResult] = await Promise.allSettled([
      fetchJson(
        `/api/coalitions/${encodeURIComponent(normalizedCoalitionId)}/directory/catalog`,
        { auth: true },
      ),
      fetchJson(
        `/api/coalitions/${encodeURIComponent(normalizedCoalitionId)}/directory/members${
          query.toString() ? `?${query.toString()}` : ""
        }`,
        { auth: true },
      ),
    ]);
    if (
      catalogResult.status === "rejected" &&
      membersResult.status === "rejected"
    ) {
      throw membersResult.reason || catalogResult.reason;
    }
    if (catalogResult.status === "fulfilled") {
      directory.catalog = normalizeCoalitionDirectoryCatalog(
        catalogResult.value,
      );
    }
    if (membersResult.status === "fulfilled") {
      const payload = membersResult.value;
      if (payload?.config) {
        directory.catalog = normalizeCoalitionDirectoryCatalog(payload.config);
      }
      directory.members = readArrayPayload(payload, ["items", "members"])
        .map(normalizeCoalitionDirectoryMember)
        .filter((member) => member.memberId);
    }
    directory.loaded = true;
  } catch (error) {
    directory.error = settingsErrorMessage(
      error,
      "Coalition member directory could not be loaded.",
    );
  } finally {
    directory.loading = false;
    scheduleRender();
  }
}

function coalitionDirectoryFiltersFromForm(formData) {
  return {
    search: normalizeString(formData.get("search")),
    category: normalizeString(formData.get("category")),
    capability: normalizeString(formData.get("capability")),
    linkStatus: normalizeString(formData.get("linkStatus")),
    sort: normalizeCoalitionDirectorySort(formData.get("sort")),
  };
}

async function applyCoalitionDirectoryFilters(formData) {
  const coalitionId = currentCoalitionDetailId();
  if (!coalitionId) {
    return;
  }
  const directory = coalitionDirectoryWorkspace();
  directory.filters = coalitionDirectoryFiltersFromForm(formData);
  await loadCoalitionDirectory(coalitionId, { refresh: true });
}

function coalitionDirectoryMemberPayloadFromForm(formData, duplicateMode = "") {
  const socialHandles = [
    "polis",
    "tiktok",
    "facebook",
    "instagram",
    "threads",
    "bluesky",
  ].reduce((handles, key) => {
    const value = normalizeString(formData.get(key));
    if (value) {
      handles[key] = value;
    }
    return handles;
  }, {});
  const payload = {
    firstName: normalizeString(formData.get("firstName")),
    lastName: normalizeString(formData.get("lastName")),
    email: normalizeString(formData.get("email")),
    phone: normalizeString(formData.get("phone")),
    addressLine1: normalizeString(formData.get("addressLine1")),
    addressLine2: normalizeString(formData.get("addressLine2")),
    city: normalizeString(formData.get("city")),
    state: normalizeString(formData.get("state")),
    postalCode: normalizeString(formData.get("postalCode")),
    roleCategory: normalizeString(formData.get("roleCategory")),
    roleTitle: normalizeString(formData.get("roleTitle")),
    roleLevel: normalizeString(formData.get("roleLevel")),
    territoryType: normalizeString(formData.get("territoryType")),
    territoryValue: normalizeString(formData.get("territoryValue")),
    organizationName: normalizeString(formData.get("organizationName")),
    capabilities: formData
      .getAll("capabilities")
      .map(normalizeString)
      .filter(Boolean),
    notes: normalizeString(formData.get("notes")),
    socialHandles,
  };
  const mode = normalizeString(duplicateMode).toLowerCase();
  if (["skip", "replace"].includes(mode)) {
    payload.duplicateMode = mode;
  }
  return payload;
}

function validateCoalitionDirectoryMemberPayload(payload) {
  if (!payload.firstName || !payload.lastName) {
    throw new Error("First and last name are required.");
  }
  if (!payload.email || !payload.email.includes("@")) {
    throw new Error("Enter a valid email address.");
  }
  if (!payload.addressLine1 || !payload.city || !payload.state) {
    throw new Error("Address line 1, city, and state are required.");
  }
}

async function createCoalitionDirectoryMember(formData, duplicateMode = "") {
  const coalitionId = currentCoalitionDetailId();
  const directory = coalitionDirectoryWorkspace();
  if (!coalitionId) {
    showToast("Coalition unavailable.");
    return false;
  }
  const payload = coalitionDirectoryMemberPayloadFromForm(
    formData,
    duplicateMode,
  );
  try {
    validateCoalitionDirectoryMemberPayload(payload);
  } catch (error) {
    directory.error =
      normalizeString(error?.message) || "Coalition member form is incomplete.";
    showToast(directory.error);
    scheduleRender();
    return false;
  }
  directory.actionPendingKey = "member-create";
  directory.error = "";
  directory.duplicate = null;
  scheduleRender();
  try {
    const response = await fetchJson(
      `/api/coalitions/${encodeURIComponent(coalitionId)}/directory/members`,
      {
        auth: true,
        method: "POST",
        body: payload,
      },
    );
    const member = response.member
      ? normalizeCoalitionDirectoryMember(response.member)
      : null;
    showToast(response.skipped ? "Existing directory member kept." : "Coalition member saved.");
    if (member?.memberId) {
      directory.members = [
        member,
        ...directory.members.filter((item) => item.memberId !== member.memberId),
      ];
    }
    await loadCoalitionDirectory(coalitionId, { refresh: true });
    return true;
  } catch (error) {
    if (Number(error?.status) === 409) {
      directory.duplicate = {
        payload,
        existing: error?.payload?.existing
          ? normalizeCoalitionDirectoryMember(error.payload.existing)
          : null,
      };
      directory.error =
        "Duplicate directory member found. Choose how to proceed.";
      showToast(directory.error);
      return false;
    }
    directory.error = settingsErrorMessage(
      error,
      "Coalition member could not be saved.",
    );
    showToast(directory.error);
    return false;
  } finally {
    if (directory.actionPendingKey === "member-create") {
      directory.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function resolveCoalitionDirectoryDuplicate(mode) {
  const coalitionId = currentCoalitionDetailId();
  const directory = coalitionDirectoryWorkspace();
  const duplicate = directory.duplicate;
  const normalizedMode = normalizeString(mode).toLowerCase();
  if (
    !coalitionId ||
    !duplicate ||
    !["skip", "replace"].includes(normalizedMode)
  ) {
    directory.duplicate = null;
    scheduleRender();
    return;
  }
  directory.actionPendingKey = `directory-duplicate:${normalizedMode}`;
  directory.error = "";
  scheduleRender();
  try {
    const response = await fetchJson(
      `/api/coalitions/${encodeURIComponent(coalitionId)}/directory/members`,
      {
        auth: true,
        method: "POST",
        body: { ...duplicate.payload, duplicateMode: normalizedMode },
      },
    );
    const member = response.member
      ? normalizeCoalitionDirectoryMember(response.member)
      : null;
    directory.duplicate = null;
    showToast(
      response.skipped ? "Existing directory member kept." : "Directory member replaced.",
    );
    if (member?.memberId) {
      directory.members = [
        member,
        ...directory.members.filter((item) => item.memberId !== member.memberId),
      ];
    }
    await loadCoalitionDirectory(coalitionId, { refresh: true });
  } catch (error) {
    directory.error = settingsErrorMessage(
      error,
      "Duplicate choice could not be saved.",
    );
    showToast(directory.error);
  } finally {
    directory.actionPendingKey = "";
    scheduleRender();
  }
}

async function previewCoalitionDirectoryImport(formData) {
  const coalitionId = currentCoalitionDetailId();
  const file = formData.get("csvFile");
  const directoryImport = coalitionDirectoryWorkspace().import;
  if (!coalitionId || !(file instanceof File) || !file.name) {
    showToast("Choose a CSV file first.");
    return false;
  }
  directoryImport.actionPendingKey = "preview";
  directoryImport.error = "";
  directoryImport.preview = null;
  directoryImport.status = null;
  scheduleRender();
  try {
    const uploadSession = await fetchJson(
      `/api/coalitions/${encodeURIComponent(coalitionId)}/directory/imports/upload`,
      {
        auth: true,
        method: "POST",
        body: {
          fileName: file.name,
          contentType: file.type || "text/csv",
        },
      },
    );
    const uploadId = normalizeString(uploadSession.uploadId);
    const upload = readObjectPayload(uploadSession.upload || uploadSession);
    const uploadUrl = normalizeString(upload.uploadUrl || upload.url);
    if (!uploadId || !uploadUrl) {
      throw new Error("Import upload session was incomplete.");
    }
    const uploadHeaders =
      upload.headers && typeof upload.headers === "object"
        ? Object.fromEntries(
            Object.entries(upload.headers).map(([key, value]) => [
              key,
              normalizeString(value),
            ]),
          )
        : { "content-type": upload.contentType || file.type || "text/csv" };
    const uploadResponse = await fetch(uploadUrl, {
      method: normalizeString(upload.method) || "PUT",
      headers: uploadHeaders,
      body: file,
    });
    if (!uploadResponse.ok) {
      throw new Error(`CSV upload failed: ${uploadResponse.status}`);
    }
    const preview = await fetchJson(
      `/api/coalitions/${encodeURIComponent(coalitionId)}/directory/imports/preview`,
      {
        auth: true,
        method: "POST",
        body: { uploadId },
      },
    );
    directoryImport.uploadId = uploadId;
    directoryImport.fileName = file.name;
    directoryImport.preview = normalizeCoalitionDirectoryImportPreview({
      ...preview,
      uploadId: preview.uploadId || uploadId,
    });
    showToast("Directory CSV preview ready.");
    return true;
  } catch (error) {
    directoryImport.error = settingsErrorMessage(
      error,
      "Directory CSV preview could not be created.",
    );
    showToast(directoryImport.error);
    return false;
  } finally {
    if (directoryImport.actionPendingKey === "preview") {
      directoryImport.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function startCoalitionDirectoryImport(duplicateMode = "") {
  const coalitionId = currentCoalitionDetailId();
  const directory = coalitionDirectoryWorkspace();
  const directoryImport = directory.import;
  const uploadId = normalizeString(directoryImport.uploadId);
  if (!coalitionId || !uploadId) {
    showToast("Run a CSV preview first.");
    return;
  }
  const mode =
    normalizeString(duplicateMode).toLowerCase() ||
    normalizeString(directoryImport.duplicateMode).toLowerCase() ||
    "replace";
  directoryImport.actionPendingKey = "start";
  directoryImport.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      `/api/coalitions/${encodeURIComponent(coalitionId)}/directory/imports/start`,
      {
        auth: true,
        method: "POST",
        body: { uploadId, duplicateMode: mode },
      },
    );
    directoryImport.status = normalizeCoalitionDirectoryImportStatus(payload);
    directoryImport.duplicateMode = mode;
    showToast("Coalition member import started.");
    if (directoryImport.status.importId) {
      await loadCoalitionDirectoryImportStatus(directoryImport.status.importId);
    }
    if (voterImportStatusIsTerminal(directoryImport.status)) {
      await loadCoalitionDirectory(coalitionId, { refresh: true });
    }
  } catch (error) {
    directoryImport.error = settingsErrorMessage(
      error,
      "Directory import could not be started.",
    );
    showToast(directoryImport.error);
  } finally {
    if (directoryImport.actionPendingKey === "start") {
      directoryImport.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function loadCoalitionDirectoryImportStatus(importId = "") {
  const coalitionId = currentCoalitionDetailId();
  const directory = coalitionDirectoryWorkspace();
  const directoryImport = directory.import;
  const normalizedImportId =
    normalizeString(importId) || normalizeString(directoryImport.status?.importId);
  if (!coalitionId || !normalizedImportId) {
    return;
  }
  directoryImport.actionPendingKey = "status";
  directoryImport.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      `/api/coalitions/${encodeURIComponent(coalitionId)}/directory/imports/${encodeURIComponent(normalizedImportId)}`,
      { auth: true },
    );
    directoryImport.status = normalizeCoalitionDirectoryImportStatus(payload);
    if (voterImportStatusIsTerminal(directoryImport.status)) {
      await loadCoalitionDirectory(coalitionId, { refresh: true });
    }
  } catch (error) {
    directoryImport.error = settingsErrorMessage(
      error,
      "Directory import status could not be loaded.",
    );
    showToast(directoryImport.error);
  } finally {
    directoryImport.actionPendingKey = "";
    scheduleRender();
  }
}

async function deleteCoalitionDirectoryMember(memberId) {
  const coalitionId = currentCoalitionDetailId();
  const normalizedMemberId = normalizeString(memberId);
  const directory = coalitionDirectoryWorkspace();
  const member = directory.members.find(
    (item) => item.memberId === normalizedMemberId,
  );
  if (!coalitionId || !normalizedMemberId) {
    return false;
  }
  const name = member?.fullName || "this coalition member";
  if (
    !(await confirmDestructiveAction({
      title: "Archive coalition member?",
      message: `${name} will be archived from the coalition directory.`,
      confirmLabel: "Archive member",
      icon: "archive",
    }))
  ) {
    return false;
  }
  directory.actionPendingKey = `directory-delete:${normalizedMemberId}`;
  directory.error = "";
  scheduleRender();
  try {
    await fetchJson(
      `/api/coalitions/${encodeURIComponent(coalitionId)}/directory/members/${encodeURIComponent(normalizedMemberId)}`,
      {
        auth: true,
        method: "DELETE",
      },
    );
    directory.members = directory.members.filter(
      (item) => item.memberId !== normalizedMemberId,
    );
    showToast("Coalition member archived.");
    await loadCoalitionDirectory(coalitionId, { refresh: true });
    return true;
  } catch (error) {
    directory.error = settingsErrorMessage(
      error,
      "Coalition member could not be archived.",
    );
    showToast(directory.error);
    return false;
  } finally {
    directory.actionPendingKey = "";
    scheduleRender();
  }
}

async function loadCandidateDashboardCampaignQuest(
  candidateId,
  { refresh = false } = {},
) {
  const normalizedCandidateId = decodeRouteSegment(candidateId);
  if (!normalizedCandidateId) {
    return;
  }
  const quest = state.pages.candidateDashboard.detail.campaignQuest;
  if (quest.loading) {
    return;
  }
  if (quest.loaded && !refresh) {
    return;
  }
  quest.loading = true;
  quest.error = "";
  scheduleRender();
  try {
    const query = new URLSearchParams({ candidateId: normalizedCandidateId });
    const mapQuery = new URLSearchParams({
      candidateId: normalizedCandidateId,
      bbox: normalizeString(quest.bbox) || "-125,24,-66,50",
      zoom: String(Number(quest.zoom) || 5),
    });
    const [configResult, progressResult, mapResult] = await Promise.allSettled([
      fetchJson(
        `/api/candidate-dashboard/campaign-quest/config?${query.toString()}`,
        { auth: true },
      ),
      fetchJson(
        `/api/candidate-dashboard/campaign-quest/progress?${query.toString()}`,
        { auth: true },
      ),
      fetchJson(
        `/api/candidate-dashboard/campaign-quest/map?${mapQuery.toString()}`,
        { auth: true },
      ),
    ]);
    if (configResult.status === "fulfilled") {
      quest.config = normalizeCampaignQuestConfig(configResult.value);
    }
    if (progressResult.status === "fulfilled") {
      quest.progress = normalizeCampaignQuestProgress(progressResult.value);
    }
      if (mapResult.status === "fulfilled") {
        const page = normalizeCampaignQuestMapPage(mapResult.value);
        quest.targets = page.targets;
        quest.clusters = page.clusters;
        if (
          quest.selectedTargetId &&
          !quest.targets.some((target) => target.recordId === quest.selectedTargetId)
        ) {
          quest.selectedTargetId = "";
        }
        if (
          quest.categoryFilter !== "all" &&
          !quest.targets.some((target) => target.targetCategory === quest.categoryFilter)
        ) {
          quest.categoryFilter = "all";
        }
        if (!quest.selectedTargetId && quest.targets[0]) {
          quest.selectedTargetId = quest.targets[0].recordId;
        }
        if (page.config.outcomeFields.length || page.config.questTemplates.length) {
          quest.config = page.config;
        }
      if (page.progress.level || page.progress.lifetimeXp) {
        quest.progress = page.progress;
      }
    }
    const failed = [configResult, progressResult, mapResult].filter(
      (entry) => entry.status === "rejected",
    );
    if (failed.length === 3) {
      throw failed[0].reason;
    }
    quest.loaded = true;
  } catch (error) {
    quest.error = settingsErrorMessage(
      error,
      "Campaign Quest could not be loaded.",
    );
  } finally {
    quest.loading = false;
    scheduleRender();
  }
}

async function loadCandidateDashboardVoterMapAccess(
  candidateId,
  { refresh = false } = {},
) {
  const normalizedCandidateId = decodeRouteSegment(candidateId);
  if (!normalizedCandidateId) {
    return;
  }
  const voterMap = state.pages.candidateDashboard.detail.voterMap;
  if (voterMap.loading) {
    return;
  }
  if (voterMap.loaded && !refresh) {
    return;
  }
  if (refresh) {
    voterMap.access = null;
    voterMap.loaded = false;
  }
  voterMap.loading = true;
  voterMap.error = "";
  scheduleRender();
  try {
    const query = new URLSearchParams({ candidateId: normalizedCandidateId });
    const payload = await fetchJson(
      `/api/candidate-dashboard/voter-map/access?${query.toString()}`,
      { auth: true },
    );
    voterMap.access = normalizeCandidateVoterMapAccess(payload);
    voterMap.loaded = true;
  } catch (error) {
    voterMap.error = settingsErrorMessage(
      error,
      "Voter-map access could not be loaded.",
    );
  } finally {
    voterMap.loading = false;
    scheduleRender();
  }
}

function candidateVoterMapOutreachTemplatesState() {
  const voterMap = state.pages.candidateDashboard.detail.voterMap;
  if (!voterMap.templates) {
    voterMap.templates = createVoterMapOutreachTemplatesState();
  }
  return voterMap.templates;
}

async function loadCandidateVoterMapOutreachTemplates(
  candidateId,
  { refresh = false } = {},
) {
  const normalizedCandidateId = decodeRouteSegment(candidateId);
  const templates = candidateVoterMapOutreachTemplatesState();
  if (!normalizedCandidateId || templates.loading) {
    return false;
  }
  if (templates.loaded && !refresh) {
    return true;
  }
  if (refresh) {
    templates.loaded = false;
    templates.notice = "";
  }
  templates.loading = true;
  templates.error = "";
  scheduleRender();
  try {
    const query = new URLSearchParams({ candidateId: normalizedCandidateId });
    const payload = await fetchJson(
      `/api/candidate-dashboard/voter-map/outreach-templates?${query.toString()}`,
      { auth: true },
    );
    templates.items = normalizeVoterMapOutreachTemplates(payload);
    templates.loaded = true;
    return true;
  } catch (error) {
    templates.error = settingsErrorMessage(
      error,
      "Campaign outreach scripts could not be loaded.",
    );
    return false;
  } finally {
    templates.loading = false;
    scheduleRender();
  }
}

async function saveCandidateVoterMapOutreachTemplates(formData) {
  const candidateId =
    normalizeString(formData.get("candidateId")) || currentCandidateDashboardId();
  const templates = candidateVoterMapOutreachTemplatesState();
  if (!candidateId || templates.actionPendingKey) {
    return false;
  }
  templates.actionPendingKey = "save";
  templates.error = "";
  templates.notice = "";
  scheduleRender();
  try {
    const query = new URLSearchParams({ candidateId });
    const payload = await fetchJson(
      `/api/candidate-dashboard/voter-map/outreach-templates?${query.toString()}`,
      {
        auth: true,
        method: "PUT",
        body: voterMapOutreachTemplatesFromForm(formData),
      },
    );
    templates.items = normalizeVoterMapOutreachTemplates(payload);
    templates.loaded = true;
    templates.notice = "Outreach scripts saved.";
    showToast(templates.notice);
    return true;
  } catch (error) {
    templates.error = settingsErrorMessage(
      error,
      "Campaign outreach scripts could not be saved.",
    );
    showToast(templates.error);
    return false;
  } finally {
    templates.actionPendingKey = "";
    scheduleRender();
  }
}

function voterMapNotesStateForOwner(ownerKind) {
  if (ownerKind === "coalition") {
    const workspace = coalitionVoterMapWorkspace();
    if (!workspace.notes) {
      workspace.notes = createVoterMapNotesState();
    }
    return workspace.notes;
  }
  const voterMap = state.pages.candidateDashboard.detail.voterMap;
  if (!voterMap.notes) {
    voterMap.notes = createVoterMapNotesState();
  }
  return voterMap.notes;
}

function resetVoterMapNotesForRecord(notes, recordId, voterName = "") {
  if (notes.recordId === recordId) {
    notes.voterName = voterName || notes.voterName;
    return;
  }
  notes.recordId = recordId;
  notes.voterName = voterName;
  notes.items = [];
  notes.nextCursor = null;
  notes.loaded = false;
  notes.loading = false;
  notes.error = "";
  notes.notice = "";
  notes.actionPendingKey = "";
  notes.selectedNoteId = "";
  notes.detail = null;
  notes.detailLoading = false;
  notes.detailError = "";
}

function candidateVoterMapNotesEndpoint(candidateId, recordId, noteId = "") {
  const query = new URLSearchParams({ candidateId });
  const suffix = noteId ? `/${encodeURIComponent(noteId)}` : "";
  return `/api/candidate-dashboard/voter-map/records/${encodeURIComponent(recordId)}/notes${suffix}?${query.toString()}`;
}

function coalitionVoterMapNotesEndpoint(coalitionId, recordId, noteId = "") {
  const suffix = noteId ? `/${encodeURIComponent(noteId)}` : "";
  return `/api/coalitions/${encodeURIComponent(coalitionId)}/voter-map/records/${encodeURIComponent(recordId)}/notes${suffix}`;
}

function voterMapNotesEndpoint(ownerKind, ownerId, recordId, noteId = "") {
  return ownerKind === "coalition"
    ? coalitionVoterMapNotesEndpoint(ownerId, recordId, noteId)
    : candidateVoterMapNotesEndpoint(ownerId, recordId, noteId);
}

async function loadVoterMapNotes({
  ownerKind = "candidate",
  ownerId = "",
  recordId = "",
  voterName = "",
  refresh = false,
} = {}) {
  const normalizedOwnerKind = ownerKind === "coalition" ? "coalition" : "candidate";
  const normalizedOwnerId = normalizeString(ownerId);
  const normalizedRecordId = normalizeString(recordId);
  const notes = voterMapNotesStateForOwner(normalizedOwnerKind);
  if (!normalizedOwnerId || !normalizedRecordId || notes.loading) {
    return false;
  }
  resetVoterMapNotesForRecord(notes, normalizedRecordId, voterName);
  if (notes.loaded && !refresh) {
    return true;
  }
  if (refresh) {
    notes.loaded = false;
    notes.notice = "";
    notes.detailError = "";
  }
  notes.loading = true;
  notes.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      voterMapNotesEndpoint(normalizedOwnerKind, normalizedOwnerId, normalizedRecordId),
      { auth: true },
    );
    const page = normalizeVoterMapNotesPage(payload);
    notes.items = page.items;
    notes.nextCursor = page.nextCursor;
    notes.loaded = true;
    return true;
  } catch (error) {
    notes.error = settingsErrorMessage(error, "Voter notes could not be loaded.");
    return false;
  } finally {
    notes.loading = false;
    scheduleRender();
  }
}

function loadCandidateVoterMapNotes(candidateId, options = {}) {
  return loadVoterMapNotes({
    ownerKind: "candidate",
    ownerId: candidateId,
    ...options,
  });
}

function loadCoalitionVoterMapNotes(coalitionId, options = {}) {
  return loadVoterMapNotes({
    ownerKind: "coalition",
    ownerId: coalitionId,
    ...options,
  });
}

async function loadVoterMapNoteDetail({
  ownerKind = "candidate",
  ownerId = "",
  recordId = "",
  noteId = "",
} = {}) {
  const normalizedOwnerKind = ownerKind === "coalition" ? "coalition" : "candidate";
  const normalizedOwnerId = normalizeString(ownerId);
  const normalizedRecordId = normalizeString(recordId);
  const normalizedNoteId = normalizeString(noteId);
  const notes = voterMapNotesStateForOwner(normalizedOwnerKind);
  if (!normalizedOwnerId || !normalizedRecordId || !normalizedNoteId) {
    return false;
  }
  resetVoterMapNotesForRecord(notes, normalizedRecordId, notes.voterName);
  notes.selectedNoteId = normalizedNoteId;
  notes.detailLoading = true;
  notes.detailError = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      voterMapNotesEndpoint(
        normalizedOwnerKind,
        normalizedOwnerId,
        normalizedRecordId,
        normalizedNoteId,
      ),
      { auth: true },
    );
    notes.detail = normalizeVoterMapNoteDetail(payload.note || payload);
    return true;
  } catch (error) {
    notes.detailError = settingsErrorMessage(error, "Note detail could not be loaded.");
    return false;
  } finally {
    notes.detailLoading = false;
    scheduleRender();
  }
}

async function createVoterMapNote(formData) {
  const ownerKind =
    normalizeString(formData.get("ownerKind")) === "coalition"
      ? "coalition"
      : "candidate";
  const ownerId = normalizeString(formData.get("ownerId"));
  const recordId = normalizeString(formData.get("recordId"));
  const voterName = normalizeString(formData.get("voterName"));
  const notes = voterMapNotesStateForOwner(ownerKind);
  const body = voterMapNotePayloadFromForm(formData);
  if (!ownerId || !recordId || notes.actionPendingKey) {
    return false;
  }
  resetVoterMapNotesForRecord(notes, recordId, voterName);
  if (!body.body) {
    notes.error = "Add a note before saving.";
    scheduleRender();
    return false;
  }
  notes.actionPendingKey = "create";
  notes.error = "";
  notes.notice = "";
  scheduleRender();
  try {
    const payload = await fetchJson(voterMapNotesEndpoint(ownerKind, ownerId, recordId), {
      auth: true,
      method: "POST",
      body,
    });
    const created = normalizeVoterMapNoteDetail(payload.note || payload);
    notes.items = [
      created,
      ...notes.items.filter((item) => item.noteId !== created.noteId),
    ].filter((item) => item.noteId);
    notes.detail = created;
    notes.selectedNoteId = created.noteId;
    notes.loaded = true;
    notes.notice = "Note saved.";
    showToast(notes.notice);
    return true;
  } catch (error) {
    notes.error = settingsErrorMessage(error, "Note could not be saved.");
    showToast(notes.error);
    return false;
  } finally {
    notes.actionPendingKey = "";
    scheduleRender();
  }
}

function saveCandidateVoterMapSettings(formData) {
  const voterMap = state.pages.candidateDashboard.detail.voterMap;
  const rawPinCap = Number(formData.get("pinCap"));
  const pinCap = Math.max(
    250,
    Math.min(5000, Number.isFinite(rawPinCap) ? Math.round(rawPinCap) : 1250),
  );
  const offlineCellular = formData.has("offlineCellular");
  voterMap.pinCap = pinCap;
  voterMap.offlineCellular = offlineCellular;
  try {
    window.localStorage?.setItem(
      CANDIDATE_VOTER_MAP_PIN_CAP_STORAGE_KEY,
      String(pinCap),
    );
    window.localStorage?.setItem(
      CANDIDATE_VOTER_MAP_OFFLINE_CELLULAR_STORAGE_KEY,
      offlineCellular ? "true" : "false",
    );
  } catch {
    // Local settings still update in memory if storage is unavailable.
  }
  showToast("Map settings saved.");
  scheduleRender();
  return true;
}

const CAMPAIGN_QUEST_XP_SECTION_CONFIG = [
  {
    key: "baseXp",
    title: "Base XP",
    description: "Points awarded before outcome and verification multipliers.",
  },
  {
    key: "outcomeMultipliers",
    title: "Outcome multipliers",
    description: "Adjust how much each field result changes the base XP.",
  },
  {
    key: "verificationMultipliers",
    title: "Verification multipliers",
    description: "Reward verified work and keep unverified or flagged actions bounded.",
  },
  {
    key: "caps",
    title: "XP caps",
    description: "Daily and action-level limits that protect score quality.",
  },
];

function readCampaignQuestFormNumber(formData, name, fallback = 0, options = {}) {
  const parsed = Number(formData.get(name));
  if (!Number.isFinite(parsed)) {
    return fallback;
  }
  const min = Number.isFinite(options.min) ? options.min : null;
  const max = Number.isFinite(options.max) ? options.max : null;
  const rounded = options.integer ? Math.trunc(parsed) : parsed;
  return Math.min(max ?? rounded, Math.max(min ?? rounded, rounded));
}

function campaignQuestJsonObjectFromForm(value, fallback = {}) {
  try {
    const parsed = JSON.parse(normalizeString(value) || "{}");
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed;
    }
  } catch {
    // Keep the last valid mapping instead of saving destructive malformed JSON.
  }
  return fallback && typeof fallback === "object" && !Array.isArray(fallback)
    ? { ...fallback }
    : {};
}

function campaignQuestNumberMapFromForm(formData, sectionKey, currentMap = {}) {
  const source =
    currentMap && typeof currentMap === "object" && !Array.isArray(currentMap)
      ? currentMap
      : {};
  const next = { ...source };
  Object.keys(source).forEach((_, index) => {
    const formKey = normalizeString(
      formData.get(`xp:${sectionKey}:${index}:key`),
    );
    if (!formKey) {
      return;
    }
    next[formKey] = readCampaignQuestFormNumber(
      formData,
      `xp:${sectionKey}:${index}:value`,
      Number(source[formKey]) || 0,
    );
  });
  return next;
}

function campaignQuestXpRulesFromForm(formData, currentRules = {}) {
  const rules =
    currentRules && typeof currentRules === "object" && !Array.isArray(currentRules)
      ? { ...currentRules }
      : {};
  CAMPAIGN_QUEST_XP_SECTION_CONFIG.forEach((section) => {
    rules[section.key] = campaignQuestNumberMapFromForm(
      formData,
      section.key,
      rules[section.key],
    );
  });
  return rules;
}

function campaignQuestOutcomeFieldsFromForm(formData, currentFields = []) {
  return currentFields.map((field, index) => {
    const outreachTypes = normalizeStringList(
      formData.get(`outcome:${index}:outreachTypes`),
    );
    return {
      ...field,
      enabled: formData.has(`outcome:${index}:enabled`),
      label:
        normalizeString(formData.get(`outcome:${index}:label`)) ||
        field.label ||
        field.id,
      outreachTypes: outreachTypes.length ? outreachTypes : field.outreachTypes,
      contactOutcome: campaignQuestJsonObjectFromForm(
        formData.get(`outcome:${index}:contactOutcome`),
        field.contactOutcome,
      ),
    };
  });
}

function campaignQuestTemplatesFromForm(formData, currentTemplates = []) {
  return currentTemplates.map((template, templateIndex) => ({
    ...template,
    enabled: formData.has(`quest:${templateIndex}:enabled`),
    title:
      normalizeString(formData.get(`quest:${templateIndex}:title`)) ||
      template.title ||
      template.id,
    period:
      normalizeString(formData.get(`quest:${templateIndex}:period`)) ||
      template.period ||
      "daily",
    rewardXp: readCampaignQuestFormNumber(
      formData,
      `quest:${templateIndex}:rewardXp`,
      Number(template.rewardXp) || 0,
      { min: 0, integer: true },
    ),
    goals: (template.goals || []).map((goal, goalIndex) => ({
      type: normalizeString(goal.type),
      target: readCampaignQuestFormNumber(
        formData,
        `quest:${templateIndex}:goal:${goalIndex}:target`,
        Number(goal.target) || 1,
        { min: 1, integer: true },
      ),
    })),
  }));
}

function campaignQuestBadgesFromForm(formData, currentBadges = []) {
  return currentBadges.map((badge, index) => ({
    ...badge,
    enabled: formData.has(`badge:${index}:enabled`),
    title:
      normalizeString(formData.get(`badge:${index}:title`)) ||
      badge.title ||
      badge.id,
    metric: normalizeString(formData.get(`badge:${index}:metric`)) || badge.metric,
    target: readCampaignQuestFormNumber(
      formData,
      `badge:${index}:target`,
      Number(badge.target) || 1,
      { min: 1, integer: true },
    ),
  }));
}

function campaignQuestConfigFromForm(formData, currentConfig = null) {
  const current = normalizeCampaignQuestConfig(currentConfig || {});
  return {
    ...current,
    enabled: formData.has("enabled"),
    xpRules: campaignQuestXpRulesFromForm(formData, current.xpRules),
    outcomeFields: campaignQuestOutcomeFieldsFromForm(
      formData,
      current.outcomeFields,
    ),
    questTemplates: campaignQuestTemplatesFromForm(
      formData,
      current.questTemplates,
    ),
    badges: campaignQuestBadgesFromForm(formData, current.badges),
    privacy: {
      ...current.privacy,
      exposeRawScoresToVolunteers: formData.has("exposeRawScoresToVolunteers"),
      individualLeaderboardsEnabled: formData.has(
        "individualLeaderboardsEnabled",
      ),
      publicBadgeVisibility:
        normalizeString(formData.get("publicBadgeVisibility")) || "campaign",
    },
    verification: {
      ...current.verification,
      gpsSoftCheckEnabled: formData.has("gpsSoftCheckEnabled"),
      gpsNearbyMeters: Math.max(
        10,
        Number(formData.get("gpsNearbyMeters")) ||
          current.verification.gpsNearbyMeters ||
          100,
      ),
      unverifiedXpMultiplier: Number.isFinite(
        Number(formData.get("unverifiedXpMultiplier")),
      )
        ? Number(formData.get("unverifiedXpMultiplier"))
        : current.verification.unverifiedXpMultiplier,
      photoRequiredForYardSigns: formData.has("photoRequiredForYardSigns"),
    },
    safety: {
      ...current.safety,
      activeShiftRequired: formData.has("activeShiftRequired"),
      canvassingHoursEnabled: formData.has("canvassingHoursEnabled"),
      canvassingHoursStart:
        normalizeString(formData.get("canvassingHoursStart")) ||
        current.safety.canvassingHoursStart,
      canvassingHoursEnd:
        normalizeString(formData.get("canvassingHoursEnd")) ||
        current.safety.canvassingHoursEnd,
      allowSkipUnsafeAddress: formData.has("allowSkipUnsafeAddress"),
    },
  };
}

async function saveCandidateCampaignQuestConfig(formData) {
  const candidateId = currentCandidateDashboardId();
  if (!candidateId) {
    showToast("Campaign unavailable.");
    return false;
  }
  const quest = state.pages.candidateDashboard.detail.campaignQuest;
  quest.actionPendingKey = "config";
  quest.error = "";
  scheduleRender();
  try {
    const query = new URLSearchParams({ candidateId });
    const config = campaignQuestConfigFromForm(formData, quest.config);
    const payload = await fetchJson(
      `/api/candidate-dashboard/campaign-quest/config?${query.toString()}`,
      {
        auth: true,
        method: "PUT",
        body: { config },
      },
    );
    quest.config = normalizeCampaignQuestConfig(payload);
    quest.loaded = true;
    showToast("Campaign Quest settings saved.");
    return true;
  } catch (error) {
    quest.error = settingsErrorMessage(
      error,
      "Campaign Quest settings could not be saved.",
    );
    showToast(quest.error);
    return false;
  } finally {
    if (quest.actionPendingKey === "config") {
      quest.actionPendingKey = "";
    }
    scheduleRender();
  }
}

function setCampaignQuestCategoryFilter(category) {
  const quest = state.pages.candidateDashboard.detail.campaignQuest;
  const normalized = normalizeString(category) || "all";
  const available = new Set([
    "all",
    ...quest.targets.map((target) => target.targetCategory).filter(Boolean),
  ]);
  quest.categoryFilter = available.has(normalized) ? normalized : "all";
  const filtered = campaignQuestFilteredTargets(quest);
  if (
    quest.selectedTargetId &&
    !filtered.some((target) => target.recordId === quest.selectedTargetId)
  ) {
    quest.selectedTargetId = "";
  }
  if (!quest.selectedTargetId && filtered[0]) {
    quest.selectedTargetId = filtered[0].recordId;
  }
  scheduleRender();
}

function selectCampaignQuestTarget(recordId) {
  const quest = state.pages.candidateDashboard.detail.campaignQuest;
  const normalizedRecordId = normalizeString(recordId);
  if (!normalizedRecordId) {
    return false;
  }
  const target = quest.targets.find((item) => item.recordId === normalizedRecordId);
  if (!target) {
    showToast("Campaign Quest target unavailable.");
    return false;
  }
  quest.selectedTargetId = target.recordId;
  scheduleRender();
  return true;
}

function stopCampaignQuestShift() {
  const quest = state.pages.candidateDashboard.detail.campaignQuest;
  quest.shiftActive = false;
  quest.locationStatus = quest.lastKnownLocation
    ? "Shift ended. Location retained for map context."
    : "Shift ended.";
  showToast("Campaign Quest shift ended.");
  scheduleRender();
}

function requestCampaignQuestLocation({ startShift = false } = {}) {
  const quest = state.pages.candidateDashboard.detail.campaignQuest;
  if (!navigator.geolocation) {
    quest.locationPending = false;
    quest.locationStatus = "Browser location is unavailable.";
    if (startShift) {
      quest.shiftActive = false;
    }
    showToast("Browser location is unavailable.");
    scheduleRender();
    return false;
  }
  quest.locationPending = true;
  quest.locationStatus = startShift ? "Starting shift..." : "Checking location...";
  scheduleRender();
  navigator.geolocation.getCurrentPosition(
    (position) => {
      quest.locationPending = false;
      quest.lastKnownLocation = {
        lat: Number(position.coords.latitude),
        lng: Number(position.coords.longitude),
        accuracy: Number(position.coords.accuracy),
        capturedAt: new Date().toISOString(),
      };
      quest.locationStatus = campaignQuestLocationCopy(quest);
      if (startShift) {
        quest.shiftActive = true;
      }
      showToast(startShift ? "Campaign Quest shift started." : "Location updated.");
      scheduleRender();
    },
    () => {
      quest.locationPending = false;
      quest.locationStatus = "Location permission is blocked.";
      if (startShift) {
        quest.shiftActive = false;
      }
      showToast("Location permission is blocked.");
      scheduleRender();
    },
    {
      enableHighAccuracy: true,
      timeout: 10000,
      maximumAge: 30000,
    },
  );
  return true;
}

function findCampaignQuestTarget(recordId) {
  const normalizedRecordId = normalizeString(recordId);
  if (!normalizedRecordId) {
    return null;
  }
  return (
    state.pages.candidateDashboard.detail.campaignQuest.targets.find(
      (target) => target.recordId === normalizedRecordId,
    ) || null
  );
}

function campaignQuestOutcomesFor(config, outreachType) {
  const normalizedOutreach = normalizeString(outreachType);
  return (config?.outcomeFields || []).filter(
    (field) =>
      field.enabled !== false &&
      (!field.outreachTypes.length ||
        field.outreachTypes.includes(normalizedOutreach)),
  );
}

async function startCampaignQuestTarget(recordId, outreachType = "") {
  const candidateId = currentCandidateDashboardId();
  const target = findCampaignQuestTarget(recordId);
  if (!candidateId || !target) {
    showToast("Campaign Quest target unavailable.");
    return;
  }
  const quest = state.pages.candidateDashboard.detail.campaignQuest;
  const actionKey = `start:${target.recordId}`;
  quest.actionPendingKey = actionKey;
  quest.error = "";
  scheduleRender();
  try {
    const query = new URLSearchParams({ candidateId });
    await fetchJson(
      `/api/candidate-dashboard/campaign-quest/targets/${encodeURIComponent(target.recordId)}/start?${query.toString()}`,
      {
        auth: true,
        method: "POST",
        body: {
          outreachType:
            normalizeString(outreachType) ||
            target.availableOutreachTypes[0] ||
            "doorKnock",
        },
      },
    );
    showToast("Campaign Quest target claimed.");
    await loadCandidateDashboardCampaignQuest(candidateId, { refresh: true });
  } catch (error) {
    quest.error = settingsErrorMessage(error, "Target could not be claimed.");
    showToast(quest.error);
  } finally {
    if (quest.actionPendingKey === actionKey) {
      quest.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function completeCampaignQuestTarget({
  recordId,
  outreachType = "",
  outcomeType = "",
  note = "",
} = {}) {
  const candidateId = currentCandidateDashboardId();
  const target = findCampaignQuestTarget(recordId);
  if (!candidateId || !target) {
    showToast("Campaign Quest target unavailable.");
    return;
  }
  const quest = state.pages.candidateDashboard.detail.campaignQuest;
  const config = quest.config || normalizeCampaignQuestConfig({});
  const normalizedOutreach =
    normalizeString(outreachType) || target.availableOutreachTypes[0] || "doorKnock";
  const outcomes = campaignQuestOutcomesFor(config, normalizedOutreach);
  const selectedOutcome =
    outcomes.find((item) => item.id === normalizeString(outcomeType)) ||
    outcomes[0] ||
    null;
  if (!selectedOutcome) {
    showToast("Choose an outcome first.");
    return;
  }
  const actionKey = `complete:${target.recordId}`;
  quest.actionPendingKey = actionKey;
  quest.error = "";
  scheduleRender();
  try {
    const query = new URLSearchParams({ candidateId });
    const payload = await fetchJson(
      `/api/candidate-dashboard/campaign-quest/targets/${encodeURIComponent(target.recordId)}/complete?${query.toString()}`,
      {
        auth: true,
        method: "POST",
        body: {
          outreachType: normalizedOutreach,
          outcomeType: selectedOutcome.id,
          latitude: target.lat,
          longitude: target.lng,
          clientEventId:
            window.crypto?.randomUUID?.() ||
            `web-${Date.now()}-${Math.random().toString(16).slice(2)}`,
          ...(Object.keys(selectedOutcome.contactOutcome || {}).length
            ? { contactOutcome: selectedOutcome.contactOutcome }
            : {}),
          ...(normalizeString(note) ? { note: normalizeString(note) } : {}),
        },
      },
    );
    const completion = normalizeCampaignQuestCompletion(payload);
    quest.lastCompletion = completion;
    quest.progress = completion.progress;
    showToast(`Target complete. +${formatCount(completion.xp.totalAwarded)} XP.`);
    await loadCandidateDashboardCampaignQuest(candidateId, { refresh: true });
  } catch (error) {
    quest.error = settingsErrorMessage(error, "Target could not be completed.");
    showToast(quest.error);
  } finally {
    if (quest.actionPendingKey === actionKey) {
      quest.actionPendingKey = "";
    }
    scheduleRender();
  }
}

function candidateDonationHasConnectedAccount(status = null) {
  return Boolean(
    normalizeString(status?.readiness?.stripeConnectedAccountId) ||
      normalizeString(status?.settings?.stripeConnectedAccountId) ||
      normalizeString(status?.profile?.stripeRecipientAccountId),
  );
}

function candidateDonationCanUseDashboard(status = null) {
  if (!candidateDonationHasConnectedAccount(status)) {
    return false;
  }
  return (
    status?.readiness?.readyToEnable === true ||
    status?.settings?.donationsEnabled === true
  );
}

function candidateFinanceSection(status = null, key = "") {
  const normalizedKey = normalizeString(key);
  return (
    (status?.sections || []).find((section) => section.key === normalizedKey) ||
    {
      key: normalizedKey,
      title: humanizeLabel(normalizedKey),
      fields: [],
      isComplete: false,
    }
  );
}

function candidateFinanceSectionComplete(status = null, key = "") {
  return candidateFinanceSection(status, key).isComplete === true;
}

function candidateDonationPayoutBank(status = null) {
  const payoutBank = status?.profile?.payoutBank;
  return payoutBank && typeof payoutBank === "object" ? payoutBank : {};
}

function candidateDonationConnectedStripeAccountId(status = null, session = null) {
  return normalizeString(
    session?.stripeConnectedAccountId ||
      status?.readiness?.stripeConnectedAccountId ||
      status?.settings?.stripeConnectedAccountId ||
      status?.profile?.stripeRecipientAccountId ||
      status?.profile?.stripeConnectedAccountId,
  );
}

function candidateDonationPayoutBillingDetails(status = null) {
  const representative = status?.profile?.representativeProfile || {};
  const committee = status?.profile?.committeeProfile || {};
  const representativeName =
    normalizeString(representative.fullName) ||
    [representative.firstName, representative.lastName]
      .map((value) => normalizeString(value))
      .filter(Boolean)
      .join(" ");
  const name =
    representativeName ||
    normalizeString(committee.legalName || committee.committeeName) ||
    "Campaign representative";
  const email =
    normalizeString(representative.email) || normalizeString(committee.email);
  const sourceAddress =
    representative.address && typeof representative.address === "object"
      ? representative.address
      : committee.address && typeof committee.address === "object"
        ? committee.address
        : {};
  const address = {
    line1: normalizeString(sourceAddress.line1 || sourceAddress.addressLine1),
    line2: normalizeString(sourceAddress.line2 || sourceAddress.addressLine2),
    city: normalizeString(sourceAddress.city),
    state: normalizeString(sourceAddress.state),
    postal_code: normalizeString(
      sourceAddress.postalCode || sourceAddress.postal_code || sourceAddress.zip,
    ),
    country: normalizeString(sourceAddress.country) || "US",
  };
  return {
    name,
    ...(email ? { email } : {}),
    ...(Object.values(address).some((value) => normalizeString(value))
      ? { address }
      : {}),
  };
}

function candidateDonationHasLinkedPayoutBank(status = null) {
  const payoutBank = candidateDonationPayoutBank(status);
  const payoutStatus = normalizeString(payoutBank.status).toLowerCase();
  return Boolean(
    payoutStatus === "linked" ||
      normalizeString(payoutBank.stripeExternalAccountId) ||
      (normalizeString(payoutBank.bankName) && normalizeString(payoutBank.last4)),
  );
}

function candidateDonationPayoutStatusTone(status = null) {
  const payoutBank = candidateDonationPayoutBank(status);
  const payoutStatus = normalizeString(payoutBank.status).toLowerCase();
  if (
    [
      "pending",
      "pending_verification",
      "processing",
      "requires_microdeposits",
      "verification_pending",
    ].includes(payoutStatus)
  ) {
    return "pending";
  }
  if (["failed", "rejected", "errored", "disabled"].includes(payoutStatus)) {
    return "bad";
  }
  if (candidateDonationHasLinkedPayoutBank(status)) return "good";
  return "pending";
}

function candidateDonationPayoutStatusCopy(status = null) {
  const payoutBank = candidateDonationPayoutBank(status);
  const payoutStatus = normalizeString(payoutBank.status).toLowerCase();
  if (
    [
      "pending",
      "pending_verification",
      "processing",
      "requires_microdeposits",
      "verification_pending",
    ].includes(payoutStatus)
  ) {
    return "Stripe has bank details and is still verifying the payout account.";
  }
  if (["failed", "rejected", "errored", "disabled"].includes(payoutStatus)) {
    return "Stripe could not use this payout account. Link a different bank or complete remediation.";
  }
  if (candidateDonationHasLinkedPayoutBank(status)) {
    return "Payout bank is linked and ready for campaign disbursements.";
  }
  if (
    !candidateFinanceSectionComplete(status, "committee") ||
    !candidateFinanceSectionComplete(status, "representative")
  ) {
    return "Committee and representative details are required before bank linking.";
  }
  return "Link a payout bank account to complete campaign finance setup.";
}

function candidateDonationReadinessReason(status = null) {
  const readinessReason = normalizeString(status?.readiness?.autoDisabledReason);
  const settingsReason = normalizeString(status?.settings?.autoDisabledReason);
  if (readinessReason) return readinessReason;
  if (settingsReason) return settingsReason;
  if (status?.ruleFound === false) return "donation_rule_missing";
  if (!candidateDonationHasConnectedAccount(status)) return "connect_account_missing";
  if (status?.readiness?.readyToEnable !== true) return "candidate_not_ready";
  return "";
}

function candidateDonationReadinessCopy(reason = "", status = null) {
  const normalizedReason = normalizeString(reason).toLowerCase();
  const readable = humanizeLabel(reason || "setup_required");
  const copy = {
    account_rejected:
      "The connected payout account needs review before this campaign can receive donations.",
    candidate_donations_not_enabled:
      "Donation CTAs are currently off. Turn them on after setup is ready.",
    candidate_not_ready: status?.isFinanceFlow
      ? "Complete committee details, representative verification, payout account, and attestation before donations go live."
      : "Finish hosted Stripe onboarding before donations go live.",
    connect_account_missing: status?.isFinanceFlow
      ? "Start finance setup to create the campaign recipient account and unlock payout steps."
      : "Connect the campaign Stripe account before donation controls can go live.",
    donation_rule_missing:
      "No campaign-finance donation rule is available for this race yet.",
    payouts_disabled:
      "Payouts are not active yet. Finish the payout account step or complete Stripe remediation.",
    requirements_due:
      "Stripe still needs campaign verification details before payouts can activate.",
    setup_required: status?.isFinanceFlow
      ? "Complete finance setup before donation reporting and export tools are available."
      : "Complete hosted setup before donation reporting and export tools are available.",
  };
  return copy[normalizedReason] || `${readable} is blocking donations right now.`;
}

function candidateDonationSetupActionLabel(status = null) {
  if (candidateDonationCanUseDashboard(status)) {
    return status?.isFinanceFlow ? "Manage payout setup" : "Manage Stripe account";
  }
  return status?.isFinanceFlow ? "Continue finance setup" : "Continue Stripe setup";
}

function candidateDonationFinanceProgress(status = null) {
  if (status?.isFinanceFlow) {
    const total = CANDIDATE_FINANCE_SECTION_KEYS.length;
    const complete = CANDIDATE_FINANCE_SECTION_KEYS.filter((key) =>
      candidateFinanceSectionComplete(status, key),
    ).length;
    return { complete, total };
  }
  return {
    complete: candidateDonationHasConnectedAccount(status) ? 1 : 0,
    total: 1,
  };
}

async function collectCandidateDonationPayoutBankAccount(session, status = null) {
  const clientSecret = normalizeString(session?.clientSecret);
  if (!clientSecret) {
    throw new Error("Stripe bank-link client secret unavailable.");
  }
  const publishableKey = getStripePublishableKey();
  if (!publishableKey) {
    throw new Error("Stripe bank linking is not configured for this website.");
  }
  const stripeFactory = await loadStripeJs();
  const stripeAccount = candidateDonationConnectedStripeAccountId(status, session);
  const stripe = stripeFactory(
    publishableKey,
    stripeAccount ? { stripeAccount } : undefined,
  );
  const sessionId = normalizeString(session?.sessionId);
  if (sessionId.startsWith("fcsess_")) {
    if (typeof stripe.collectFinancialConnectionsAccounts !== "function") {
      throw new Error("Stripe Financial Connections is unavailable in this browser.");
    }
    const result = await stripe.collectFinancialConnectionsAccounts({
      clientSecret,
    });
    if (result?.error) {
      throw new Error(
        normalizeString(result.error.message) || "Bank account collection failed.",
      );
    }
    const accountsPayload = result?.financialConnectionsSession?.accounts;
    const linkedAccounts = Array.isArray(accountsPayload)
      ? accountsPayload
      : Array.isArray(accountsPayload?.data)
        ? accountsPayload.data
        : [];
    if (!linkedAccounts.length) {
      throw new Error("Bank linking was canceled before an account was selected.");
    }
    return result.financialConnectionsSession;
  }
  if (typeof stripe.collectBankAccountForSetup !== "function") {
    throw new Error("Stripe bank account setup is unavailable in this browser.");
  }
  const result = await stripe.collectBankAccountForSetup({
    clientSecret,
    params: {
      payment_method_type: "us_bank_account",
      payment_method_data: {
        billing_details: candidateDonationPayoutBillingDetails(status),
      },
    },
  });
  if (result?.error) {
    throw new Error(
      normalizeString(result.error.message) || "Bank account collection failed.",
    );
  }
  let setupIntent = result?.setupIntent || null;
  if (
    normalizeString(setupIntent?.status).toLowerCase() ===
    "requires_confirmation"
  ) {
    if (typeof stripe.confirmUsBankAccountSetup !== "function") {
      throw new Error("Stripe bank account confirmation is unavailable.");
    }
    const confirmation = await stripe.confirmUsBankAccountSetup(clientSecret);
    if (confirmation?.error) {
      throw new Error(
        normalizeString(confirmation.error.message) ||
          "Bank account confirmation failed.",
      );
    }
    setupIntent = confirmation?.setupIntent || setupIntent;
  }
  const setupStatus = normalizeString(setupIntent?.status).toLowerCase();
  if (!setupIntent || setupStatus === "requires_payment_method") {
    throw new Error("Bank linking was canceled before an account was selected.");
  }
  if (setupStatus === "canceled") {
    throw new Error("Bank linking was canceled.");
  }
  return setupIntent;
}

async function collectAndAttachCandidateDonationPayoutSession(session) {
  const donations = state.pages.candidateDashboard.detail.donations;
  const normalizedSession = normalizeCandidateDonationSession(session);
  donations.pendingPayoutSession = normalizedSession;
  if (!normalizedSession.clientSecret) {
    showToast("Stripe bank-link client secret unavailable.");
    return;
  }
  donations.actionPendingKey = "payout-collect";
  donations.error = "";
  scheduleRender();
  try {
    const collectionResult = await collectCandidateDonationPayoutBankAccount(
      normalizedSession,
      donations.status,
    );
    donations.pendingPayoutSession = {
      ...normalizedSession,
      clientCollectionError: "",
      setupIntentStatus: normalizeString(collectionResult?.status),
    };
    showToast("Bank details collected. Checking payout status...");
    await attachCandidateDonationPayoutSession();
  } catch (error) {
    const message = settingsErrorMessage(
      error,
      "Bank account collection could not be completed.",
    );
    donations.pendingPayoutSession = {
      ...normalizedSession,
      clientCollectionError: message,
    };
    donations.error = message;
    showToast(message);
  } finally {
    if (donations.actionPendingKey === "payout-collect") {
      donations.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function resumeCandidateDonationPayoutCollection() {
  const donations = state.pages.candidateDashboard.detail.donations;
  const session = donations.pendingPayoutSession;
  if (!session?.clientSecret) {
    showToast("No browser bank-link session is waiting.");
    return;
  }
  if (!hasStripeBrowserConfig()) {
    showToast("Stripe bank linking is not configured for this website.");
    return;
  }
  await collectAndAttachCandidateDonationPayoutSession(session);
}

async function fetchCandidateDonationStatus(candidateId) {
  const query = new URLSearchParams({ candidateId });
  try {
    const payload = await fetchJson(
      `/api/candidate-dashboard/donations/finance/status?${query.toString()}`,
      { auth: true },
    );
    return normalizeCandidateDonationStatusPayload(payload, {
      financeFlow: true,
    });
  } catch (error) {
    const code = normalizeString(error?.payload?.error || error?.message);
    if (
      Number(error?.status) !== 409 ||
      ![
        "candidate_finance_api_disabled",
        "candidate_finance_payouts_disabled",
      ].includes(code)
    ) {
      throw error;
    }
  }

  const payload = await fetchJson(
    `/api/candidate-dashboard/donations/connect/status?${query.toString()}`,
    { auth: true },
  );
  return normalizeCandidateDonationStatusPayload(payload, {
    financeFlow: false,
  });
}

function buildCandidateDonationTransactionsQuery(
  candidateId,
  resource,
  { cursor = "" } = {},
) {
  const filters = resource.filters || {};
  const query = new URLSearchParams({
    candidateId,
    limit: "50",
    sort: normalizeString(filters.sort).toLowerCase() === "asc" ? "asc" : "desc",
  });
  const status = normalizeString(filters.status);
  const paymentMethod = normalizeString(filters.paymentMethod);
  const search = normalizeString(filters.search);
  if (status) query.set("status", status);
  if (paymentMethod) query.set("paymentMethod", paymentMethod);
  if (search) query.set("search", search);
  if (normalizeString(cursor)) query.set("cursor", normalizeString(cursor));
  return query;
}

async function loadCandidateDonationTransactions(
  candidateId,
  { refresh = false, append = false } = {},
) {
  const normalizedCandidateId = decodeRouteSegment(candidateId);
  if (!normalizedCandidateId) {
    return;
  }
  const donations = state.pages.candidateDashboard.detail.donations;
  if (append ? donations.loadingMore : donations.transactionsLoading) {
    return;
  }
  if (append && !donations.nextCursor) {
    return;
  }
  if (refresh && !append) {
    donations.transactions = [];
    donations.nextCursor = null;
    donations.transactionsError = "";
  }
  if (append) {
    donations.loadingMore = true;
  } else {
    donations.transactionsLoading = true;
  }
  scheduleRender();
  try {
    const query = buildCandidateDonationTransactionsQuery(
      normalizedCandidateId,
      donations,
      { cursor: append ? donations.nextCursor : "" },
    );
    const payload = await fetchJson(
      `/api/candidate-dashboard/donations/transactions?${query.toString()}`,
      { auth: true },
    );
    const page = normalizeCandidateDonationTransactionsPage(payload);
    donations.transactions = append
      ? donations.transactions.concat(page.items)
      : page.items;
    donations.nextCursor = page.nextCursor;
    donations.transactionsError = "";
  } catch (error) {
    donations.transactionsError = settingsErrorMessage(
      error,
      append
        ? "More donations could not be loaded."
        : "Donation transactions could not be loaded.",
    );
    showToast(donations.transactionsError);
  } finally {
    donations.transactionsLoading = false;
    donations.loadingMore = false;
    scheduleRender();
  }
}

async function loadCandidateDashboardDonations(
  candidateId,
  { refresh = false } = {},
) {
  const normalizedCandidateId = decodeRouteSegment(candidateId);
  if (!normalizedCandidateId) {
    return;
  }
  const donations = state.pages.candidateDashboard.detail.donations;
  if (donations.loading) {
    return;
  }
  if (donations.loaded && !refresh) {
    return;
  }
  if (refresh) {
    donations.loaded = false;
    donations.error = "";
  }
  donations.loading = true;
  scheduleRender();
  try {
    const status = await fetchCandidateDonationStatus(normalizedCandidateId);
    donations.status = status;
    donations.financeStatus = status.isFinanceFlow ? status : null;
    donations.loaded = true;
    donations.error = "";
    if (candidateDonationCanUseDashboard(status)) {
      await loadCandidateDonationTransactions(normalizedCandidateId, {
        refresh: true,
      });
    } else {
      donations.transactions = [];
      donations.nextCursor = null;
      donations.transactionsError = "";
    }
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Donation readiness could not be loaded.",
    );
  } finally {
    donations.loading = false;
    scheduleRender();
  }
}

async function refreshCandidateDashboardDonations() {
  const candidateId = currentCandidateDashboardId();
  if (!candidateId) {
    return;
  }
  await loadCandidateDashboardDonations(candidateId, { refresh: true });
}

async function applyCandidateDonationFilters(formData) {
  const candidateId = currentCandidateDashboardId();
  if (!candidateId) {
    return false;
  }
  const donations = state.pages.candidateDashboard.detail.donations;
  donations.filters = {
    status: normalizeString(formData.get("status")),
    paymentMethod: normalizeString(formData.get("paymentMethod")),
    search: normalizeString(formData.get("search")),
    sort: normalizeString(formData.get("sort")).toLowerCase() === "asc" ? "asc" : "desc",
  };
  await loadCandidateDonationTransactions(candidateId, { refresh: true });
  return true;
}

async function saveCandidateDonationSettings(formData) {
  const candidateId = currentCandidateDashboardId();
  if (!candidateId) {
    showToast("Campaign unavailable.");
    return false;
  }
  const donations = state.pages.candidateDashboard.detail.donations;
  donations.actionPendingKey = "settings";
  donations.error = "";
  scheduleRender();
  try {
    await fetchJson("/api/candidate-dashboard/donations/settings", {
      auth: true,
      method: "POST",
      body: {
        candidateId,
        donationsEnabled: formData.has("donationsEnabled"),
        defaultDonationCtaMode:
          normalizeCandidateDonationCtaMode(
            formData.get("defaultDonationCtaMode"),
          ) || "show",
      },
    });
    showToast("Donation settings saved.");
    await loadCandidateDashboardDonations(candidateId, { refresh: true });
    return true;
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Donation settings could not be saved.",
    );
    showToast(donations.error);
    return false;
  } finally {
    if (donations.actionPendingKey === "settings") {
      donations.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function bootstrapCandidateDonationFinance() {
  const candidateId = currentCandidateDashboardId();
  if (!candidateId) {
    return;
  }
  const donations = state.pages.candidateDashboard.detail.donations;
  donations.actionPendingKey = "bootstrap";
  donations.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      "/api/candidate-dashboard/donations/finance/bootstrap",
      {
        auth: true,
        method: "POST",
        body: { candidateId },
      },
    );
    const status = normalizeCandidateDonationStatusPayload(payload, {
      financeFlow: true,
    });
    donations.status = status;
    donations.financeStatus = status;
    donations.loaded = true;
    showToast("Finance setup refreshed.");
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Finance setup could not be started.",
    );
    showToast(donations.error);
  } finally {
    if (donations.actionPendingKey === "bootstrap") {
      donations.actionPendingKey = "";
    }
    scheduleRender();
  }
}

function candidateDonationDigitsOnly(value) {
  return normalizeString(value).replace(/\D+/g, "");
}

async function saveCandidateDonationFinanceSection(formData, section) {
  const candidateId = currentCandidateDashboardId();
  const normalizedSection = normalizeString(section).toLowerCase();
  if (!candidateId || !["committee", "representative"].includes(normalizedSection)) {
    showToast("Finance section unavailable.");
    return false;
  }
  const donations = state.pages.candidateDashboard.detail.donations;
  donations.actionPendingKey = `finance:${normalizedSection}`;
  donations.error = "";
  scheduleRender();
  const body =
    normalizedSection === "committee"
      ? {
          section: "committee",
          candidateId,
          legalName: normalizeString(formData.get("legalName")),
          email: normalizeString(formData.get("email")),
          phone: normalizeString(formData.get("phone")),
          website: normalizeString(formData.get("website")),
          ein: candidateDonationDigitsOnly(formData.get("ein")),
          fecCandidateId: normalizeString(formData.get("fecCandidateId")),
          fecCommitteeId: normalizeString(formData.get("fecCommitteeId")),
          addressLine1: normalizeString(formData.get("addressLine1")),
          addressLine2: normalizeString(formData.get("addressLine2")),
          city: normalizeString(formData.get("city")),
          state: normalizeString(formData.get("state")).toUpperCase(),
          postalCode: normalizeString(formData.get("postalCode")),
        }
      : {
          section: "representative",
          candidateId,
          firstName: normalizeString(formData.get("firstName")),
          lastName: normalizeString(formData.get("lastName")),
          email: normalizeString(formData.get("email")),
          phone: normalizeString(formData.get("phone")),
          role: normalizeString(formData.get("role")) || "candidate",
          dobMonth: normalizeString(formData.get("dobMonth")),
          dobDay: normalizeString(formData.get("dobDay")),
          dobYear: normalizeString(formData.get("dobYear")),
          ssnLast4: candidateDonationDigitsOnly(formData.get("ssnLast4")),
          addressLine1: normalizeString(formData.get("addressLine1")),
          addressLine2: normalizeString(formData.get("addressLine2")),
          city: normalizeString(formData.get("city")),
          state: normalizeString(formData.get("state")).toUpperCase(),
          postalCode: normalizeString(formData.get("postalCode")),
        };
  try {
    const payload = await fetchJson(
      "/api/candidate-dashboard/donations/finance/update",
      {
        auth: true,
        method: "POST",
        body,
      },
    );
    const status = normalizeCandidateDonationStatusPayload(payload, {
      financeFlow: true,
    });
    donations.status = status;
    donations.financeStatus = status;
    donations.loaded = true;
    showToast(
      normalizedSection === "committee"
        ? "Committee details saved."
        : "Representative details saved.",
    );
    return true;
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      normalizedSection === "committee"
        ? "Committee details could not be saved."
        : "Representative details could not be saved.",
    );
    showToast(donations.error);
    return false;
  } finally {
    donations.actionPendingKey = "";
    scheduleRender();
  }
}

async function startCandidateDonationPayoutSession() {
  const candidateId = currentCandidateDashboardId();
  const donations = state.pages.candidateDashboard.detail.donations;
  if (!candidateId) {
    return;
  }
  if (
    !candidateFinanceSectionComplete(donations.status, "committee") ||
    !candidateFinanceSectionComplete(donations.status, "representative")
  ) {
    showToast("Save committee and representative details before linking payouts.");
    return;
  }
  donations.actionPendingKey = "payout";
  donations.error = "";
  scheduleRender();
  try {
    const session = normalizeCandidateDonationSession(
      await fetchJson(
        "/api/candidate-dashboard/donations/finance/payout-bank/session",
        {
          auth: true,
          method: "POST",
          body: { candidateId },
        },
      ),
    );
    donations.pendingPayoutSession = session;
    donations.confirmingPayoutBankRemoval = false;
    if (session.url) {
      window.open(session.url, "_blank", "noopener,noreferrer");
      showToast("Payout bank link opened. Refresh status after completion.");
    } else if (session.clientSecret) {
      if (!hasStripeBrowserConfig()) {
        showToast(
          "Bank-link session is ready, but this website needs Stripe publishable-key config.",
        );
      } else {
        showToast("Secure Stripe bank link opened.");
        await collectAndAttachCandidateDonationPayoutSession(session);
      }
    } else {
      showToast("Stripe bank linking is unavailable on web for this session.");
    }
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Payout bank link could not be started.",
    );
    showToast(donations.error);
  } finally {
    if (donations.actionPendingKey === "payout") {
      donations.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function attachCandidateDonationPayoutSession() {
  const candidateId = currentCandidateDashboardId();
  const donations = state.pages.candidateDashboard.detail.donations;
  const sessionId = normalizeString(donations.pendingPayoutSession?.sessionId);
  if (!candidateId || !sessionId) {
    showToast("No payout session is waiting to be attached.");
    return;
  }
  donations.actionPendingKey = "payout-attach";
  donations.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      "/api/candidate-dashboard/donations/finance/payout-bank/attach",
      {
        auth: true,
        method: "POST",
        body: { candidateId, sessionId },
      },
    );
    const status = normalizeCandidateDonationStatusPayload(payload, {
      financeFlow: true,
    });
    donations.status = status;
    donations.financeStatus = status;
    donations.pendingPayoutSession = null;
    donations.confirmingPayoutBankRemoval = false;
    showToast("Payout bank status updated.");
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Payout bank could not be attached yet.",
    );
    showToast(donations.error);
  } finally {
    donations.actionPendingKey = "";
    scheduleRender();
  }
}

async function removeCandidateDonationPayoutBank() {
  const candidateId = currentCandidateDashboardId();
  const donations = state.pages.candidateDashboard.detail.donations;
  if (!candidateId) {
    return;
  }
  if (!candidateDonationHasLinkedPayoutBank(donations.status)) {
    donations.confirmingPayoutBankRemoval = false;
    showToast("No payout bank is linked.");
    scheduleRender();
    return;
  }
  donations.actionPendingKey = "payout-remove";
  donations.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      "/api/candidate-dashboard/donations/finance/payout-bank/remove",
      {
        auth: true,
        method: "POST",
        body: { candidateId },
      },
    );
    const status = normalizeCandidateDonationStatusPayload(payload, {
      financeFlow: true,
    });
    donations.status = status;
    donations.financeStatus = status;
    donations.pendingPayoutSession = null;
    donations.confirmingPayoutBankRemoval = false;
    donations.loaded = true;
    showToast("Linked payout bank removed.");
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Payout bank could not be removed.",
    );
    showToast(donations.error);
  } finally {
    if (donations.actionPendingKey === "payout-remove") {
      donations.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function submitCandidateDonationFinanceAttestation(formData) {
  const candidateId = currentCandidateDashboardId();
  const donations = state.pages.candidateDashboard.detail.donations;
  if (!candidateId) {
    return false;
  }
  if (!formData.has("accept")) {
    showToast("Accept the finance attestation before submitting.");
    return false;
  }
  donations.actionPendingKey = "attestation";
  donations.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      "/api/candidate-dashboard/donations/finance/submit",
      {
        auth: true,
        method: "POST",
        body: { candidateId, accept: true },
      },
    );
    const status = normalizeCandidateDonationStatusPayload(payload, {
      financeFlow: true,
    });
    donations.status = status;
    donations.financeStatus = status;
    showToast(
      status.readiness.readyToEnable
        ? "Finance setup is ready. You can enable donations."
        : "Finance setup submitted. Refresh after Stripe finishes activation.",
    );
    return true;
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Finance setup could not be submitted.",
    );
    showToast(donations.error);
    return false;
  } finally {
    donations.actionPendingKey = "";
    scheduleRender();
  }
}

async function openCandidateDonationHostedSetup() {
  const candidateId = currentCandidateDashboardId();
  const donations = state.pages.candidateDashboard.detail.donations;
  if (!candidateId) {
    return;
  }
  const status = donations.status;
  donations.actionPendingKey = "hosted-setup";
  donations.error = "";
  scheduleRender();
  try {
    let session = null;
    if (status?.isFinanceFlow) {
      const needsRemediation =
        status?.remediationState?.requiresStripeRemediation === true;
      if (!needsRemediation) {
        await bootstrapCandidateDonationFinance();
        return;
      }
      session = normalizeCandidateDonationSession(
        await fetchJson(
          "/api/candidate-dashboard/donations/finance/remediation-link",
          {
            auth: true,
            method: "POST",
            body: { candidateId },
          },
        ),
      );
    } else {
      session = normalizeCandidateDonationSession(
        await fetchJson(
          "/api/candidate-dashboard/donations/connect/onboarding-link",
          {
            auth: true,
            method: "POST",
            body: { candidateId },
          },
        ),
      );
    }
    if (!session?.url) {
      throw new Error("Stripe hosted URL unavailable.");
    }
    window.open(session.url, "_blank", "noopener,noreferrer");
    showToast("Stripe setup opened. Refresh after returning.");
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Stripe setup could not be opened.",
    );
    showToast(donations.error);
  } finally {
    if (donations.actionPendingKey === "hosted-setup") {
      donations.actionPendingKey = "";
    }
    scheduleRender();
  }
}

function candidateCanReceiveDonations(candidate = {}) {
  return Boolean(
    normalizeString(candidate.candidateId) &&
      candidate.donationsAvailable === true &&
      candidate.donationsEnabled === true,
  );
}

function currentCandidateDonationFlow() {
  const detail = state.pages.candidates.detail;
  if (!detail.donationFlow) {
    detail.donationFlow = createCandidateDonationFlowState();
  }
  return detail.donationFlow;
}

function candidateDonationReadableStep(step = "") {
  const key = normalizeString(step).toLowerCase();
  const copy = {
    full_legal_name: "Enter your full legal name.",
    missing_full_legal_name: "Enter your full legal name.",
    residential_address: "Enter your residential address.",
    missing_residential_address: "Enter your residential address.",
    residential_address_no_po_box: "Residential address cannot be a P.O. Box.",
    po_box_not_allowed: "Residential address cannot be a P.O. Box.",
    occupation: "Enter your occupation.",
    missing_occupation: "Enter your occupation.",
    employer: "Enter your employer.",
    missing_employer: "Enter your employer.",
    identity_verification: "Complete Stripe identity verification.",
    identity_not_verified: "Complete Stripe identity verification.",
    identity_binding:
      "Re-run identity verification so the verified identity can be bound to this account.",
    identity_binding_missing:
      "Re-run identity verification so the verified identity can be bound to this account.",
    identity_blocked:
      "This verified identity is already tied to another Polis account.",
    duplicate_identity_bound:
      "This verified identity is already tied to another Polis account.",
    bank_link: "Link a U.S. bank account before donating.",
    bank_not_linked: "Link a U.S. bank account before donating.",
    candidate_donations_not_enabled: "This candidate has not enabled donations.",
    candidate_not_ready_to_receive:
      "This candidate is not currently ready to receive donations.",
    candidate_connect_not_ready:
      "This candidate is not currently ready to receive donations.",
    federal_only_lockout:
      "Donations are currently available for federal races only.",
    donation_rule_missing:
      "Donation rules are not yet available for this race.",
    amount_exceeds_remaining_limit:
      "That amount exceeds your remaining legal contribution limit.",
    cert_us_citizen_or_lpr:
      "Accept the U.S. citizen or lawful permanent resident attestation.",
    missing_cert_us_citizen_or_lpr:
      "Accept the U.S. citizen or lawful permanent resident attestation.",
    cert_own_funds: "Accept the own-funds attestation.",
    missing_cert_own_funds: "Accept the own-funds attestation.",
    cert_campaign_attribution:
      "Accept the campaign attribution attestation.",
    missing_cert_campaign_attribution:
      "Accept the campaign attribution attestation.",
  };
  return copy[key] || humanizeLabel(key || "donation requirement");
}

function candidateDonationFlowPrimaryEligibilityMessage(eligibility = null) {
  const reason =
    eligibility?.reasons?.[0] ||
    eligibility?.missingSteps?.[0] ||
    "donation requirement";
  return candidateDonationReadableStep(reason);
}

function candidateDonationErrorMessage(error, fallback) {
  const details =
    error?.payload?.details && typeof error.payload.details === "object"
      ? error.payload.details
      : error?.payload && typeof error.payload === "object"
        ? error.payload
        : {};
  const reasons = Array.isArray(details.reasons)
    ? details.reasons
    : Array.isArray(error?.payload?.reasons)
      ? error.payload.reasons
      : [];
  const firstReason = reasons.map(normalizeString).find(Boolean);
  if (firstReason) {
    return candidateDonationReadableStep(firstReason);
  }
  const errorCode =
    normalizeString(error?.payload?.error) || normalizeString(error?.message);
  if (errorCode && errorCode !== "request_failed") {
    return candidateDonationReadableStep(errorCode);
  }
  return fallback;
}

function candidateDonationFlowIdentityLocked(flow = null) {
  return (
    normalizeString(flow?.eligibility?.donorProfile?.identityStatus).toLowerCase() ===
    "verified"
  );
}

function candidateDonationFlowNeedsIdentity(flow = null) {
  const status = normalizeString(
    flow?.eligibility?.donorProfile?.identityStatus,
  ).toLowerCase();
  if (status !== "verified") {
    return true;
  }
  return (flow?.eligibility?.missingSteps || []).includes("identity_verification");
}

function candidateDonationFlowNeedsBankLink(flow = null) {
  const status = normalizeString(
    flow?.eligibility?.donorProfile?.bankLinkStatus,
  ).toLowerCase();
  if (status !== "linked") {
    return true;
  }
  return (flow?.eligibility?.missingSteps || []).includes("bank_link");
}

function candidateDonationFlowAmountCents(flow = null) {
  const raw = normalizeString(flow?.amount).replace(/[^0-9.]/g, "");
  if (!raw) {
    return null;
  }
  const value = Number.parseFloat(raw);
  return Number.isFinite(value) && value > 0 ? Math.round(value * 100) : null;
}

function candidateDonationFlowAddressSummary(flow = null) {
  const fields = flow?.fields || {};
  return [
    normalizeString(fields.addressLine1),
    normalizeString(fields.addressLine2),
    [
      normalizeString(fields.city),
      normalizeString(fields.state),
      normalizeString(fields.postalCode),
    ]
      .filter(Boolean)
      .join(" "),
  ]
    .filter(Boolean)
    .join(", ");
}

function seedCandidateDonationFlowFromEligibility(
  flow,
  eligibility,
  { initialLoad = false } = {},
) {
  if (!flow || !eligibility) {
    return;
  }
  flow.eligibility = eligibility;
  const donor = eligibility.donorProfile || {};
  const address = donor.residentialAddress || {};
  const identityLocked =
    normalizeString(donor.identityStatus).toLowerCase() === "verified";
  if (initialLoad && !normalizeString(flow.amount)) {
    const remaining = Number(eligibility.remainingAllowedCents) || 0;
    if (remaining > 0) {
      const suggestedDollars =
        remaining >= 2500 ? 25 : Math.max(1, Math.floor(remaining / 100));
      flow.amount = String(Math.min(suggestedDollars, 3500));
    }
  }
  if (!flow.fields.fullLegalName || identityLocked) {
    flow.fields.fullLegalName = donor.fullLegalName || "";
  }
  if (!flow.fields.addressLine1 || identityLocked) {
    flow.fields.addressLine1 = address.line1 || "";
  }
  if (!flow.fields.addressLine2 || identityLocked) {
    flow.fields.addressLine2 = address.line2 || "";
  }
  if (!flow.fields.city || identityLocked) {
    flow.fields.city = address.city || "";
  }
  if (!flow.fields.state || identityLocked) {
    flow.fields.state = normalizeString(address.state).toUpperCase();
  }
  if (!flow.fields.postalCode || identityLocked) {
    flow.fields.postalCode = address.postalCode || "";
  }
  if (!flow.fields.occupation) {
    flow.fields.occupation = donor.occupation || "";
  }
  if (!flow.fields.employer) {
    flow.fields.employer = donor.employer || "";
  }
  if (!flow.fields.jobTitle) {
    flow.fields.jobTitle = donor.jobTitle || "";
  }
  if (initialLoad) {
    flow.certifications.usCitizenOrLpr =
      donor.certifications?.usCitizenOrLpr === true;
    flow.certifications.ownFunds = donor.certifications?.ownFunds === true;
    flow.certifications.campaignAttribution =
      donor.certifications?.campaignAttribution === true;
  }
}

function candidateDonationReturnUrl(status = "") {
  try {
    const url = new URL(window.location.href);
    if (status) {
      url.searchParams.set("donation", normalizeString(status));
    }
    return url.href;
  } catch {
    return window.location.href;
  }
}

function candidateDonationFlowCompliancePayload(flow = null) {
  const fields = flow?.fields || {};
  return {
    fullLegalName: normalizeString(fields.fullLegalName),
    occupation: normalizeString(fields.occupation),
    employer: normalizeString(fields.employer),
    jobTitle: normalizeString(fields.jobTitle),
    residentialAddress: {
      line1: normalizeString(fields.addressLine1),
      line2: normalizeString(fields.addressLine2),
      city: normalizeString(fields.city),
      state: normalizeString(fields.state).toUpperCase(),
      postalCode: normalizeString(fields.postalCode),
      country: "US",
    },
  };
}

function candidateDonationFlowPayload(flow = null) {
  const amountCents = candidateDonationFlowAmountCents(flow);
  return {
    candidateId: normalizeString(flow?.candidateId),
    amountCents,
    ...candidateDonationFlowCompliancePayload(flow),
    certifications: {
      usCitizenOrLpr: flow?.certifications?.usCitizenOrLpr === true,
      ownFunds: flow?.certifications?.ownFunds === true,
      campaignAttribution:
        flow?.certifications?.campaignAttribution === true,
    },
  };
}

function setCandidateDonationFlowError(message) {
  const flow = currentCandidateDonationFlow();
  flow.error = normalizeString(message);
  flow.notice = "";
  showToast(flow.error);
}

async function loadCandidateDonationFlowEligibility({ initialLoad = false } = {}) {
  const flow = currentCandidateDonationFlow();
  const candidateId = normalizeString(flow.candidateId);
  if (!candidateId) {
    return;
  }
  flow.loading = true;
  flow.error = "";
  if (initialLoad) {
    flow.notice = "";
  }
  scheduleRender();
  try {
    const payload = await fetchJson(
      `/api/donations/eligibility?candidateId=${encodeURIComponent(candidateId)}`,
      { auth: true },
    );
    const eligibility = normalizeCandidateDonationEligibilityResult(payload);
    seedCandidateDonationFlowFromEligibility(flow, eligibility, { initialLoad });
    flow.error = "";
    flow.notice = initialLoad ? "" : "Donation checks refreshed.";
  } catch (error) {
    flow.error = candidateDonationErrorMessage(
      error,
      "Donation checks could not be loaded.",
    );
    showToast(flow.error);
  } finally {
    flow.loading = false;
    scheduleRender();
  }
}

function openCandidateDonationFlow(candidate = null) {
  const selectedCandidate = candidate || state.pages.candidates.detail.item;
  if (!selectedCandidate || !candidateCanReceiveDonations(selectedCandidate)) {
    const reason =
      normalizeString(selectedCandidate?.donationDisabledReason) ||
      "This candidate cannot receive donations right now.";
    showToast(reason);
    return;
  }
  if (!state.auth.session) {
    openAuthModal("route-protected", {
      title: `Donate to ${selectedCandidate.displayName}`,
      message:
        "Sign in to complete the same secure donation flow available in the Polis app.",
      targetPath: getCurrentPathWithQuery(),
    });
    return;
  }
  state.pages.candidates.detail.donationFlow = createCandidateDonationFlowState({
    open: true,
    step: "amount",
    candidateId: selectedCandidate.candidateId,
    candidateName: selectedCandidate.displayName,
    unavailableReason: normalizeString(selectedCandidate.donationDisabledReason),
  });
  scheduleRender();
  loadCandidateDonationFlowEligibility({ initialLoad: true }).catch(() => {});
}

function closeCandidateDonationFlow() {
  const flow = currentCandidateDonationFlow();
  flow.open = false;
  flow.error = "";
  flow.notice = "";
  flow.actionPendingKey = "";
  flow.submitting = false;
  scheduleRender();
}

function updateCandidateDonationFlowField(name, value) {
  const flow = currentCandidateDonationFlow();
  const fieldName = normalizeString(name);
  if (fieldName === "amount") {
    flow.amount = normalizeString(value);
    return;
  }
  if (Object.prototype.hasOwnProperty.call(flow.fields, fieldName)) {
    flow.fields[fieldName] =
      fieldName === "state"
        ? normalizeString(value).toUpperCase()
        : normalizeString(value);
  }
}

function updateCandidateDonationFlowCertification(name, checked) {
  const flow = currentCandidateDonationFlow();
  const fieldName = normalizeString(name);
  if (Object.prototype.hasOwnProperty.call(flow.certifications, fieldName)) {
    flow.certifications[fieldName] = checked === true;
  }
}

function advanceCandidateDonationAmount(formData = null) {
  const flow = currentCandidateDonationFlow();
  if (formData) {
    updateCandidateDonationFlowField("amount", formData.get("amount"));
  }
  const amountCents = candidateDonationFlowAmountCents(flow);
  if (!amountCents || amountCents <= 0) {
    setCandidateDonationFlowError("Enter a valid donation amount.");
    return false;
  }
  const remaining = flow.eligibility?.remainingAllowedCents;
  if (remaining !== null && remaining !== undefined && amountCents > remaining) {
    setCandidateDonationFlowError(
      "That amount exceeds your remaining legal contribution limit.",
    );
    return false;
  }
  flow.step = "profile";
  flow.error = "";
  flow.notice = "";
  scheduleRender();
  return true;
}

function advanceCandidateDonationProfile(formData = null) {
  const flow = currentCandidateDonationFlow();
  if (formData) {
    [
      "fullLegalName",
      "addressLine1",
      "addressLine2",
      "city",
      "state",
      "postalCode",
      "occupation",
      "employer",
      "jobTitle",
    ].forEach((fieldName) => {
      updateCandidateDonationFlowField(fieldName, formData.get(fieldName));
    });
  }
  const fields = flow.fields || {};
  if (!candidateDonationFlowIdentityLocked(flow)) {
    if (!normalizeString(fields.fullLegalName)) {
      setCandidateDonationFlowError("Enter your full legal name.");
      return false;
    }
    if (
      !normalizeString(fields.addressLine1) ||
      !normalizeString(fields.city) ||
      !normalizeString(fields.state) ||
      !normalizeString(fields.postalCode)
    ) {
      setCandidateDonationFlowError("Enter your residential address.");
      return false;
    }
  }
  if (!normalizeString(fields.occupation)) {
    setCandidateDonationFlowError("Enter your occupation.");
    return false;
  }
  if (!normalizeString(fields.employer)) {
    setCandidateDonationFlowError("Enter your employer.");
    return false;
  }
  flow.step = "acknowledgements";
  flow.error = "";
  flow.notice = "";
  scheduleRender();
  return true;
}

async function openCandidateDonationHostedDonorSession(kind = "") {
  const flow = currentCandidateDonationFlow();
  const normalizedKind = normalizeString(kind);
  const endpoint =
    normalizedKind === "bank"
      ? "/api/donations/bank-link/session"
      : "/api/donations/identity/session";
  flow.actionPendingKey = normalizedKind;
  flow.error = "";
  flow.notice = "";
  scheduleRender();
  try {
    const session = normalizeCandidateDonationSession(
      await fetchJson(endpoint, {
        auth: true,
        method: "POST",
        body: { returnUrl: candidateDonationReturnUrl(normalizedKind) },
      }),
    );
    if (!session.url) {
      throw new Error(
        normalizedKind === "bank"
          ? "Stripe bank-link URL unavailable."
          : "Stripe Identity URL unavailable.",
      );
    }
    const opened = window.open(session.url, "_blank", "noopener,noreferrer");
    if (!opened) {
      window.location.assign(session.url);
      return;
    }
    flow.notice =
      normalizedKind === "bank"
        ? "Complete bank link in the Stripe page, then refresh checks."
        : "Complete identity verification in the Stripe page, then refresh checks.";
    showToast(flow.notice);
  } catch (error) {
    flow.error = candidateDonationErrorMessage(
      error,
      normalizedKind === "bank"
        ? "Bank link could not be started."
        : "Identity verification could not be started.",
    );
    showToast(flow.error);
  } finally {
    flow.actionPendingKey = "";
    scheduleRender();
  }
}

async function preflightCandidateDonation(formData = null) {
  const flow = currentCandidateDonationFlow();
  if (formData) {
    ["usCitizenOrLpr", "ownFunds", "campaignAttribution"].forEach(
      (fieldName) => {
        updateCandidateDonationFlowCertification(
          fieldName,
          formData.has(fieldName),
        );
      },
    );
  }
  if (normalizeString(flow.unavailableReason)) {
    setCandidateDonationFlowError(flow.unavailableReason);
    return false;
  }
  if (candidateDonationFlowNeedsIdentity(flow) || candidateDonationFlowNeedsBankLink(flow)) {
    setCandidateDonationFlowError(
      "Complete identity verification and bank link first.",
    );
    return false;
  }
  if (
    !flow.certifications.usCitizenOrLpr ||
    !flow.certifications.ownFunds ||
    !flow.certifications.campaignAttribution
  ) {
    setCandidateDonationFlowError("Accept all required legal acknowledgements.");
    return false;
  }
  const amountCents = candidateDonationFlowAmountCents(flow);
  if (!amountCents || amountCents <= 0) {
    setCandidateDonationFlowError("Enter a valid donation amount.");
    return false;
  }
  flow.submitting = true;
  flow.error = "";
  flow.notice = "";
  scheduleRender();
  try {
    const payload = await fetchJson("/api/donations/preflight", {
      auth: true,
      method: "POST",
      body: candidateDonationFlowPayload(flow),
    });
    const eligibility = normalizeCandidateDonationEligibilityResult(payload);
    seedCandidateDonationFlowFromEligibility(flow, eligibility, {
      initialLoad: false,
    });
    if (!eligibility.eligible) {
      flow.error = candidateDonationFlowPrimaryEligibilityMessage(eligibility);
      showToast(flow.error);
      return false;
    }
    flow.step = "review";
    return true;
  } catch (error) {
    flow.error = candidateDonationErrorMessage(
      error,
      "Donation could not be reviewed.",
    );
    showToast(flow.error);
    return false;
  } finally {
    flow.submitting = false;
    scheduleRender();
  }
}

async function startCandidateDonationCheckout() {
  const flow = currentCandidateDonationFlow();
  const amountCents = candidateDonationFlowAmountCents(flow);
  if (!amountCents || amountCents <= 0) {
    setCandidateDonationFlowError("Enter a valid donation amount.");
    return false;
  }
  flow.submitting = true;
  flow.error = "";
  flow.notice = "";
  scheduleRender();
  try {
    const payload = await fetchJson("/api/donations/checkout-session", {
      auth: true,
      method: "POST",
      body: {
        ...candidateDonationFlowPayload(flow),
        idempotencyKey: createClientElectionId("donation"),
        successUrl: candidateDonationReturnUrl("success"),
        cancelUrl: candidateDonationReturnUrl("cancel"),
      },
    });
    const checkout = normalizeCandidateDonationCheckoutSession(payload);
    flow.checkoutSession = checkout;
    if (!checkout.checkoutUrl) {
      throw new Error("Stripe Checkout URL unavailable.");
    }
    flow.submittedMessage =
      "Stripe Checkout is ready. Use the button below if the secure payment page did not open automatically.";
    flow.step = "submitted";
    scheduleRender();
    let opened = null;
    try {
      opened = window.open(
        checkout.checkoutUrl,
        "_blank",
        "noopener,noreferrer",
      );
    } catch {
      opened = null;
    }
    if (opened) {
      flow.submittedMessage =
        "Stripe Checkout is open. Finish the donation there, then return to Polis for final status.";
    }
    showToast(opened ? "Stripe Checkout opened." : "Stripe Checkout is ready.");
    return true;
  } catch (error) {
    flow.error = candidateDonationErrorMessage(
      error,
      "Stripe Checkout could not be opened.",
    );
    showToast(flow.error);
    return false;
  } finally {
    flow.submitting = false;
    scheduleRender();
  }
}

async function openCandidateDonationTransactionDetail(donationId) {
  const candidateId = currentCandidateDashboardId();
  const normalizedDonationId = normalizeString(donationId);
  const donations = state.pages.candidateDashboard.detail.donations;
  if (!candidateId || !normalizedDonationId) {
    return;
  }
  donations.actionPendingKey = `detail:${normalizedDonationId}`;
  donations.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      `/api/candidate-dashboard/donations/transactions/${encodeURIComponent(normalizedDonationId)}`,
      { auth: true },
    );
    donations.selectedTransaction = normalizeCandidateDonationTransaction(
      payload.item || payload.transaction || payload.donation || payload,
    );
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Donation detail could not be loaded.",
    );
    showToast(donations.error);
  } finally {
    if (donations.actionPendingKey === `detail:${normalizedDonationId}`) {
      donations.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function exportCandidateDonationTransactions() {
  const candidateId = currentCandidateDashboardId();
  const donations = state.pages.candidateDashboard.detail.donations;
  if (!candidateId) {
    return;
  }
  donations.actionPendingKey = "export";
  donations.error = "";
  scheduleRender();
  try {
    const baseUrl = getApiBaseUrl();
    if (!baseUrl) {
      throw new Error("video_backend_base_url_missing");
    }
    const query = buildCandidateDonationTransactionsQuery(candidateId, donations);
    const response = await fetch(
      `${baseUrl}/api/candidate-dashboard/donations/transactions/export?${query.toString()}`,
      {
        headers: buildAuthorizedHeaders(state.auth.session),
      },
    );
    if (!response.ok) {
      throw new Error(`Export failed: ${response.status}`);
    }
    const blob = await response.blob();
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `candidate-${candidateId}-donations.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
    showToast("Donation CSV downloaded.");
  } catch (error) {
    donations.error = settingsErrorMessage(
      error,
      "Donation CSV could not be exported.",
    );
    showToast(donations.error);
  } finally {
    if (donations.actionPendingKey === "export") {
      donations.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function markCandidateDashboardEngagementRead(postId, kind = "all") {
  const candidateId = currentCandidateDashboardId();
  const normalizedPostId = normalizeString(postId);
  const normalizedKind =
    normalizeString(kind).toLowerCase() === "post_like"
      ? "likes"
      : normalizeString(kind).toLowerCase() === "post_comment"
        ? "comments"
        : normalizeString(kind).toLowerCase() || "all";
  if (!candidateId || !normalizedPostId) {
    return;
  }
  const detail = state.pages.candidateDashboard.detail;
  const engagement = detail.engagement;
  const actionKey = `read:${normalizedPostId}:${normalizedKind}`;
  engagement.actionPendingKey = actionKey;
  engagement.error = "";
  scheduleRender();
  try {
    const responseMode = candidateDashboardEngagementSelectedMode(
      engagement,
      detail.access || findCandidateDashboardAccess(candidateId),
    );
    await fetchJson(
      `/api/candidateDashboard/${encodeURIComponent(candidateId)}/engagement/read`,
      {
        auth: true,
        method: "POST",
        body: {
          postId: normalizedPostId,
          kind: normalizedKind,
          ...(responseMode ? { responseMode } : {}),
        },
      },
    );
    showToast("Engagement marked read.");
    await loadCandidateDashboardEngagement(candidateId, { refresh: true });
  } catch (error) {
    engagement.error = settingsErrorMessage(
      error,
      "Engagement could not be marked read.",
    );
    showToast(engagement.error);
  } finally {
    if (engagement.actionPendingKey === actionKey) {
      engagement.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function submitCandidateDashboardEngagementReply(formData) {
  const candidateId = currentCandidateDashboardId();
  const postId = normalizeString(formData.get("postId"));
  const replyTo = normalizeString(formData.get("replyTo"));
  const text = normalizeString(formData.get("text"));
  if (!candidateId || !postId || !text) {
    showToast("Reply text is required.");
    return false;
  }
  const detail = state.pages.candidateDashboard.detail;
  const engagement = detail.engagement;
  const responseMode = candidateDashboardEngagementSelectedMode(
    engagement,
    detail.access || findCandidateDashboardAccess(candidateId),
  );
  if (!responseMode) {
    showToast("This campaign access cannot reply from the web.");
    return false;
  }
  const actionKey = `reply:${replyTo || postId}`;
  engagement.actionPendingKey = actionKey;
  engagement.error = "";
  scheduleRender();
  try {
    await fetchJson(
      `/api/candidateDashboard/${encodeURIComponent(candidateId)}/posts/${encodeURIComponent(postId)}/comments`,
      {
        auth: true,
        method: "POST",
        body: {
          text,
          responseMode,
          ...(replyTo ? { replyTo } : {}),
        },
      },
    );
    showToast("Reply sent.");
    await loadCandidateDashboardEngagement(candidateId, { refresh: true });
    return true;
  } catch (error) {
    engagement.error = settingsErrorMessage(error, "Reply could not be sent.");
    showToast(engagement.error);
    return false;
  } finally {
    if (engagement.actionPendingKey === actionKey) {
      engagement.actionPendingKey = "";
    }
    scheduleRender();
  }
}

