async function toggleProfileFollow(userId) {
  const normalizedUserId = normalizeString(userId);
  if (!normalizedUserId) {
    return;
  }
  const profileState = state.pages.profile;
  const payload = await fetchJson(
    `/api/users/${encodeURIComponent(normalizedUserId)}/follow`,
    {
      auth: true,
      method: "POST",
      body: {},
    },
  );
  const nextFollowing = payload.following === true;
  if (profileState.current?.userId === normalizedUserId) {
    profileState.current = {
      ...profileState.current,
      isFollowing: nextFollowing,
      followersCount: Math.max(
        0,
        profileState.current.followersCount + (nextFollowing ? 1 : -1),
      ),
    };
  }
  profileState.connections.items = profileState.connections.items
    .map((entry) =>
      normalizeString(entry.userId) === normalizedUserId
        ? { ...entry, viewerIsFollowing: nextFollowing }
        : entry,
    )
    .filter(
      (entry) =>
        profileState.connections.kind !== "following" ||
        normalizeString(entry.userId) !== normalizedUserId ||
        nextFollowing,
    );
  scheduleRender();
}

function profileSafetyHandleLabel(profile = {}) {
  const username = normalizeString(profile.username).replace(/^@/u, "");
  if (username) {
    return `@${username}`;
  }
  return normalizeString(profile.displayName) || "this user";
}

function patchProfileSafetyState(userId, patch = {}) {
  const normalizedUserId = normalizeString(userId);
  if (!normalizedUserId) {
    return;
  }
  const profileState = state.pages.profile;
  if (profileState.current?.userId === normalizedUserId) {
    profileState.current = {
      ...profileState.current,
      ...patch,
    };
    if (patch.isBlocked === true) {
      profileState.current.isFollowing = false;
      profileState.posts.items = [];
      profileState.posts.nextCursor = null;
    }
  }
  profileState.connections.items = profileState.connections.items.map((entry) =>
    normalizeString(entry.userId) === normalizedUserId
      ? { ...entry, ...patch }
      : entry,
  );
}

function invalidateSettingsSafetyList(kind) {
  const resource = settingsSafetyResource(kind === "muted" ? "muted" : "blocked");
  if (!resource) {
    return;
  }
  resource.loaded = false;
  resource.nextCursor = null;
}

async function applyProfileSafetyAction(kind, userId) {
  const normalizedKind = kind === "block" ? "block" : "mute";
  const normalizedUserId = normalizeString(userId);
  const profileState = state.pages.profile;
  const profile = profileState.current;
  if (!normalizedUserId || !profile || profile.userId !== normalizedUserId) {
    showToast("Profile safety action unavailable.");
    return;
  }
  if (!state.auth.session) {
    openAuthModal("profile_safety", {
      title: "Log in to manage safety",
      message: "Sign in to mute or block people from your Polis account.",
      targetPath: getCurrentPathWithQuery(),
    });
    return;
  }
  if (normalizedUserId === state.auth.user?.userId) {
    showToast("You cannot mute or block your own profile.");
    return;
  }
  const pendingKey = `${normalizedKind}:${normalizedUserId}`;
  profileState.safetyActionPendingKey = pendingKey;
  profileState.error = "";
  scheduleRender();
  try {
    await fetchJson(
      `/api/users/${encodeURIComponent(normalizedUserId)}/${normalizedKind}`,
      {
        auth: true,
        method: "PUT",
        body: { source: "profile" },
      },
    );
    if (normalizedKind === "block") {
      patchProfileSafetyState(normalizedUserId, {
        isBlocked: true,
        isFollowing: false,
      });
      invalidateSettingsSafetyList("blocked");
    } else {
      patchProfileSafetyState(normalizedUserId, { isMuted: true });
      invalidateSettingsSafetyList("muted");
    }
    profileState.blockConfirmUserId = "";
    showToast(
      `${normalizedKind === "block" ? "Blocked" : "Muted"} ${profileSafetyHandleLabel(profile)}.`,
    );
  } catch (error) {
    const message = settingsErrorMessage(
      error,
      normalizedKind === "block"
        ? "User could not be blocked."
        : "User could not be muted.",
    );
    profileState.error = message;
    showToast(message);
  } finally {
    if (profileState.safetyActionPendingKey === pendingKey) {
      profileState.safetyActionPendingKey = "";
    }
    scheduleRender();
  }
}

function parseMessagingSubroute(route = state.route) {
  const rawPath = normalizeString(route?.routeParams?.messagePath);
  const segments = rawPath.split("/").filter(Boolean);
  const searchParams = readCurrentSearchParams();
  const routeMessageId = normalizeString(searchParams.get("messageId"));
  const fromNotification =
    normalizeString(searchParams.get("fromNotification")) === "1";
  if (!segments.length) {
    const tab = normalizeString(searchParams.get("tab")).toLowerCase();
    if (tab === "requests") {
      return {
        view: "requests",
        segments: ["requests"],
        aliasPath: "/messages/requests",
      };
    }
    return {
      view: "inbox",
      segments: [],
      restoreSavedTarget: normalizeString(searchParams.get("restore")) !== "0",
    };
  }
  if (segments[0] === "requests") {
    return { view: "requests", segments };
  }
  if (segments[0] === "compose") {
    return { view: "compose", segments };
  }
  if (segments[0] === "settings") {
    return { view: "settings", segments };
  }
  if (segments[0] === "devices") {
    if (segments[1] === "link") {
      return {
        view: "device-link",
        linkId: decodeRouteSegment(segments[2]),
        segments,
      };
    }
    return { view: "devices", segments };
  }
  if (segments[0] === "recovery") {
    if (segments[1] === "restore") {
      return { view: "recovery-restore", segments };
    }
    return { view: "recovery", segments };
  }
  if (segments[0] === "security-activity") {
    return { view: "security", segments };
  }
  if (
    (segments[0] === "servers" || segments[0] === "spaces") &&
    segments.length >= 3
  ) {
    const scopeType = decodeRouteSegment(segments[1]);
    const scopeId = decodeRouteSegment(segments[2]);
    if (segments[0] === "spaces") {
      return {
        view: "server",
        scopeType,
        scopeId,
        alias: true,
        segments,
      };
    }
    if (segments.length === 3) {
      return {
        view: "server",
        scopeType,
        scopeId,
        segments,
      };
    }
    if (segments[3] === "settings") {
      if (segments[4]) {
        return {
          view: "server-settings-section",
          scopeType,
          scopeId,
          sectionId: decodeRouteSegment(segments[4]),
          segments,
        };
      }
      return {
        view: "server-settings",
        scopeType,
        scopeId,
        segments,
      };
    }
    if (segments[3] === "roles") {
      if (segments[4]) {
        return {
          view: "server-role",
          scopeType,
          scopeId,
          roleId: decodeRouteSegment(segments[4]),
          segments,
        };
      }
      return {
        view: "server-roles",
        scopeType,
        scopeId,
        segments,
      };
    }
    if (segments[3] === "members") {
      if (segments[4]) {
        return {
          view: "server-member",
          scopeType,
          scopeId,
          userId: decodeRouteSegment(segments[4]),
          segments,
        };
      }
      return {
        view: "server-members",
        scopeType,
        scopeId,
        segments,
      };
    }
    if (segments[3] === "bans") {
      return {
        view: "server-bans",
        scopeType,
        scopeId,
        segments,
      };
    }
    if (segments[3] === "workflows") {
      return {
        view: "server-workflows",
        scopeType,
        scopeId,
        segments,
      };
    }
    if (segments[3] === "moderation") {
      return {
        view: "server-moderation",
        scopeType,
        scopeId,
        segments,
      };
    }
    if (segments[3] === "categories" && segments[4]) {
      const categoryId = decodeRouteSegment(segments[4]);
      if (segments[5] === "permissions") {
        if (segments[6] === "roles" && segments[7]) {
          return {
            view: "category-permission-role",
            scopeType,
            scopeId,
            categoryId,
            roleId: decodeRouteSegment(segments[7]),
            segments,
          };
        }
        return {
          view: "category-permissions",
          scopeType,
          scopeId,
          categoryId,
          segments,
        };
      }
      return {
        view: "server",
        scopeType,
        scopeId,
        categoryId,
        segments,
      };
    }
    if (segments[3] === "rooms" && segments[4]) {
      const conversationId = decodeRouteSegment(segments[4]);
      if (segments.length === 5) {
        return {
          view: "server-room",
          scopeType,
          scopeId,
          conversationId,
          routeMessageId,
          fromNotification,
          segments,
        };
      }
      if (segments[5] === "settings") {
        if (!segments[6]) {
          return {
            view: "room-settings",
            scopeType,
            scopeId,
            conversationId,
            segments,
          };
        }
        if (segments[6] === "notifications") {
          return {
            view: "room-settings-notifications",
            scopeType,
            scopeId,
            conversationId,
            segments,
          };
        }
        if (segments[6] === "pinned-messages") {
          return {
            view: "room-settings-pins",
            scopeType,
            scopeId,
            conversationId,
            sectionId: decodeRouteSegment(segments[6]),
            segments,
          };
        }
        if (segments[6] === "invites") {
          return {
            view: "room-settings-invites",
            scopeType,
            scopeId,
            conversationId,
            sectionId: decodeRouteSegment(segments[6]),
            segments,
          };
        }
        if (segments[6] === "integrations") {
          return {
            view: "room-settings-integrations",
            scopeType,
            scopeId,
            conversationId,
            sectionId: decodeRouteSegment(segments[6]),
            segments,
          };
        }
        if (segments[6] === "permissions") {
          if (segments[7] === "roles" && segments[8]) {
            return {
              view: "room-permission-role",
              scopeType,
              scopeId,
              conversationId,
              roleId: decodeRouteSegment(segments[8]),
              segments,
            };
          }
          return {
            view: "room-permissions",
            scopeType,
            scopeId,
            conversationId,
            segments,
          };
        }
        return {
          view: "room-settings-section",
          scopeType,
          scopeId,
          conversationId,
          sectionId: decodeRouteSegment(segments[6]),
          segments,
        };
      }
    }
    return {
      view: "server",
      scopeType,
      scopeId,
      segments,
    };
  }
  if (segments[0] === "conversations" && segments[1]) {
    if (segments[2] === "settings") {
      return {
        view: "conversation-settings",
        conversationId: decodeRouteSegment(segments[1]),
        segments,
      };
    }
    if (segments[2] === "people") {
      return {
        view: "conversation-people",
        conversationId: decodeRouteSegment(segments[1]),
        segments,
      };
    }
    return {
      view: "conversation",
      conversationId: decodeRouteSegment(segments[1]),
      routeMessageId,
      fromNotification,
      segments,
    };
  }
  return { view: "unsupported", segments };
}

function messagingMessageMatchesRouteTarget(message, targetMessageId) {
  const normalizedTargetMessageId = normalizeString(targetMessageId);
  if (!normalizedTargetMessageId) {
    return false;
  }
  return (
    normalizeString(message?.messageId) === normalizedTargetMessageId ||
    normalizeString(message?.sortKey) === normalizedTargetMessageId
  );
}

function clearMessagingRouteHighlight({ schedule = true } = {}) {
  if (messagingRouteHighlightClearTimer) {
    window.clearTimeout(messagingRouteHighlightClearTimer);
    messagingRouteHighlightClearTimer = null;
  }
  lastMessagingRouteHighlightKey = "";
  const conversation = state.pages.messaging.conversation;
  if (conversation.highlightedMessageId) {
    conversation.highlightedMessageId = "";
    if (schedule) {
      scheduleRender();
    }
  }
}

function syncMessagingRouteHighlightAfterRender() {
  const conversation = state.pages.messaging.conversation;
  const targetMessageId = normalizeString(conversation.highlightedMessageId);
  if (!targetMessageId) {
    return;
  }
  const conversationId = normalizeString(conversation.item?.conversationId);
  const highlightKey = `${conversationId}:${targetMessageId}`;
  if (lastMessagingRouteHighlightKey === highlightKey) {
    return;
  }
  const target = Array.from(
    root?.querySelectorAll(
      ".shared-message[data-message-id], .shared-message-system[data-message-id]",
    ) || [],
  ).find((item) => item.getAttribute("data-message-id") === targetMessageId);
  if (!target) {
    return;
  }
  lastMessagingRouteHighlightKey = highlightKey;
  target.scrollIntoView({ behavior: "smooth", block: "center" });
  if (messagingRouteHighlightClearTimer) {
    window.clearTimeout(messagingRouteHighlightClearTimer);
  }
  messagingRouteHighlightClearTimer = window.setTimeout(() => {
    if (
      normalizeString(
        state.pages.messaging.conversation.highlightedMessageId,
      ) === targetMessageId
    ) {
      state.pages.messaging.conversation.highlightedMessageId = "";
      scheduleRender();
    }
    if (lastMessagingRouteHighlightKey === highlightKey) {
      lastMessagingRouteHighlightKey = "";
    }
    messagingRouteHighlightClearTimer = null;
  }, 2200);
}

function buildMessagingScopeQuery(scopeType, scopeId, extra = {}) {
  const params = new URLSearchParams({
    scopeType: normalizeString(scopeType),
    scopeId: normalizeString(scopeId),
  });
  Object.entries(extra).forEach(([key, value]) => {
    const normalized = normalizeString(value);
    if (normalized) {
      params.set(key, normalized);
    }
  });
  return params.toString();
}

async function ensureMessagingDeviceRegistered() {
  const messaging = state.pages.messaging;
  if (messaging.device.registering) {
    return;
  }
  messaging.device.currentDeviceId =
    (await messagingDevice.currentDeviceId()) || "";
  messaging.device.registering = true;
  messaging.device.error = "";
  scheduleRender();

  try {
    const registrationPayload =
      await messagingDevice.buildRegistrationPayload();
    await fetchJson("/api/messaging/devices/register", {
      auth: true,
      method: "POST",
      body: registrationPayload,
      headers: await messagingDevice.buildDeviceHeaders(),
    });
    messaging.device.registered = true;
  } catch (error) {
    messaging.device.error =
      normalizeString(error?.message) ||
      "Messaging device registration failed.";
  } finally {
    messaging.device.registering = false;
    scheduleRender();
  }
}

async function ensureMessagingInitialized({ force = false } = {}) {
  const messaging = state.pages.messaging;
  if (messaging.loading) {
    return;
  }
  if (messaging.initialized && !force) {
    return;
  }
  messaging.loading = true;
  messaging.error = "";
  scheduleRender();

  try {
    const bootstrap = await fetchJson("/api/messaging/bootstrap", {
      auth: true,
    });
    messaging.bootstrap = bootstrap;
    messaging.settings = bootstrap.settings || null;
    messaging.initialized = true;
    await ensureMessagingDeviceRegistered();
  } catch (error) {
    messaging.error = messagingServiceErrorMessage(
      error?.message,
      "Messaging could not be initialized.",
    );
  } finally {
    messaging.loading = false;
    scheduleRender();
  }
}

async function connectMessagingSocketForRoute() {
  const subroute = parseMessagingSubroute();
  const wsUrl =
    normalizeString(state.pages.messaging.bootstrap?.wsUrl) ||
    normalizeString(runtimeConfig.messaging?.wsUrl);
  if (!messagingSessionRetained) {
    await messagingSocket.retainSession(wsUrl);
    messagingSessionRetained = true;
  } else {
    await messagingSocket.ensureConnected(wsUrl);
  }
  if (
    (subroute.view === "conversation" || subroute.view === "server-room") &&
    subroute.conversationId
  ) {
    messagingSocket.subscribeConversation(subroute.conversationId);
  } else {
    clearMessagingTypingParticipants();
    stopMessagingTyping();
    if (state.pages.messaging.conversation.item?.conversationId) {
      messagingSocket.unsubscribeConversation(
        state.pages.messaging.conversation.item.conversationId,
      );
    }
    messagingSocket.unsubscribeInbox();
    messagingSocket.subscribeInbox();
  }
}

