function upsertMessagingServerRole(role) {
  const normalizedRole = normalizeMessagingRole(role);
  if (!normalizedRole.roleId) {
    return null;
  }
  const rolesState = state.pages.messaging.serverRoles;
  const existingIndex = rolesState.items.findIndex(
    (item) => item.roleId === normalizedRole.roleId,
  );
  if (existingIndex >= 0) {
    rolesState.items = rolesState.items.map((item, index) =>
      index === existingIndex ? normalizedRole : item,
    );
  } else {
    rolesState.items = [...rolesState.items, normalizedRole].sort(
      (left, right) => left.position - right.position,
    );
  }
  if (rolesState.selected?.roleId === normalizedRole.roleId) {
    rolesState.selected = normalizedRole;
  }
  rolesState.loaded = true;
  return normalizedRole;
}

