function messagingDefaultInboxConversation(
  conversations = state.pages.messaging.inbox.items || [],
) {
  const items = Array.isArray(conversations) ? conversations : [];
  return (
    items.find((conversation) => Number(conversation.unreadCount) > 0) ||
    items[0] ||
    null
  );
}

function upsertMessagingServerMember(memberPayload) {
  const member = normalizeMessagingMember(memberPayload || {});
  if (!member.userId) {
    return null;
  }
  const membersState = state.pages.messaging.serverMembers;
  const existingIndex = membersState.items.findIndex(
    (item) => normalizeString(item.userId) === member.userId,
  );
  if (existingIndex >= 0) {
    membersState.items = membersState.items.map((item, index) =>
      index === existingIndex ? { ...item, ...member } : item,
    );
  } else if (membersState.loaded) {
    membersState.items = [member, ...membersState.items];
  }
  if (
    membersState.detail?.member &&
    normalizeString(membersState.detail.member.userId) === member.userId
  ) {
    membersState.detail = {
      ...membersState.detail,
      member: { ...membersState.detail.member, ...member },
    };
  }
  return member;
}

