function messagingModerationStatusFromSearch() {
  const requested = normalizeString(readCurrentSearchParams().get("status"))
    .toLowerCase();
  if (["open", "approved", "rejected", "resolved", "all"].includes(requested)) {
    return requested;
  }
  return "open";
}

