async function toggleMessagingCategoryMute(scopeType, scopeId, categoryId, muted) {
  const normalizedScopeType = normalizeString(scopeType);
  const normalizedScopeId = normalizeString(scopeId);
  const normalizedCategoryId = normalizeString(categoryId);
  const settingsState = state.pages.messaging.serverSettings;
  const pendingKey = `category:mute:${normalizedCategoryId}`;
  if (!normalizedScopeType || !normalizedScopeId || !normalizedCategoryId) {
    showToast("Category mute unavailable.");
    return false;
  }
  const directory = state.pages.messaging.serverDirectory.item;
  const channels = messagingDirectoryCategoryChannels(
    directory,
    normalizedCategoryId,
  );
  if (!channels.length) {
    showToast("No rooms in this category.");
    return false;
  }
  if (settingsState.actionPendingKey) {
    return false;
  }
  settingsState.actionPendingKey = pendingKey;
  settingsState.error = "";
  scheduleRender();
  try {
    await Promise.all(
      channels
        .map((channel) => normalizeString(channel.conversationId))
        .filter(Boolean)
        .map((conversationId) =>
          fetchJson(
            `/api/messaging/conversations/${encodeURIComponent(conversationId)}/preferences`,
            {
              auth: true,
              method: "PATCH",
              body: {
                muted,
              },
            },
          ),
        ),
    );
    await refreshMessagingServerDirectoryManagement(
      normalizedScopeType,
      normalizedScopeId,
    );
    showToast(muted ? "Category muted." : "Category unmuted.");
    return true;
  } catch (error) {
    settingsState.error =
      normalizeString(error?.message) ||
      "Category notifications could not be updated.";
    showToast(settingsState.error);
    return false;
  } finally {
    if (settingsState.actionPendingKey === pendingKey) {
      settingsState.actionPendingKey = "";
    }
    scheduleRender();
  }
}

