async function updateMessagingServerMemberProfile(formData) {
  const scopeType = normalizeString(formData.get("scopeType"));
  const scopeId = normalizeString(formData.get("scopeId"));
  const userId = normalizeString(formData.get("userId"));
  const nickname = normalizeString(formData.get("nickname"));
  const roleIds = Array.from(
    new Set(
      formData
        .getAll("roleId")
        .map((entry) => normalizeString(entry))
        .filter(Boolean),
    ),
  );
  if (!scopeType || !scopeId || !userId) {
    showToast("Member update is unavailable.");
    return false;
  }
  const membersState = state.pages.messaging.serverMembers;
  const pendingKey = `${userId}:save`;
  if (membersState.actionPendingKey) {
    return false;
  }
  membersState.actionPendingKey = pendingKey;
  membersState.detailError = "";
  membersState.error = "";
  scheduleRender();

  try {
    const query = buildMessagingScopeQuery(scopeType, scopeId);
    const encodedUserId = encodeURIComponent(userId);
    const profilePayload = await fetchJson(
      `/api/messaging/server-members/${encodedUserId}?${query}`,
      {
        auth: true,
        method: "PATCH",
        body: { nickname: nickname || null },
      },
    );
    upsertMessagingServerMember(profilePayload.member || {});
    const rolesPayload = await fetchJson(
      `/api/messaging/server-members/${encodedUserId}/roles?${query}`,
      {
        auth: true,
        method: "PUT",
        body: { roleIds },
      },
    );
    upsertMessagingServerMember(rolesPayload.member || {});
    await Promise.all([
      loadMessagingServerMember(scopeType, scopeId, userId, { refresh: true }),
      loadMessagingServerMembers(scopeType, scopeId, { refresh: true }).catch(
        () => {},
      ),
    ]);
    showToast("Member updated.");
    return true;
  } catch (error) {
    membersState.detailError =
      normalizeString(error?.message) || "Member update failed.";
    showToast(membersState.detailError);
    return false;
  } finally {
    if (membersState.actionPendingKey === pendingKey) {
      membersState.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function setMessagingServerMemberTimeout(
  scopeType,
  scopeId,
  userId,
  durationMs,
) {
  const normalizedUserId = normalizeString(userId);
  const normalizedDuration = Number(durationMs);
  if (
    !normalizeString(scopeType) ||
    !normalizeString(scopeId) ||
    !normalizedUserId ||
    !Number.isFinite(normalizedDuration) ||
    normalizedDuration <= 0
  ) {
    showToast("Timeout action is unavailable.");
    return false;
  }
  const membersState = state.pages.messaging.serverMembers;
  const pendingKey = `${normalizedUserId}:timeout`;
  if (membersState.actionPendingKey) {
    return false;
  }
  membersState.actionPendingKey = pendingKey;
  membersState.detailError = "";
  scheduleRender();

  try {
    const timeoutUntil = Date.now() + normalizedDuration;
    const query = buildMessagingScopeQuery(scopeType, scopeId);
    const payload = await fetchJson(
      `/api/messaging/server-members/${encodeURIComponent(normalizedUserId)}/timeout?${query}`,
      {
        auth: true,
        method: "PUT",
        body: { timeoutUntil },
      },
    );
    upsertMessagingServerMember(payload.member || {});
    await Promise.all([
      loadMessagingServerMember(scopeType, scopeId, normalizedUserId, {
        refresh: true,
      }),
      loadMessagingServerMembers(scopeType, scopeId, { refresh: true }).catch(
        () => {},
      ),
    ]);
    showToast("Member timed out.");
    return true;
  } catch (error) {
    membersState.detailError =
      normalizeString(error?.message) || "Timeout update failed.";
    showToast(membersState.detailError);
    return false;
  } finally {
    if (membersState.actionPendingKey === pendingKey) {
      membersState.actionPendingKey = "";
    }
    scheduleRender();
  }
}

