function createSettingsAudienceGroupSearchState() {
  return {
    groupId: "create",
    query: "",
    items: [],
    loading: false,
    error: "",
    loaded: false,
    lastSearchQuery: "",
    token: 0,
  };
}

function settingsAudienceGroupDraftKey(groupId = "") {
  return normalizeString(groupId) || "create";
}

function settingsAudienceGroupSearch(resource = state.pages.settings.audienceGroups) {
  if (!resource.search) {
    resource.search = createSettingsAudienceGroupSearchState();
  }
  return resource.search;
}

function settingsAudienceGroupDraft(
  resource,
  groupId = "",
  fallback = {},
) {
  if (!resource.drafts || typeof resource.drafts !== "object") {
    resource.drafts = {};
  }
  const key = settingsAudienceGroupDraftKey(groupId);
  if (!resource.drafts[key]) {
    resource.drafts[key] = {
      name: normalizeString(fallback.name),
      memberUserIds: normalizeAudienceGroupMemberIds(
        fallback.memberUserIds,
      ).join("\n"),
    };
  }
  return resource.drafts[key];
}

function clearSettingsAudienceGroupDraft(resource, groupId = "") {
  const key = settingsAudienceGroupDraftKey(groupId);
  if (resource?.drafts && typeof resource.drafts === "object") {
    delete resource.drafts[key];
  }
}

function settingsAudienceGroupByKey(resource, groupId = "") {
  const normalizedGroupId = normalizeString(groupId);
  if (!normalizedGroupId) {
    return {};
  }
  return (
    resource.items.find((group) => group.groupId === normalizedGroupId) || {}
  );
}

