async function saveAdminCertificationParsedResults({
  sourceId,
  importId,
  reason,
  rows,
  mappings,
}) {
  const imports = adminCertificationImportsSlice();
  const normalizedSourceId = normalizeString(sourceId);
  const normalizedImportId = normalizeString(importId);
  const normalizedReason = normalizeString(reason);
  if (
    !normalizedSourceId ||
    !normalizedImportId ||
    !normalizedReason ||
    !Array.isArray(rows) ||
    !rows.length ||
    !Array.isArray(mappings) ||
    !mappings.length
  ) {
    imports.error =
      "Reason, at least one parsed row, and at least one mapping are required.";
    showToast(imports.error);
    scheduleRender();
    return false;
  }
  const pendingKey = adminPendingKey(normalizedImportId, "parsed-results");
  imports.actionPendingKey = pendingKey;
  imports.error = "";
  imports.notice = "";
  scheduleRender();
  try {
    await fetchJson(
      adminCertificationImportsEndpoint(
        normalizedSourceId,
        normalizedImportId,
        "parsed-results",
      ),
      {
        auth: true,
        method: "PUT",
        body: { rows, mappings, reason: normalizedReason },
      },
    );
    imports.mappingDraft = createAdminCertificationMappingDraftState();
    imports.notice = "Parsed rows and mappings saved.";
    showToast(imports.notice);
    await loadAdminCertificationImports(normalizedSourceId, { refresh: true });
    return true;
  } catch (error) {
    imports.error = settingsErrorMessage(
      error,
      "Parsed rows and mappings could not be saved.",
    );
    showToast(imports.error);
    return false;
  } finally {
    if (imports.actionPendingKey === pendingKey) {
      imports.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function submitAdminCertificationMappedResults(formData) {
  const imports = adminCertificationImportsSlice();
  const draft = imports.mappingDraft || createAdminCertificationMappingDraftState();
  const sourceId = normalizeString(formData.get("sourceId") || draft.sourceId);
  const importId = normalizeString(formData.get("importId") || draft.importId);
  const reason = normalizeString(formData.get("reason") || draft.reason);
  let rows = draft.rows;
  if (!Array.isArray(rows) || !rows.length) {
    try {
      rows = JSON.parse(normalizeString(formData.get("rowsJson")) || "[]");
    } catch {
      rows = [];
    }
  }
  const mappings = [];
  rows.forEach((row, index) => {
    const scope = adminCertificationRowScope(row);
    const suggestions = draft.suggestionsByScope?.[scope.key] || [];
    const candidateId = normalizeString(formData.get(`candidateId:${index}`));
    const mappingReason = normalizeString(formData.get(`mappingReason:${index}`));
    const selected = suggestions.find((candidate) => candidate.candidateId === candidateId);
    if (!candidateId || !mappingReason) return;
    mappings.push({
      sourceContestId: row.sourceContestId,
      sourceCandidateId: row.sourceCandidateId,
      candidateId,
      matchType:
        selected && adminCertificationSuggestionMatchesRowIds(selected, row)
          ? "exact_id"
          : "admin_reviewed",
      mappingReason,
    });
  });
  if (mappings.length !== rows.length) {
    imports.error = "Every certification row needs a mapped candidate and reason.";
    showToast(imports.error);
    scheduleRender();
    return false;
  }
  return saveAdminCertificationParsedResults({
    sourceId,
    importId,
    reason,
    rows,
    mappings,
  });
}

async function submitAdminCertificationImportAction(formData) {
  const imports = adminCertificationImportsSlice();
  const sourceId = normalizeString(formData.get("sourceId") || getAdminDetailId());
  const importId = normalizeString(formData.get("importId"));
  const action = normalizeString(formData.get("certificationAction"));
  if (!sourceId || !importId || !["parse", "approve", "reject", "process"].includes(action)) {
    showToast("Certification import action unavailable.");
    return false;
  }
  const reason = normalizeString(formData.get("reason"));
  if (["approve", "reject"].includes(action) && !reason) {
    imports.error = "A reason is required for approval decisions.";
    showToast(imports.error);
    scheduleRender();
    return false;
  }
  const pendingKey = adminPendingKey(importId, action);
  imports.actionPendingKey = pendingKey;
  imports.error = "";
  imports.notice = "";
  scheduleRender();
  try {
    await fetchJson(adminCertificationImportsEndpoint(sourceId, importId, action), {
      auth: true,
      method: "POST",
      body: reason ? { reason } : {},
    });
    imports.notice =
      action === "parse"
        ? "Certification import parsed."
        : action === "process"
          ? "Certification processing started."
          : action === "approve"
            ? "Certification import approval recorded."
            : "Certification import rejected.";
    showToast(imports.notice);
    await loadAdminCertificationImports(sourceId, { refresh: true });
    if (["approve", "process"].includes(action)) {
      await loadAdminDetail("election-sources", sourceId, { refresh: true });
    }
    return true;
  } catch (error) {
    imports.error = settingsErrorMessage(
      error,
      "Certification import action failed.",
    );
    showToast(imports.error);
    return false;
  } finally {
    if (imports.actionPendingKey === pendingKey) {
      imports.actionPendingKey = "";
    }
    scheduleRender();
  }
}

async function loadAdminList(sectionKey, { refresh = false } = {}) {
  const slice = adminSliceForSection(sectionKey);
  const endpoint = adminListEndpoint(sectionKey);
  if (!slice || !endpoint) return;
  if (slice.loading) return;
  if (slice.loaded && !refresh && slice.loadedEndpoint === endpoint) return;
  slice.loading = true;
  slice.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(endpoint, { auth: true });
    const rawItems = readAdminItemsPayload(sectionKey, payload);
    slice.items = rawItems
      .map((item, index) => normalizeAdminItem(sectionKey, item, index))
      .filter((item) => item.id);
    slice.nextCursor =
      normalizeString(payload?.nextCursor || payload?.cursor || payload?.next) ||
      null;
    if (sectionKey === "feed-config" || sectionKey === "voter-map-costs") {
      slice.item = normalizeAdminItem(sectionKey, payload, 0);
    }
    if (sectionKey === "feed-config") {
      syncAdminFeedConfigDraft(slice, payload);
    }
    slice.loadedEndpoint = endpoint;
    slice.loaded = true;
  } catch (error) {
    slice.error = settingsErrorMessage(
      error,
      `${adminSectionConfig(sectionKey).label} could not be loaded.`,
    );
    slice.loadedEndpoint = endpoint;
    slice.loaded = true;
  } finally {
    slice.loading = false;
    scheduleRender();
  }
}

async function loadMoreAdminQueue(sectionKey) {
  const queueLabel = adminPagedQueueLabel(sectionKey);
  if (!queueLabel) return;
  const slice = adminSliceForSection(sectionKey);
  const cursor = normalizeString(slice?.nextCursor);
  if (!slice || !cursor || slice.loading || slice.loadingMore) return;
  const endpoint = adminListEndpointWithCursor(sectionKey, cursor);
  if (!endpoint) return;
  slice.loadingMore = true;
  slice.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(endpoint, { auth: true });
    const nextItems = readAdminItemsPayload(sectionKey, payload)
      .map((item, index) =>
        normalizeAdminItem(sectionKey, item, slice.items.length + index),
      )
      .filter((item) => item.id);
    const seen = new Set(slice.items.map((item) => item.id));
    slice.items = [
      ...slice.items,
      ...nextItems.filter((item) => {
        if (seen.has(item.id)) return false;
        seen.add(item.id);
        return true;
      }),
    ];
    slice.nextCursor =
      normalizeString(payload?.nextCursor || payload?.cursor || payload?.next) ||
      null;
  } catch (error) {
    slice.error = settingsErrorMessage(
      error,
      `More ${queueLabel} could not be loaded.`,
    );
  } finally {
    slice.loadingMore = false;
    scheduleRender();
  }
}

