function adminReportAuditItemsFromPayload(payload = {}) {
  const direct = readArrayPayload(payload, [
    "audit",
    "items",
    "data",
    "results",
    "actions",
    "moderationActions",
  ]);
  if (direct.length) {
    return direct;
  }
  const data = payload?.data;
  return data && typeof data === "object" && !Array.isArray(data)
    ? readArrayPayload(data, ["audit", "items", "results", "actions"])
    : [];
}

function normalizeAdminReportDetailSource(payload = {}, id = "", auditPayload = null, auditError = "") {
  const body = payload && typeof payload === "object" ? payload : {};
  const explicit = adminFirstObject(body, [
    "report",
    "item",
    "data",
    "details",
    "reportDetail",
  ]);
  const summary = adminFirstObject(body, ["summary"]);
  const hasSummary = Object.keys(summary).length > 0;
  const hasExplicit = Object.keys(explicit).length > 0;
  const source = {
    ...(hasSummary ? summary : {}),
    ...(hasExplicit ? explicit : hasSummary ? {} : body),
  };
  const postId =
    adminFirstValue(source, ["postId", "id"]) ||
    adminFirstValue(summary, ["postId", "id"]) ||
    normalizeString(id);
  if (postId) {
    source.postId = postId;
  }
  if (!source.status && source.statusKey) {
    source.status = source.statusKey;
  }
  if (!source.updatedAt && !source.updatedAtIso && source.statusUpdatedAt) {
    source.updatedAt = source.statusUpdatedAt;
  }
  [
    "reportRateDay",
    "reportRateHour",
    "uniqueReportersDay",
    "weightedUniqueReportersDay",
    "impressionsDay",
    "uniqueReportersHour",
    "weightedUniqueReportersHour",
    "impressionsHour",
    "escalatedAt",
    "escalatedReason",
  ].forEach((key) => {
    if (source[key] === undefined && body[key] !== undefined) {
      source[key] = body[key];
    }
  });
  if (!adminHasDetailObject(source.categoryCounts)) {
    const categoryCounts = adminFirstObject(body, [
      "categoryCounts",
      "category_counts",
      "summary.categoryCounts",
      "summary.category_counts",
    ]);
    if (adminHasDetailObject(categoryCounts)) {
      source.categoryCounts = categoryCounts;
    }
  }
  if (!adminHasDetailObject(source.postSnapshot)) {
    const postSnapshot = adminFirstObject(body, [
      "postSnapshot",
      "post_snapshot",
      "post",
      "content",
      "summary.postSnapshot",
      "summary.post_snapshot",
      "summary.post",
      "summary.content",
    ]);
    if (adminHasDetailObject(postSnapshot)) {
      source.postSnapshot = postSnapshot;
    }
  }
  const reporters = adminFirstArray(body, ["reporters", "reports", "items"]);
  if (reporters.length && !Array.isArray(source.reporters)) {
    source.reporters = reporters;
  }
  const audit = auditPayload ? adminReportAuditItemsFromPayload(auditPayload) : [];
  if (audit.length) {
    source.audit = audit;
  }
  if (auditError) {
    source.auditError = auditError;
  }
  if (source.summary && typeof source.summary === "object") {
    delete source.summary;
  }
  if (hasSummary) {
    source.detailSummary = summary;
  }
  source.rawDetail = body;
  return source;
}

async function loadAdminDetail(sectionKey, id, { refresh = false } = {}) {
  const slice = adminSliceForSection(sectionKey);
  const endpoint = adminDetailEndpoint(sectionKey, id);
  if (!slice || !endpoint) return;
  if (slice.item?.id === id && !refresh) return;
  slice.loading = true;
  slice.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(endpoint, { auth: true });
    let source = null;
    if (sectionKey === "reports") {
      let auditPayload = null;
      let auditError = "";
      try {
        auditPayload = await fetchJson(`${endpoint}/audit`, { auth: true });
      } catch (error) {
        auditError = settingsErrorMessage(
          error,
          "Report audit trail could not be loaded.",
        );
      }
      source = normalizeAdminReportDetailSource(payload, id, auditPayload, auditError);
    } else {
      source =
        payload?.item ||
        payload?.application ||
        payload?.report ||
        payload?.donation ||
        payload?.request ||
        payload?.event ||
        payload?.source ||
        payload?.question ||
        payload;
    }
    if (
      source &&
      typeof source === "object" &&
      payload &&
      typeof payload === "object" &&
      source !== payload
    ) {
      source = {
        ...source,
        audit: source.audit || payload.audit || payload.actions || payload.moderationActions,
        regions: source.regions || payload.regions || payload.items,
        history: source.history || payload.history || payload.entries,
        rawDetail: payload,
      };
    }
    slice.item = normalizeAdminItem(sectionKey, source, 0);
    if (sectionKey === "policy-questions") {
      syncAdminPolicyQuestionDraft(slice, slice.item, { reset: true });
    }
    slice.loaded = true;
  } catch (error) {
    slice.error = settingsErrorMessage(
      error,
      `${adminSectionConfig(sectionKey).label} detail could not be loaded.`,
    );
  } finally {
    slice.loading = false;
    scheduleRender();
  }
}

async function loadAdminPage({ refresh = false } = {}) {
  const section = getAdminSection();
  const detailId = getAdminDetailId();
  state.pages.admin.selectedSection = section;
  state.pages.admin.selectedId = detailId;
  if (section === "overview") {
    await Promise.allSettled(
      ADMIN_SECTIONS.filter((item) => item.key !== "overview").map((item) =>
        loadAdminList(item.key, { refresh }),
      ),
    );
    state.pages.admin.overviewLoaded = true;
    scheduleRender();
    return;
  }
  await loadAdminList(section, { refresh });
  if (section === "election-sources") {
    await loadAdminElectionSourceOperations({ refresh });
  }
  if (section === "feed-config") {
    await loadAdminFeedConfigHistory({ refresh });
    return;
  }
  if (section === "policy-questions") {
    await loadAdminPolicyQuestionIssueCatalog({ refresh });
  }
  if (detailId) {
    await loadAdminDetail(section, detailId, { refresh });
    if (section === "election-sources") {
      await loadAdminCertificationImports(detailId, { refresh });
    }
  }
}

function applyPostComposerPublishingDefaults() {
  const composer = state.pages.create;
  const publishing = state.pages.settings.publishing;
  if (!publishing.loaded || composer.publishingDefaultsApplied) {
    return;
  }
  const defaults = publishing.item || defaultPublishingDefaults();
  const preferences = normalizePostReviewPreferences(
    defaults.postReviewPreferences || {},
  );
  composer.visibility = normalizePostComposerVisibility(
    defaults.defaultPostVisibility,
  );
  composer.audienceGroupIds =
    composer.visibility === "custom"
      ? normalizeStringList(defaults.defaultAudienceGroupIds).join(", ")
      : "";
  composer.allowComments = preferences.allowComments;
  composer.allowReuseContent = preferences.allowReuseContent;
  composer.aiGeneratedContent = preferences.aiGeneratedContent;
  composer.saveToDevice = preferences.saveToDevice;
  composer.savePostsWithWatermark = preferences.savePostsWithWatermark !== false;
  composer.brandingOverlayEnabled = preferences.brandingOverlayEnabled !== false;
  composer.publishingDefaultsApplied = true;
}

function applyPostComposerCrosspostDefaults() {
  const composer = state.pages.create;
  const social = state.pages.settings.social;
  const crosspost = state.pages.settings.crosspost;
  if (
    composer.crosspostSelectionInitialized ||
    !social.loaded ||
    !crosspost.loaded
  ) {
    return;
  }
  const defaults = crosspost.item || defaultCrosspostDefaults();
  composer.youtubePrivacy = defaults.youtubePrivacy;
  composer.youtubeTitle = defaults.youtubeTitle;
  composer.youtubeDescription = defaults.youtubeDescription;
  const selectedPreferenceKeys = new Set(
    normalizeStringList(defaults.selectedTargetKeys),
  );
  const selectedTargets = postComposerCrosspostTargets().filter((target) => {
    if (!selectedPreferenceKeys.has(postComposerCrosspostPreferenceKey(target))) {
      return false;
    }
    return !postComposerCrosspostTargetDisabledReason(target, composer);
  });
  composer.selectedCrosspostTargetKeys = selectedTargets.map(
    postComposerCrosspostSelectionKey,
  );
  composer.crosspostSelectionInitialized = true;
}

async function loadPostComposerPage({ refresh = false } = {}) {
  scheduleRender();
  await Promise.all([
    loadPublishingDefaults({ refresh }).catch(() => {}),
    loadCrosspostDefaults({ refresh }).catch(() => {}),
    loadSettingsSocialConnections({ refresh }).catch(() => {}),
    loadSettingsAudienceGroups({ refresh }).catch(() => {}),
    loadPostComposerIssueCatalog({ refresh }).catch(() => {}),
  ]);
  applyPostComposerPublishingDefaults();
  applyPostComposerCrosspostDefaults();
  syncFocusedPostComposerFieldBeforeRender();
  scheduleRender();
}

function adminPendingKey(itemId, actionKey) {
  return `${normalizeString(itemId) || "section"}:${normalizeString(actionKey)}`;
}

