function messagingServerMediaUploadsState() {
  const settingsState = state.pages.messaging.serverSettings;
  settingsState.mediaUploads =
    settingsState.mediaUploads || createMessagingServerMediaUploadsState();
  settingsState.mediaUploads.avatar =
    settingsState.mediaUploads.avatar ||
    createMessagingServerMediaUploadState("avatar");
  settingsState.mediaUploads.banner =
    settingsState.mediaUploads.banner ||
    createMessagingServerMediaUploadState("banner");
  return settingsState.mediaUploads;
}

function messagingServerMediaUploadState(kind) {
  const mediaKind = normalizeMessagingServerMediaKind(kind);
  return messagingServerMediaUploadsState()[mediaKind];
}

function messagingServerMediaCurrentUrl(kind, server = {}) {
  const mediaKind = normalizeMessagingServerMediaKind(kind);
  if (mediaKind === "banner") {
    return normalizeUrl(server.bannerUrl || server.raw?.bannerUrl || server.raw?.coverUrl);
  }
  return normalizeUrl(server.avatarUrl || server.raw?.avatarUrl || server.raw?.iconUrl);
}

function clearCandidateAvatarUpload({ abort = true } = {}) {
  const detail = state.pages.candidates.detail;
  const upload = detail.avatarUpload || createCandidateAvatarUploadState();
  if (abort && upload.uploadId) {
    abortCandidateAvatarUpload(upload.uploadId).catch(() => {});
  }
  if (detail.item && upload.remoteUrl) {
    detail.item = {
      ...detail.item,
      avatarUrl: upload.previousAvatarUrl,
      avatarUploadId: upload.previousAvatarUploadId,
    };
  }
  detail.avatarUpload = createCandidateAvatarUploadState();
  scheduleRender();
}

function clearProfileAvatarUpload({ abort = true } = {}) {
  const profileState = state.pages.profile;
  const upload = profileState.avatarUpload || createProfileAvatarUploadState();
  if (abort && upload.uploadId) {
    abortProfileAvatarUpload(upload.uploadId).catch(() => {});
  }
  if (upload.previewUrl) {
    window.URL?.revokeObjectURL(upload.previewUrl);
  }
  if (upload.remoteUrl) {
    const previousAvatarUrl = upload.previousAvatarUrl || "";
    const previousAvatarUploadId = upload.previousAvatarUploadId || "";
    if (profileState.me) {
      profileState.me = {
        ...profileState.me,
        avatarUrl: previousAvatarUrl,
        avatarUploadId: previousAvatarUploadId,
      };
    }
    if (profileState.current) {
      profileState.current = {
        ...profileState.current,
        avatarUrl: previousAvatarUrl,
        avatarUploadId: previousAvatarUploadId,
      };
    }
  }
  profileState.avatarUpload = createProfileAvatarUploadState();
  scheduleRender();
}

