async function uploadCandidateAvatarFile(file) {
  const detail = state.pages.candidates.detail;
  if (!file) {
    return;
  }
  if (!normalizeString(file.type).startsWith("image/")) {
    detail.avatarUpload = {
      ...createCandidateAvatarUploadState(),
      error: "Choose an image file.",
    };
    scheduleRender();
    return;
  }
  if (Number(file.size) <= 0) {
    detail.avatarUpload = {
      ...createCandidateAvatarUploadState(),
      error: "Selected image is empty.",
    };
    scheduleRender();
    return;
  }

  const previousUpload = detail.avatarUpload || createCandidateAvatarUploadState();
  if (previousUpload.uploadId) {
    abortCandidateAvatarUpload(previousUpload.uploadId).catch(() => {});
  }
  const previousAvatarUrl =
    previousUpload.previousAvatarUrl || normalizeString(detail.item?.avatarUrl);
  const previousAvatarUploadId =
    previousUpload.previousAvatarUploadId ||
    normalizeString(detail.item?.avatarUploadId);
  detail.avatarUpload = {
    ...createCandidateAvatarUploadState(),
    uploading: true,
    previousAvatarUrl,
    previousAvatarUploadId,
  };
  scheduleRender();

  try {
    const contentType = normalizeString(file.type) || "image/jpeg";
    const fileName = normalizeString(file.name) || "candidate-avatar.jpg";
    const uploadPayload = await fetchJson("/api/uploads/create", {
      auth: true,
      method: "POST",
      body: {
        type: "image",
        fileName,
        fileSize: Number(file.size) || 0,
        contentType,
      },
    });
    const upload = normalizeCreateUploadPayload(uploadPayload);
    if (!upload.uid || !upload.uploadUrl) {
      throw new Error("Upload session was incomplete.");
    }
    await uploadPostComposerFile(upload, file);
    const remoteUrl = upload.deliveryUrl || upload.publicUrl;
    if (!remoteUrl) {
      throw new Error("Upload finished without a candidate photo URL.");
    }
    detail.avatarUpload = {
      uploading: false,
      error: "",
      uploadId: upload.uid,
      remoteUrl,
      fileName,
      previousAvatarUrl,
      previousAvatarUploadId,
    };
    if (detail.item) {
      detail.item = {
        ...detail.item,
        avatarUrl: remoteUrl,
        avatarUploadId: upload.uid,
      };
    }
  } catch (error) {
    detail.avatarUpload = {
      ...createCandidateAvatarUploadState(),
      error: candidateAvatarUploadErrorMessage(error),
      previousAvatarUrl,
      previousAvatarUploadId,
    };
  } finally {
    scheduleRender();
  }
}

async function uploadPetitionCoverFile(ownerType, ownerId, file) {
  const normalizedOwnerType =
    normalizeString(ownerType).toLowerCase() || "candidate";
  const normalizedOwnerId = normalizeString(ownerId);
  const workspace = petitionWorkspaceForOwner(normalizedOwnerType);
  const draft = syncPetitionBuilderDraftFromDom(normalizedOwnerType);
  const previousUpload =
    workspace.coverUpload || createPetitionCoverUploadState();
  const previousCoverImageUrl =
    previousUpload.previousCoverImageUrl || normalizeString(draft.coverImageUrl);
  const previousCoverImageUploadId =
    previousUpload.previousCoverImageUploadId ||
    normalizeString(draft.coverImageUploadId);
  const resetWithError = (message) => {
    workspace.coverUpload = {
      ...createPetitionCoverUploadState(),
      error: message,
      ownerType: normalizedOwnerType,
      ownerId: normalizedOwnerId,
      previousCoverImageUrl,
      previousCoverImageUploadId,
    };
    scheduleRender();
  };

  if (!file) {
    return;
  }
  if (!normalizeString(file.type).startsWith("image/")) {
    resetWithError("Choose an image file.");
    return;
  }
  if (Number(file.size) <= 0) {
    resetWithError("Selected image is empty.");
    return;
  }
  if (Number(file.size) > MESSAGING_ATTACHMENT_IMAGE_MAX_BYTES) {
    resetWithError(
      `Images must be ${formatComposerFileSize(MESSAGING_ATTACHMENT_IMAGE_MAX_BYTES)} or smaller.`,
    );
    return;
  }

  if (previousUpload.uploadId) {
    abortPetitionCoverUpload(previousUpload.uploadId).catch(() => {});
  }
  if (previousUpload.previewUrl) {
    window.URL?.revokeObjectURL(previousUpload.previewUrl);
  }
  const previewUrl = window.URL?.createObjectURL(file) || "";
  const fileName = normalizeString(file.name) || "petition-cover.jpg";
  workspace.coverUpload = {
    ...createPetitionCoverUploadState(),
    uploading: true,
    ownerType: normalizedOwnerType,
    ownerId: normalizedOwnerId,
    fileName,
    previewUrl,
    previousCoverImageUrl,
    previousCoverImageUploadId,
  };
  scheduleRender();

  try {
    const contentType = normalizeString(file.type) || "image/jpeg";
    const uploadPayload = await fetchJson("/api/uploads/create", {
      auth: true,
      method: "POST",
      body: {
        type: "image",
        fileName,
        fileSize: Number(file.size) || 0,
        contentType,
      },
    });
    const upload = normalizeCreateUploadPayload(uploadPayload);
    if (!upload.uid || !upload.uploadUrl) {
      throw new Error("Upload session was incomplete.");
    }
    await uploadPostComposerFile(upload, file);
    const remoteUrl = upload.deliveryUrl || upload.publicUrl;
    if (!remoteUrl) {
      throw new Error("Upload finished without a petition cover URL.");
    }
    if (previewUrl) {
      window.URL?.revokeObjectURL(previewUrl);
    }
    workspace.coverUpload = {
      ...createPetitionCoverUploadState(),
      ownerType: normalizedOwnerType,
      ownerId: normalizedOwnerId,
      uploadId: upload.uid,
      remoteUrl,
      fileName,
      previousCoverImageUrl,
      previousCoverImageUploadId,
    };
    workspace.draft = {
      ...workspace.draft,
      coverImageUrl: remoteUrl,
      coverImageUploadId: upload.uid,
    };
  } catch (error) {
    if (previewUrl) {
      window.URL?.revokeObjectURL(previewUrl);
    }
    workspace.coverUpload = {
      ...createPetitionCoverUploadState(),
      ownerType: normalizedOwnerType,
      ownerId: normalizedOwnerId,
      error: petitionCoverUploadErrorMessage(error),
      previousCoverImageUrl,
      previousCoverImageUploadId,
    };
    workspace.draft = {
      ...workspace.draft,
      coverImageUrl: previousCoverImageUrl,
      coverImageUploadId: previousCoverImageUploadId,
    };
  } finally {
    scheduleRender();
  }
}

