async function uploadMessagingServerMediaFile(kind, file) {
  const mediaKind = normalizeMessagingServerMediaKind(kind);
  const settingsState = state.pages.messaging.serverSettings;
  const server = settingsState.item?.server || {};
  const scopeType = normalizeString(server.scopeType).toLowerCase();
  const scopeId = normalizeString(server.scopeId);
  const uploads = messagingServerMediaUploadsState();
  const previousUpload =
    uploads[mediaKind] || createMessagingServerMediaUploadState(mediaKind);
  const previousUrl =
    previousUpload.previousUrl ||
    messagingServerMediaCurrentUrl(mediaKind, server);
  const resetWithError = (message) => {
    uploads[mediaKind] = {
      ...createMessagingServerMediaUploadState(mediaKind),
      error: message,
      scopeType,
      scopeId,
      previousUrl,
    };
    scheduleRender();
  };

  if (!file) {
    return;
  }
  if (!scopeType || !scopeId || !settingsState.item) {
    resetWithError("Workspace settings are unavailable.");
    return;
  }
  if (server.canManage !== true) {
    resetWithError(
      `Manager access is required to update the ${messagingServerMediaLabel(mediaKind)}.`,
    );
    return;
  }
  if (!normalizeString(file.type).startsWith("image/")) {
    resetWithError("Choose an image file.");
    return;
  }
  if (Number(file.size) <= 0) {
    resetWithError("Selected image is empty.");
    return;
  }
  if (Number(file.size) > MESSAGING_ATTACHMENT_IMAGE_MAX_BYTES) {
    resetWithError(
      `Images must be ${formatComposerFileSize(MESSAGING_ATTACHMENT_IMAGE_MAX_BYTES)} or smaller.`,
    );
    return;
  }

  if (previousUpload.uploadId) {
    abortMessagingServerMediaUpload(previousUpload.uploadId).catch(() => {});
  }
  if (previousUpload.previewUrl) {
    window.URL?.revokeObjectURL(previousUpload.previewUrl);
  }
  const previewUrl = window.URL?.createObjectURL(file) || "";
  const fileName =
    normalizeString(file.name) ||
    (mediaKind === "banner" ? "workspace-banner.jpg" : "workspace-icon.jpg");
  uploads[mediaKind] = {
    ...createMessagingServerMediaUploadState(mediaKind),
    uploading: true,
    scopeType,
    scopeId,
    fileName,
    previewUrl,
    previousUrl,
  };
  scheduleRender();

  try {
    const contentType = normalizeString(file.type) || "image/jpeg";
    const uploadPayload = await fetchJson("/api/uploads/create", {
      auth: true,
      method: "POST",
      body: {
        type: "image",
        fileName,
        fileSize: Number(file.size) || 0,
        contentType,
      },
    });
    const upload = normalizeCreateUploadPayload(uploadPayload);
    if (!upload.uid || !upload.uploadUrl) {
      throw new Error("Upload session was incomplete.");
    }
    await uploadPostComposerFile(upload, file);
    const remoteUrl = upload.deliveryUrl || upload.publicUrl;
    if (!remoteUrl) {
      throw new Error(`Upload finished without a ${messagingServerMediaLabel(mediaKind)} URL.`);
    }
    if (previewUrl) {
      window.URL?.revokeObjectURL(previewUrl);
    }
    uploads[mediaKind] = {
      ...createMessagingServerMediaUploadState(mediaKind),
      scopeType,
      scopeId,
      uploadId: upload.uid,
      remoteUrl,
      fileName,
      previousUrl,
    };
  } catch (error) {
    if (previewUrl) {
      window.URL?.revokeObjectURL(previewUrl);
    }
    uploads[mediaKind] = {
      ...createMessagingServerMediaUploadState(mediaKind),
      scopeType,
      scopeId,
      error: messagingServerMediaUploadErrorMessage(mediaKind, error),
      previousUrl,
    };
  } finally {
    scheduleRender();
  }
}

function coalitionImageUploadStateForTarget(target = "start") {
  const normalizedTarget = normalizeString(target).toLowerCase();
  if (normalizedTarget === "edit") {
    const detail = state.pages.coalitions.detail;
    detail.imageUpload =
      detail.imageUpload || createCoalitionImageUploadState();
    return detail.imageUpload;
  }
  const onboarding = state.pages.coalitions.onboarding;
  onboarding.imageUpload =
    onboarding.imageUpload || createCoalitionImageUploadState();
  return onboarding.imageUpload;
}

function setCoalitionImageUploadState(target = "start", nextUpload = {}) {
  const normalizedTarget = normalizeString(target).toLowerCase();
  const normalizedUpload = {
    ...createCoalitionImageUploadState(),
    ...nextUpload,
  };
  if (normalizedTarget === "edit") {
    state.pages.coalitions.detail.imageUpload = normalizedUpload;
    return normalizedUpload;
  }
  state.pages.coalitions.onboarding.imageUpload = normalizedUpload;
  return normalizedUpload;
}

function coalitionImageUploadErrorMessage(error) {
  if (error?.status === 401) {
    return "Please sign in to upload a coalition image.";
  }
  if (error?.status === 413) {
    return "That image is too large for upload.";
  }
  return normalizeString(error?.message) || "Coalition image could not be uploaded.";
}

async function abortCoalitionImageUpload(uploadId) {
  const normalizedUploadId = normalizeString(uploadId);
  if (!normalizedUploadId) {
    return;
  }
  await fetchJson("/api/uploads/abort", {
    auth: true,
    method: "POST",
    body: { uploadId: normalizedUploadId },
  }).catch(() => {});
}

function clearCoalitionImageUpload(target = "start", { abort = true } = {}) {
  const upload = coalitionImageUploadStateForTarget(target);
  if (abort && upload.uploadId) {
    abortCoalitionImageUpload(upload.uploadId).catch(() => {});
  }
  setCoalitionImageUploadState(target, createCoalitionImageUploadState());
  scheduleRender();
}

async function uploadCoalitionImageFile(target = "start", file) {
  const normalizedTarget = normalizeString(target).toLowerCase() || "start";
  if (!file) {
    return;
  }
  if (!normalizeString(file.type).startsWith("image/")) {
    setCoalitionImageUploadState(normalizedTarget, {
      error: "Choose an image file.",
    });
    scheduleRender();
    return;
  }
  if (Number(file.size) <= 0) {
    setCoalitionImageUploadState(normalizedTarget, {
      error: "Selected image is empty.",
    });
    scheduleRender();
    return;
  }

  const previousUpload = coalitionImageUploadStateForTarget(normalizedTarget);
  if (previousUpload.uploadId) {
    abortCoalitionImageUpload(previousUpload.uploadId).catch(() => {});
  }
  setCoalitionImageUploadState(normalizedTarget, {
    uploading: true,
  });
  scheduleRender();

  try {
    const contentType = normalizeString(file.type) || "image/jpeg";
    const fileName = normalizeString(file.name) || "coalition-image.jpg";
    const uploadPayload = await fetchJson("/api/uploads/create", {
      auth: true,
      method: "POST",
      body: {
        type: "image",
        fileName,
        fileSize: Number(file.size) || 0,
        contentType,
      },
    });
    const upload = normalizeCreateUploadPayload(uploadPayload);
    if (!upload.uid || !upload.uploadUrl) {
      throw new Error("Upload session was incomplete.");
    }
    await uploadPostComposerFile(upload, file);
    const remoteUrl = upload.deliveryUrl || upload.publicUrl;
    if (!remoteUrl) {
      throw new Error("Upload finished without a coalition image URL.");
    }
    setCoalitionImageUploadState(normalizedTarget, {
      uploading: false,
      uploadId: upload.uid,
      remoteUrl,
      fileName,
    });
  } catch (error) {
    setCoalitionImageUploadState(normalizedTarget, {
      error: coalitionImageUploadErrorMessage(error),
    });
  } finally {
    scheduleRender();
  }
}

function postComposerErrorMessage(error) {
  if (error?.status === 401) {
    return "Please sign in to create posts.";
  }
  if (error?.status === 413) {
    return "That file is too large for upload.";
  }
  return normalizeString(error?.message) || "Post could not be published.";
}

function postComposerReviewPreferences(composer = state.pages.create) {
  return {
    brandingOverlayEnabled: true,
    allowComments: composer.allowComments === true,
    allowReuseContent: composer.allowReuseContent === true,
    aiGeneratedContent: composer.aiGeneratedContent === true,
    saveToDevice: composer.saveToDevice === true,
    savePostsWithWatermark: true,
  };
}

function normalizePostComposerSaveAsset(payload) {
  const raw = payload?.asset && typeof payload.asset === "object"
    ? payload.asset
    : payload;
  return {
    status: normalizeString(raw?.status).toLowerCase() || "queued",
    progress: Number.isFinite(Number(raw?.progress))
      ? Math.max(0, Math.min(1, Number(raw.progress)))
      : Number.isFinite(Number(raw?.progressPct))
        ? Math.max(0, Math.min(1, Number(raw.progressPct) / 100))
        : null,
    retryAfterMs: Math.max(1000, Number(raw?.retryAfterMs) || 3000),
    url: normalizeUrl(raw?.url),
    fileName: normalizeString(raw?.fileName) || "polis-video.mp4",
  };
}

function postComposerSaveAssetLabel(asset) {
  const status = normalizeString(asset?.status).toLowerCase();
  if (status === "ready") {
    return "Download ready";
  }
  if (status === "rendering") {
    return "Rendering watermarked copy";
  }
  if (status === "source_pending") {
    return "Waiting for video processing";
  }
  if (status === "failed") {
    return "Save copy failed";
  }
  return "Preparing watermarked copy";
}

function updatePostComposerSaveExport(patch = {}) {
  const composer = state.pages.create;
  composer.saveExport = createPostComposerSaveExportState({
    ...(composer.saveExport || {}),
    ...patch,
  });
  scheduleRender();
}

function triggerPostComposerBrowserDownload(url, fileName) {
  const safeUrl = normalizeUrl(url);
  if (!safeUrl) {
    return false;
  }
  const link = document.createElement("a");
  link.href = safeUrl;
  link.download = normalizeString(fileName) || "polis-video.mp4";
  link.rel = "noopener";
  link.style.display = "none";
  document.body.appendChild(link);
  try {
    link.click();
  } finally {
    link.remove();
  }
  return true;
}

function waitForPostComposerSaveRetry(ms) {
  return new Promise((resolve) => {
    window.setTimeout(resolve, Math.max(500, Number(ms) || 1000));
  });
}

async function preparePostComposerSaveDownload(postId, { attempts = 12 } = {}) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    return;
  }
  updatePostComposerSaveExport({
    status: "queued",
    label: "Preparing watermarked copy",
    progress: 0.02,
    error: "",
  });
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const payload = await fetchJson(
      `/api/posts/${encodeURIComponent(normalizedPostId)}/share-assets/social-video`,
      { auth: true, method: "POST", body: {} },
    );
    const asset = normalizePostComposerSaveAsset(payload);
    updatePostComposerSaveExport({
      status: asset.status,
      label: postComposerSaveAssetLabel(asset),
      progress: asset.progress,
      url: asset.url,
      fileName: asset.fileName,
      error: "",
    });
    if (asset.status === "ready" && asset.url) {
      triggerPostComposerBrowserDownload(asset.url, asset.fileName);
      updatePostComposerSaveExport({
        status: "ready",
        label: "Download started",
        progress: 1,
        url: asset.url,
        fileName: asset.fileName,
        error: "",
      });
      showToast("Watermarked video download started.");
      return;
    }
    if (asset.status === "failed") {
      throw new Error("Watermarked video render failed.");
    }
    await waitForPostComposerSaveRetry(asset.retryAfterMs);
  }
  updatePostComposerSaveExport({
    status: "queued",
    label: "Still preparing",
    error: "The watermarked copy is still preparing. Use the download link when it becomes ready.",
  });
}

async function submitPostComposer(formData) {
  const composer = state.pages.create;
  if (composer.pending) {
    return;
  }
  updatePostComposerField("description", formData.get("description"));
  updatePostComposerField("issueIds", formData.get("issueIds"));
  updatePostComposerField("visibility", formData.get("visibility"));
  updatePostComposerField("audienceGroupIds", formData.get("audienceGroupIds"));
  updatePostComposerField("allowComments", formData.has("allowComments"));
  updatePostComposerField("allowReuseContent", formData.has("allowReuseContent"));
  updatePostComposerField(
    "aiGeneratedContent",
    formData.has("aiGeneratedContent"),
  );
  updatePostComposerField(
    "saveToDevice",
    composer.mediaType === "video" && formData.has("saveToDevice"),
  );
  if (formData.has("youtubeTitle")) {
    updatePostComposerField("youtubeTitle", formData.get("youtubeTitle"));
  }
  if (formData.has("youtubeDescription")) {
    updatePostComposerField(
      "youtubeDescription",
      formData.get("youtubeDescription"),
    );
  }
  if (formData.has("youtubePrivacy")) {
    updatePostComposerField("youtubePrivacy", formData.get("youtubePrivacy"));
  }
  if (composer.captionError) {
    composer.error = composer.captionError;
    scheduleRender();
    return;
  }
  if (!composer.file) {
    composer.error = "Choose or record media before publishing.";
    scheduleRender();
    return;
  }
  const durationError = postComposerVideoDurationError(composer);
  if (durationError) {
    composer.error = durationError;
    scheduleRender();
    return;
  }
  const invalidCrosspost = firstInvalidPostComposerCrosspostSelection(composer);
  if (invalidCrosspost) {
    composer.error = `${invalidCrosspost.target.label || "Publish target"}: ${invalidCrosspost.reason}`;
    scheduleRender();
    return;
  }
  if (postComposerHasSelectedYouTubeTarget(composer)) {
    ensurePostComposerYouTubeDefaults(composer);
    if (
      !normalizeString(composer.youtubeTitle) ||
      !normalizeString(composer.youtubeDescription)
    ) {
      composer.error = "YouTube crossposts require a title and description.";
      scheduleRender();
      return;
    }
  }

  const file = composer.file;
  if (Number(file.size) <= 0) {
    composer.error = "Selected media is empty. Choose or record it again.";
    scheduleRender();
    return;
  }
  const mediaType = composer.mediaType === "video" ? "video" : "image";
  const contentType =
    normalizeString(file.type) ||
    (mediaType === "video" ? "video/mp4" : "image/jpeg");
  const fileName =
    normalizeString(file.name) ||
    `polis-${mediaType}.${mediaType === "video" ? "mp4" : "jpg"}`;
  composer.pending = true;
  composer.stage = "Preparing upload";
  composer.error = "";
  composer.notice = "";
  composer.createdPostId = "";
  composer.saveExport = createPostComposerSaveExportState();
  scheduleRender();

  try {
    const uploadPayload = await fetchJson("/api/uploads/create", {
      auth: true,
      method: "POST",
      body: {
        type: mediaType,
        fileName,
        fileSize: Number(file.size) || 0,
        contentType,
        ...(mediaType === "video"
          ? { maxDurationSeconds: POST_COMPOSER_MAX_VIDEO_SECONDS }
          : {}),
      },
    });
    const upload = normalizeCreateUploadPayload(uploadPayload);
    if (!upload.uid || !upload.uploadUrl) {
      throw new Error("Upload session was incomplete.");
    }

    composer.stage = `Uploading ${mediaType}`;
    scheduleRender();
    await uploadPostComposerFile(upload, file);

    const description = normalizeString(composer.description);
    const issueIds = readPostComposerIssueIds(composer.issueIds);
    const audienceGroupIds =
      composer.visibility === "custom"
        ? readPostComposerAudienceGroupIds(composer.audienceGroupIds)
        : [];
    const crosspostSelections = buildPostComposerCrosspostSelections(composer);
    const crosspostDraft = buildPostComposerCrosspostDraft(composer);
    const reviewPreferences = postComposerReviewPreferences(composer);
    const postId = upload.postId || upload.uid;
    let coverPayload = null;
    let coverFrameMs = null;
    if (mediaType === "video") {
      await uploadPostComposerCoverImageIfNeeded(composer);
      coverPayload = postComposerCoverPayload(composer);
      coverFrameMs = postComposerCoverFrameMs(composer);
    }
    const editTimeline =
      mediaType === "video" ? buildPostComposerEditTimeline(composer) : "";
    const editRange =
      mediaType === "video" ? postComposerTrimRange(composer) : null;
    const editDraft = mediaType === "video"
      ? normalizePostComposerEdit(composer)
      : null;
    const trimPayload =
      editDraft?.trimEnabled &&
      editRange?.durationMs > 0 &&
      (editRange.startMs > 0 || editRange.endMs < editRange.durationMs)
        ? {
            startMs: Math.round(editRange.startMs),
            endMs: Math.round(editRange.endMs),
          }
        : null;
    composer.stage = "Saving post details";
    scheduleRender();
    await fetchJson("/api/posts/metadata", {
      auth: true,
      method: "POST",
      body: {
        postId,
        uid: upload.uid,
        type: mediaType,
        description,
        fileName,
        fileSize: Number(file.size) || 0,
        contentType,
        allowComments: composer.allowComments,
        allowReuseContent: composer.allowReuseContent,
        aiGeneratedContent: composer.aiGeneratedContent,
        postReviewPreferences: reviewPreferences,
        ...(mediaType === "video"
          ? {
              coverFrameMs,
              cover: coverPayload,
              ...(editTimeline ? { editTimeline } : {}),
            }
          : {}),
      },
    });

    composer.stage = "Publishing post";
    scheduleRender();
    const createPayload = await fetchJson("/api/posts", {
      auth: true,
      method: "POST",
      body: {
        type: mediaType,
        cfUid: upload.uid,
        ...(mediaType === "image"
          ? {
              imageKey: upload.uid,
              imageUrl: upload.deliveryUrl || upload.publicUrl || undefined,
            }
          : {
              originalSize: Number(file.size) || undefined,
              masterSize: Number(file.size) || undefined,
            }),
        postId,
        description,
        visibility: composer.visibility,
        ...(composer.visibility === "custom" ? { audienceGroupIds } : {}),
        issueIds,
        ...(trimPayload ? { trim: trimPayload } : {}),
        ...(editTimeline ? { editTimeline } : {}),
        allowComments: composer.allowComments,
        allowReuseContent: composer.allowReuseContent,
        aiGeneratedContent: composer.aiGeneratedContent,
        postReviewPreferences: reviewPreferences,
        ...(crosspostSelections.length
          ? {
              crosspostSelections,
              crosspostDraft,
            }
          : {}),
      },
    });
    composer.createdPostId =
      normalizeString(
        createPayload.postId ||
          createPayload.post?.postId ||
          createPayload.item?.postId,
      ) || postId;
    composer.notice =
      mediaType === "video" && composer.saveToDevice
        ? "Video upload started. Preparing the watermarked save copy."
        : mediaType === "video"
        ? "Video upload started. It will appear when processing finishes."
        : "Post published.";
    showToast(composer.notice);
    if (mediaType === "video" && composer.saveToDevice) {
      preparePostComposerSaveDownload(composer.createdPostId).catch((error) => {
        updatePostComposerSaveExport({
          status: "failed",
          label: "Save copy failed",
          error:
            normalizeString(error?.message) ||
            "Watermarked video could not be prepared.",
        });
        showToast("Watermarked video could not be saved yet.");
      });
    }
  } catch (error) {
    composer.error = postComposerErrorMessage(error);
    showToast(composer.error);
  } finally {
    composer.pending = false;
    composer.stage = "";
    scheduleRender();
  }
}

async function loadSettingsMyProfile({ refresh = false } = {}) {
  const profile = state.pages.settings.voterProfile.profile;
  if (profile.loaded && !refresh) {
    return;
  }
  profile.loading = true;
  profile.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson("/api/profile/me", { auth: true });
    profile.item = normalizeMyProfile(payload);
    profile.loaded = true;
  } catch (error) {
    profile.error = settingsErrorMessage(error, "Voter profile could not be loaded.");
  } finally {
    profile.loading = false;
    scheduleRender();
  }
}

async function loadSettingsMyDistricts({ refresh = false } = {}) {
  const districts = state.pages.settings.voterProfile.districts;
  if (districts.loaded && !refresh) {
    return;
  }
  districts.loading = true;
  districts.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson("/api/me/districts?includeElections=1", {
      auth: true,
    });
    districts.item = normalizeMyDistricts(payload);
    districts.loaded = true;
  } catch (error) {
    const code = normalizeString(error?.message || error?.payload?.error);
    if (code === "home_address_missing" || code === "profile_not_found") {
      districts.item = null;
      districts.loaded = true;
      districts.error = "";
    } else {
      districts.error = settingsErrorMessage(
        error,
        "District context could not be loaded.",
      );
    }
  } finally {
    districts.loading = false;
    scheduleRender();
  }
}

function settingsHomeLocationErrorMessage(error, fallback) {
  const code = normalizeString(error?.payload?.error || error?.message).toLowerCase();
  if (code === "address_change_review_required" || error?.status === 403) {
    return "Verified accounts require review to change home location.";
  }
  if (code === "home_address_preferred" || error?.status === 409) {
    return "A saved home address is already being used for your districts.";
  }
  if (code === "manual_district_update_rate_limited") {
    const nextAllowedAt = Number(error?.payload?.nextAllowedAt) || 0;
    return nextAllowedAt
      ? `Manual district changes unlock ${formatSettingsDate(nextAllowedAt)}.`
      : "Manual district changes are limited to once every 60 days.";
  }
  if (
    code === "invalid_stateid" ||
    code === "invalid_state" ||
    code === "district_state_mismatch"
  ) {
    return "Choose a valid state for this district.";
  }
  if (code === "invalid_congressionaldistrictid") {
    return "Choose a valid congressional district.";
  }
  return settingsErrorMessage(error, fallback);
}

async function loadSettingsManualDistrictOptions(stateId, { refresh = false } = {}) {
  const resource = state.pages.settings.voterProfile.manualDistrict;
  const normalizedStateId = normalizeString(stateId).toUpperCase();
  if (!normalizedStateId) {
    resource.items = [];
    resource.loadedStateId = "";
    resource.error = "";
    scheduleRender();
    return;
  }
  if (
    resource.loadedStateId === normalizedStateId &&
    resource.items.length &&
    !refresh
  ) {
    return;
  }
  resource.stateId = normalizedStateId;
  resource.loading = true;
  resource.error = "";
  scheduleRender();
  try {
    const query = new URLSearchParams({ stateId: normalizedStateId });
    const payload = await fetchJson(
      `/api/geo/congressional-districts?${query.toString()}`,
      { auth: Boolean(state.auth.session) },
    );
    const items = readArrayPayload(payload, ["districts", "items"])
      .map(normalizeSettingsCongressionalDistrictOption)
      .filter((item) => item.stateId && item.congressionalDistrictId);
    resource.items = items;
    resource.loadedStateId = normalizedStateId;
    if (
      resource.selectedDistrictId &&
      !items.some(
        (item) => item.congressionalDistrictId === resource.selectedDistrictId,
      )
    ) {
      resource.selectedDistrictId = "";
    }
  } catch (error) {
    resource.items = [];
    resource.loadedStateId = "";
    resource.error = settingsHomeLocationErrorMessage(
      error,
      "Districts could not be loaded.",
    );
  } finally {
    resource.loading = false;
    scheduleRender();
  }
}

async function saveSettingsManualDistrict(formData) {
  const voterProfile = state.pages.settings.voterProfile;
  const resource = voterProfile.manualDistrict;
  const stateId = normalizeString(formData.get("stateId") || resource.stateId).toUpperCase();
  const congressionalDistrictId = normalizeString(
    formData.get("congressionalDistrictId") || resource.selectedDistrictId,
  ).toUpperCase();
  const acknowledgedRestrictions = formCheckboxValue(
    formData,
    "acknowledgedRestrictions",
    resource.acknowledged === true,
  );
  if (!stateId || !congressionalDistrictId) {
    resource.error = "Choose a state and congressional district.";
    showToast(resource.error);
    scheduleRender();
    return false;
  }
  if (!acknowledgedRestrictions) {
    resource.error = "Acknowledge the manual district restrictions before saving.";
    showToast(resource.error);
    scheduleRender();
    return false;
  }
  resource.saving = true;
  resource.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson("/api/me/home-location/manual-district", {
      auth: true,
      method: "PUT",
      body: {
        stateId,
        congressionalDistrictId,
        acknowledgedRestrictions: true,
      },
    });
    const nextProfile = payload.profile ? normalizeMyProfile(payload) : null;
    if (nextProfile?.userId) {
      voterProfile.profile.item = nextProfile;
      voterProfile.profile.loaded = true;
    }
    resource.stateId = stateId;
    resource.selectedDistrictId = congressionalDistrictId;
    resource.acknowledged = false;
    showToast(payload.saved === false ? "Home district saved." : "Home district updated.");
    await Promise.all([
      loadSettingsMyProfile({ refresh: true }),
      loadSettingsMyDistricts({ refresh: true }),
    ]);
    return true;
  } catch (error) {
    resource.error = settingsHomeLocationErrorMessage(
      error,
      "Home district could not be saved.",
    );
    showToast(resource.error);
    return false;
  } finally {
    resource.saving = false;
    scheduleRender();
  }
}

async function loadSettingsManualDistrictForCurrentProfile({ refresh = false } = {}) {
  await loadSettingsMyProfile({ refresh });
  const voterProfile = state.pages.settings.voterProfile;
  const profile = voterProfile.profile.item || normalizeMyProfile();
  if (settingsProfileIsVerified(profile) || settingsProfileHasSavedAddress(profile)) {
    return;
  }
  const resource = voterProfile.manualDistrict;
  const stateId =
    resource.stateId ||
    profile.manualDistrictStateId ||
    profile.locationStateId ||
    "";
  if (stateId) {
    await loadSettingsManualDistrictOptions(stateId, { refresh });
  }
}

