async function saveSettingsHomeLocation(formData) {
  const voterProfile = state.pages.settings.voterProfile;
  const redirectTo = normalizeString(formData.get("redirectTo"));
  const addressLine1 = normalizeString(formData.get("addressLine1"));
  const city = normalizeString(formData.get("city"));
  const stateId = normalizeString(formData.get("state")).toUpperCase();
  if (!addressLine1 || !city || !stateId) {
    voterProfile.profile.error = "Address, city, and state are required.";
    showToast(voterProfile.profile.error);
    scheduleRender();
    return;
  }
  voterProfile.homeLocationSaving = true;
  voterProfile.profile.error = "";
  voterProfile.districts.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson("/api/me/home-location/address", {
      auth: true,
      method: "PUT",
      body: {
        addressLine1,
        addressLine2: normalizeString(formData.get("addressLine2")),
        city,
        state: stateId,
        postalCode: normalizeString(formData.get("postalCode")),
      },
    });
    const nextProfile = payload.profile ? normalizeMyProfile(payload) : null;
    if (nextProfile?.userId) {
      voterProfile.profile.item = nextProfile;
      voterProfile.profile.loaded = true;
    }
    showToast(
      payload.requested === true
        ? "Home location review requested."
        : "Home location saved.",
    );
    await Promise.all([
      loadSettingsMyProfile({ refresh: true }),
      loadSettingsMyDistricts({ refresh: true }),
    ]);
    if (redirectTo) {
      navigateTo(redirectTo, { replace: true });
    }
  } catch (error) {
    voterProfile.profile.error = settingsErrorMessage(
      error,
      "Home location could not be saved.",
    );
    showToast(voterProfile.profile.error);
  } finally {
    voterProfile.homeLocationSaving = false;
    scheduleRender();
  }
}

function settingsAddressChangeRequestState() {
  if (!state.pages.settings.voterProfile.addressChange) {
    state.pages.settings.voterProfile.addressChange =
      createSettingsAddressChangeRequestState();
  }
  return state.pages.settings.voterProfile.addressChange;
}

async function loadSettingsAddressChangeRequests({
  refresh = false,
  append = false,
} = {}) {
  const resource = settingsAddressChangeRequestState();
  if (append ? resource.loadingMore : resource.loading) {
    return;
  }
  if (!append && resource.loaded && !refresh) {
    scheduleRender();
    return;
  }
  if (append && !resource.nextCursor) {
    return;
  }
  if (append) {
    resource.loadingMore = true;
  } else {
    resource.loading = true;
    resource.error = "";
    if (refresh) {
      resource.nextCursor = null;
    }
  }
  scheduleRender();
  try {
    const query = new URLSearchParams({ limit: "10" });
    if (append && resource.nextCursor) {
      query.set("cursor", resource.nextCursor);
    }
    const payload = await fetchJson(
      `/api/address-change-requests/mine?${query.toString()}`,
      { auth: true },
    );
    const items = readArrayPayload(payload, ["requests", "items"])
      .map(normalizeAddressChangeRequest)
      .filter((item) => item.requestId || formatAddressChangeAddress(item.requestedAddress));
    resource.items = append ? resource.items.concat(items) : items;
    resource.nextCursor = normalizeString(payload.nextCursor);
    resource.loaded = true;
    resource.error = "";
  } catch (error) {
    resource.error = settingsErrorMessage(
      error,
      "Address change requests could not be loaded.",
    );
  } finally {
    resource.loading = false;
    resource.loadingMore = false;
    scheduleRender();
  }
}

function inferAddressChangeAttachmentType(file) {
  const contentType = normalizeString(file?.type).toLowerCase();
  const fileName = normalizeString(file?.name).toLowerCase();
  if (contentType === "application/pdf" || fileName.endsWith(".pdf")) {
    return "pdf";
  }
  if (contentType.startsWith("image/") || /\.(?:png|jpe?g|webp)$/iu.test(fileName)) {
    return "image";
  }
  return "";
}

function normalizeAddressChangeUploadPayload(payload = {}) {
  const upload =
    payload?.upload && typeof payload.upload === "object" ? payload.upload : {};
  return {
    uploadUrl: normalizeUrl(upload.uploadUrl || payload.uploadUrl),
    method: normalizeString(upload.method || payload.method).toUpperCase() || "PUT",
    requiresMultipart:
      upload.requiresMultipart === true || payload.requiresMultipart === true,
    headers:
      upload.headers && typeof upload.headers === "object"
        ? upload.headers
        : payload.headers && typeof payload.headers === "object"
          ? payload.headers
          : {},
    fields:
      upload.fields && typeof upload.fields === "object"
        ? upload.fields
        : payload.fields && typeof payload.fields === "object"
          ? payload.fields
          : {},
    fileFieldName:
      normalizeString(upload.fileFieldName || payload.fileFieldName) || "file",
  };
}

async function addSettingsAddressChangeAttachmentFile(file) {
  const resource = settingsAddressChangeRequestState();
  if (!file) {
    return;
  }
  if (resource.attachments.length >= 3) {
    resource.attachmentError = "You can attach up to 3 files.";
    showToast(resource.attachmentError);
    scheduleRender();
    return;
  }
  if (Number(file.size) <= 0) {
    resource.attachmentError = "Selected file is empty.";
    showToast(resource.attachmentError);
    scheduleRender();
    return;
  }
  const attachmentType = inferAddressChangeAttachmentType(file);
  if (!attachmentType) {
    resource.attachmentError = "Attach a PNG, JPG, WEBP, or PDF file.";
    showToast(resource.attachmentError);
    scheduleRender();
    return;
  }
  resource.actionPendingKey = "attachment-upload";
  resource.attachmentError = "";
  scheduleRender();
  try {
    const fileName =
      normalizeString(file.name) ||
      `home-location-evidence.${attachmentType === "pdf" ? "pdf" : "jpg"}`;
    const contentType =
      attachmentType === "pdf"
        ? "application/pdf"
        : normalizeString(file.type) || "image/jpeg";
    let attachment;
    if (attachmentType === "pdf") {
      const uploadPayload = await fetchJson(
        "/api/address-change-requests/attachments/create",
        {
          auth: true,
          method: "POST",
          body: {
            fileName,
            fileSize: Number(file.size) || 0,
            contentType,
          },
        },
      );
      const upload = normalizeAddressChangeUploadPayload(uploadPayload);
      await uploadPostComposerFile(upload, file);
      attachment = normalizeAddressChangeAttachment({
        ...(uploadPayload.attachment || {}),
        type: "pdf",
        fileName,
        contentType,
        sizeBytes: Number(file.size) || 0,
      });
    } else {
      const uploadPayload = await fetchJson("/api/uploads/create", {
        auth: true,
        method: "POST",
        body: {
          type: "image",
          fileName,
          fileSize: Number(file.size) || 0,
          contentType,
        },
      });
      const upload = normalizeCreateUploadPayload(uploadPayload);
      await uploadPostComposerFile(upload, file);
      const remoteUrl = upload.deliveryUrl || upload.publicUrl;
      if (!remoteUrl) {
        throw new Error("Image upload finished without a public URL.");
      }
      attachment = normalizeAddressChangeAttachment({
        type: "image",
        fileName,
        contentType,
        sizeBytes: Number(file.size) || 0,
        url: remoteUrl,
      });
    }
    resource.attachments = resource.attachments.concat(attachment).slice(0, 3);
    showToast("Evidence attached.");
  } catch (error) {
    resource.attachmentError = settingsErrorMessage(
      error,
      "Evidence upload failed.",
    );
    showToast(resource.attachmentError);
  } finally {
    if (resource.actionPendingKey === "attachment-upload") {
      resource.actionPendingKey = "";
    }
    scheduleRender();
  }
}

function removeSettingsAddressChangeAttachment(attachmentId) {
  const resource = settingsAddressChangeRequestState();
  const normalized = normalizeString(attachmentId);
  resource.attachments = resource.attachments.filter(
    (attachment) =>
      normalizeString(attachment.attachmentId) !== normalized &&
      normalizeString(attachment.fileName) !== normalized,
  );
  resource.attachmentError = "";
  scheduleRender();
}

async function submitSettingsHomeLocationRequest(formData) {
  const resource = settingsAddressChangeRequestState();
  if (resource.actionPendingKey) {
    return false;
  }
  const addressLine1 = normalizeString(formData.get("addressLine1"));
  const city = normalizeString(formData.get("city"));
  const stateId = normalizeString(formData.get("state")).toUpperCase();
  const postalCode = normalizeString(formData.get("postalCode"));
  const message = normalizeString(formData.get("message"));
  if (!addressLine1 || !city || !stateId || !postalCode || !message) {
    resource.error =
      "Address, city, state, ZIP, and request note are required.";
    showToast(resource.error);
    scheduleRender();
    return false;
  }
  const requestedAddress = {
    addressLine1,
    city,
    state: stateId,
    postalCode,
    country: "US",
  };
  const addressLine2 = normalizeString(formData.get("addressLine2"));
  const county = normalizeString(formData.get("county"));
  const district = normalizeString(formData.get("district"));
  if (addressLine2) requestedAddress.addressLine2 = addressLine2;
  if (county) requestedAddress.county = county;
  if (district) requestedAddress.district = district;
  resource.actionPendingKey = "submit";
  resource.error = "";
  scheduleRender();
  try {
    const body = {
      message,
      requestedAddress,
      justification: message,
      addressLine1,
      city,
      state: stateId,
      postalCode,
      country: "US",
      ...(addressLine2 ? { addressLine2 } : {}),
      ...(county ? { county } : {}),
      ...(district ? { district } : {}),
      ...(resource.attachments.length
        ? { attachments: resource.attachments }
        : {}),
    };
    const payload = await fetchJson("/api/address-change-requests", {
      auth: true,
      method: "POST",
      body,
    });
    const created = normalizeAddressChangeRequest(
      payload.request || payload.addressChangeRequest || {
        ...body,
        status: "pending",
      },
    );
    resource.submittedRequest = created;
    resource.attachments = [];
    resource.items = [
      created,
      ...resource.items.filter((item) => item.requestId !== created.requestId),
    ];
    resource.loaded = true;
    showToast("Home location change request submitted.");
    return true;
  } catch (error) {
    resource.error = settingsErrorMessage(
      error,
      "Home location request could not be submitted.",
    );
    showToast(resource.error);
    return false;
  } finally {
    if (resource.actionPendingKey === "submit") {
      resource.actionPendingKey = "";
    }
    scheduleRender();
  }
}

function voterIntelFederalDistrictLabel(stateId, district) {
  const stateCode = normalizeString(stateId).toUpperCase();
  const rawDistrict = normalizeString(district).toUpperCase();
  if (!rawDistrict) {
    return "";
  }
  const canonical = rawDistrict.match(/^([A-Z]{2})-(\d{1,2}|AL|AT-LARGE)$/u);
  if (canonical) {
    const suffix = canonical[2];
    return suffix === "AL" || suffix === "AT-LARGE"
      ? `${canonical[1]}-AL`
      : `${canonical[1]}-${suffix.padStart(2, "0")}`;
  }
  if (!stateCode) {
    return rawDistrict;
  }
  if (rawDistrict === "0" || rawDistrict === "00" || rawDistrict === "AT LARGE" || rawDistrict === "AT-LARGE") {
    return `${stateCode}-AL`;
  }
  const numeric = rawDistrict.match(/^(\d{1,2})$/u);
  if (numeric) {
    return `${stateCode}-${numeric[1].padStart(2, "0")}`;
  }
  return rawDistrict;
}

function voterIntelDistrictSuffix(value) {
  const text = normalizeString(value).toUpperCase();
  if (!text) {
    return "";
  }
  const canonical = text.match(/^[A-Z]{2}-(\d{1,2}|AL|AT-LARGE)$/u);
  if (canonical) {
    const suffix = canonical[1];
    return suffix === "AL" || suffix === "AT-LARGE" ? "AL" : suffix.padStart(2, "0");
  }
  const numeric = text.match(/^(\d{1,2})$/u);
  if (numeric) {
    return numeric[1].padStart(2, "0");
  }
  if (text === "AT LARGE" || text === "AT-LARGE") {
    return "AL";
  }
  return "";
}

function voterIntelJurisdictionContextFromDistricts(districts = null) {
  const federal = districts?.jurisdictions?.federal || {};
  const stateJurisdiction = districts?.jurisdictions?.state || {};
  const manualDistrict = districts?.manualDistrict || {};
  const stateId = normalizeString(
    federal.stateId ||
      stateJurisdiction.stateId ||
      districts?.address?.stateId ||
      manualDistrict.stateId,
  ).toUpperCase();
  if (!stateId) {
    return { stateId: "", district: "", jurisdictionKey: "" };
  }
  const district =
    voterIntelFederalDistrictLabel(
      stateId,
      federal.congressionalDistrictId ||
        federal.congressionalDistrictCode ||
        manualDistrict.congressionalDistrictId,
    ) || "";
  const districtSuffix = voterIntelDistrictSuffix(district);
  return {
    stateId,
    district,
    jurisdictionKey: districtSuffix ? `US#${stateId}#${districtSuffix}` : `US#${stateId}`,
  };
}

function voterIntelSnapshotPath() {
  const context = voterIntelJurisdictionContextFromDistricts(
    state.pages.settings.voterProfile.districts.item,
  );
  const query = new URLSearchParams();
  if (context.stateId) {
    query.set("state", context.stateId);
  }
  if (context.district) {
    query.set("district", context.district);
  }
  if (context.jurisdictionKey) {
    query.set("jurisdictionKey", context.jurisdictionKey);
  }
  const suffix = query.toString();
  return `/api/voter-intel/me${suffix ? `?${suffix}` : ""}`;
}

async function loadVoterIntelSnapshot({ refresh = false } = {}) {
  const snapshot = state.pages.settings.voterIntel.snapshot;
  if (snapshot.loaded && !refresh) {
    return;
  }
  snapshot.loading = true;
  snapshot.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(voterIntelSnapshotPath(), { auth: true });
    snapshot.item = normalizeVoterIntelSnapshot(payload);
    snapshot.loaded = true;
  } catch (error) {
    snapshot.error = settingsErrorMessage(
      error,
      "Voter intelligence could not be loaded.",
    );
  } finally {
    snapshot.loading = false;
    scheduleRender();
  }
}

async function loadVoterIntelBallotGuide({
  refresh = false,
  silent = false,
} = {}) {
  const guide = state.pages.settings.voterIntel.guide;
  if (guide.loaded && !refresh) {
    return;
  }
  guide.loading = true;
  if (!silent) {
    guide.error = "";
  }
  scheduleRender();
  try {
    const payload = await fetchJson("/api/voter-intel/ballot-guide", {
      auth: true,
    });
    guide.item = normalizeBallotGuide(payload);
    guide.loaded = true;
    guide.error = "";
  } catch (error) {
    if (!silent) {
      guide.error = settingsErrorMessage(
        error,
        "Ballot guide could not be loaded.",
      );
    }
    guide.loaded = true;
  } finally {
    guide.loading = false;
    scheduleRender();
  }
}

function voterIntelRankingsState() {
  const voterIntel = state.pages.settings.voterIntel;
  voterIntel.rankings =
    voterIntel.rankings || {
      selectedContestId: "",
      loadingContestId: "",
      savingContestId: "",
      errorByContestId: {},
      aggregateByContestId: {},
      preferencesByContestId: {},
    };
  voterIntel.rankings.errorByContestId =
    voterIntel.rankings.errorByContestId || {};
  voterIntel.rankings.aggregateByContestId =
    voterIntel.rankings.aggregateByContestId || {};
  voterIntel.rankings.preferencesByContestId =
    voterIntel.rankings.preferencesByContestId || {};
  return voterIntel.rankings;
}

function normalizeContestRankingAggregate(raw = {}) {
  const aggregate =
    raw.aggregate && typeof raw.aggregate === "object" ? raw.aggregate : raw;
  return {
    contestId: normalizeString(aggregate.contestId),
    available: aggregate.available === true,
    privacySuppressed: aggregate.privacySuppressed === true,
    totalRankings: Number(aggregate.totalRankings) || 0,
    minTotalRankings: Number(aggregate.minTotalRankings) || 25,
    minSegmentCount: Number(aggregate.minSegmentCount) || 10,
    updatedAtIso: normalizeString(aggregate.updatedAtIso),
    candidates: readArrayPayload(aggregate, ["candidates"]).map((candidate) => ({
      candidateId: normalizeString(candidate.candidateId || candidate.id),
      firstChoiceCount: Number(candidate.firstChoiceCount) || 0,
      firstChoicePct: Number(candidate.firstChoicePct) || 0,
      rankedCount: Number(candidate.rankedCount) || 0,
      avgRank: Number.isFinite(Number(candidate.avgRank))
        ? Number(candidate.avgRank)
        : null,
    })),
  };
}

function normalizeContestRankingCandidate(candidate = {}) {
  return {
    candidateId: normalizeString(candidate.candidateId || candidate.id),
    displayName:
      normalizeString(candidate.displayName || candidate.name) ||
      normalizeString(candidate.candidateId || candidate.id) ||
      "Candidate",
    rank: Number(candidate.rank) || 0,
  };
}

function normalizeContestRankingPreferences(raw = []) {
  const seen = new Set();
  return (Array.isArray(raw) ? raw : [])
    .map(normalizeContestRankingCandidate)
    .sort((left, right) => left.rank - right.rank)
    .filter((candidate) => {
      const id = normalizeString(candidate.candidateId);
      if (!id || seen.has(id)) {
        return false;
      }
      seen.add(id);
      return true;
    })
    .map((candidate, index) => ({ ...candidate, rank: index + 1 }));
}

function voterIntelSlug(value, fallback = "candidate") {
  const slug = normalizeString(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/gu, "-")
    .replace(/^-+|-+$/gu, "");
  return slug || fallback;
}

function voterIntelDateKey(value) {
  const normalized = normalizeString(value);
  if (!normalized) return "";
  const dateOnly = normalized.match(/^(\d{4})-(\d{2})-(\d{2})/u);
  if (dateOnly) {
    return `${dateOnly[1]}-${dateOnly[2]}-${dateOnly[3]}`;
  }
  const timestamp = Date.parse(normalized);
  return Number.isNaN(timestamp) ? "" : formatDateInputValue(timestamp);
}

function voterIntelDistrictElectionData(districts = {}) {
  return districts?.electionData && typeof districts.electionData === "object"
    ? districts.electionData
    : {};
}

function voterIntelDistrictRaceContestId({
  electionId = "",
  electionDay = "",
  office = "",
  jurisdiction = "",
} = {}) {
  const parts = [
    normalizeString(electionId) || voterIntelDateKey(electionDay),
    normalizeString(office),
    normalizeString(jurisdiction),
  ].filter(Boolean);
  return voterIntelSlug(parts.join("|"), "contest");
}

function voterIntelDistrictCandidateId(candidate = {}, index = 0) {
  const appCandidateId = normalizeString(candidate.appCandidateId);
  if (appCandidateId) return appCandidateId;
  const name = settingsDistrictPersonName(candidate);
  return `${voterIntelSlug(name, "candidate")}-${index}`;
}

function normalizeVoterIntelDistrictCandidate(candidate = {}, index = 0, group = {}) {
  const name = normalizeString(
    candidate.name || candidate.displayName || candidate.fullName,
  );
  const candidateId = voterIntelDistrictCandidateId(candidate, index);
  return {
    candidateId,
    id: candidateId,
    name,
    displayName: name,
    partyLabel:
      normalizeString(candidate.partyLabel || candidate.party || group.partyLabel) ||
      normalizeString(candidate.partyToken || group.partyToken),
    partyToken: normalizeElectionPartyToken(
      candidate.partyToken || candidate.partyCode || group.partyToken,
    ),
    avatarUrl: normalizeUrl(candidate.appAvatarUrl || candidate.avatarUrl),
    initials: settingsDistrictPersonInitials(candidate),
  };
}

function voterIntelDistrictCandidateSources(reelection = {}, candidateGroups = []) {
  const directCandidates = readArrayPayload(reelection, ["candidates"]);
  if (directCandidates.length) {
    return directCandidates.map((candidate, index) => ({
      candidate,
      group: {},
      index,
    }));
  }
  let index = 0;
  return candidateGroups.flatMap((group) =>
    readArrayPayload(group, ["candidates"]).map((candidate) => ({
      candidate,
      group,
      index: index++,
    })),
  );
}

function voterIntelRankableRaceFromDistrictEntry(districts, entry = {}) {
  const { office = {}, index = 0 } = entry;
  const reelection = settingsDistrictOfficeReelection(office);
  const candidateGroups = settingsDistrictCandidateGroups(reelection);
  const electionData = voterIntelDistrictElectionData(districts);
  const title =
    normalizeString(office.office || office.title || office.officeTitle) ||
    `Race ${index + 1}`;
  const jurisdiction = normalizeString(
    office.jurisdiction || office.district || office.state,
  );
  const electionId = normalizeString(
    reelection.electionId || electionData.electionId,
  );
  const electionDay = voterIntelDateKey(
    reelection.electionDay || electionData.electionDay,
  );
  const candidates = voterIntelDistrictCandidateSources(
    reelection,
    candidateGroups,
  )
    .map(({ candidate, group, index: candidateIndex }) =>
      normalizeVoterIntelDistrictCandidate(candidate, candidateIndex, group),
    )
    .filter((candidate) => candidate.candidateId && candidate.name);
  return {
    contestId: voterIntelDistrictRaceContestId({
      electionId,
      electionDay,
      office: title,
      jurisdiction,
    }),
    raceId: voterIntelDistrictRaceContestId({
      electionId,
      electionDay,
      office: title,
      jurisdiction,
    }),
    title,
    officeTitle: title,
    level:
      normalizeString(office.level) ||
      settingsDistrictOfficeLevelKey(office.level),
    jurisdiction,
    districtId: normalizeString(office.districtId || office.district),
    stateId: normalizeString(office.state || electionData.stateId),
    electionId,
    electionName: normalizeString(
      reelection.electionName || electionData.electionName,
    ),
    electionDay,
    status: normalizeString(reelection.status),
    candidateGroups,
    candidates,
  };
}

function voterIntelRankableRacesFromDistricts(districts) {
  const offices = settingsDistrictOffices(districts);
  const grouped = settingsDistrictGroupedOffices(offices);
  return SETTINGS_DISTRICT_LEVELS.flatMap((level) => grouped[level.key] || [])
    .map((entry) => voterIntelRankableRaceFromDistrictEntry(districts, entry))
    .filter((race) => voterIntelRaceContestId(race));
}

function voterIntelRaceStatusIsRankable(status) {
  const normalized = normalizeString(status).toLowerCase();
  return (
    !normalized ||
    normalized.includes("up_for") ||
    normalized.includes("open")
  );
}

function voterIntelRaceIsRankable(race = {}) {
  return (
    Boolean(voterIntelRaceContestId(race)) &&
    Array.isArray(race.candidates) &&
    race.candidates.length > 0 &&
    voterIntelRaceStatusIsRankable(race.status)
  );
}

function findVoterIntelRankableRace(contestId) {
  const normalizedContestId = normalizeString(contestId);
  if (!normalizedContestId) return null;
  const districts = state.pages.settings.voterProfile.districts.item;
  return (
    voterIntelRankableRacesFromDistricts(districts).find(
      (race) => voterIntelRaceContestId(race) === normalizedContestId,
    ) || null
  );
}

function findVoterIntelSavedContest(contestId) {
  const normalizedContestId = normalizeString(contestId);
  const guide = state.pages.settings.voterIntel.guide.item || normalizeBallotGuide();
  return (
    guide.contests.find(
      (contest) => normalizeString(contest.contestId) === normalizedContestId,
    ) || null
  );
}

function voterIntelRaceContestId(race = {}) {
  if (!race || typeof race !== "object") return "";
  return normalizeString(race.raceId || race.contestId || race.id);
}

function voterIntelRaceCandidates(race = {}) {
  if (!race || typeof race !== "object") return [];
  const seen = new Set();
  return (race.candidates || [])
    .map((candidate) => ({
      candidateId: normalizeString(candidate.id || candidate.candidateId),
      displayName:
        normalizeString(candidate.displayName || candidate.name) ||
        "Candidate",
      partyLabel: normalizeString(
        candidate.partyLabel || candidate.party || candidate.partyToken,
      ),
      partyToken: normalizeElectionPartyToken(
        candidate.partyToken || candidate.partyCode || candidate.partyLabel,
      ),
      avatarUrl: normalizeUrl(
        candidate.avatarUrl || candidate.appAvatarUrl || candidate.photoUrl,
      ),
      initials: normalizeString(candidate.initials),
    }))
    .filter((candidate) => {
      if (!candidate.candidateId || seen.has(candidate.candidateId)) {
        return false;
      }
      seen.add(candidate.candidateId);
      return true;
    });
}

function voterIntelRaceContext(race = {}) {
  const source = race && typeof race === "object" ? race : {};
  return {
    stateId: normalizeString(source.stateId),
    districtId: normalizeString(source.districtId),
    office: normalizeString(source.officeTitle || source.title || source.office),
    level: normalizeString(source.level),
    jurisdiction: normalizeString(source.jurisdiction),
    electionId: normalizeString(source.electionId),
    electionName: normalizeString(source.electionName),
    electionDay: normalizeString(source.electionDay || source.date),
  };
}

function ensureVoterIntelRaceRanking(race = {}) {
  const contestId = voterIntelRaceContestId(race);
  if (!contestId) return;
  const rankingState = voterIntelRankingsState();
  if (!rankingState.preferencesByContestId[contestId]) {
    const saved = findVoterIntelSavedContest(contestId);
    rankingState.preferencesByContestId[contestId] =
      normalizeContestRankingPreferences(saved?.ranking || []);
  }
  if (
    !rankingState.aggregateByContestId[contestId] &&
    rankingState.loadingContestId !== contestId
  ) {
    loadVoterIntelContestAggregate(contestId).catch(() => {});
  }
}

async function loadVoterIntelContestAggregate(contestId, { refresh = false } = {}) {
  const normalizedContestId = normalizeString(contestId);
  if (!normalizedContestId) return;
  const rankingState = voterIntelRankingsState();
  if (rankingState.aggregateByContestId[normalizedContestId] && !refresh) {
    return;
  }
  rankingState.loadingContestId = normalizedContestId;
  rankingState.errorByContestId[normalizedContestId] = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      `/api/elections/contests/${encodeURIComponent(normalizedContestId)}/ranking-aggregate`,
      { auth: true },
    );
    rankingState.aggregateByContestId[normalizedContestId] =
      normalizeContestRankingAggregate(payload);
    if (payload.myRanking?.ranking) {
      rankingState.preferencesByContestId[normalizedContestId] =
        normalizeContestRankingPreferences(payload.myRanking.ranking);
    }
  } catch (error) {
    rankingState.errorByContestId[normalizedContestId] = settingsErrorMessage(
      error,
      "Ranking data could not be loaded.",
    );
  } finally {
    if (rankingState.loadingContestId === normalizedContestId) {
      rankingState.loadingContestId = "";
    }
    scheduleRender();
  }
}

function setVoterIntelRacePreferences(contestId, preferences) {
  const normalizedContestId = normalizeString(contestId);
  if (!normalizedContestId) return;
  voterIntelRankingsState().preferencesByContestId[normalizedContestId] =
    normalizeContestRankingPreferences(preferences);
}

async function saveVoterIntelRaceRanking(race = {}) {
  const contestId = voterIntelRaceContestId(race);
  if (!contestId) return;
  const rankingState = voterIntelRankingsState();
  const ranking = normalizeContestRankingPreferences(
    rankingState.preferencesByContestId[contestId] || [],
  );
  if (!ranking.length) {
    rankingState.errorByContestId[contestId] = "Rank at least one candidate.";
    scheduleRender();
    return;
  }
  rankingState.savingContestId = contestId;
  rankingState.errorByContestId[contestId] = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      `/api/elections/contests/${encodeURIComponent(contestId)}/ranking`,
      {
        auth: true,
        method: "PUT",
        body: {
          ...voterIntelRaceContext(race),
          ranking: ranking.map((candidate, index) => ({
            candidateId: candidate.candidateId,
            displayName: candidate.displayName,
            rank: index + 1,
          })),
        },
      },
    );
    rankingState.aggregateByContestId[contestId] =
      normalizeContestRankingAggregate(payload);
    await Promise.allSettled([
      loadVoterIntelSnapshot({ refresh: true }),
      loadVoterIntelBallotGuide({ refresh: true, silent: true }),
    ]);
    showToast("Ranking saved.");
  } catch (error) {
    rankingState.errorByContestId[contestId] = settingsErrorMessage(
      error,
      "Ranking could not be saved.",
    );
    showToast(rankingState.errorByContestId[contestId]);
  } finally {
    if (rankingState.savingContestId === contestId) {
      rankingState.savingContestId = "";
    }
    scheduleRender();
  }
}

function addVoterIntelRaceRankingCandidate(contestId, candidateId) {
  const race = findVoterIntelRankableRace(contestId);
  const normalizedContestId = voterIntelRaceContestId(race);
  const normalizedCandidateId = normalizeString(candidateId);
  if (!race || !normalizedContestId || !normalizedCandidateId) {
    showToast("Candidate ranking is unavailable.");
    return;
  }
  const candidate = voterIntelRaceCandidates(race).find(
    (item) => item.candidateId === normalizedCandidateId,
  );
  if (!candidate) {
    showToast("Candidate could not be found for this race.");
    return;
  }
  const current = voterIntelRankingPreferencesForContest(normalizedContestId);
  if (current.some((item) => item.candidateId === normalizedCandidateId)) {
    return;
  }
  setVoterIntelRacePreferences(normalizedContestId, [
    ...current,
    {
      candidateId: candidate.candidateId,
      displayName: candidate.displayName,
      rank: current.length + 1,
    },
  ]);
  scheduleRender();
}

function removeVoterIntelRaceRankingCandidate(contestId, candidateId) {
  const normalizedContestId = normalizeString(contestId);
  const normalizedCandidateId = normalizeString(candidateId);
  if (!normalizedContestId || !normalizedCandidateId) return;
  setVoterIntelRacePreferences(
    normalizedContestId,
    voterIntelRankingPreferencesForContest(normalizedContestId).filter(
      (candidate) => candidate.candidateId !== normalizedCandidateId,
    ),
  );
  scheduleRender();
}

function moveVoterIntelRaceRankingCandidate(contestId, candidateId, direction) {
  const normalizedContestId = normalizeString(contestId);
  const normalizedCandidateId = normalizeString(candidateId);
  const numericDirection = Number(direction);
  if (
    !normalizedContestId ||
    !normalizedCandidateId ||
    !Number.isInteger(numericDirection)
  ) {
    return;
  }
  const next = voterIntelRankingPreferencesForContest(normalizedContestId);
  const index = next.findIndex(
    (candidate) => candidate.candidateId === normalizedCandidateId,
  );
  const nextIndex = index + numericDirection;
  if (index < 0 || nextIndex < 0 || nextIndex >= next.length) {
    return;
  }
  const [candidate] = next.splice(index, 1);
  next.splice(nextIndex, 0, candidate);
  setVoterIntelRacePreferences(
    normalizedContestId,
    next.map((entry, entryIndex) => ({ ...entry, rank: entryIndex + 1 })),
  );
  scheduleRender();
}

async function loadVoterIntelPolicyQuestions({ refresh = false } = {}) {
  const questions = state.pages.settings.voterIntel.questions;
  if (questions.loaded && !refresh) {
    return;
  }
  questions.loading = true;
  questions.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson("/api/policy-questions?limit=8", {
      auth: true,
    });
    const summaries = readArrayPayload(payload, ["items"])
      .map(normalizePolicyQuestion)
      .filter((question) => question.questionId);
    const details = await Promise.allSettled(
      summaries.map((question) =>
        fetchJson(
          `/api/policy-questions/${encodeURIComponent(question.questionId)}`,
          { auth: true },
        ),
      ),
    );
    questions.items = summaries.map((summary, index) => {
      const result = details[index];
      if (result?.status !== "fulfilled") {
        return summary;
      }
      const detail =
        result.value?.question && typeof result.value.question === "object"
          ? result.value.question
          : result.value;
      return normalizePolicyQuestion({ ...summary, ...detail });
    });
    questions.nextCursor =
      normalizeString(payload.cursor || payload.nextCursor) || null;
    questions.loaded = true;
  } catch (error) {
    questions.error = settingsErrorMessage(
      error,
      "Policy questions could not be loaded.",
    );
  } finally {
    questions.loading = false;
    scheduleRender();
  }
}

async function answerVoterIntelPolicyQuestion(questionId, optionId) {
  const questions = state.pages.settings.voterIntel.questions;
  const normalizedQuestionId = normalizeString(questionId);
  const normalizedOptionId = normalizeString(optionId);
  if (!normalizedQuestionId || !normalizedOptionId) {
    return;
  }
  questions.actionPendingKey = `${normalizedQuestionId}:${normalizedOptionId}`;
  questions.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      `/api/policy-questions/${encodeURIComponent(normalizedQuestionId)}/answer`,
      {
        auth: true,
        method: "PUT",
        body: { optionId: normalizedOptionId },
      },
    );
    const selectedAnswer = payload.answer
      ? {
          optionId: normalizeString(payload.answer.optionId),
          answerText: normalizeString(payload.answer.answerText),
          updatedAtIso: normalizeString(payload.answer.updatedAtIso),
        }
      : { optionId: normalizedOptionId, answerText: "", updatedAtIso: "" };
    questions.items = questions.items.map((question) =>
      question.questionId === normalizedQuestionId
        ? {
            ...question,
            selectedAnswer,
            aggregate: payload.aggregate
              ? {
                  total: Number(payload.aggregate.total) || 0,
                  options: readArrayPayload(payload.aggregate, ["options"]),
                }
              : question.aggregate,
          }
        : question,
    );
    if (payload.profile) {
      const snapshot = state.pages.settings.voterIntel.snapshot;
      snapshot.item = normalizeVoterIntelSnapshot({
        ...(snapshot.item || {}),
        profile: payload.profile,
        shares: snapshot.item?.shares || [],
        identityLinks: snapshot.item?.identityLinks || [],
        capability: snapshot.item?.capability || {},
      });
      snapshot.loaded = true;
    }
    showToast("Answer saved.");
  } catch (error) {
    questions.error = settingsErrorMessage(error, "Answer could not be saved.");
    showToast(questions.error);
  } finally {
    questions.actionPendingKey = "";
    scheduleRender();
  }
}

