async function loadSettingsAudienceGroupSearch(
  query,
  groupId = "create",
  { refresh = false } = {},
) {
  const resource = state.pages.settings.audienceGroups;
  const search = settingsAudienceGroupSearch(resource);
  const normalizedGroupId = settingsAudienceGroupDraftKey(groupId);
  const normalizedQuery = normalizeString(query).replace(/^@/u, "");
  search.groupId = normalizedGroupId;
  search.query = normalizeString(query);
  if (normalizedQuery.length < 2) {
    search.items = [];
    search.loading = false;
    search.error = "";
    search.loaded = false;
    search.lastSearchQuery = "";
    scheduleRender();
    return;
  }
  if (
    search.loading ||
    (!refresh &&
      search.loaded &&
      search.lastSearchQuery === normalizedQuery &&
      search.groupId === normalizedGroupId)
  ) {
    return;
  }
  const token = search.token + 1;
  search.token = token;
  search.lastSearchQuery = normalizedQuery;
  search.loading = true;
  search.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      settingsAudienceMemberSearchEndpoint(normalizedQuery),
      { auth: true },
    );
    if (search.token !== token) return;
    search.items = normalizeSearchResultsPayload(payload, "users").items
      .map(normalizeSettingsAudienceMemberSearchResult)
      .filter(Boolean);
    search.loaded = true;
  } catch (error) {
    if (search.token !== token) return;
    search.error =
      normalizeString(error?.message) || "Member search failed.";
    search.loaded = true;
  } finally {
    if (search.token === token) {
      search.loading = false;
      scheduleRender();
    }
  }
}

function queueSettingsAudienceGroupSearch() {
  window.clearTimeout(settingsAudienceGroupSearchTimer);
  const resource = state.pages.settings.audienceGroups;
  const search = settingsAudienceGroupSearch(resource);
  const query = normalizeString(search.query);
  if (query.replace(/^@/u, "").length < 2) {
    loadSettingsAudienceGroupSearch(query, search.groupId).catch(() => {});
    return;
  }
  settingsAudienceGroupSearchTimer = window.setTimeout(() => {
    loadSettingsAudienceGroupSearch(query, search.groupId).catch(() => {});
  }, 300);
}

function addSettingsAudienceSearchResultToDraft(target) {
  const resource = state.pages.settings.audienceGroups;
  const groupId = normalizeString(target.getAttribute("data-group-id"));
  const userId = normalizeString(target.getAttribute("data-user-id"));
  if (!userId) {
    showToast("Selected account is missing a user ID.");
    return;
  }
  const group = settingsAudienceGroupByKey(resource, groupId);
  const draft = settingsAudienceGroupDraft(resource, groupId, group);
  const memberUserIds = normalizeAudienceGroupMemberIds(draft.memberUserIds);
  if (!memberUserIds.includes(userId)) {
    memberUserIds.push(userId);
  }
  draft.memberUserIds = memberUserIds.join("\n");
  const search = settingsAudienceGroupSearch(resource);
  search.query = "";
  search.items = [];
  search.error = "";
  search.loading = false;
  search.loaded = false;
  search.lastSearchQuery = "";
  showToast("Member added to audience group.");
  scheduleRender();
}

async function saveSettingsAudienceGroup(formData) {
  const audienceGroups = state.pages.settings.audienceGroups;
  const groupId = normalizeString(formData.get("groupId"));
  const name = normalizeString(formData.get("name"));
  const memberUserIds = normalizeAudienceGroupMemberIds(
    formData.get("memberUserIds"),
  );
  if (!name) {
    audienceGroups.error = "Audience group name is required.";
    scheduleRender();
    return false;
  }
  const isUpdate = Boolean(groupId);
  audienceGroups.savingKey = isUpdate ? `save:${groupId}` : "create";
  audienceGroups.error = "";
  scheduleRender();
  try {
    const payload = await fetchJson(
      isUpdate
        ? `/api/me/audience-groups/${encodeURIComponent(groupId)}`
        : "/api/me/audience-groups",
      {
        auth: true,
        method: isUpdate ? "PUT" : "POST",
        body: {
          ...(isUpdate ? { groupId } : {}),
          name,
          memberUserIds,
        },
      },
    );
    audienceGroups.items = readArrayPayload(payload, [
      "groups",
      "audienceGroups",
    ]).map(normalizeAudienceGroup);
    audienceGroups.loaded = true;
    clearSettingsAudienceGroupDraft(audienceGroups, groupId);
    const search = settingsAudienceGroupSearch(audienceGroups);
    search.query = "";
    search.items = [];
    search.loaded = false;
    search.lastSearchQuery = "";
    showToast(isUpdate ? "Audience group saved." : "Audience group created.");
    return true;
  } catch (error) {
    audienceGroups.error = settingsErrorMessage(
      error,
      "Audience group save failed.",
    );
    showToast(audienceGroups.error);
    return false;
  } finally {
    audienceGroups.savingKey = "";
    scheduleRender();
  }
}

