function settingsAccountSecurity() {
  if (!state.pages.settings.accountSecurity) {
    state.pages.settings.accountSecurity = createSettingsAccountSecurityState();
  }
  return state.pages.settings.accountSecurity;
}

function defaultSettingsSecurityIdentifier() {
  const reset = settingsAccountSecurity().reset;
  return (
    reset.identifier ||
    state.auth.user?.email ||
    state.auth.user?.username ||
    ""
  );
}

async function requestSettingsPasswordReset(formData) {
  const account = settingsAccountSecurity();
  const reset = account.reset;
  const identifier = normalizeString(formData.get("identifier"));
  if (!identifier) {
    reset.error = "Email or username is required.";
    reset.notice = "";
    scheduleRender();
    return false;
  }
  reset.identifier = identifier;
  reset.requesting = true;
  reset.error = "";
  reset.notice = "";
  scheduleRender();
  try {
    const result = await requestSharedFeedPasswordReset(state.auth.config, {
      identifier,
    });
    reset.username = result.username || identifier;
    reset.deliveryDestination = result.deliveryDestination || "";
    reset.deliveryMedium = result.deliveryMedium || "";
    reset.notice = reset.deliveryDestination
      ? `Reset code sent to ${reset.deliveryDestination}.`
      : "Reset code sent if the account can receive one.";
    showToast("Password reset code sent.");
    return true;
  } catch (error) {
    reset.error = settingsErrorMessage(
      error,
      "Password reset could not be started.",
    );
    showToast(reset.error);
    return false;
  } finally {
    reset.requesting = false;
    scheduleRender();
  }
}

async function confirmSettingsPasswordReset(formData) {
  const account = settingsAccountSecurity();
  const reset = account.reset;
  const identifier =
    normalizeString(formData.get("identifier")) ||
    reset.username ||
    reset.identifier;
  const code = normalizeString(formData.get("code"));
  const password = String(formData.get("password") || "");
  if (!identifier || !code || !password) {
    reset.error = "Email or username, code, and new password are required.";
    reset.notice = "";
    scheduleRender();
    return false;
  }
  reset.identifier = identifier;
  reset.confirming = true;
  reset.error = "";
  reset.notice = "";
  scheduleRender();
  try {
    await confirmSharedFeedPasswordReset(state.auth.config, {
      identifier,
      code,
      password,
    });
    reset.notice = "Password updated. Use the new password the next time you sign in.";
    showToast("Password updated.");
    return true;
  } catch (error) {
    reset.error = settingsErrorMessage(
      error,
      "Password reset could not be confirmed.",
    );
    showToast(reset.error);
    return false;
  } finally {
    reset.confirming = false;
    scheduleRender();
  }
}

async function startSettingsTotpSetup() {
  const account = settingsAccountSecurity();
  const totp = account.totp;
  totp.starting = true;
  totp.error = "";
  totp.notice = "";
  totp.copied = false;
  scheduleRender();
  try {
    const result = await startSharedFeedTotpSetup(
      state.auth.config,
      state.auth.session,
    );
    totp.setupUri = result.setupUri || "";
    totp.secretCode = result.secretCode || "";
    totp.setupSession = result.setupSession || "";
    totp.notice = "Authenticator setup started. Add the setup URI to your app.";
    showToast("Authenticator setup started.");
  } catch (error) {
    totp.error = settingsErrorMessage(
      error,
      "Authenticator setup could not be started.",
    );
    showToast(totp.error);
  } finally {
    totp.starting = false;
    scheduleRender();
  }
}

async function copySettingsTotpSetupUri() {
  const totp = settingsAccountSecurity().totp;
  if (!totp.setupUri) {
    totp.error = "Start setup before copying the URI.";
    scheduleRender();
    return;
  }
  if (!navigator.clipboard?.writeText) {
    totp.error = "Clipboard copy is unavailable in this browser.";
    scheduleRender();
    return;
  }
  try {
    await navigator.clipboard.writeText(totp.setupUri);
    totp.copied = true;
    totp.notice = "Setup URI copied.";
    totp.error = "";
    showToast("Setup URI copied.");
  } catch {
    totp.error = "Setup URI could not be copied.";
  } finally {
    scheduleRender();
  }
}

function openSettingsTotpSetupUri() {
  const totp = settingsAccountSecurity().totp;
  if (!totp.setupUri) {
    totp.error = "Start setup before opening the authenticator URI.";
    scheduleRender();
    return;
  }
  window.location.assign(totp.setupUri);
}

async function verifySettingsTotpSetup(formData) {
  const account = settingsAccountSecurity();
  const totp = account.totp;
  const code = normalizeString(formData.get("code"));
  if (!code) {
    totp.error = "Enter the code from your app.";
    totp.notice = "";
    scheduleRender();
    return false;
  }
  totp.verifying = true;
  totp.error = "";
  totp.notice = "";
  scheduleRender();
  try {
    await verifySharedFeedTotpSetup(state.auth.config, state.auth.session, {
      code,
      setupSession: totp.setupSession,
    });
    totp.setupUri = "";
    totp.secretCode = "";
    totp.setupSession = "";
    totp.copied = false;
    totp.notice = "Authenticator app verified.";
    totp.error = "";
    showToast("Authenticator app verified.");
    navigateTo("/settings/account-security", { replace: true });
    return true;
  } catch (error) {
    totp.error = settingsErrorMessage(
      error,
      "Authenticator setup could not be verified.",
    );
    showToast(totp.error);
    return false;
  } finally {
    totp.verifying = false;
    scheduleRender();
  }
}

async function loadCurrentRoute({ refresh = false } = {}) {
  const route = getCurrentRoute();
  state.renderError = "";
  if (!(await requireAuthForRoute(route))) {
    return;
  }

  if (getRouteSection(route) !== "messages") {
    if (state.pages.messaging.conversation.item?.conversationId) {
      messagingSocket.unsubscribeConversation(
        state.pages.messaging.conversation.item.conversationId,
      );
    }
    messagingSocket.releaseSession();
    messagingSessionRetained = false;
  }

  if (isFeedRoute(route)) {
    if (isShareRoute(route)) {
      state.mode = FEED_MODE_FOR_YOU;
    }
    state.feedContext = isShareRoute(route)
      ? {
          kind: "share",
          anchorPostId:
            normalizeString(route.routeParams.postId) ||
            normalizeString(runtimeConfig.shareContext?.postId),
        }
      : {
          kind: "app",
          anchorPostId: "",
        };
    if (
      normalizeString(route.routeKey) === ROUTE_KEY_FEED &&
      state.mode === FEED_MODE_FOLLOWING
    ) {
      await Promise.all([
        loadFollowingFeed({ refresh }),
        loadFeedFollowedIssues({ refresh }),
      ]);
      return;
    }
    await Promise.all([
      loadInitialFeed({ refresh }),
      loadFeedFollowedIssues({ refresh }),
    ]);
    return;
  }

  const routeKey = normalizeString(route.routeKey);
  if (routeKey !== ROUTE_KEY_ELECTION_DAY) {
    clearElectionPolling();
  }
  if (isPublicAccountRoute(route)) {
    scheduleRender();
    return;
  }
  if (routeKey === ROUTE_KEY_POST_VIEW) {
    scheduleRender();
    return;
  }
  if (routeKey === ROUTE_KEY_CREATE) {
    await loadPostComposerPage({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_POST_ANALYTICS) {
    await loadPostAnalyticsPage(route.routeParams.postId, { refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_DISCOVER) {
    await loadDiscoverPage({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_ACHIEVEMENTS) {
    await loadAchievementsPage({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_CTA_INVITE) {
    await loadCtaInvitePage(route.routeParams.token, { refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_PUBLIC_PETITION) {
    await loadPublicPetitionPage(route.routeParams.publicSlug, { refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_PUBLIC_PETITION_RESULTS) {
    await loadPublicPetitionResultsPage(route.routeParams.shareToken, { refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_SEARCH) {
    await loadSearchLanding({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_SEARCH_RESULTS) {
    await loadSearchResultsPage({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_CANDIDATES) {
    await Promise.all([
      loadCandidateList({ refresh }),
      loadCandidateDirectoryTagCatalog({ refresh }),
      loadElectionContext({ refresh }).catch(() => state.pages.elections.context),
    ]);
    return;
  }
  if (routeKey === ROUTE_KEY_ELECTION_DAY) {
    await loadElectionDayPage({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_CONGRESSIONAL_REPORT_CARD) {
    await loadCongressionalReportCard({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_OFFICIAL_DETAIL) {
    await loadOfficialDetail(route.routeParams.officialId, { refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_AUTO_CANDIDATE_DETAIL) {
    await loadAutoCandidateDetail(route.routeParams.entityId, { refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_OFFICIAL_REPORT_CARD) {
    await Promise.all([
      loadOfficialDetail(route.routeParams.officialId, { refresh }),
      loadOfficialReportCard(route.routeParams.officialId, { refresh }),
    ]);
    return;
  }
  if (
    routeKey === ROUTE_KEY_CANDIDATE_DETAIL ||
    routeKey === ROUTE_KEY_CANDIDATE_EDIT
  ) {
    const candidateId = resolveCandidateEditRouteCandidateId(route);
    if (!candidateId) {
      const detail = state.pages.candidates.detail;
      detail.item = null;
      detail.posts = [];
      detail.relatedEvents = [];
      detail.loading = false;
      detail.error =
        routeKey === ROUTE_KEY_CANDIDATE_EDIT
          ? "No candidate found to edit."
          : "Candidate page unavailable.";
      scheduleRender();
      return;
    }
    const legacyOfficialId = extractOfficialIdFromCandidateRouteId(
      candidateId,
    );
    if (legacyOfficialId) {
      navigateTo(buildOfficialProfileRoute(legacyOfficialId), {
        replace: true,
      });
      return;
    }
    const legacyEntityId = extractAutoCandidateEntityId(
      candidateId,
    );
    if (legacyEntityId) {
      navigateTo(buildAutoCandidateRoute(legacyEntityId), { replace: true });
      return;
    }
    if (routeKey === ROUTE_KEY_CANDIDATE_EDIT) {
      await Promise.allSettled([
        loadCandidateDetail(candidateId, { refresh }),
        loadSettingsMyProfile({ refresh }),
        loadSettingsCandidateAccessApplication({ refresh }),
        loadCandidateEditorTagCatalog({ refresh }),
      ]);
      return;
    }
    await loadCandidateDetail(candidateId, { refresh });
    return;
  }
  if (
    routeKey === ROUTE_KEY_CANDIDATE_DASHBOARD ||
    routeKey === ROUTE_KEY_CANDIDATE_DASHBOARD_DETAIL ||
    routeKey === ROUTE_KEY_CANDIDATE_DASHBOARD_SECTION
  ) {
    await loadCandidateDashboardPage({ refresh });
    return;
  }
  if (
    routeKey === ROUTE_KEY_CANDIDATE_VOTER_MAP ||
    routeKey === ROUTE_KEY_CANDIDATE_VOTER_MAP_SECTION
  ) {
    await loadCandidateVoterMapPage({ refresh });
    return;
  }
  if (
    routeKey === ROUTE_KEY_COALITIONS ||
    routeKey === ROUTE_KEY_COALITION_START ||
    routeKey === ROUTE_KEY_COALITION_JOIN ||
    routeKey === ROUTE_KEY_COALITION_DETAIL ||
    routeKey === ROUTE_KEY_COALITION_SECTION
  ) {
    await loadCoalitionsPage({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_MISSIONS) {
    await loadMissionsList({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_MISSION_DETAIL) {
    await loadMissionDetail(route.routeParams.missionId, { refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_EVENTS) {
    await Promise.all([
      loadEventsTagCatalog({ refresh }),
      loadEventsList({ refresh }),
    ]);
    return;
  }
  if (
    routeKey === ROUTE_KEY_EVENT_DETAIL ||
    routeKey === ROUTE_KEY_EVENT_SIGNUP ||
    routeKey === ROUTE_KEY_EVENT_PAYMENT ||
    routeKey === ROUTE_KEY_MANAGE_EVENTS_NEW ||
    routeKey === ROUTE_KEY_MANAGE_EVENTS_EDIT
  ) {
    if (route.routeParams.eventId) {
      await loadEventDetail(route.routeParams.eventId, { refresh });
    } else {
      scheduleRender();
    }
    return;
  }
  if (routeKey === ROUTE_KEY_MANAGE_EVENTS) {
    await loadManageEvents({ refresh });
    return;
  }
  if (
    routeKey === ROUTE_KEY_PROFILE_SELF ||
    routeKey === ROUTE_KEY_PROFILE_EDIT
  ) {
    await loadProfilePage("", { refresh });
    if (routeKey === ROUTE_KEY_PROFILE_EDIT) {
      return;
    }
    return;
  }
  if (routeKey === ROUTE_KEY_PROFILE_USER) {
    await loadProfilePage(route.routeParams.userId, { refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_PROFILE_CONNECTIONS) {
    await loadProfilePage("", { refresh });
    await loadProfileConnections(
      normalizeString(readCurrentSearchParams().get("kind")) || "followers",
    );
    return;
  }
  if (routeKey === ROUTE_KEY_PROFILE_NOTIFICATIONS) {
    await loadProfilePage("", { refresh });
    await loadProfileNotifications({ refresh });
    return;
  }
  if (
    routeKey === ROUTE_KEY_ONBOARDING_PROFILE ||
    routeKey === ROUTE_KEY_ONBOARDING_PHOTO
  ) {
    await loadProfilePage("", { refresh });
    return;
  }
  if (
    routeKey === ROUTE_KEY_ONBOARDING_LOCATION ||
    routeKey === ROUTE_KEY_ONBOARDING_ADDRESS
  ) {
    await Promise.all([
      loadProfilePage("", { refresh }).catch(() => {}),
      loadSettingsMyProfile({ refresh }),
      loadSettingsMyDistricts({ refresh }),
    ]);
    return;
  }
  if (
    routeKey === ROUTE_KEY_SETTINGS ||
    routeKey === ROUTE_KEY_SETTINGS_SECTION
  ) {
    await loadSettingsPage({ refresh });
    return;
  }
  if (
    routeKey === ROUTE_KEY_TOPICS ||
    routeKey === ROUTE_KEY_ONBOARDING_TOPICS
  ) {
    await loadTopicsPage({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_POLICY_QUESTIONS) {
    await loadPolicyQuestionsPage({ refresh });
    return;
  }
  if (routeKey === ROUTE_KEY_POLICY_QUESTION_DETAIL) {
    await loadPolicyQuestionDetail(route.routeParams.questionId, { refresh });
    return;
  }
  if (
    routeKey === ROUTE_KEY_ADMIN ||
    routeKey === ROUTE_KEY_ADMIN_SECTION
  ) {
    await loadAdminPage({ refresh });
    return;
  }
  if (
    routeKey === ROUTE_KEY_MESSAGES_ROOT ||
    routeKey === ROUTE_KEY_MESSAGES_WILDCARD
  ) {
    const subroute = parseMessagingSubroute(route);
    if (subroute.aliasPath) {
      navigateTo(subroute.aliasPath, {
        replace: true,
      });
      return;
    }
    if (subroute.alias) {
      navigateTo(
        buildMessagingServerRoute(subroute.scopeType, subroute.scopeId),
        {
          replace: true,
        },
      );
      return;
    }
    if (subroute.view === "inbox" && subroute.restoreSavedTarget) {
      const restoreRoute = messagingRouteForWorkspaceTarget(
        readMessagingWorkspaceTarget(),
      );
      if (restoreRoute) {
        navigateTo(restoreRoute, {
          replace: true,
        });
        return;
      }
    }
    if (messagingAppLockBlocksMessages()) {
      releaseMessagingSessionForLock();
      scheduleRender();
      return;
    }
    rememberMessagingWorkspaceForSubroute(subroute);
    await ensureMessagingInitialized({ force: refresh });
    await connectMessagingSocketForRoute();
    if (subroute.view === "inbox") {
      await Promise.all([
        loadMessagingInbox({ refresh }),
        loadMessagingRequests(),
        loadMessagingServers(),
      ]);
      const defaultConversation = messagingDefaultInboxConversation();
      const defaultConversationId = normalizeString(
        defaultConversation?.conversationId,
      );
      const conversation = state.pages.messaging.conversation;
      const loadedConversationId = normalizeString(
        conversation.item?.conversationId,
      );
      if (
        defaultConversationId &&
        (refresh || !conversation.loaded || loadedConversationId !== defaultConversationId)
      ) {
        await loadMessagingConversation(defaultConversationId, {
          refresh:
            refresh ||
            !conversation.loaded ||
            loadedConversationId !== defaultConversationId,
        });
      }
      return;
    }
    if (subroute.view === "requests") {
      await Promise.all([
        loadMessagingRequests(),
        loadMessagingInbox({ refresh }).catch(() => {}),
        loadMessagingServers(),
      ]);
      return;
    }
    if (subroute.view === "compose") {
      await Promise.all([
        loadMessagingInbox({ refresh }).catch(() => {}),
        loadMessagingServers(),
        loadMessagingComposeFriends({ refresh }).catch(() => {}),
      ]);
      return;
    }
    if (subroute.view === "settings") {
      await Promise.all([
        loadMessagingSettings(),
        loadMessagingInbox({ refresh }).catch(() => {}),
        loadMessagingServers(),
      ]);
      return;
    }
    if (subroute.view === "devices") {
      await Promise.all([
        loadMessagingDevices(),
        loadMessagingRecovery().catch(() => {}),
        loadMessagingSecurity().catch(() => {}),
        loadMessagingServers(),
      ]);
      return;
    }
    if (subroute.view === "device-link") {
      await Promise.all([
        loadMessagingDevices(),
        loadMessagingRecovery().catch(() => {}),
        loadMessagingSecurity(),
        loadMessagingServers(),
      ]);
      if (subroute.linkId) {
        await loadMessagingDeviceLink(subroute.linkId);
      }
      return;
    }
    if (subroute.view === "recovery") {
      await Promise.all([
        loadMessagingRecovery(),
        loadMessagingDevices().catch(() => {}),
        loadMessagingSecurity().catch(() => {}),
        loadMessagingServers(),
      ]);
      return;
    }
    if (subroute.view === "recovery-restore") {
      await Promise.all([
        loadMessagingRecovery(),
        loadMessagingDevices().catch(() => {}),
        loadMessagingSecurity().catch(() => {}),
        loadMessagingServers(),
      ]);
      return;
    }
    if (subroute.view === "security") {
      await Promise.all([
        loadMessagingSecurity(),
        loadMessagingDevices().catch(() => {}),
        loadMessagingRecovery().catch(() => {}),
        loadMessagingServers(),
      ]);
      return;
    }
    if (subroute.view === "server") {
      await Promise.all([
        loadMessagingInbox({ refresh }).catch(() => {}),
        loadMessagingRequests().catch(() => {}),
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }),
      ]);
      return;
    }
    if (
      subroute.view === "server-settings" ||
      subroute.view === "server-settings-section"
    ) {
      const settingsPromises = [
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingServerSettings(subroute.scopeType, subroute.scopeId, {
          refresh,
        }),
      ];
      const settingsSectionId = messagingServerSettingsKnownSection(
        subroute.sectionId,
      );
      if (settingsSectionId === "audit-log") {
        settingsPromises.push(
          loadMessagingServerAudit(subroute.scopeType, subroute.scopeId, {
            refresh,
          }),
        );
      }
      if (settingsSectionId === "emoji" || settingsSectionId === "stickers") {
        settingsPromises.push(
          loadMessagingServerAssets(
            subroute.scopeType,
            subroute.scopeId,
            settingsSectionId === "emoji" ? "emoji" : "sticker",
            { refresh },
          ),
        );
      }
      if (settingsSectionId === "security") {
        settingsPromises.push(
          loadMessagingServerSecurityPolicy(
            subroute.scopeType,
            subroute.scopeId,
            { refresh },
          ),
        );
      }
      if (
        settingsSectionId === "community-settings" ||
        settingsSectionId === "invites"
      ) {
        settingsPromises.push(
          loadMessagingServerInvites(subroute.scopeType, subroute.scopeId, {
            refresh,
          }),
        );
        if (settingsSectionId === "invites") {
          settingsPromises.push(
            loadMessagingServerMembers(subroute.scopeType, subroute.scopeId, {
              refresh,
            }).catch(() => {}),
            loadMessagingServerBans(subroute.scopeType, subroute.scopeId, {
              refresh,
            }).catch(() => {}),
          );
        }
      }
      await Promise.all(settingsPromises);
      return;
    }
    if (subroute.view === "server-roles") {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingServerRoles(subroute.scopeType, subroute.scopeId, {
          refresh,
        }),
      ]);
      return;
    }
    if (subroute.view === "server-role") {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingServerRoleDetail(
          subroute.scopeType,
          subroute.scopeId,
          subroute.roleId,
          { refresh },
        ),
      ]);
      return;
    }
    if (subroute.view === "server-members") {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingServerMembers(subroute.scopeType, subroute.scopeId, {
          refresh,
        }),
      ]);
      return;
    }
    if (subroute.view === "server-member") {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingServerMembers(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingServerMember(
          subroute.scopeType,
          subroute.scopeId,
          subroute.userId,
          { refresh },
        ),
      ]);
      return;
    }
    if (subroute.view === "server-bans") {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingServerBans(subroute.scopeType, subroute.scopeId, {
          refresh,
        }),
      ]);
      return;
    }
    if (subroute.view === "server-workflows") {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingServerWorkflows(subroute.scopeType, subroute.scopeId, {
          refresh,
        }),
      ]);
      return;
    }
    if (subroute.view === "server-moderation") {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingServerModerationQueue(
          subroute.scopeType,
          subroute.scopeId,
          { refresh },
        ),
        loadMessagingServerAutomodRules(subroute.scopeType, subroute.scopeId, {
          refresh,
        }),
      ]);
      return;
    }
    if (subroute.view === "conversation") {
      await Promise.all([
        loadMessagingInbox({ refresh }),
        loadMessagingRequests().catch(() => {}),
        loadMessagingServers(),
        loadMessagingConversation(subroute.conversationId, {
          refresh,
          routeTargetMessageId: subroute.routeMessageId,
          fromNotification: subroute.fromNotification,
        }),
      ]);
      await loadMessagingSecureBrowserContextIfNeeded();
      return;
    }
    if (subroute.view === "conversation-people") {
      await Promise.all([
        loadMessagingInbox({ refresh }),
        loadMessagingRequests().catch(() => {}),
        loadMessagingServers(),
        loadMessagingConversation(subroute.conversationId, { refresh }),
        loadMessagingConversationMembers(subroute.conversationId, {
          refresh,
        }).catch(() => {}),
        loadMessagingGroupPeopleFriends({ refresh }).catch(() => {}),
      ]);
      await loadMessagingSecureBrowserContextIfNeeded();
      return;
    }
    if (subroute.view === "conversation-settings") {
      await Promise.all([
        loadMessagingInbox({ refresh }),
        loadMessagingRequests().catch(() => {}),
        loadMessagingServers(),
        loadMessagingConversation(subroute.conversationId, { refresh }),
        loadMessagingConversationMembers(subroute.conversationId, {
          refresh,
        }).catch(() => {}),
      ]);
      await loadMessagingSecureBrowserContextIfNeeded();
      return;
    }
    if (subroute.view === "server-room") {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingRequests().catch(() => {}),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingConversation(subroute.conversationId, {
          refresh,
          routeTargetMessageId: subroute.routeMessageId,
          fromNotification: subroute.fromNotification,
        }),
        loadMessagingConversationMembers(subroute.conversationId, {
          refresh,
        }).catch(() => {}),
        loadMessagingChannelPins(subroute.conversationId, {
          refresh,
        }).catch(() => {}),
      ]);
      await loadMessagingSecureBrowserContextIfNeeded();
      return;
    }
    if (
      subroute.view === "room-settings" ||
      subroute.view === "room-settings-notifications" ||
      subroute.view === "room-settings-pins" ||
      subroute.view === "room-settings-invites" ||
      subroute.view === "room-settings-integrations" ||
      subroute.view === "room-settings-section"
    ) {
      const roomSettingsLoaders = [
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingConversation(subroute.conversationId, { refresh }),
        loadMessagingConversationMembers(subroute.conversationId, { refresh }),
      ];
      if (subroute.view === "room-settings-invites") {
        roomSettingsLoaders.push(
          loadMessagingChannelInviteLinks(subroute.conversationId, {
            refresh,
          }),
        );
      }
      if (subroute.view === "room-settings-pins") {
        roomSettingsLoaders.push(
          loadMessagingChannelPins(subroute.conversationId, {
            refresh,
          }),
        );
      }
      if (subroute.view === "room-settings-integrations") {
        roomSettingsLoaders.push(
          loadMessagingServerWorkflows(subroute.scopeType, subroute.scopeId, {
            refresh,
          }),
        );
      }
      await Promise.all(roomSettingsLoaders);
      return;
    }
    if (
      subroute.view === "room-permissions" ||
      subroute.view === "room-permission-role"
    ) {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingConversation(subroute.conversationId, { refresh }).catch(
          () => {},
        ),
        loadMessagingPermissionTarget("channel", subroute.conversationId, {
          refresh,
        }),
      ]);
      if (subroute.roleId) {
        await loadMessagingServerRoles(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {});
      }
      return;
    }
    if (
      subroute.view === "category-permissions" ||
      subroute.view === "category-permission-role"
    ) {
      await Promise.all([
        loadMessagingServers(),
        loadMessagingServerDirectory(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {}),
        loadMessagingPermissionTarget("category", subroute.categoryId, {
          refresh,
        }),
      ]);
      if (subroute.roleId) {
        await loadMessagingServerRoles(subroute.scopeType, subroute.scopeId, {
          refresh,
        }).catch(() => {});
      }
      return;
    }
  }
}

function findFeedPostItem(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    return null;
  }
  return (
    getCurrentItems().find(
      (item) => item.kind === "post" && item.postId === normalizedPostId,
    ) || null
  );
}

function findPostShareFeedItem(postId) {
  return findFeedPostItem(postId);
}

function findWebPostItem(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    return null;
  }
  return (
    findFeedPostItem(normalizedPostId) ||
    state.pages.profile.posts.items.find(
      (item) => item.kind === "post" && item.postId === normalizedPostId,
    ) ||
    null
  );
}

function canManagePostItem(item = {}) {
  const currentUserId = normalizeString(state.auth.user?.userId);
  return Boolean(
    item?.kind === "post" &&
      normalizeString(item.postId) &&
      currentUserId &&
      normalizeString(item.authorUserId) === currentUserId,
  );
}

function canDeletePostItem(item = {}) {
  return canManagePostItem(item);
}

function normalizeCrosspostTimestamp(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
}

function crosspostProviderLabel(provider) {
  const normalized = normalizeString(provider).toLowerCase();
  const labels = {
    facebook: "Facebook",
    instagram: "Instagram",
    linkedin: "LinkedIn",
    meta: "Meta",
    tiktok: "TikTok",
    x: "X",
    youtube: "YouTube",
  };
  return labels[normalized] || humanizeLabel(normalized) || "Social account";
}

function normalizeCrosspostJobStatus(raw = {}) {
  if (!raw || typeof raw !== "object") {
    return null;
  }
  const provider = normalizeString(raw.provider || raw.platform || raw.network);
  const status =
    normalizeString(raw.status || raw.state || raw.jobStatus) || "queued";
  const jobId =
    normalizeString(raw.jobId || raw.id || raw.job_id) ||
    `${provider || "crosspost"}:${normalizeString(raw.targetId || raw.target_id)}`;
  if (!jobId) {
    return null;
  }
  return {
    jobId,
    provider,
    providerLabel: crosspostProviderLabel(provider),
    targetId: normalizeString(raw.targetId || raw.target_id),
    targetKind: normalizeString(raw.targetKind || raw.target_kind),
    targetLabel: normalizeString(raw.targetLabel || raw.target_label),
    status,
    externalPostId: normalizeString(raw.externalPostId || raw.external_post_id),
    externalPostUrl: normalizeUrl(raw.externalPostUrl || raw.external_post_url),
    lastError: normalizeString(raw.lastError || raw.last_error || raw.error),
    scheduledAt: normalizeCrosspostTimestamp(raw.scheduledAt || raw.scheduled_at),
    updatedAt: normalizeCrosspostTimestamp(raw.updatedAt || raw.updated_at),
    retryEligible:
      raw.retryEligible !== false &&
      raw.retry_eligible !== false &&
      raw.canRetry !== false,
    raw,
  };
}

function normalizeCrosspostJobsPayload(payload = {}) {
  return readArrayPayload(payload, ["jobs", "items", "crossposts", "statuses"])
    .map(normalizeCrosspostJobStatus)
    .filter(Boolean);
}

function crosspostStatusTone(status = "") {
  const normalized = normalizeString(status).toLowerCase();
  if (["published", "complete", "completed", "succeeded", "success"].includes(normalized)) {
    return "success";
  }
  if (["failed", "error", "canceled", "cancelled"].includes(normalized)) {
    return "danger";
  }
  if (["processing", "publishing", "running", "in_progress"].includes(normalized)) {
    return "active";
  }
  if (["scheduled", "queued", "pending"].includes(normalized)) {
    return "pending";
  }
  return "neutral";
}

function canRetryCrosspostJob(job = {}) {
  const status = normalizeString(job.status).toLowerCase();
  return Boolean(
    job.retryEligible !== false && ["failed", "canceled", "cancelled"].includes(status),
  );
}

function normalizePostReportCategory(raw = {}) {
  const key = normalizeString(raw.key || raw.id || raw.category);
  const label =
    normalizeString(raw.label || raw.name || raw.title) ||
    humanizeLabel(key);
  if (!key || !label) {
    return null;
  }
  return {
    key,
    label,
    description: normalizeString(raw.description || raw.detail || raw.copy),
    severity: normalizeString(raw.severity),
    defaultAction: normalizeString(raw.defaultAction || raw.default_action),
    requiresHumanReview: raw.requiresHumanReview === true,
  };
}

function currentPostReportSource() {
  if (state.feedContext.kind === "share") {
    return "web_share";
  }
  return state.mode === FEED_MODE_FOLLOWING ? "following" : "for_you";
}

function currentPostReportSessionId() {
  return normalizeString(state.feeds[state.mode]?.sessionId);
}

function removeReportedPostFromActiveFeed(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId || state.feedContext.kind === "share") {
    return;
  }
  for (const mode of [FEED_MODE_FOR_YOU, FEED_MODE_FOLLOWING]) {
    state.feeds[mode].items = state.feeds[mode].items.filter(
      (item) => item.kind !== "post" || item.postId !== normalizedPostId,
    );
  }
  ensureActiveIndexInBounds();
}

function removePostFromWebCollections(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    return;
  }
  for (const mode of [FEED_MODE_FOR_YOU, FEED_MODE_FOLLOWING]) {
    state.feeds[mode].items = state.feeds[mode].items.filter(
      (item) => item.kind !== "post" || item.postId !== normalizedPostId,
    );
  }
  state.pages.profile.posts.items = state.pages.profile.posts.items.filter(
    (item) => item.kind !== "post" || item.postId !== normalizedPostId,
  );
  if (state.ui.comments.postId === normalizedPostId) {
    state.ui.comments.open = false;
  }
  if (state.ui.likers.postId === normalizedPostId) {
    state.ui.likers.open = false;
  }
  ensureActiveIndexInBounds();
}

async function loadPostReportCategories({ refresh = false } = {}) {
  const report = state.ui.postReport;
  if (!report.open || report.loading) {
    return;
  }
  if (!refresh && report.categoriesLoaded && report.categories.length) {
    return;
  }
  state.ui.postReport = createPostReportState({
    ...report,
    loading: true,
    error: "",
    notice: "",
  });
  scheduleRender();
  try {
    const payload = await fetchJson("/api/report/categories", {
      auth: Boolean(state.auth.session),
    });
    const categories = readArrayPayload(payload, ["categories", "items"])
      .map(normalizePostReportCategory)
      .filter(Boolean);
    if (!categories.length) {
      throw new Error("Unable to load report reasons. Please try again.");
    }
    if (!state.ui.postReport.open) {
      return;
    }
    state.ui.postReport = createPostReportState({
      ...state.ui.postReport,
      categories,
      categoriesLoaded: true,
      loading: false,
      error: "",
    });
  } catch (error) {
    if (!state.ui.postReport.open) {
      return;
    }
    state.ui.postReport = createPostReportState({
      ...state.ui.postReport,
      loading: false,
      categoriesLoaded: false,
      error: settingsErrorMessage(
        error,
        "Unable to load report reasons. Please try again.",
      ),
    });
  } finally {
    scheduleRender();
  }
}

async function openPostReport(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    showToast("Report unavailable for this post.");
    return;
  }
  const item = findFeedPostItem(normalizedPostId);
  if (!item) {
    showToast("Report unavailable for this post.");
    return;
  }
  if (!state.auth.session) {
    openAuthModal("report_post", {
      postId: normalizedPostId,
      title: "Log in to report posts",
      message: "Sign in to send this post to Polis moderators for review.",
      targetPath: getCurrentPathWithQuery(),
    });
    return;
  }
  const previous = state.ui.postReport;
  state.ui.postReport = createPostReportState({
    open: true,
    postId: normalizedPostId,
    categories: previous.categories,
    categoriesLoaded: previous.categoriesLoaded,
  });
  scheduleRender();
  await loadPostReportCategories();
}

function closePostReport() {
  const report = state.ui.postReport;
  state.ui.postReport = createPostReportState({
    categories: report.categories,
    categoriesLoaded: report.categoriesLoaded,
  });
  scheduleRender();
}

async function submitPostReport(formData) {
  const report = state.ui.postReport;
  const postId = normalizeString(report.postId);
  const item = findFeedPostItem(postId);
  const category = normalizeString(formData.get("category"));
  const details = normalizeString(formData.get("details"));
  if (!postId || !item) {
    state.ui.postReport = createPostReportState({
      ...report,
      error: "Report unavailable for this post.",
    });
    scheduleRender();
    return;
  }
  if (!category) {
    state.ui.postReport = createPostReportState({
      ...report,
      details,
      error: "Choose a reason before sending.",
    });
    scheduleRender();
    return;
  }
  if (!state.auth.session) {
    openAuthModal("report_post", {
      postId,
      title: "Log in to report posts",
      message: "Sign in to send this post to Polis moderators for review.",
      targetPath: getCurrentPathWithQuery(),
    });
    return;
  }
  state.ui.postReport = createPostReportState({
    ...report,
    selectedCategory: category,
    details,
    submitting: true,
    error: "",
    notice: "",
  });
  scheduleRender();
  try {
    const body = {
      category,
      source: currentPostReportSource(),
    };
    const sessionId = currentPostReportSessionId();
    if (details) {
      body.details = details;
    }
    if (sessionId) {
      body.sessionId = sessionId;
    }
    if (item.impressionToken) {
      body.impressionToken = item.impressionToken;
    }
    if (Number.isFinite(Number(item.feedSlot))) {
      body.feedSlot = Number(item.feedSlot);
    }
    await fetchJson(`/api/posts/${encodeURIComponent(postId)}/report`, {
      auth: true,
      method: "POST",
      body,
    });
    const previousCategories = state.ui.postReport.categories;
    state.ui.postReport = createPostReportState({
      categories: previousCategories,
      categoriesLoaded: true,
    });
    removeReportedPostFromActiveFeed(postId);
    showToast("Thanks for letting us know.");
  } catch (error) {
    state.ui.postReport = createPostReportState({
      ...state.ui.postReport,
      submitting: false,
      error: settingsErrorMessage(
        error,
        "Failed to send report. Please try again.",
      ),
    });
    scheduleRender();
  }
}

function postCrosspostErrorMessage(error, fallback) {
  if (error?.status === 401) {
    return "Sign in to view crosspost status.";
  }
  if (error?.status === 403) {
    return "Crosspost status is only available for your own posts.";
  }
  if (error?.status === 404) {
    return "No crosspost status was found for this post.";
  }
  return settingsErrorMessage(error, fallback);
}

function readCrosspostRetryCount(payload = {}) {
  if (typeof payload === "number") {
    return Math.max(0, Math.floor(payload));
  }
  if (Array.isArray(payload)) {
    return payload.length;
  }
  const numeric = Number(
    payload?.requeued ||
      payload?.requeuedCount ||
      payload?.retried ||
      payload?.retryCount ||
      payload?.count,
  );
  if (Number.isFinite(numeric)) {
    return Math.max(0, Math.floor(numeric));
  }
  return readArrayPayload(payload, ["jobs", "items", "crossposts"]).length;
}

async function loadPostCrossposts({ refresh = false } = {}) {
  const panel = state.ui.postCrossposts;
  const postId = normalizeString(panel.postId);
  if (!postId || panel.loading) {
    return;
  }
  state.ui.postCrossposts = createPostCrosspostsState({
    ...panel,
    loading: true,
    loaded: refresh ? false : panel.loaded,
    error: "",
  });
  scheduleRender();
  try {
    const payload = await fetchJson(
      `/api/posts/${encodeURIComponent(postId)}/crossposts`,
      { auth: true },
    );
    state.ui.postCrossposts = createPostCrosspostsState({
      ...state.ui.postCrossposts,
      jobs: normalizeCrosspostJobsPayload(payload),
      loaded: true,
      loading: false,
      error: "",
    });
  } catch (error) {
    state.ui.postCrossposts = createPostCrosspostsState({
      ...state.ui.postCrossposts,
      loading: false,
      loaded: false,
      error: postCrosspostErrorMessage(
        error,
        "Crosspost status could not be loaded.",
      ),
    });
  } finally {
    scheduleRender();
  }
}

async function openPostCrossposts(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    showToast("Crosspost status unavailable for this post.");
    return;
  }
  const item = findWebPostItem(normalizedPostId);
  if (item && !canManagePostItem(item)) {
    showToast("Crosspost status is only available for your own posts.");
    return;
  }
  if (!state.auth.session) {
    openAuthModal("crosspost_status", {
      postId: normalizedPostId,
      title: "Log in to view crosspost status",
      message: "Sign in to review social publishing jobs for your Polis posts.",
      targetPath: getCurrentPathWithQuery(),
    });
    return;
  }
  state.ui.postCrossposts = createPostCrosspostsState({
    open: true,
    postId: normalizedPostId,
  });
  scheduleRender();
  await loadPostCrossposts({ refresh: true });
}

function closePostCrossposts() {
  state.ui.postCrossposts = createPostCrosspostsState();
  scheduleRender();
}

async function retryPostCrossposts() {
  const panel = state.ui.postCrossposts;
  const postId = normalizeString(panel.postId);
  if (!postId || panel.retrying || panel.loading) {
    return;
  }
  const retryableCount = panel.jobs.filter(canRetryCrosspostJob).length;
  if (!retryableCount) {
    showToast("No failed crossposts are ready to retry.");
    return;
  }
  state.ui.postCrossposts = createPostCrosspostsState({
    ...panel,
    retrying: true,
    error: "",
    notice: "",
  });
  scheduleRender();
  try {
    const payload = await fetchJson(
      `/api/posts/${encodeURIComponent(postId)}/crossposts/retry`,
      { auth: true, method: "POST", body: {} },
    );
    const requeued = readCrosspostRetryCount(payload);
    const notice = `Requeued ${formatCount(requeued)} crosspost ${
      requeued === 1 ? "job" : "jobs"
    }.`;
    state.ui.postCrossposts = createPostCrosspostsState({
      ...state.ui.postCrossposts,
      retrying: false,
      notice,
    });
    showToast(notice);
    await loadPostCrossposts({ refresh: true });
  } catch (error) {
    state.ui.postCrossposts = createPostCrosspostsState({
      ...state.ui.postCrossposts,
      retrying: false,
      error: postCrosspostErrorMessage(error, "Retry failed. Please try again."),
    });
    scheduleRender();
  }
}

function openPostAnalyticsForPost(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    showToast("Post analytics unavailable.");
    return;
  }
  const item = findWebPostItem(normalizedPostId);
  if (item && !canManagePostItem(item)) {
    showToast("Analytics are only available for your own posts.");
    return;
  }
  if (!state.auth.session) {
    openAuthModal("post_analytics", {
      postId: normalizedPostId,
      title: "Log in to view analytics",
      message: "Sign in to see analytics for your Polis posts.",
      targetPath: getCurrentPathWithQuery(),
    });
    return;
  }
  navigateTo(`/posts/${encodeURIComponent(normalizedPostId)}/analytics`);
}

async function openPostDelete(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    showToast("Delete unavailable for this post.");
    return;
  }
  const item = findFeedPostItem(normalizedPostId) ||
    state.pages.profile.posts.items.find(
      (candidate) =>
        candidate.kind === "post" && candidate.postId === normalizedPostId,
    );
  if (!item || !canDeletePostItem(item)) {
    showToast("Delete unavailable for this post.");
    return;
  }
  if (!state.auth.session) {
    openAuthModal("delete_post", {
      postId: normalizedPostId,
      title: "Log in to delete posts",
      message: "Sign in to delete posts from your Polis profile.",
      targetPath: getCurrentPathWithQuery(),
    });
    return;
  }
  state.ui.postDelete = createPostDeleteState({
    open: true,
    postId: normalizedPostId,
  });
  scheduleRender();
}

function closePostDelete() {
  state.ui.postDelete = createPostDeleteState();
  scheduleRender();
}

async function submitPostDelete() {
  const deleteState = state.ui.postDelete;
  const postId = normalizeString(deleteState.postId);
  const item = findFeedPostItem(postId) ||
    state.pages.profile.posts.items.find(
      (candidate) => candidate.kind === "post" && candidate.postId === postId,
    );
  if (!postId || !item || !canDeletePostItem(item)) {
    state.ui.postDelete = createPostDeleteState({
      ...deleteState,
      error: "Delete unavailable for this post.",
    });
    scheduleRender();
    return;
  }
  state.ui.postDelete = createPostDeleteState({
    ...deleteState,
    submitting: true,
    error: "",
  });
  scheduleRender();
  try {
    const payload = await fetchJson(`/api/posts/${encodeURIComponent(postId)}`, {
      auth: true,
      method: "DELETE",
    });
    const deletionState = normalizeString(
      payload?.deletionState || payload?.state || payload?.status,
    ).toUpperCase();
    state.ui.postDelete = createPostDeleteState();
    removePostFromWebCollections(postId);
    showToast(
      deletionState === "SOFT_DELETED_PENDING_REPORTS"
        ? "Removed from your profile while under review."
        : "Post deleted.",
    );
    if (isShareRoute()) {
      navigateTo("/profile", { replace: true });
      return;
    }
  } catch (error) {
    state.ui.postDelete = createPostDeleteState({
      ...state.ui.postDelete,
      submitting: false,
      error: settingsErrorMessage(error, "Failed to delete post."),
    });
    scheduleRender();
  }
}

function postShareTitleFromCaption(caption = "") {
  const normalized = normalizeString(caption).replace(/\s+/gu, " ");
  if (!normalized) {
    return "";
  }
  return normalized.length > 88 ? `${normalized.slice(0, 85)}...` : normalized;
}

function buildPostSharePreviewFromPost(postId) {
  const normalizedPostId = normalizeString(postId);
  const item = findPostShareFeedItem(normalizedPostId);
  const caption = normalizeString(item?.caption);
  const mediaType = normalizeString(item?.mediaType).toLowerCase();
  return {
    postId: normalizedPostId,
    brandName: "Polis",
    authorDisplayName: normalizeString(item?.authorDisplayName) || "Polis",
    authorUsername: normalizeString(item?.authorUsername),
    canonicalUrl:
      normalizeUrl(item?.canonicalUrl) ||
      (normalizedPostId ? getShareUrl(normalizedPostId) : ""),
    previewTitle:
      normalizeString(item?.previewTitle) ||
      postShareTitleFromCaption(caption) ||
      "Shared Polis post",
    previewText: caption,
    mediaType: mediaType === "image" ? "image" : "video",
    previewVideoUrl:
      mediaType === "video"
        ? normalizeUrl(item?.videoUrl || item?.mp4Url || item?.raw?.mediaUrl)
        : "",
    previewMediaThumbnail: normalizeUrl(item?.posterUrl || item?.imageUrl),
    postTimestamp: Number(item?.createdAt) || null,
  };
}

function normalizePostSharePreviewPayload(payload = {}, postId = "") {
  const source =
    payload?.preview && typeof payload.preview === "object"
      ? payload.preview
      : payload?.snapshot && typeof payload.snapshot === "object"
        ? payload.snapshot
        : payload && typeof payload === "object"
          ? payload
          : {};
  const fallback = buildPostSharePreviewFromPost(postId);
  return {
    ...source,
    postId:
      normalizeString(source.postId || source.id || postId) ||
      fallback.postId,
    brandName: normalizeString(source.brandName) || fallback.brandName,
    authorDisplayName:
      normalizeString(source.authorDisplayName || source.displayName) ||
      fallback.authorDisplayName,
    authorUsername:
      normalizeString(source.authorUsername || source.username) ||
      fallback.authorUsername,
    canonicalUrl:
      normalizeUrl(source.canonicalUrl || source.url) || fallback.canonicalUrl,
    previewTitle:
      normalizeString(source.previewTitle || source.title) ||
      fallback.previewTitle,
    previewText:
      normalizeString(source.previewText || source.text || source.description) ||
      fallback.previewText,
    mediaType:
      normalizeString(source.mediaType || source.type).toLowerCase() ||
      fallback.mediaType,
    previewVideoUrl:
      normalizeUrl(
        source.previewVideoUrl ||
          source.playbackUrl ||
          source.videoUrl ||
          source.mediaUrl,
      ) || fallback.previewVideoUrl,
    previewMediaThumbnail:
      normalizeUrl(
        source.previewMediaThumbnail ||
          source.thumbnailUrl ||
          source.imageUrl ||
          source.mediaThumbnailUrl,
      ) || fallback.previewMediaThumbnail,
    postTimestamp:
      Number(source.postTimestamp || source.createdAt || source.timestamp) ||
      fallback.postTimestamp,
  };
}

function normalizePostShareServerDirectoryPayload(payload = {}, server = {}) {
  const source =
    payload?.directory && typeof payload.directory === "object"
      ? payload.directory
      : payload && typeof payload === "object"
        ? payload
        : {};
  return {
    scopeType: normalizeString(server.scopeType || source.scopeType).toLowerCase(),
    scopeId: normalizeString(server.scopeId || source.scopeId),
    title: normalizeString(server.title || source.title) || "Workspace",
    avatarUrl: normalizeUrl(server.avatarUrl || source.avatarUrl),
    scopeBadge: normalizeString(server.scopeBadge || source.scopeBadge) || "Workspace",
    canManage: server.canManage === true || source.canManage === true,
    channels: (Array.isArray(source.channels) ? source.channels : [])
      .map(normalizeMessagingConversation)
      .filter((channel) =>
        postShareChannelIsPostable(channel, {
          canManageServer: server.canManage === true || source.canManage === true,
        }),
      ),
  };
}

async function fetchPostSharePreview(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    return null;
  }
  const payload = await fetchJson("/api/messaging/share-preview", {
    auth: true,
    method: "POST",
    body: { postId: normalizedPostId },
  });
  return normalizePostSharePreviewPayload(payload, normalizedPostId);
}

async function fetchPostShareServerDirectory(server) {
  const scopeType = normalizeString(server?.scopeType).toLowerCase();
  const scopeId = normalizeString(server?.scopeId);
  if (!scopeType || !scopeId) {
    return normalizePostShareServerDirectoryPayload({}, server);
  }
  const query = buildMessagingScopeQuery(scopeType, scopeId);
  const payload = await fetchJson(`/api/messaging/server-directory?${query}`, {
    auth: true,
  });
  return normalizePostShareServerDirectoryPayload(payload, server);
}

function closePostShare() {
  state.ui.postShare = createPostShareState();
  scheduleRender();
}

async function loadPostShareSheetData(postId, { refreshConversations = false } = {}) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    return;
  }
  const currentShare = state.ui.postShare;
  if (!currentShare.open || currentShare.postId !== normalizedPostId) {
    return;
  }
  state.ui.postShare = createPostShareState({
    ...currentShare,
    loading: true,
    error: "",
    notice: "",
  });
  scheduleRender();

  const previewTask = fetchPostSharePreview(normalizedPostId);
  const inboxTask = (async () => {
    await ensureMessagingInitialized();
    await Promise.all([
      loadMessagingInbox({
        refresh: refreshConversations || !state.pages.messaging.inbox.loaded,
      }),
      refreshConversations || !state.pages.messaging.servers.loaded
        ? loadMessagingServers()
        : Promise.resolve(),
    ]);
  })();
  const [previewResult] = await Promise.allSettled([previewTask, inboxTask]);
  if (
    !state.ui.postShare.open ||
    state.ui.postShare.postId !== normalizedPostId
  ) {
    return;
  }

  const preview =
    previewResult.status === "fulfilled" && previewResult.value
      ? previewResult.value
      : buildPostSharePreviewFromPost(normalizedPostId);
  const inboxError = normalizeString(state.pages.messaging.inbox.error);
  const serversError = normalizeString(state.pages.messaging.servers.error);
  const messagingError = normalizeString(state.pages.messaging.error);
  const hasConversations = Boolean(state.pages.messaging.inbox.items?.length);
  const hasServers = Boolean(state.pages.messaging.servers.items?.length);
  state.ui.postShare = createPostShareState({
    ...state.ui.postShare,
    preview,
    loading: false,
    error:
      inboxError && !hasConversations && !hasServers
        ? inboxError
        : serversError && !hasConversations && !hasServers
          ? serversError
          : messagingError && !hasConversations && !hasServers
          ? messagingError
          : "",
  });
  scheduleRender();
}

function findPostShareServer(scopeType, scopeId) {
  const normalizedScopeType = normalizeString(scopeType).toLowerCase();
  const normalizedScopeId = normalizeString(scopeId);
  return (
    state.pages.messaging.servers.items.find(
      (server) =>
        normalizeString(server.scopeType).toLowerCase() === normalizedScopeType &&
        normalizeString(server.scopeId) === normalizedScopeId,
    ) || null
  );
}

function postShareChannelIsPostable(channel = {}, { canManageServer = false } = {}) {
  const raw = channel.raw && typeof channel.raw === "object" ? channel.raw : {};
  const settings =
    raw.settings && typeof raw.settings === "object" && !Array.isArray(raw.settings)
      ? raw.settings
      : {};
  const kind = normalizeString(channel.kind || raw.kind || raw.type).toLowerCase();
  const folder = normalizeString(channel.folder || raw.folder).toLowerCase();
  if (kind !== "room" || folder === "request") {
    return false;
  }
  if (
    channel.isReadOnly ||
    raw.isHidden === true ||
    raw.hidden === true ||
    raw.isArchived === true ||
    raw.archived === true ||
    raw.isDraft === true ||
    raw.draft === true
  ) {
    return false;
  }
  const membershipState = normalizeString(raw.membershipState || raw.membership_state)
    .toLowerCase();
  if (membershipState && membershipState !== "active") {
    return false;
  }
  const roomType = normalizeString(settings.roomType || raw.roomType).toLowerCase();
  const announcementOnly =
    roomType === "announcement_only" ||
    settings.announcementOnly === true ||
    raw.announcementOnly === true;
  return !announcementOnly || canManageServer === true;
}

function postShareChannelSubtitle(channel = {}) {
  const raw = channel.raw && typeof channel.raw === "object" ? channel.raw : {};
  const settings =
    raw.settings && typeof raw.settings === "object" && !Array.isArray(raw.settings)
      ? raw.settings
      : {};
  const roomType = normalizeString(settings.roomType || raw.roomType).toLowerCase();
  if (normalizeString(channel.lastMessagePreview)) {
    return channel.lastMessagePreview;
  }
  if (settings.announcementOnly === true || roomType === "announcement_only") {
    return "Announcement room";
  }
  if (roomType === "private_invite_only") return "Private room";
  if (roomType === "staff_only") return "Staff room";
  if (roomType === "volunteer") return "Volunteer room";
  if (roomType === "ops") return "Operations room";
  return "Room";
}

async function openPostShareServerPicker(scopeType, scopeId) {
  const share = state.ui.postShare;
  if (!share.open || share.sendingConversationId) {
    return;
  }
  const server = findPostShareServer(scopeType, scopeId);
  if (!server) {
    state.ui.postShare = createPostShareState({
      ...share,
      error: "Workspace unavailable.",
    });
    scheduleRender();
    return;
  }
  const pickerSeed = {
    open: true,
    loading: true,
    error: "",
    scopeType: server.scopeType,
    scopeId: server.scopeId,
    title: server.title,
    avatarUrl: server.avatarUrl,
    scopeBadge: server.scopeBadge,
    canManage: server.canManage,
    channels: [],
  };
  state.ui.postShare = createPostShareState({
    ...share,
    roomPicker: pickerSeed,
    error: "",
    notice: "",
  });
  scheduleRender();
  try {
    const directory = await fetchPostShareServerDirectory(server);
    if (
      !state.ui.postShare.open ||
      normalizeString(state.ui.postShare.roomPicker.scopeType) !==
        normalizeString(server.scopeType).toLowerCase() ||
      normalizeString(state.ui.postShare.roomPicker.scopeId) !==
        normalizeString(server.scopeId)
    ) {
      return;
    }
    state.ui.postShare = createPostShareState({
      ...state.ui.postShare,
      roomPicker: {
        ...directory,
        open: true,
        loading: false,
        error: "",
      },
    });
  } catch (error) {
    if (
      state.ui.postShare.open &&
      normalizeString(state.ui.postShare.roomPicker.scopeType) ===
        normalizeString(server.scopeType).toLowerCase() &&
      normalizeString(state.ui.postShare.roomPicker.scopeId) ===
        normalizeString(server.scopeId)
    ) {
      state.ui.postShare = createPostShareState({
        ...state.ui.postShare,
        roomPicker: {
          ...pickerSeed,
          loading: false,
          error:
            normalizeString(error?.message) ||
            "Rooms could not be loaded for this workspace.",
        },
      });
    }
  } finally {
    scheduleRender();
  }
}

function closePostShareServerPicker() {
  state.ui.postShare = createPostShareState({
    ...state.ui.postShare,
    roomPicker: { open: false },
    error: "",
  });
  scheduleRender();
}

async function openPostShare(postId) {
  const normalizedPostId = normalizeString(postId);
  if (!normalizedPostId) {
    showToast("Post unavailable.");
    return;
  }
  if (!state.auth.session) {
    await sharePostExternally(normalizedPostId);
    return;
  }
  state.ui.postShare = createPostShareState({
    open: true,
    postId: normalizedPostId,
    preview: buildPostSharePreviewFromPost(normalizedPostId),
    loading: true,
  });
  scheduleRender();
  await loadPostShareSheetData(normalizedPostId);
}

async function sharePostExternally(postId) {
  const shareUrl = getShareUrl(postId);
  try {
    if (navigator.share) {
      await navigator.share({
        title: "Polis",
        text: "Watch this Polis post",
        url: shareUrl,
      });
      return;
    }
    await navigator.clipboard.writeText(shareUrl);
    showToast("Link copied.");
  } catch {
    showToast("Sharing unavailable on this device.");
  }
}

async function copyPostShareLink() {
  const postId = normalizeString(state.ui.postShare.postId);
  if (!postId) {
    showToast("Post link unavailable.");
    return;
  }
  try {
    await navigator.clipboard.writeText(getShareUrl(postId));
    state.ui.postShare = createPostShareState({
      ...state.ui.postShare,
      notice: "Link copied.",
      error: "",
    });
    showToast("Link copied.");
    scheduleRender();
  } catch {
    state.ui.postShare = createPostShareState({
      ...state.ui.postShare,
      error: "Copy is unavailable in this browser.",
    });
    showToast("Copy unavailable.");
    scheduleRender();
  }
}

function appendPostShareMessageToActiveConversation(conversationId, rawMessage) {
  const normalizedConversationId = normalizeString(conversationId);
  const conversation = state.pages.messaging.conversation;
  if (
    !normalizedConversationId ||
    normalizeString(conversation.item?.conversationId) !== normalizedConversationId
  ) {
    return;
  }
  const message = normalizeMessagingMessage(rawMessage);
  if (!message.messageId) {
    return;
  }
  const existingIndex = conversation.messages.findIndex(
    (item) => item.messageId === message.messageId,
  );
  if (existingIndex >= 0) {
    conversation.messages = conversation.messages.map((item, index) =>
      index === existingIndex ? message : item,
    );
  } else {
    conversation.messages = [...conversation.messages, message];
  }
}

async function sendPostShareToConversation(conversationId) {
  const normalizedConversationId = normalizeString(conversationId);
  const share = state.ui.postShare;
  const postId = normalizeString(share.postId);
  if (!normalizedConversationId || !postId) {
    showToast("Choose a conversation first.");
    return;
  }
  if (!state.auth.session) {
    openAuthModal("share-post", {
      postId,
      title: "Log in to share in Polis",
      message: "Sign in to send this post through Polis messages.",
    });
    return;
  }
  state.ui.postShare = createPostShareState({
    ...share,
    sendingConversationId: normalizedConversationId,
    error: "",
    notice: "",
  });
  scheduleRender();
  try {
    const preview =
      share.preview || normalizePostSharePreviewPayload({}, postId);
    const payload = await fetchJson(
      `/api/messaging/conversations/${encodeURIComponent(normalizedConversationId)}/messages`,
      {
        auth: true,
        method: "POST",
        body: {
          clientMessageId: buildMessagingClientMessageId(),
          type: "post_share",
          postId,
          snapshot: preview,
        },
      },
    );
    appendPostShareMessageToActiveConversation(
      normalizedConversationId,
      payload.message || payload,
    );
    closePostShare();
    showToast("Post sent in messages.");
    loadMessagingInbox({ refresh: true }).catch(() => {});
  } catch (error) {
    if (
      state.ui.postShare.open &&
      state.ui.postShare.postId === postId &&
      state.ui.postShare.sendingConversationId === normalizedConversationId
    ) {
      state.ui.postShare = createPostShareState({
        ...state.ui.postShare,
        sendingConversationId: "",
        error: normalizeString(error?.message) || "Post could not be sent.",
      });
      scheduleRender();
    }
  }
}

async function handleShare(postId) {
  await openPostShare(postId);
}

function requestAppOpen(postId, commentId = "") {
  const targetUrl = buildAppOpenUrl(postId, commentId);
  if (!targetUrl) {
    showToast("App link unavailable.");
    return;
  }
  window.location.assign(targetUrl);
}

