function buildSearchResultsRoute(query) {
  return buildRouteWithQuery("/search/results", { q: query });
}

function renderSearchForm({ query = "", compact = false } = {}) {
  const formClass = compact
    ? "shared-search-form shared-search-form--compact"
    : "shared-search-form";
  return `<form class="${formClass}" data-route-form="global-search">
    <span class="shared-search-form__icon" aria-hidden="true">${renderIcon("search")}</span>
    <input type="search" name="q" value="${escapeHtml(query)}" placeholder="Search Polis" autocomplete="off" />
    <button class="shared-feed-chip shared-feed-chip--primary" type="submit">Search</button>
  </form>`;
}

function renderSearchSuggestionButton(item) {
  return `<button class="shared-search-query-chip" type="button" data-action="search-query" data-query="${escapeHtml(item.label)}">
    <span>${escapeHtml(item.label)}</span>
    ${item.secondary ? `<small>${escapeHtml(item.secondary)}</small>` : ""}
  </button>`;
}

