function renderPostAnalyticsPage() {
  const resource = state.pages.postAnalytics;
  const postId =
    normalizeString(resource.postId) ||
    normalizeString(getCurrentRoute().routeParams?.postId);
  const item = resource.item;
  const postRoute = postId ? `/posts/${encodeURIComponent(postId)}` : "/feed";
  const engagementTotal = item ? item.likes + item.comments + item.shares : 0;
  const engagementRate =
    item && item.views > 0 ? (engagementTotal / item.views) * 100 : null;
  const maxBreakdown = item
    ? Math.max(item.likes, item.comments, item.shares, 1)
    : 1;
  const cards = item
    ? [
        {
          icon: "chart",
          label: "Views",
          value: formatCount(item.views),
          caption: "Reach",
        },
        {
          icon: "heart",
          label: "Likes",
          value: formatCount(item.likes),
          caption: "Reactions",
        },
        {
          icon: "comment",
          label: "Comments",
          value: formatCount(item.comments),
          caption: "Replies",
        },
        {
          icon: "share",
          label: "Shares",
          value: formatCount(item.shares),
          caption: "Amplification",
        },
        {
          icon: "play",
          label: "Avg watch time",
          value: formatPostAnalyticsDuration(item.avgWatchTimeMs),
          caption: "Video retention",
        },
      ]
    : [];

  return `<section class="shared-page shared-post-analytics-page">
    ${renderTopChrome()}
    <div class="shared-page__content">
      <section class="shared-post-analytics-hero">
        <div>
          <span class="shared-discover-eyebrow">Post analytics</span>
          <h1>Post performance</h1>
          <p>Measure reach, response, sharing, and watch quality for this post.</p>
        </div>
        <div class="shared-post-analytics-actions">
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(postRoute)}">Open post</button>
          <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="refresh-current-route"${disabledAttr(resource.loading)}>Refresh</button>
        </div>
      </section>
      ${
        resource.loading && !item
          ? '<div class="shared-page__loading">Loading post analytics...</div>'
          : ""
      }
      ${
        resource.error
          ? `<div class="shared-post-analytics-error">
              <strong>${escapeHtml(resource.error)}</strong>
              <button class="shared-feed-chip" type="button" data-action="refresh-current-route"${disabledAttr(resource.loading)}>Try again</button>
            </div>`
          : ""
      }
      ${
        item
          ? `<section class="shared-post-analytics-grid">
              ${cards.map(renderPostAnalyticsMetricCard).join("")}
            </section>
            <div class="shared-post-analytics-layout">
              <section class="shared-post-analytics-panel">
                <div class="shared-post-analytics-panel__header">
                  <div>
                    <span class="shared-discover-eyebrow">Response mix</span>
                    <h2>Engagement breakdown</h2>
                    <p>${escapeHtml(`${formatCount(engagementTotal)} combined response${engagementTotal === 1 ? "" : "s"} across likes, comments, and shares.`)}</p>
                  </div>
                  <strong>${escapeHtml(formatPostAnalyticsRate(engagementRate))}</strong>
                </div>
                <div class="shared-post-analytics-breakdown">
                  ${renderPostAnalyticsBreakdownRow("Likes", item.likes, maxBreakdown, "likes")}
                  ${renderPostAnalyticsBreakdownRow("Comments", item.comments, maxBreakdown, "comments")}
                  ${renderPostAnalyticsBreakdownRow("Shares", item.shares, maxBreakdown, "shares")}
                </div>
              </section>
              <aside class="shared-post-analytics-panel shared-post-analytics-panel--summary">
                <span class="shared-discover-eyebrow">Post</span>
                <h2>${escapeHtml(postId || item.postId || "Current post")}</h2>
                <div class="shared-post-analytics-summary">
                  <span><strong>${escapeHtml(formatCount(engagementTotal))}</strong><small>Total engagement</small></span>
                  <span><strong>${escapeHtml(formatPostAnalyticsRate(engagementRate))}</strong><small>Engagement rate</small></span>
                  <span><strong>${escapeHtml(formatPostAnalyticsDuration(item.avgWatchTimeMs))}</strong><small>Average watch</small></span>
                </div>
              </aside>
            </div>`
          : !resource.loading && !resource.error
            ? '<div class="shared-page__empty">No analytics found for this post.</div>'
            : ""
      }
    </div>
  </section>`;
}

