function renderDiscoverModuleManagerRow(moduleKey, index, preferences) {
  const config = discoverModuleConfig(moduleKey);
  if (!config) {
    return "";
  }
  const locked = Boolean(config.locked);
  const visible = !locked && !preferences.hidden.has(moduleKey);
  const hidden = !visible;
  const statusLabel = locked ? "Coming soon" : visible ? "Visible" : "Hidden";
  const rowClass = [
    "shared-discover-module-manager__row",
    visible ? "is-visible" : "is-hidden",
    locked ? "is-locked" : "",
  ]
    .filter(Boolean)
    .join(" ");
  return `<article class="${rowClass}" data-discover-module-key="${escapeHtml(moduleKey)}">
    <span class="shared-discover-module-manager__icon" aria-hidden="true">${renderIcon(config.icon)}</span>
    <div class="shared-discover-module-manager__copy">
      <strong>${escapeHtml(config.title)}</strong>
      <small>${escapeHtml(config.description)}</small>
      <em>${escapeHtml(statusLabel)}</em>
    </div>
    <div class="shared-discover-module-manager__actions">
      <button class="shared-feed-chip" data-action="discover-module-move" data-module-key="${escapeHtml(moduleKey)}" data-direction="up" ${index === 0 ? "disabled" : ""}>Up</button>
      <button class="shared-feed-chip" data-action="discover-module-move" data-module-key="${escapeHtml(moduleKey)}" data-direction="down" ${index === preferences.order.length - 1 ? "disabled" : ""}>Down</button>
      <button class="shared-feed-chip${hidden && !locked ? " shared-feed-chip--primary" : ""}" data-action="discover-module-toggle" data-module-key="${escapeHtml(moduleKey)}" data-visible="${visible ? "false" : "true"}" aria-pressed="${visible ? "true" : "false"}" ${locked ? "disabled" : ""}>${escapeHtml(locked ? "Locked" : visible ? "Hide" : "Show")}</button>
    </div>
  </article>`;
}

function renderDiscoverModuleManager() {
  const discover = state.pages.discover;
  if (!discover.manageOpen) {
    return "";
  }
  const preferences = currentDiscoverModulePreferences();
  const visibleCount = preferences.order.filter((moduleKey) => {
    const config = discoverModuleConfig(moduleKey);
    return config && !config.locked && !preferences.hidden.has(moduleKey);
  }).length;
  const optionalCount = preferences.order.filter((moduleKey) => {
    const config = discoverModuleConfig(moduleKey);
    return config && !config.locked;
  }).length;
  return `<section class="shared-discover-module-manager" aria-label="Manage Discover modules">
    <header class="shared-discover-module-manager__header">
      <div>
        <span class="shared-discover-eyebrow">Manage Discover</span>
        <h2>${escapeHtml(formatCount(visibleCount))} of ${escapeHtml(formatCount(optionalCount))} modules visible</h2>
        <p>Match the app controls by choosing which modules appear and moving high-priority cards up.</p>
      </div>
      <div class="shared-discover-module-manager__header-actions">
        <button class="shared-feed-chip" data-action="discover-modules-reset">Reset defaults</button>
        <button class="shared-feed-chip" data-action="discover-manage-toggle">Close</button>
      </div>
    </header>
    <div class="shared-discover-module-manager__list">
      ${preferences.order
        .map((moduleKey, index) =>
          renderDiscoverModuleManagerRow(moduleKey, index, preferences),
        )
        .join("")}
    </div>
  </section>`;
}

function renderDiscoverPage() {
  const discover = state.pages.discover;
  const communityServers = [
    ...discover.communityServers.items,
    ...discover.standaloneServers.items,
  ].slice(0, 8);
  const serverSlice = {
    ...discover.communityServers,
    items: communityServers,
    loading:
      discover.communityServers.loading || discover.standaloneServers.loading,
    error:
      discover.communityServers.error && discover.standaloneServers.error
        ? discover.communityServers.error
        : "",
    loaded:
      discover.communityServers.loaded || discover.standaloneServers.loaded,
  };

  return `<section class="shared-page shared-discover-page">
    ${renderTopChrome()}
    <div class="shared-page__content">
      <section class="shared-discover-hero">
        <div>
          <span class="shared-discover-eyebrow">Discover</span>
          <h1>Find what is worth opening next.</h1>
          <p>Search once, then move between posts, people, events, questions, ballot guidance, missions, rooms, and calendar items without losing your place.</p>
          <div class="shared-discover-hero__actions">
            <button class="shared-feed-chip shared-feed-chip--primary" data-action="navigate" data-route="/feed">Open feed</button>
            <button class="shared-feed-chip" data-action="discover-manage-toggle" aria-expanded="${discover.manageOpen ? "true" : "false"}">${escapeHtml(discover.manageOpen ? "Close modules" : "Manage modules")}</button>
            <button class="shared-feed-chip" data-action="discover-refresh">Refresh</button>
          </div>
        </div>
        <form class="shared-discover-search" data-route-form="discover-search">
          <input name="q" placeholder="Search posts, people, and tags" autocomplete="off" />
          <button class="shared-feed-chip shared-feed-chip--primary" type="submit">Search</button>
        </form>
        <div class="shared-discover-stats">
          ${renderDiscoverStat("Posts", discover.feed.items.length)}
          ${renderDiscoverStat("People", discover.candidates.items.length)}
          ${renderDiscoverStat("Events", discover.events.items.length)}
          ${renderDiscoverStat("Rooms", communityServers.length)}
        </div>
      </section>

      ${
        discover.error
          ? `<div class="shared-page__error">${escapeHtml(discover.error)}</div>`
          : ""
      }

      ${renderDiscoverModuleManager()}

      ${renderDiscoverActionDeck()}

      ${renderDiscoverDestinationRail()}

      ${renderDiscoverModuleSections({ serverSlice })}

      <div class="shared-discover-footer-actions">
        <button class="shared-feed-chip" data-action="discover-refresh">Refresh Discover</button>
        <button class="shared-feed-chip" data-action="open-app-shell">Open app</button>
      </div>
    </div>
  </section>`;
}

function formatAbsoluteDateTime(value) {
  const timestamp = Number(value);
  if (!Number.isFinite(timestamp) || timestamp <= 0) {
    return "";
  }
  return new Date(timestamp).toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

function formatDateTimeInputValue(value) {
  const timestamp = Number(value);
  if (!Number.isFinite(timestamp) || timestamp <= 0) {
    return "";
  }
  const date = new Date(timestamp);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  const hours = String(date.getHours()).padStart(2, "0");
  const minutes = String(date.getMinutes()).padStart(2, "0");
  return `${year}-${month}-${day}T${hours}:${minutes}`;
}

function formatDateInputValue(value) {
  const timestamp = Number(value);
  if (!Number.isFinite(timestamp) || timestamp <= 0) {
    return "";
  }
  const date = new Date(timestamp);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function renderMediaThumbnailGrid(
  items = [],
  {
    emptyMessage = "Nothing here yet.",
    gridClassName = "",
    getRoute,
    getMediaUrl,
    getAltText,
    getOverlayText,
    getPlaceholderLabel,
    getDetailAction,
    getCornerAction,
    getEngagementActions,
    getSupplementalContent,
    overlayBare = false,
    isOverlayBare,
  } = {},
) {
  if (!items.length) {
    return `<div class="shared-page__empty">${escapeHtml(emptyMessage)}</div>`;
  }

  const normalizedGridClassName = normalizeString(gridClassName);

  return `<div class="shared-media-grid${normalizedGridClassName ? ` ${escapeHtml(normalizedGridClassName)}` : ""}">${items
    .map((item) => {
      const route = normalizeString(getRoute?.(item));
      const mediaUrl = normalizeUrl(getMediaUrl?.(item));
      const overlayText = normalizeString(getOverlayText?.(item));
      const altText = normalizeString(getAltText?.(item)) || "Media item";
      const overlayIsBare =
        typeof isOverlayBare === "function" ? isOverlayBare(item) : overlayBare;
      const detailAction =
        typeof getDetailAction === "function" ? getDetailAction(item) : null;
      const cornerAction =
        typeof getCornerAction === "function" ? getCornerAction(item) : null;
      const engagementActions =
        typeof getEngagementActions === "function"
          ? (getEngagementActions(item) || []).filter(Boolean)
          : [];
      const supplementalHtml =
        typeof getSupplementalContent === "function"
          ? normalizeString(getSupplementalContent(item))
          : "";
      const detailActionLabel = normalizeString(detailAction?.label);
      const detailActionName = normalizeString(detailAction?.action);
      const detailPostId = normalizeString(detailAction?.postId);
      const detailActionHtml =
        detailActionLabel && detailActionName
          ? `<button class="shared-media-tile__detail" type="button" data-action="${escapeHtml(detailActionName)}"${detailPostId ? ` data-post-id="${escapeHtml(detailPostId)}"` : ""}>${escapeHtml(detailActionLabel)}</button>`
          : "";
      const cornerActionLabel = normalizeString(cornerAction?.label);
      const cornerActionName = normalizeString(cornerAction?.action);
      const cornerPostId = normalizeString(cornerAction?.postId);
      const cornerIcon = normalizeString(cornerAction?.icon) || "share";
      const cornerActionHtml =
        cornerActionLabel && cornerActionName
          ? `<button class="shared-media-tile__corner-action" type="button" data-action="${escapeHtml(cornerActionName)}"${cornerPostId ? ` data-post-id="${escapeHtml(cornerPostId)}"` : ""} aria-label="${escapeHtml(cornerActionLabel)}" title="${escapeHtml(cornerActionLabel)}">${renderIcon(cornerIcon)}<span class="shared-sr-only">${escapeHtml(cornerActionLabel)}</span></button>`
          : "";
      const engagementActionHtml = engagementActions.length
        ? `<div class="shared-media-tile__engagement" aria-label="Post actions">
            ${engagementActions
              .map((actionItem) => {
                const actionName = normalizeString(actionItem.action);
                const label = normalizeString(actionItem.label);
                const icon = normalizeString(actionItem.icon);
                const postId = normalizeString(actionItem.postId);
                const count =
                  actionItem.count === undefined || actionItem.count === null
                    ? ""
                    : formatCount(Number(actionItem.count) || 0);
                const activeClass = actionItem.active
                  ? " is-active"
                  : "";
                const countedClass = count ? " is-counted" : "";
                if (!actionName || !label || !icon) {
                  return "";
                }
                return `<button class="shared-media-tile__engagement-button${activeClass}${countedClass}" type="button" data-action="${escapeHtml(actionName)}"${postId ? ` data-post-id="${escapeHtml(postId)}"` : ""} aria-label="${escapeHtml(label)}" title="${escapeHtml(label)}">${renderIcon(icon)}${count ? `<span>${escapeHtml(count)}</span>` : `<span class="shared-sr-only">${escapeHtml(label)}</span>`}</button>`;
              })
              .join("")}
          </div>`
        : "";
      const placeholderLabel =
        normalizeString(getPlaceholderLabel?.(item))
          .slice(0, 1)
          .toUpperCase() ||
        altText.slice(0, 1).toUpperCase() ||
        "M";

      const tile = `<button class="shared-media-tile" type="button" data-action="navigate" data-route="${escapeHtml(route)}" aria-label="${escapeHtml(altText)}">
        ${
          mediaUrl
            ? `<img class="shared-media-tile__image" src="${escapeHtml(mediaUrl)}" alt="${escapeHtml(altText)}" loading="lazy" />`
            : `<div class="shared-media-tile__placeholder" aria-hidden="true">${escapeHtml(placeholderLabel)}</div>`
        }
        ${
          overlayText
            ? `<span class="shared-media-tile__overlay${overlayIsBare ? " shared-media-tile__overlay--bare" : ""}${detailActionHtml ? " shared-media-tile__overlay--has-action" : ""}${engagementActionHtml ? " shared-media-tile__overlay--has-engagement" : ""}">${escapeHtml(overlayText)}</span>`
            : ""
        }
      </button>`;
      return detailActionHtml || cornerActionHtml || engagementActionHtml || supplementalHtml
        ? `<article class="shared-media-tile-shell">${tile}${cornerActionHtml}${supplementalHtml ? `<div class="shared-media-tile__supplemental">${supplementalHtml}</div>` : ""}<div class="shared-media-tile__actions">${detailActionHtml}</div>${engagementActionHtml}</article>`
        : tile;
    })
    .join("")}</div>`;
}

function getFeedGridItems(items = []) {
  return items.filter(
    (item) => item?.kind === "post" || item?.kind === "event",
  );
}

function getFeedPromptItems(items = []) {
  return items.filter(
    (item) =>
      item?.kind === "prompt" ||
      item?.kind === "candidatePrompt" ||
      item?.kind === "civicPrompt",
  );
}

function feedCandidatePromptContactDescription(key) {
  const descriptions = {
    doorKnock: "Allow campaign volunteers to request in-person outreach.",
    mailPhysical: "Allow campaign mailers, postcards, and yard-sign follow-up.",
    mailEmail: "Allow campaign email updates and voter information.",
    phoneCall: "Allow a campaign phone call when a person needs to reach you.",
    textMessage: "Allow SMS outreach for campaign updates and reminders.",
    yardSign: "Allow the campaign to follow up about a yard sign.",
  };
  return descriptions[key] || candidateContactTypeDescription(key);
}

function renderFeedCandidatePromptAvatar(item = {}) {
  const name = normalizeString(item.displayName) || "Candidate";
  if (item.avatarUrl) {
    return `<img class="shared-candidate-optin-card__avatar" src="${escapeHtml(item.avatarUrl)}" alt="" loading="lazy" />`;
  }
  return `<div class="shared-candidate-optin-card__avatar shared-candidate-optin-card__avatar--placeholder" aria-hidden="true">${escapeHtml(
    name.slice(0, 1).toUpperCase() || "C",
  )}</div>`;
}

function renderFeedCandidatePromptChoice(type, pending, selectedChoice = "unset") {
  const name = `contact:${type.key}`;
  const selected = normalizeVoterPreferenceChoice(selectedChoice);
  const options = [
    ["yes", "Yes"],
    ["unset", "Unset"],
    ["no", "No"],
  ];
  return `<fieldset class="shared-candidate-optin-choice">
    <legend>
      <strong>${escapeHtml(type.label)}</strong>
      <span>${escapeHtml(feedCandidatePromptContactDescription(type.key))}</span>
    </legend>
    <div class="shared-candidate-optin-choice__segmented">
      ${options
        .map(
          ([value, label]) => `<label>
            <input type="radio" name="${escapeHtml(name)}" value="${escapeHtml(value)}"${checkedAttr(value === selected)}${disabledAttr(pending)} />
            <span>${escapeHtml(label)}</span>
          </label>`,
        )
        .join("")}
    </div>
  </fieldset>`;
}

function feedCandidatePromptCommunityActionLabel(item = {}) {
  const server = item.communityServer || {};
  const serverName = normalizeString(server.name) || "campaign";
  if (server.joined) {
    return `Enter ${serverName}'s workspace`;
  }
  if (server.name) {
    return `Join ${serverName}'s workspace`;
  }
  return item.variant === "community" ? "Join community" : "Join campaign workspace";
}

function renderFeedCandidatePromptCommunityAction(item, promptKey, pending) {
  const server = item.communityServer || null;
  const visible = item.variant === "community" || Boolean(server?.enabled);
  if (!visible) {
    return "";
  }
  const disabled =
    pending ||
    !item.candidateId ||
    Boolean(server && !server.joined && server.canJoin !== true);
  const title = server?.name || "Campaign community";
  const description =
    item.variant === "community"
      ? "Follow updates, ask questions, and stay close to this campaign in its community workspace."
      : "This campaign also has a community workspace you can join from the web.";
  return `<div class="shared-candidate-optin-community">
    <div>
      <strong>${escapeHtml(title)}</strong>
      <span>${escapeHtml(description)}</span>
    </div>
    <button class="shared-feed-chip" type="button" data-action="feed-candidate-community-join" data-candidate-id="${escapeHtml(item.candidateId)}" data-prompt-key="${escapeHtml(promptKey)}"${disabledAttr(disabled)}>
      ${renderIcon("messages")}
      <span>${escapeHtml(feedCandidatePromptCommunityActionLabel(item))}</span>
    </button>
  </div>`;
}

function renderFeedCandidatePromptMissingActions(missing = {}) {
  if (!hasFeedCandidatePromptMissingFields(missing)) {
    return "";
  }
  const actions = [];
  if (missing.address) {
    actions.push(
      `<button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/voter-profile/home-location">Add address</button>`,
    );
  }
  if (missing.phone || missing.email) {
    actions.push(
      `<button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/voter-profile">Update profile</button>`,
    );
  }
  return `<div class="shared-candidate-optin-card__repair">${actions.join("")}</div>`;
}

function renderFeedCandidatePromptCompactState(item, promptKey, status) {
  const prompts = currentFeedPromptState();
  const saved = status === "saved";
  const text = saved
    ? normalizeString(prompts.savedMessages[promptKey]) ||
      (item.variant === "community" ? "Joined campaign workspace" : "Preferences saved")
    : "No problem";
  const detail = saved
    ? "Your choice was recorded for this campaign prompt."
    : "This prompt is dismissed for this visit.";
  return `<article class="shared-card shared-candidate-optin-card shared-candidate-optin-card--compact">
    <div class="shared-candidate-optin-compact__icon" aria-hidden="true">${renderIcon(saved ? "check" : "close")}</div>
    <div>
      <strong>${escapeHtml(text)}</strong>
      <span>${escapeHtml(detail)}</span>
    </div>
  </article>`;
}

function feedCivicPromptIcon(item = {}) {
  const kind = normalizeString(item.promptKind).toLowerCase();
  const destination = normalizeString(item.destinationPath).toLowerCase();
  if (kind.includes("topic") || destination.startsWith("/topics")) {
    return "tag";
  }
  if (kind.includes("district") || destination.includes("home-location")) {
    return "map";
  }
  if (
    kind.includes("ballot") ||
    kind.includes("election") ||
    kind.includes("rank") ||
    destination.includes("voter-intel")
  ) {
    return "election";
  }
  if (kind.includes("policy") || kind.includes("issue") || kind.includes("stance")) {
    return "flag";
  }
  return "election";
}

function feedCivicPromptActionLabel(item = {}) {
  const kind = normalizeString(item.promptKind).toLowerCase();
  const destination = normalizeString(item.destinationPath).toLowerCase();
  if (feedCivicPromptPolicyQuestionId(item) || destination.startsWith("/questions")) {
    return "Open question";
  }
  if (kind.includes("topic") || destination.startsWith("/topics")) {
    return "Choose topics";
  }
  if (kind.includes("district") || destination.includes("home-location")) {
    return "Set voting area";
  }
  if (
    kind.includes("ballot") ||
    kind.includes("rank") ||
    destination.includes("voter-intel")
  ) {
    return "Rank a race";
  }
  return "Start";
}

function feedCivicPromptDestinationDescription(item = {}) {
  const kind = normalizeString(item.promptKind).toLowerCase();
  const destination = normalizeString(item.destinationPath);
  if (feedCivicPromptPolicyQuestionId(item) || destination.startsWith("/questions")) {
    return "Read the background, sources, and aggregate answers.";
  }
  if (kind.includes("topic") || destination.startsWith("/topics")) {
    return "Update topic preferences that shape your feed and recommendations.";
  }
  if (kind.includes("district") || destination.includes("home-location")) {
    return "Add home location so Polis can show local offices and races.";
  }
  if (
    kind.includes("ballot") ||
    kind.includes("rank") ||
    destination.includes("voter-intel")
  ) {
    return "Continue ballot ranking and voter-intelligence setup.";
  }
  return destination || "Continue this civic prompt in Polis web.";
}

function renderFeedCivicPromptCompactState(item, promptKey, status) {
  const prompts = currentFeedPromptState();
  const saved = status === "saved";
  const text = saved
    ? normalizeString(prompts.savedMessages[promptKey]) || "Civic prompt recorded"
    : "Prompt dismissed";
  const detail = saved
    ? feedCivicPromptPolicyQuestionId(item)
      ? "Your policy answer was saved and applied to your voter profile."
      : "Your action was recorded for voter intelligence."
    : "This prompt is hidden for this visit.";
  return `<article class="shared-card shared-civic-prompt-card shared-civic-prompt-card--compact">
    <div class="shared-civic-prompt-card__compact-icon" aria-hidden="true">${renderIcon(saved ? "check" : "close")}</div>
    <div>
      <strong>${escapeHtml(text)}</strong>
      <span>${escapeHtml(detail)}</span>
    </div>
  </article>`;
}

function renderFeedCivicPromptChoices(item, promptKey, pending) {
  const choices = Array.isArray(item.choices) ? item.choices : [];
  if (!choices.length) {
    return "";
  }
  return `<div class="shared-civic-prompt-card__choices">
    ${choices
      .map(
        (choice) => `<button class="shared-civic-prompt-choice" type="button" data-action="feed-civic-prompt-answer" data-prompt-key="${escapeHtml(promptKey)}" data-choice-value="${escapeHtml(choice.value)}"${disabledAttr(pending)}>
          <span>${renderIcon("check")}</span>
          <strong>${escapeHtml(choice.label)}</strong>
        </button>`,
      )
      .join("")}
  </div>`;
}

function renderFeedCivicPromptDestination(
  item,
  promptKey,
  pending,
  { secondary = false } = {},
) {
  if (!item.destinationPath) {
    if (secondary) {
      return "";
    }
    return `<div class="shared-civic-prompt-card__destination is-disabled">
      <span>${renderIcon("lock")}</span>
      <strong>This prompt can be answered here.</strong>
    </div>`;
  }
  const pendingOpen =
    currentFeedPromptState().actionPendingKey === `open:${promptKey}`;
  return `<div class="shared-civic-prompt-card__destination${secondary ? " shared-civic-prompt-card__destination--secondary" : ""}">
    <span>${renderIcon(feedCivicPromptIcon(item))}</span>
    <div>
      <strong>${escapeHtml(feedCivicPromptActionLabel(item))}</strong>
      <em>${escapeHtml(feedCivicPromptDestinationDescription(item))}</em>
    </div>
    <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="feed-civic-prompt-open" data-prompt-key="${escapeHtml(promptKey)}"${disabledAttr(pending)}>
      <span>${escapeHtml(pendingOpen ? "Opening..." : secondary ? "Open" : feedCivicPromptActionLabel(item))}</span>
    </button>
  </div>`;
}

function renderFeedCivicPromptCard(item = {}) {
  const promptKey =
    normalizeString(item.key) ||
    `civicPrompt:${normalizeString(item.promptFamily)}:${normalizeString(item.promptId)}`;
  const prompts = currentFeedPromptState();
  if (prompts.savedKeys[promptKey]) {
    return renderFeedCivicPromptCompactState(item, promptKey, "saved");
  }
  if (prompts.dismissedKeys[promptKey]) {
    return renderFeedCivicPromptCompactState(item, promptKey, "dismissed");
  }

  const pendingKey = normalizeString(prompts.actionPendingKey);
  const pending =
    pendingKey === `answer:${promptKey}` ||
    pendingKey === `open:${promptKey}` ||
    pendingKey === `dismiss:${promptKey}`;
  const error = normalizeString(prompts.errors[promptKey]);
  const choices = Array.isArray(item.choices) ? item.choices : [];

  return `<article class="shared-card shared-civic-prompt-card">
    <div class="shared-civic-prompt-card__header">
      <span class="shared-civic-prompt-card__icon" aria-hidden="true">${renderIcon(feedCivicPromptIcon(item))}</span>
      <div>
        <p class="shared-page__eyebrow">Civic prompt</p>
        <h3>${escapeHtml(item.title || "Civic prompt")}</h3>
        <p>${escapeHtml(item.body || "Answer this prompt to improve your Polis recommendations.")}</p>
      </div>
    </div>
    <div class="shared-civic-prompt-card__body">
      ${
        choices.length
          ? `${renderFeedCivicPromptChoices(item, promptKey, pending)}
             ${renderFeedCivicPromptDestination(item, promptKey, pending, {
               secondary: true,
             })}`
          : renderFeedCivicPromptDestination(item, promptKey, pending)
      }
      ${
        error
          ? `<div class="shared-page__error shared-civic-prompt-card__error">${escapeHtml(error)}</div>`
          : ""
      }
      <div class="shared-civic-prompt-card__actions">
        <button class="shared-feed-chip" type="button" data-action="feed-civic-prompt-dismiss" data-prompt-key="${escapeHtml(promptKey)}"${disabledAttr(pending)}>
          <span>${escapeHtml(pendingKey === `dismiss:${promptKey}` ? "Dismissing..." : "Not now")}</span>
        </button>
      </div>
    </div>
  </article>`;
}

function renderFeedCandidateOptInCard(item = {}) {
  const promptKey = normalizeString(item.key) || `candidatePrompt:${item.candidateId}`;
  const prompts = currentFeedPromptState();
  if (prompts.savedKeys[promptKey]) {
    return renderFeedCandidatePromptCompactState(item, promptKey, "saved");
  }
  if (prompts.dismissedKeys[promptKey]) {
    return renderFeedCandidatePromptCompactState(item, promptKey, "dismissed");
  }

  const pendingKey = normalizeString(prompts.actionPendingKey);
  const pending =
    pendingKey === `save:${promptKey}` || pendingKey === `community:${promptKey}`;
  const communityOnly = item.variant === "community";
  const candidateName = normalizeString(item.displayName) || "Candidate";
  const enabledTypes = normalizeCandidateContactEnabledTypes(
    item.enabledContactTypes || {},
  );
  const contactTypes = CANDIDATE_CONTACT_TYPE_CONFIG.filter(
    (type) => enabledTypes[type.key] === true,
  );
  const draftChoices = normalizeFeedCandidatePromptDraftChoices(
    prompts.draftChoicesByKey[promptKey],
  );
  const error = normalizeString(prompts.errors[promptKey]);
  const missing = prompts.missingFieldsByKey[promptKey] || {};
  const communityServer = item.communityServer || null;
  const communityActionDisabled =
    pending ||
    !item.candidateId ||
    Boolean(
      communityServer &&
        !communityServer.joined &&
        communityServer.canJoin !== true,
    );

  return `<article class="shared-card shared-candidate-optin-card">
    <div class="shared-candidate-optin-card__header">
      ${renderFeedCandidatePromptAvatar(item)}
      <div class="shared-candidate-optin-card__identity">
        <p class="shared-page__eyebrow">Campaign prompt</p>
        <h3>${escapeHtml(candidateName)}</h3>
        <p>${escapeHtml(
          communityOnly
            ? "Join the campaign conversation from Polis web."
            : `Choose how ${candidateName} can contact you.`,
        )}</p>
      </div>
      ${
        item.party
          ? `<span class="shared-candidate-optin-card__party">${escapeHtml(item.party)}</span>`
          : ""
      }
    </div>
    ${
      communityOnly
        ? `<div class="shared-candidate-optin-card__body">
            <p class="shared-candidate-optin-card__copy">Follow updates, ask questions, and stay close to this campaign in its community workspace.</p>
          </div>`
        : `<form class="shared-candidate-optin-card__body" data-route-form="feed-candidate-opt-in">
            <input type="hidden" name="candidateId" value="${escapeHtml(item.candidateId)}" />
            <input type="hidden" name="promptKey" value="${escapeHtml(promptKey)}" />
            <div class="shared-candidate-optin-card__toolbar">
              <strong>Contact preferences</strong>
              <div>
                <button class="shared-feed-chip" type="button" data-action="feed-candidate-prompt-set-all" data-choice="yes"${disabledAttr(pending)}>All yes</button>
                <button class="shared-feed-chip" type="button" data-action="feed-candidate-prompt-set-all" data-choice="no"${disabledAttr(pending)}>All no</button>
              </div>
            </div>
            ${
              contactTypes.length
                ? `<div class="shared-candidate-optin-choice-list">${contactTypes
                    .map((type) =>
                      renderFeedCandidatePromptChoice(
                        type,
                        pending,
                        draftChoices[type.key],
                      ),
                    )
                    .join("")}</div>`
                : `<p class="shared-candidate-optin-card__copy">This campaign has not enabled any contact channels for this prompt.</p>`
            }
            ${renderFeedCandidatePromptCommunityAction(item, promptKey, pending)}
            ${
              error
                ? `<div class="shared-page__error shared-candidate-optin-card__error">${escapeHtml(error)}${renderFeedCandidatePromptMissingActions(missing)}</div>`
                : ""
            }
            <div class="shared-candidate-optin-card__actions">
              <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(pending || !item.candidateId || !contactTypes.length)}>
                ${renderIcon("check")}
                <span>${escapeHtml(pendingKey === `save:${promptKey}` ? "Saving..." : "Save preferences")}</span>
              </button>
              <button class="shared-feed-chip" type="button" data-action="feed-candidate-prompt-dismiss" data-prompt-key="${escapeHtml(promptKey)}"${disabledAttr(pending)}>
                <span>No thanks</span>
              </button>
            </div>
          </form>`
    }
    ${
      communityOnly && error
        ? `<div class="shared-page__error shared-candidate-optin-card__error">${escapeHtml(error)}</div>`
        : ""
    }
    ${
      communityOnly
        ? `<div class="shared-candidate-optin-card__actions shared-candidate-optin-card__actions--community">
            <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="feed-candidate-community-join" data-candidate-id="${escapeHtml(item.candidateId)}" data-prompt-key="${escapeHtml(promptKey)}"${disabledAttr(communityActionDisabled)}>
              ${renderIcon("messages")}
              <span>${escapeHtml(pendingKey === `community:${promptKey}` ? "Joining..." : feedCandidatePromptCommunityActionLabel(item))}</span>
            </button>
            <button class="shared-feed-chip" type="button" data-action="feed-candidate-prompt-dismiss" data-prompt-key="${escapeHtml(promptKey)}"${disabledAttr(pending)}>Not now</button>
          </div>`
        : ""
    }
  </article>`;
}

function renderGenericFeedPromptCard(item = {}) {
  return `<article class="shared-card">
    <div class="shared-card__body">
      <p class="shared-page__eyebrow">Prompt</p>
      <h3>${escapeHtml(item.title || "Continue in Polis")}</h3>
      <p class="shared-card__summary">${escapeHtml(item.description || "Continue this feed step from Polis web.")}</p>
      <button class="shared-feed-chip shared-feed-chip--primary" data-action="open-app-shell">Open app</button>
    </div>
  </article>`;
}

function renderFeedPromptCards(items = []) {
  if (!items.length) {
    return "";
  }

  return `<section class="shared-feed-prompts" aria-label="Feed prompts">
    <h2>Feed prompts</h2>
    <div class="shared-card-grid shared-card-grid--detail shared-feed-prompt-grid">
      ${items
        .map((item) =>
          item?.kind === "candidatePrompt"
            ? renderFeedCandidateOptInCard(item)
            : item?.kind === "civicPrompt"
              ? renderFeedCivicPromptCard(item)
            : renderGenericFeedPromptCard(item),
        )
        .join("")}
    </div>
  </section>`;
}

function renderFeedOverviewPage() {
  const feed = getCurrentFeedState();
  const items = getCurrentItems();
  const mediaItems = getFeedGridItems(items);
  const promptItems = getFeedPromptItems(items);
  const modeLabel =
    state.mode === FEED_MODE_FOLLOWING ? "Following" : "For You";

  return `<section class="shared-page">
    ${renderTopChrome()}
    <div class="shared-page__content">
      <div class="shared-page__header">
        <div>
          <p class="shared-page__eyebrow">Feed</p>
          <h1>${escapeHtml(modeLabel)}</h1>
          <p>Browse the latest Polis posts and events in a compact web grid.</p>
        </div>
        <div class="shared-card__actions">
          ${
            feed.nextCursor
              ? `<button class="shared-feed-chip" data-action="load-more-feed-grid"${feed.loadingMore ? " disabled" : ""}>${feed.loadingMore ? "Loading..." : "Load more"}</button>`
              : ""
          }
          <button class="shared-feed-chip shared-feed-chip--primary" data-action="refresh-feed-grid"${feed.loading ? " disabled" : ""}>${feed.loading ? "Refreshing..." : "Refresh"}</button>
        </div>
      </div>
      ${
        feed.loading && !items.length
          ? '<div class="shared-page__loading">Loading feed...</div>'
          : ""
      }
      ${feed.error ? `<div class="shared-page__error">${escapeHtml(feed.error)}</div>` : ""}
      ${renderMediaThumbnailGrid(mediaItems, {
        emptyMessage: promptItems.length
          ? "No posts or events in this feed yet."
          : "No feed items yet.",
        gridClassName: "shared-media-grid--five-wide",
        getRoute: (item) => {
          if (item.kind === "event" && item.eventId) {
            return `/events/${encodeURIComponent(item.eventId)}`;
          }
          return item.postId ? `/posts/${encodeURIComponent(item.postId)}` : "";
        },
        getMediaUrl: (item) =>
          item.kind === "event"
            ? item.imageUrl
            : item.posterUrl || item.imageUrl,
        getAltText: (item) =>
          item.kind === "event"
            ? item.title || "Event"
            : item.previewTitle ||
              item.caption ||
              item.authorDisplayName ||
              "Post",
        getOverlayText: (item) => {
          if (item.kind === "event") {
            if (Number(item.attendeeCount) > 0) {
              return `${formatCount(item.attendeeCount)} going`;
            }
            return item.startAt
              ? formatAbsoluteDateTime(item.startAt)
              : item.hostDisplayName || "Event";
          }
          return item.authorDisplayName || item.previewTitle || "Post";
        },
        getCornerAction: (item) =>
          item.kind === "post" && item.postId
            ? {
                action: "share",
                label: "Share post",
                icon: "share",
                postId: item.postId,
              }
            : null,
        getEngagementActions: (item) =>
          item.kind === "post" && item.postId
            ? [
                {
                  action: "toggle-like",
                  label: item.likedByMe ? "Unlike post" : "Like post",
                  icon: item.likedByMe ? "heart" : "heartOutline",
                  postId: item.postId,
                  count: item.likesCount,
                  active: item.likedByMe,
                },
                {
                  action: "open-comments",
                  label: "Open comments",
                  icon: "comment",
                  postId: item.postId,
                  count: item.commentsCount,
                },
                {
                  action: "toggle-save",
                  label: item.savedByMe ? "Unsave post" : "Save post",
                  icon: item.savedByMe ? "saveFilled" : "save",
                  postId: item.postId,
                  active: item.savedByMe,
                },
              ]
            : [],
        getSupplementalContent: (item) =>
          item.kind === "post" && item.postId
            ? renderFeedPostIssueTags(item, { compact: true })
            : "",
        getPlaceholderLabel: (item) => (item.kind === "event" ? "E" : "P"),
        isOverlayBare: (item) => item.kind === "post",
      })}
      ${
        feed.loadingMore
          ? '<div class="shared-page__hint">Loading more feed items...</div>'
          : ""
      }
      ${renderFeedPromptCards(promptItems)}
    </div>
  </section>`;
}

function electionStatusLabel(snapshot = null, option = null) {
  if (option?.future && option.clickable !== true) return "Upcoming";
  if (snapshot?.isActive || option?.active) return "Live";
  if (snapshot?.isFinalized || option?.finalized) return "Final";
  return "Election";
}

function electionReportingLine(snapshot = null) {
  if (!snapshot) return "Select a state to view federal race results.";
  const reporting = snapshot.reporting || {};
  const precinctsReported = Number(reporting.precinctsReported);
  const precinctsTotal = Number(reporting.precinctsTotal);
  const percent = Number(reporting.percent);
  const parts = [];
  if (
    Number.isFinite(precinctsReported) &&
    Number.isFinite(precinctsTotal) &&
    precinctsTotal > 0
  ) {
    parts.push(
      `${formatElectionVotes(precinctsReported)} of ${formatElectionVotes(precinctsTotal)} precincts`,
    );
  }
  if (Number.isFinite(percent) && percent > 0) {
    parts.push(`${formatElectionPercent(percent)} reporting`);
  }
  if (snapshot.updatedAt) {
    parts.push(`Updated ${formatCalendarDate(snapshot.updatedAt)}`);
  }
  return parts.join(" | ") || "Results update as vote totals are reported.";
}

function electionPreviousCandidateMap(snapshot = null) {
  const map = new Map();
  for (const race of snapshot?.races || []) {
    for (const candidate of race.candidates || []) {
      map.set(`${race.raceId}:${candidate.id}`, candidate);
    }
  }
  return map;
}

function electionMapDistrictOptions(election = state.pages.elections) {
  const features = Array.isArray(election.map.geometry?.districts?.features)
    ? election.map.geometry.districts.features
    : [];
  return features
    .map((feature) => {
      const properties =
        feature?.properties && typeof feature.properties === "object"
          ? feature.properties
          : {};
      const districtId = normalizeString(
        properties.districtId || properties.id || feature?.id,
      );
      if (!districtId) return null;
      return {
        districtId,
        label:
          normalizeString(properties.name || properties.districtName) ||
          districtId.replace(/^([A-Z]{2})-(HD|SD)-(\d+)$/u, "$2 $3"),
      };
    })
    .filter(Boolean)
    .sort((left, right) => {
      const leftNumber = Number(left.districtId.match(/-(\d+)$/u)?.[1]);
      const rightNumber = Number(right.districtId.match(/-(\d+)$/u)?.[1]);
      if (Number.isFinite(leftNumber) && Number.isFinite(rightNumber)) {
        return leftNumber - rightNumber;
      }
      return left.label.localeCompare(right.label);
    });
}

function selectedElectionDistrictLabel(election = state.pages.elections) {
  const selectedDistrict = normalizeString(election.selectedDistrictId);
  if (!selectedDistrict) {
    return `${election.selectedStateId || "State"} view`;
  }
  const option = electionMapDistrictOptions(election).find(
    (district) => district.districtId === selectedDistrict,
  );
  return option?.label || selectedDistrict;
}

function shouldRenderElectionMap(election = state.pages.elections) {
  const scope = normalizeElectionScope(election.selectedScope);
  if (ELECTION_AUTH_SCOPES.has(scope)) return false;
  return scope !== ELECTION_SCOPE_STATE || Boolean(selectedElectionMapChamber());
}

function formatElectionTimestamp(value) {
  const normalized = normalizeString(value);
  if (!normalized) return "";
  const numeric = Number(normalized);
  const date =
    Number.isFinite(numeric) && numeric > 0
      ? new Date(numeric)
      : new Date(normalized);
  if (Number.isNaN(date.getTime())) return normalized;
  return date.toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

function electionCountyCoverageLine(snapshot = null) {
  const coverage = snapshot?.countyCoverage;
  if (!coverage) return "";
  const expected = Number(coverage.expectedCount) || coverage.counties.length;
  const reporting = Number(coverage.reportingCount) || 0;
  const parts = [
    expected
      ? `${formatElectionVotes(reporting)} of ${formatElectionVotes(expected)} counties reporting`
      : `${formatElectionVotes(reporting)} counties reporting`,
  ];
  const updatedAt = formatElectionTimestamp(coverage.updatedAt);
  if (updatedAt) parts.push(`Updated ${updatedAt}`);
  return parts.join(" | ");
}

function groupElectionRaces(snapshot = null, selectedDistrictId = "") {
  const races = snapshot?.races || [];
  if (!races.length) return [];
  const selectedDistrict = normalizeString(selectedDistrictId);
  if (selectedDistrict) {
    const districtName =
      races.find((race) => normalizeString(race.districtName))?.districtName ||
      selectedDistrict;
    return [{ title: districtName, races }];
  }
  if (
    normalizeElectionScope(snapshot?.scope) === ELECTION_SCOPE_STATE &&
    normalizeElectionRaceType(snapshot?.raceType) === "statewide"
  ) {
    return [{ title: "Statewide state races", races }];
  }
  const groups = new Map();
  for (const race of races) {
    const key = normalizeString(race.districtId) || "statewide";
    const title =
      normalizeString(race.districtName || race.districtId) || "Statewide";
    const entry = groups.get(key) || { title, races: [] };
    entry.races.push(race);
    groups.set(key, entry);
  }
  return Array.from(groups.values()).sort((left, right) =>
    left.title.localeCompare(right.title),
  );
}

function electionRaceResultScope(race = {}) {
  return normalizeElectionScope(race.scope || race.resultScope);
}

function electionCandidatePartyKey(candidate = {}) {
  return normalizeElectionPartyToken(
    candidate.partyToken || candidate.partyCode || candidate.partyLabel,
  ) || "UNK";
}

function electionRaceIsPrimary(race = {}) {
  const stage = normalizeString(race.stage).toLowerCase();
  const title = normalizeString(race.officeTitle).toLowerCase();
  return stage.includes("primary") || title.includes(" primary");
}

function electionRaceTitlePrimaryPartyToken(race = {}) {
  const title = normalizeString(race.officeTitle).toUpperCase();
  const match = title.match(
    /(?:^|[-\u2013\u2014])\s*([A-Z][A-Z .&/]+?)\s+PRIMARY(?:\b|$)/u,
  );
  return normalizeElectionPartyToken(match?.[1]) || "";
}

function electionRaceCandidatePrimaryPartyToken(race = {}) {
  const parties = Array.from(
    new Set(
      (race.candidates || [])
        .map(electionCandidatePartyKey)
        .filter((party) => party && party !== "UNK" && party !== "OTH"),
    ),
  );
  return parties.length === 1 ? parties[0] : "";
}

function electionRacePrimaryPartyToken(race = {}) {
  if (!electionRaceIsPrimary(race)) return "";
  return (
    electionRaceTitlePrimaryPartyToken(race) ||
    electionRaceCandidatePrimaryPartyToken(race)
  );
}

function electionRaceVisibleForPartyFilter(race = {}, partyFilter = "all") {
  const normalizedPartyFilter = normalizeElectionPartyFilter(partyFilter);
  if (normalizedPartyFilter === "all") return true;
  const hasSelectedPartyCandidate = (race.candidates || []).some(
    (candidate) => electionCandidatePartyKey(candidate) === normalizedPartyFilter,
  );
  if (hasSelectedPartyCandidate) return true;
  const primaryParty = electionRacePrimaryPartyToken(race);
  return !primaryParty || primaryParty === normalizedPartyFilter;
}

function filterElectionRacesForPartyView(races = [], options = {}) {
  const partyFilter = normalizeElectionPartyFilter(options.partyFilter);
  return (races || []).filter((race) =>
    electionRaceVisibleForPartyFilter(race, partyFilter),
  );
}

function electionPartyFilterOptions(snapshot = null) {
  const userParty = normalizeElectionPartyToken(
    state.pages.elections.context?.userPartyToken ||
      state.pages.elections.context?.userPartyLabel,
  );
  const options = new Map();
  if (userParty) {
    options.set(userParty, {
      value: userParty,
      label: candidatePartyLabelForKey(userParty),
    });
  }
  for (const race of snapshot?.races || []) {
    for (const candidate of race.candidates || []) {
      const value = electionCandidatePartyKey(candidate);
      if (!options.has(value)) {
        options.set(value, {
          value,
          label: candidatePartyLabelForKey(value, candidate),
        });
      }
    }
  }
  return [
    { value: "all", label: "All" },
    ...Array.from(options.values()).sort((left, right) => {
      const leftRank = candidatePartySortRank(left.value, userParty);
      const rightRank = candidatePartySortRank(right.value, userParty);
      if (leftRank !== rightRank) return leftRank - rightRank;
      return left.label.localeCompare(right.label);
    }),
  ];
}

function selectedElectionPartyFilterValue(snapshot = null) {
  const selected = normalizeElectionPartyFilter(
    state.pages.elections.selectedPartyFilter,
  );
  if (selected === "all") return "all";
  const options = electionPartyFilterOptions(snapshot);
  return options.some((option) => option.value === selected) ? selected : "all";
}

function renderElectionPartyFilterControl(election) {
  const snapshot = election.results.snapshot;
  const selected = selectedElectionPartyFilterValue(snapshot);
  const options = electionPartyFilterOptions(snapshot);
  return `<label>
    <span>Party</span>
    <select data-election-control="party-filter">
      ${options
        .map(
          (option) =>
            `<option value="${escapeHtml(option.value)}"${option.value === selected ? " selected" : ""}>${escapeHtml(option.label)}</option>`,
        )
        .join("")}
    </select>
  </label>`;
}

function renderElectionAuthPrompt(scope) {
  return `<section class="shared-election-upcoming">
    <h2>${escapeHtml(electionScopeLabel(scope))} results require sign-in</h2>
    <p>Sign in to load district-specific and saved election views for your account.</p>
    <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="auth-login-inline">Sign in</button>
  </section>`;
}

function renderElectionCustomViewSelector(election) {
  const custom = election.customViews;
  const selected = selectedElectionCustomView(election);
  const atLimit = custom.items.length >= custom.maxViews;
  return `<div class="shared-election-custom-toolbar">
    <label>
      <span>Saved slate</span>
      <select data-election-control="custom-view"${custom.items.length ? "" : " disabled"}>
        ${
          custom.items.length
            ? custom.items
                .map(
                  (view) =>
                    `<option value="${escapeHtml(view.viewId)}"${view.viewId === selected?.viewId ? " selected" : ""}>${escapeHtml(view.name)}</option>`,
                )
                .join("")
            : '<option value="">No saved slates</option>'
        }
      </select>
    </label>
    <div class="shared-election-custom-toolbar__actions">
      <button class="shared-feed-chip${custom.items.length ? "" : " shared-feed-chip--primary"}" type="button" data-action="election-custom-new"${atLimit ? " disabled" : ""}>New</button>
      <button class="shared-feed-chip" type="button" data-action="election-custom-edit"${selected ? "" : " disabled"}>Edit</button>
      <button class="shared-feed-chip" type="button" data-action="election-custom-share"${selected ? "" : " disabled"}>Copy share link</button>
      <button class="shared-feed-chip" type="button" data-action="election-custom-delete"${selected ? "" : " disabled"}>Delete</button>
    </div>
  </div>`;
}

function renderElectionCustomEditor(election) {
  const custom = election.customViews;
  const draft = custom.draft || createElectionCustomDraft(selectedElectionCustomView(election));
  normalizeElectionCustomAddSelection(election);
  const addStateId = electionCustomAddStateId(election);
  const targetOptions = electionCustomTargetTypeOptions(election);
  const targetType = normalizeString(custom.addType || targetOptions[0]?.value);
  const districtOptions = electionCustomDistrictOptionsForType(targetType, election);
  const selectedDistrict =
    normalizeString(custom.addDistrict) ||
    electionCustomDefaultDistrictForType(targetType, election);
  const stateOptions = (election.context?.states || [])
    .map(
      (option) =>
        `<option value="${escapeHtml(option.stateId)}"${normalizeString(option.stateId).toUpperCase() === addStateId ? " selected" : ""}>${escapeHtml(option.stateName || option.stateId)}</option>`,
    )
    .join("");
  return `<div class="shared-election-custom-editor">
    <label>
      <span>Name</span>
      <input data-election-custom-field="name" value="${escapeHtml(draft.name)}" maxlength="80" />
    </label>
    <div class="shared-election-custom-add">
      <label>
        <span>State</span>
        <select data-election-custom-field="target-state"${stateOptions ? "" : " disabled"}>
          ${stateOptions || '<option value="">No states available</option>'}
        </select>
      </label>
      <label>
        <span>Race</span>
        <select data-election-custom-field="target-type"${targetOptions.length ? "" : " disabled"}>
          ${
            targetOptions.length
              ? targetOptions
                  .map(
                    (option) =>
                      `<option value="${escapeHtml(option.value)}"${option.value === targetType ? " selected" : ""}>${escapeHtml(option.label)}</option>`,
                  )
                  .join("")
              : '<option value="">No supported races</option>'
          }
        </select>
      </label>
      ${
        districtOptions.length
          ? `<label>
              <span>District</span>
              <select data-election-custom-field="target-district">
                ${districtOptions
                  .map(
                    (option) =>
                      `<option value="${escapeHtml(option.value)}"${option.value === selectedDistrict ? " selected" : ""}>${escapeHtml(option.label)}</option>`,
                  )
                  .join("")}
              </select>
            </label>`
          : ""
      }
      <button class="shared-feed-chip" type="button" data-action="election-custom-add-item">Add</button>
    </div>
    ${
      custom.targetLoadingKey
        ? '<div class="shared-page__loading">Loading race options...</div>'
        : ""
    }
    ${custom.targetError ? `<div class="shared-page__error">${escapeHtml(custom.targetError)}</div>` : ""}
    <div class="shared-election-custom-items">
      ${
        draft.items.length
          ? draft.items
              .map(
                (item, index) => `<div class="shared-election-custom-item">
                  <div>
                    <strong>${escapeHtml(electionCustomItemLabel(item))}</strong>
                    <span>${escapeHtml(electionScopeLabel(item.scope))}</span>
                  </div>
                  <div class="shared-election-custom-item__actions">
                    <button class="shared-feed-icon-button" type="button" data-action="election-custom-move-item" data-index="${index}" data-direction="-1" aria-label="Move up">^</button>
                    <button class="shared-feed-icon-button" type="button" data-action="election-custom-move-item" data-index="${index}" data-direction="1" aria-label="Move down">v</button>
                    <button class="shared-feed-icon-button" type="button" data-action="election-custom-remove-item" data-index="${index}" aria-label="Remove">x</button>
                  </div>
                </div>`,
              )
              .join("")
          : '<div class="shared-page__empty">Add races to this slate.</div>'
      }
    </div>
    <div class="shared-card__actions">
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="election-custom-save"${custom.saving ? " disabled" : ""}>Save</button>
      <button class="shared-feed-chip" type="button" data-action="election-custom-cancel">Cancel</button>
    </div>
  </div>`;
}

function renderElectionCustomControls(election) {
  if (normalizeElectionScope(election.selectedScope) !== ELECTION_SCOPE_CUSTOM) {
    return "";
  }
  if (normalizeString(election.selectedCustomShareId)) return "";
  if (!state.auth.session) return "";
  const custom = election.customViews;
  return `<section class="shared-election-custom-panel">
    ${custom.loading ? '<div class="shared-page__loading">Loading custom views...</div>' : ""}
    ${custom.error ? `<div class="shared-page__error">${escapeHtml(custom.error)}</div>` : ""}
    ${renderElectionCustomViewSelector(election)}
    ${custom.editing ? renderElectionCustomEditor(election) : ""}
  </section>`;
}

function renderElectionControls(election, selectedOption) {
  const states = election.context?.states || [];
  const selectedScope = normalizeElectionScope(election.selectedScope);
  const stateAvailable = electionStateTrackingAvailable(selectedOption);
  const myDistrictAvailable = electionOptionSupportsScope(
    selectedOption,
    ELECTION_SCOPE_MY_DISTRICT,
  );
  const customAvailable = electionOptionSupportsScope(
    selectedOption,
    ELECTION_SCOPE_CUSTOM,
  );
  const showPartyFilter =
    selectedScope === ELECTION_SCOPE_MY_DISTRICT ||
    selectedScope === ELECTION_SCOPE_CUSTOM;
  const raceTypes = stateAvailable
    ? electionStateRaceTypesForOption(selectedOption)
    : [];
  const selectedRaceType = selectedElectionRaceType() || "statewide";
  const stateOptions = states
    .map((option) => {
      const selected =
        normalizeString(option.stateId) ===
        normalizeString(election.selectedStateId);
      return `<option value="${escapeHtml(option.stateId)}"${selected ? " selected" : ""}>${escapeHtml(electionStateOptionLabel(option))}</option>`;
    })
    .join("");
  return `<div class="shared-election-controls">
    <label>
      <span>Race level</span>
      <select data-election-control="scope">
        <option value="federal"${selectedScope === ELECTION_SCOPE_FEDERAL ? " selected" : ""}>Federal</option>
        <option value="state"${selectedScope === ELECTION_SCOPE_STATE ? " selected" : ""}${stateAvailable ? "" : " disabled"}>State</option>
        <option value="my-district"${selectedScope === ELECTION_SCOPE_MY_DISTRICT ? " selected" : ""}${myDistrictAvailable ? "" : " disabled"}>My District</option>
        <option value="custom"${selectedScope === ELECTION_SCOPE_CUSTOM ? " selected" : ""}${customAvailable ? "" : " disabled"}>Custom</option>
        <option value="local" disabled>Local</option>
      </select>
    </label>
    ${
      selectedScope === ELECTION_SCOPE_CUSTOM
        ? ""
        : `<label>
      <span>State</span>
      <select data-election-control="state"${states.length ? "" : " disabled"}>
        ${stateOptions || '<option value="">No elections available</option>'}
      </select>
    </label>`
    }
    ${showPartyFilter ? renderElectionPartyFilterControl(election) : ""}
    ${
      selectedOption?.future && selectedOption.clickable !== true
        ? `<div class="shared-election-controls__hint">Next Election Date ${escapeHtml(formatElectionDate(selectedOption.electionDate) || "unavailable")}</div>`
        : ""
    }
    ${
      selectedScope === ELECTION_SCOPE_STATE
        ? `<div class="shared-election-race-tabs" role="tablist" aria-label="State race type">
            ${raceTypes
              .map(
                (raceType) =>
                  `<button class="shared-feed-chip${raceType === selectedRaceType ? " shared-feed-chip--primary" : ""}" type="button" data-action="election-race-type" data-race-type="${escapeHtml(raceType)}" aria-pressed="${raceType === selectedRaceType ? "true" : "false"}">${escapeHtml(electionRaceTypeLabel(raceType))}</button>`,
              )
              .join("")}
          </div>`
        : ""
    }
  </div>`;
}

function renderElectionMapPanel(election) {
  const selectedDistrict = normalizeString(election.selectedDistrictId);
  const selectedDistrictLabel = selectedElectionDistrictLabel(election);
  return `<section class="shared-election-map-panel">
    <div class="shared-election-map" id="shared-election-map">
      ${
        election.map.loading && !election.map.geometry
          ? '<div class="shared-page__loading">Loading election map...</div>'
          : ""
      }
      ${
        election.map.error && !election.map.geometry
          ? `<div class="shared-page__error">${escapeHtml(election.map.error)}</div>`
          : ""
      }
    </div>
    <div class="shared-election-map-panel__chrome">
      <span>${escapeHtml(selectedDistrictLabel)}</span>
      ${
        selectedDistrict
          ? '<button class="shared-feed-chip" data-action="election-state-view">State view</button>'
          : ""
      }
    </div>
  </section>`;
}

function renderElectionDistrictFilters(election) {
  if (
    normalizeElectionScope(election.selectedScope) !== ELECTION_SCOPE_STATE ||
    !selectedElectionMapChamber()
  ) {
    return "";
  }
  const districts = electionMapDistrictOptions(election);
  if (!districts.length) {
    return election.map.loading
      ? ""
      : '<div class="shared-page__empty">District filters will appear when the map loads.</div>';
  }
  const selectedDistrict = normalizeString(election.selectedDistrictId);
  return `<div class="shared-election-districts" aria-label="District filters">
    <button class="shared-feed-chip${selectedDistrict ? "" : " shared-feed-chip--primary"}" type="button" data-action="election-district-select" data-district-id="">All districts</button>
    ${districts
      .map(
        (district) =>
          `<button class="shared-feed-chip${district.districtId === selectedDistrict ? " shared-feed-chip--primary" : ""}" type="button" data-action="election-district-select" data-district-id="${escapeHtml(district.districtId)}">${escapeHtml(district.label)}</button>`,
      )
      .join("")}
  </div>`;
}

function renderElectionCandidateRow(candidate, race, previousCandidateMap) {
  const previous = previousCandidateMap.get(`${race.raceId}:${candidate.id}`);
  const changed =
    previous &&
    (Number(previous.votes) !== Number(candidate.votes) ||
      Number(previous.votePercent) !== Number(candidate.votePercent));
  const color = electionPartyColor(
    candidate.partyToken || candidate.partyLabel,
  );
  const width = Math.max(0, Math.min(100, Number(candidate.votePercent) || 0));
  return `<div class="shared-election-candidate${candidate.isWinner ? " is-winner" : ""}${changed ? " is-updated" : ""}" style="--party-color:${escapeHtml(color)}">
    ${
      candidate.avatarUrl
        ? `<img class="shared-election-candidate__avatar" src="${escapeHtml(candidate.avatarUrl)}" alt="${escapeHtml(candidate.name)}" />`
        : `<div class="shared-election-candidate__avatar shared-election-candidate__avatar--placeholder">${escapeHtml(candidate.name.slice(0, 1).toUpperCase() || "C")}</div>`
    }
    <div class="shared-election-candidate__body">
      <div class="shared-election-candidate__topline">
        <strong>${escapeHtml(candidate.name)}</strong>
        <span>${escapeHtml(candidate.partyLabel || candidate.partyToken || "Other")}</span>
      </div>
      <div class="shared-election-candidate__bar">
        <span style="width:${width}%"></span>
      </div>
    </div>
    <div class="shared-election-candidate__numbers">
      <strong data-election-counter data-from="${escapeHtml(String(previous?.votes ?? candidate.votes))}" data-to="${escapeHtml(String(candidate.votes))}">${escapeHtml(formatElectionVotes(candidate.votes))}</strong>
      <span>${escapeHtml(formatElectionPercent(candidate.votePercent))}</span>
      ${candidate.isWinner ? "<em>Winner</em>" : ""}
    </div>
  </div>`;
}

function renderElectionCountyCandidate(candidate) {
  return `<div class="shared-election-county-candidate">
    <span>${escapeHtml(candidate.name)}</span>
    <strong>${escapeHtml(formatElectionVotes(candidate.votes))}</strong>
    <em>${escapeHtml(formatElectionPercent(candidate.votePercent))}</em>
  </div>`;
}

function renderElectionCountyResultRow(county, { partyFilter = "all" } = {}) {
  const candidates = (county.candidates || []).filter(
    (candidate) =>
      partyFilter === "all" || electionCandidatePartyKey(candidate) === partyFilter,
  );
  return `<div class="shared-election-county-row">
    <div class="shared-election-county-row__header">
      <strong>${escapeHtml(county.countyName)}</strong>
      <span>${escapeHtml(formatElectionVotes(county.totalVotes))} votes</span>
    </div>
    <div class="shared-election-county-row__candidates">
      ${
        candidates.length
          ? candidates.map(renderElectionCountyCandidate).join("")
          : '<span class="shared-election-empty-candidates">No matching county candidate rows.</span>'
      }
    </div>
  </div>`;
}

function renderElectionCountyResults(race, options = {}) {
  const counties = Array.isArray(race.countyResults)
    ? race.countyResults
    : [];
  if (!counties.length) return "";
  return `<details class="shared-election-county-results">
    <summary>County results <span>${escapeHtml(formatElectionVotes(counties.length))}</span></summary>
    <div class="shared-election-county-results__list">
      ${counties
        .map((county) => renderElectionCountyResultRow(county, options))
        .join("")}
    </div>
  </details>`;
}

function renderElectionRaceCard(race, previousCandidateMap, options = {}) {
  const partyFilter = normalizeElectionPartyFilter(options.partyFilter);
  const userPartyToken = normalizeElectionPartyToken(
    state.pages.elections.context?.userPartyToken ||
      state.pages.elections.context?.userPartyLabel,
  );
  const orderedCandidates = [...(race.candidates || [])].sort(
    (left, right) => {
      if (options.partyFirst) {
        const leftRank = candidatePartySortRank(
          electionCandidatePartyKey(left),
          userPartyToken,
        );
        const rightRank = candidatePartySortRank(
          electionCandidatePartyKey(right),
          userPartyToken,
        );
        if (leftRank !== rightRank) return leftRank - rightRank;
      }
      const votes = Number(right.votes) - Number(left.votes);
      if (votes) return votes;
      return normalizeString(left.name).localeCompare(normalizeString(right.name));
    },
  );
  const visibleCandidates = orderedCandidates.filter(
    (candidate) =>
      partyFilter === "all" || electionCandidatePartyKey(candidate) === partyFilter,
  );
  const selectedPartyLabel =
    partyFilter === "all" ? "" : candidatePartyLabelForKey(partyFilter);
  return `<article class="shared-election-race">
    <div class="shared-election-race__header">
      <div>
        <div class="shared-card__meta">
          ${race.stateName ? `<span>${escapeHtml(race.stateName)}</span>` : ""}
          ${race.districtId ? `<span>${escapeHtml(race.districtId)}</span>` : ""}
          ${race.stage ? `<span>${escapeHtml(humanizeLabel(race.stage))}</span>` : ""}
          ${race.called ? "<span>Called</span>" : ""}
        </div>
        <h3>${escapeHtml(race.officeTitle)}</h3>
      </div>
      ${
        race.called
          ? `<span class="shared-election-status shared-election-status--called">Called</span>`
          : ""
      }
    </div>
    <div class="shared-election-race__candidates">
      ${
        visibleCandidates.length
          ? visibleCandidates
              .map((candidate) =>
                renderElectionCandidateRow(candidate, race, previousCandidateMap),
              )
              .join("")
          : `<div class="shared-election-empty-candidates">No ${escapeHtml(selectedPartyLabel)} candidates in this office.</div>`
      }
    </div>
    ${renderElectionCountyResults(race, { partyFilter })}
  </article>`;
}

function renderElectionMissingDistrictNotice(snapshot = null) {
  const missing = snapshot?.missingDistricts;
  if (!missing?.stateHouse && !missing?.stateSenate) return "";
  return `<div class="shared-page__empty">Home address needed for state legislative races.</div>`;
}

function renderElectionRaceList(races, previousCandidateMap, options = {}) {
  return filterElectionRacesForPartyView(races, options)
    .map((race) => renderElectionRaceCard(race, previousCandidateMap, options))
    .join("");
}

function electionCustomRaceSortValue(race = {}) {
  return Number.isFinite(Number(race.customOrder))
    ? Number(race.customOrder)
    : Number.MAX_SAFE_INTEGER;
}

function groupElectionCustomRacesByState(races = []) {
  const groups = new Map();
  for (const race of [...races].sort((left, right) => {
    const order = electionCustomRaceSortValue(left) - electionCustomRaceSortValue(right);
    if (order) return order;
    return normalizeString(left.officeTitle).localeCompare(
      normalizeString(right.officeTitle),
    );
  })) {
    const stateId = normalizeString(race.stateId || "unknown");
    const existing =
      groups.get(stateId) || {
        stateId,
        stateName: race.stateName || electionStateNameForId(stateId),
        firstOrder: electionCustomRaceSortValue(race),
        races: [],
      };
    existing.firstOrder = Math.min(
      existing.firstOrder,
      electionCustomRaceSortValue(race),
    );
    existing.races.push(race);
    groups.set(stateId, existing);
  }
  return Array.from(groups.values()).sort((left, right) => {
    if (left.firstOrder !== right.firstOrder) return left.firstOrder - right.firstOrder;
    return normalizeString(left.stateName).localeCompare(normalizeString(right.stateName));
  });
}

function renderElectionCustomStateGroups(
  races,
  previousCandidateMap,
  options = {},
) {
  return groupElectionCustomRacesByState(races)
    .map(
      (group) => `<div class="shared-election-custom-state-group">
        <h4>${escapeHtml(group.stateName || group.stateId)}</h4>
        ${group.races
          .map((race) => renderElectionRaceCard(race, previousCandidateMap, options))
          .join("")}
      </div>`,
    )
    .join("");
}

function renderElectionCustomColumns(snapshot, previousCandidateMap, options = {}) {
  const federalRaces = (snapshot.races || []).filter(
    (race) => electionRaceResultScope(race) === ELECTION_SCOPE_FEDERAL,
  );
  const stateRaces = (snapshot.races || []).filter(
    (race) => electionRaceResultScope(race) === ELECTION_SCOPE_STATE,
  );
  const visibleFederalRaces = filterElectionRacesForPartyView(
    federalRaces,
    options,
  );
  const visibleStateRaces = filterElectionRacesForPartyView(stateRaces, options);
  return `<div class="shared-election-custom-columns">
    <section class="shared-election-custom-column">
      <h3>Federal</h3>
      ${
        visibleFederalRaces.length
          ? renderElectionCustomStateGroups(
              visibleFederalRaces,
              previousCandidateMap,
              options,
            )
          : federalRaces.length
            ? '<div class="shared-page__empty">No federal races match this party filter.</div>'
          : '<div class="shared-page__empty">No federal races in this slate.</div>'
      }
    </section>
    <section class="shared-election-custom-column">
      <h3>State level</h3>
      ${
        visibleStateRaces.length
          ? renderElectionCustomStateGroups(
              visibleStateRaces,
              previousCandidateMap,
              options,
            )
          : stateRaces.length
            ? '<div class="shared-page__empty">No state races match this party filter.</div>'
          : '<div class="shared-page__empty">No state races in this slate.</div>'
      }
    </section>
  </div>`;
}

function renderElectionResults(election, selectedOption) {
  const selectedScope = normalizeElectionScope(election.selectedScope);
  const sharedCustom =
    selectedScope === ELECTION_SCOPE_CUSTOM &&
    Boolean(normalizeString(election.selectedCustomShareId));
  if (
    electionScopeRequiresAuth(selectedScope) &&
    !state.auth.session &&
    !sharedCustom
  ) {
    return renderElectionAuthPrompt(selectedScope);
  }
  if (
    selectedScope !== ELECTION_SCOPE_CUSTOM &&
    selectedOption?.future &&
    selectedOption.clickable !== true
  ) {
    return `<section class="shared-election-upcoming">
      <h2>Next Election Date ${escapeHtml(formatElectionDate(selectedOption.electionDate) || "unavailable")}</h2>
      <p>${escapeHtml(selectedOption.electionName || "Results will appear here when vote totals are available.")}</p>
    </section>`;
  }
  const snapshot = election.results.snapshot;
  if (election.results.loading && !snapshot) {
    return '<div class="shared-page__loading">Loading election results...</div>';
  }
  if (election.results.error && !snapshot) {
    return `<div class="shared-page__error">${escapeHtml(election.results.error)}</div>`;
  }
  if (!snapshot) {
    return `<div class="shared-page__empty">No ${escapeHtml(electionScopeLabel(election.selectedScope))} race results are available for this selection.</div>`;
  }
  const previousCandidateMap = electionPreviousCandidateMap(
    election.results.previousSnapshot,
  );
  const partyFilter =
    selectedScope === ELECTION_SCOPE_MY_DISTRICT ||
    selectedScope === ELECTION_SCOPE_CUSTOM
      ? selectedElectionPartyFilterValue(snapshot)
      : "all";
  const groups = groupElectionRaces(snapshot, election.selectedDistrictId);
  const countyCoverageLine = electionCountyCoverageLine(snapshot);
  const customResults =
    selectedScope === ELECTION_SCOPE_CUSTOM
      ? renderElectionCustomColumns(snapshot, previousCandidateMap, {
          partyFilter,
          partyFirst: true,
        })
      : "";
  const myDistrictResults =
    selectedScope === ELECTION_SCOPE_MY_DISTRICT
      ? (() => {
          const visibleRaces = filterElectionRacesForPartyView(
            snapshot.races || [],
            { partyFilter },
          );
          return `<div class="shared-election-group">
            <h3>My District ballot</h3>
            ${renderElectionMissingDistrictNotice(snapshot)}
            ${
              visibleRaces.length
                ? renderElectionRaceList(visibleRaces, previousCandidateMap, {
                    partyFilter,
                    partyFirst: true,
                  })
                : (snapshot.races || []).length
                  ? '<div class="shared-page__empty">No races match this party filter.</div>'
                  : '<div class="shared-page__empty">No tracked races are available for your district.</div>'
            }
          </div>`;
        })()
      : "";
  return `<section class="shared-election-results">
    <div class="shared-election-results__header">
      <div>
        <h2>${escapeHtml(snapshot.electionName || `${electionScopeLabel(snapshot.scope)} election`)}</h2>
        <p>${escapeHtml(electionReportingLine(snapshot))}</p>
      </div>
      <span class="shared-election-status">${escapeHtml(electionStatusLabel(snapshot, selectedOption))}</span>
    </div>
    ${
      countyCoverageLine
        ? `<div class="shared-election-coverage">${escapeHtml(countyCoverageLine)}</div>`
        : ""
    }
    ${
      customResults ||
      myDistrictResults ||
      (groups.length
        ? groups
            .map(
              (group) => `<div class="shared-election-group">
                <h3>${escapeHtml(group.title)}</h3>
                ${group.races
                  .map((race) =>
                    renderElectionRaceCard(race, previousCandidateMap, {
                      partyFilter: "all",
                      partyFirst: false,
                    }),
                  )
                  .join("")}
              </div>`,
            )
            .join("")
        : `<div class="shared-page__empty">No ${escapeHtml(electionScopeLabel(snapshot.scope))} race results are available for this selection.</div>`)
    }
  </section>`;
}

function renderElectionDayPage() {
  const election = state.pages.elections;
  const selectedOption = selectedElectionStateOption();
  const snapshot = election.results.snapshot;
  const status = electionStatusLabel(snapshot, selectedOption);
  const selectedScope = normalizeElectionScope(election.selectedScope);
  const showMap = shouldRenderElectionMap(election);
  const subtitle =
    selectedOption?.future && selectedOption.clickable !== true
      ? `Next Election Date ${formatElectionDate(selectedOption.electionDate) || "unavailable"}`
      : electionReportingLine(snapshot);
  return `<section class="shared-page shared-election-page">
    ${renderTopChrome()}
    <div class="shared-page__content">
      <div class="shared-page__header shared-page__header--hero">
        <div>
          <p class="shared-page__eyebrow">Election Day</p>
          <h1>Live election results</h1>
          <p>${escapeHtml(subtitle)}</p>
          <div class="shared-card__meta">
            <span>${escapeHtml(status)}</span>
            ${election.selectedStateId ? `<span>${escapeHtml(election.selectedStateId)}</span>` : ""}
            ${selectedScope === ELECTION_SCOPE_STATE ? `<span>${escapeHtml(electionRaceTypeLabel(selectedElectionRaceType()))}</span>` : ""}
            ${election.selectedDistrictId ? `<span>${escapeHtml(election.selectedDistrictId)}</span>` : ""}
          </div>
        </div>
        <div class="shared-card__actions">
          <button class="shared-feed-chip shared-feed-chip--primary" data-action="election-refresh">Refresh</button>
          <button class="shared-feed-chip" data-action="open-app-shell">Open app</button>
        </div>
      </div>
      ${election.contextError ? `<div class="shared-page__error">${escapeHtml(election.contextError)}</div>` : ""}
      ${renderElectionControls(election, selectedOption)}
      ${renderElectionCustomControls(election)}
      ${showMap ? renderElectionMapPanel(election) : ""}
      ${renderElectionDistrictFilters(election)}
      ${renderElectionResults(election, selectedOption)}
    </div>
  </section>`;
}

function normalizedCandidatePartyToken(candidate = {}) {
  return normalizeElectionPartyToken(
    candidate.partyToken || candidate.partyCode || candidate.partyLabel,
  );
}

function candidatePartyGroupKey(candidate = {}) {
  return normalizedCandidatePartyToken(candidate) || "UNK";
}

function candidatePartyLabelForKey(key, sample = null) {
  const normalizedKey = normalizeString(key).toUpperCase();
  const sampleLabel = normalizeString(sample?.partyLabel);
  if (sampleLabel) return sampleLabel;
  switch (normalizedKey) {
    case "DEM":
      return "Democratic";
    case "REP":
      return "Republican";
    case "LIB":
      return "Libertarian";
    case "GRN":
      return "Green";
    case "IND":
      return "Independent";
    case "OTH":
      return "Other";
    default:
      return "Unknown party";
  }
}

function candidatePartyColorForKey(key) {
  return electionPartyColor(key || "OTH");
}

function selectedUserCandidatePartyToken() {
  const params = readCurrentSearchParams();
  return normalizeElectionPartyToken(
    params.get("partyToken") ||
      params.get("party") ||
      params.get("partyLabel") ||
      state.pages.elections.context?.userPartyToken ||
      state.pages.elections.context?.userPartyLabel,
  );
}

function candidatePartySortRank(key, userPartyToken = "") {
  const normalizedKey = normalizeString(key).toUpperCase();
  const normalizedUserParty = normalizeString(userPartyToken).toUpperCase();
  if (normalizedUserParty && normalizedKey === normalizedUserParty) {
    return -10;
  }
  const rank = ["DEM", "REP", "LIB", "GRN", "IND", "OTH", "UNK"].indexOf(
    normalizedKey,
  );
  return rank >= 0 ? rank : 999;
}

function compareCandidateDirectoryItems(left = {}, right = {}) {
  if (left.isFollowing !== right.isFollowing) {
    return left.isFollowing ? -1 : 1;
  }
  if (Boolean(left.activeElection?.path) !== Boolean(right.activeElection?.path)) {
    return left.activeElection?.path ? -1 : 1;
  }
  const leftOffice = normalizeString(left.officeTitle || left.levelOfOffice);
  const rightOffice = normalizeString(right.officeTitle || right.levelOfOffice);
  const officeCompare = leftOffice.localeCompare(rightOffice);
  if (officeCompare) return officeCompare;
  return normalizeString(left.displayName).localeCompare(
    normalizeString(right.displayName),
  );
}

function candidatePartyGroups(items = []) {
  const userPartyToken = selectedUserCandidatePartyToken();
  const groups = new Map();
  for (const candidate of items) {
    const key = candidatePartyGroupKey(candidate);
    const existing = groups.get(key) || {
      key,
      title: candidatePartyLabelForKey(key, candidate),
      items: [],
    };
    existing.items.push(candidate);
    if (!existing.title || existing.title === "Unknown party") {
      existing.title = candidatePartyLabelForKey(key, candidate);
    }
    groups.set(key, existing);
  }
  return Array.from(groups.values())
    .map((group) => ({
      ...group,
      items: [...group.items].sort(compareCandidateDirectoryItems),
      count: group.items.length,
      preferred: Boolean(
        userPartyToken && normalizeString(group.key).toUpperCase() === userPartyToken,
      ),
    }))
    .sort((left, right) => {
      const leftRank = candidatePartySortRank(left.key, userPartyToken);
      const rightRank = candidatePartySortRank(right.key, userPartyToken);
      if (leftRank !== rightRank) return leftRank - rightRank;
      return left.title.localeCompare(right.title);
    });
}

function ensureCandidateCollapsedPartyGroupsLoaded() {
  if (candidateCollapsedPartyGroupsLoaded) return;
  candidateCollapsedPartyGroupsLoaded = true;
  try {
    const raw = window.localStorage?.getItem(
      CANDIDATE_PARTY_COLLAPSE_STORAGE_KEY,
    );
    const parsed = raw ? JSON.parse(raw) : [];
    candidateCollapsedPartyGroups = new Set(
      Array.isArray(parsed) ? parsed.map((entry) => normalizeString(entry)) : [],
    );
  } catch {
    candidateCollapsedPartyGroups = new Set();
  }
}

function persistCandidateCollapsedPartyGroups() {
  try {
    window.localStorage?.setItem(
      CANDIDATE_PARTY_COLLAPSE_STORAGE_KEY,
      JSON.stringify(Array.from(candidateCollapsedPartyGroups).filter(Boolean)),
    );
  } catch {
    // Collapsed state is an enhancement.
  }
}

function renderCandidatePreviewCard(candidate, currentPath) {
  const followTarget = resolveCandidateFollowTarget(candidate);
  const partyToken = normalizedCandidatePartyToken(candidate);
  const partyLabel = candidatePartyLabelForKey(partyToken || "UNK", candidate);
  const partyColor = candidatePartyColorForKey(partyToken || "OTH");
  const districtLabel = candidateDisplayDistrictLabel(candidate);
  return `<article class="shared-card shared-card--candidate-preview" style="--candidate-party-color:${escapeHtml(partyColor)}">
    ${
      candidate.avatarUrl
        ? `<img class="shared-card__avatar" src="${escapeHtml(candidate.avatarUrl)}" alt="${escapeHtml(candidate.displayName)}" />`
        : `<div class="shared-card__avatar shared-card__avatar--placeholder">${escapeHtml(candidate.displayName.slice(0, 1).toUpperCase() || "C")}</div>`
    }
    <div class="shared-card__body shared-card__body--candidate-preview">
      <div class="shared-card__meta">
        <span class="shared-candidate-party-pill">${escapeHtml(partyToken || partyLabel)}</span>
        <span>${escapeHtml(candidate.officeTitle || candidate.levelOfOffice || "Candidate")}</span>
        ${
          districtLabel
            ? `<span>${escapeHtml(districtLabel)}</span>`
            : ""
        }
      </div>
      <h3>${escapeHtml(partyToken ? `${candidate.displayName} (${partyToken})` : candidate.displayName)}</h3>
      <p class="shared-card__summary">${escapeHtml(candidate.bio || (candidate.kind === "official" ? "Open the official profile to see office details and the report card." : candidate.kind === "raceCandidate" ? "Open the auto-generated profile to see election details and any linked Polis profile." : "Open the candidate page to see recent posts, events, and campaign details."))}</p>
      <div class="shared-card__meta shared-card__meta--candidate-preview">
        <span>${escapeHtml(formatCount(candidate.followersCount))} followers</span>
        ${
          candidate.tags.length
            ? `<span>${escapeHtml(candidate.tags.join(", "))}</span>`
            : ""
        }
      </div>
      <div class="shared-card__actions">
        <button class="shared-feed-chip shared-feed-chip--primary" data-action="navigate" data-route="${escapeHtml(resolveCandidateOpenRoute(candidate, currentPath))}">Open</button>
        ${
          candidate.activeElection?.path
            ? `<button class="shared-feed-chip" data-action="navigate" data-route="${escapeHtml(candidate.activeElection.path)}">${renderIcon("election")} Results</button>`
            : ""
        }
        ${
          followTarget.candidateId || followTarget.officialId
            ? `<button class="shared-feed-chip" data-action="candidate-follow" data-candidate-id="${escapeHtml(followTarget.candidateId)}" data-official-id="${escapeHtml(followTarget.officialId)}">${candidate.isFollowing ? "Following" : "Follow"}</button>`
            : ""
        }
        ${
          candidate.canEdit
            ? `<button class="shared-feed-chip" data-action="navigate" data-route="${escapeHtml(resolveCandidateEditRoute(candidate))}">Edit</button>`
            : ""
        }
      </div>
    </div>
  </article>`;
}

function renderCandidatePartyGroup(group, currentPath) {
  const collapsed = candidateCollapsedPartyGroups.has(group.key);
  const color = candidatePartyColorForKey(group.key);
  return `<section class="shared-candidate-party-group" style="--candidate-party-color:${escapeHtml(color)}">
    <button class="shared-candidate-party-group__header" type="button" data-action="candidate-party-toggle" data-party-key="${escapeHtml(group.key)}" aria-expanded="${collapsed ? "false" : "true"}">
      <span class="shared-candidate-party-group__chevron" aria-hidden="true">${renderIcon(collapsed ? "arrowRight" : "chevronDown")}</span>
      <span class="shared-candidate-party-group__title">${escapeHtml(group.title)}</span>
      ${group.preferred ? '<span class="shared-candidate-party-group__badge">Your party</span>' : ""}
      <span class="shared-candidate-party-group__count">${escapeHtml(formatCount(group.count))}</span>
    </button>
    ${
      collapsed
        ? ""
        : `<div class="shared-card-grid shared-card-grid--candidates">
            ${group.items
              .map((candidate) => renderCandidatePreviewCard(candidate, currentPath))
              .join("")}
          </div>`
    }
  </section>`;
}

function renderCandidateListPage() {
  const list = state.pages.candidates.list;
  const currentPath = getCurrentPathWithQuery();
  const directoryOptions = candidateDirectoryOptionsFromParams();
  const feedMode = directoryOptions.feed;
  const isOfficialsMode = feedMode === "officials";
  const activeFeedLabel = candidateDirectoryFeedLabel(feedMode);
  const actionRoute = isOfficialsMode
    ? buildCongressionalReportCardRoute({ returnTo: currentPath })
    : "/election-day";
  ensureCandidateCollapsedPartyGroupsLoaded();
  const groups = candidatePartyGroups(list.items);
  const directoryModes = [
    {
      key: "candidates",
      label: "Candidates",
      copy: "Campaigns, races, and Election Day links.",
    },
    {
      key: "officials",
      label: "Elected Officials",
      copy: "Report cards, votes, offices, and bills.",
    },
  ];
  return `<section class="shared-page">
    ${renderTopChrome()}
    <div class="shared-page__content">
      <div class="shared-page__header">
        <div>
          <p class="shared-page__eyebrow">Officials</p>
          <h1>Officials and candidates</h1>
          <p>${escapeHtml(candidateDirectoryFeedDescription(feedMode))}</p>
        </div>
        <div class="shared-card__actions">
          <button class="shared-feed-chip shared-feed-chip--primary" data-action="navigate" data-route="${escapeHtml(actionRoute)}">${renderIcon(isOfficialsMode ? "file" : "election")} ${isOfficialsMode ? "Bills" : "Election Day"}</button>
        </div>
      </div>
      <section class="shared-candidate-directory-toolbar" aria-label="Candidate directory mode">
        <div class="shared-candidate-directory-mode" role="tablist" aria-label="Directory mode">
          ${directoryModes
            .map((mode) => {
              const active = mode.key === feedMode;
              return `<button type="button" role="tab" class="${active ? "is-active" : ""}" aria-selected="${active ? "true" : "false"}" data-action="navigate" data-route="${escapeHtml(buildCandidateDirectoryRoute({ feed: mode.key }))}">
                <strong>${escapeHtml(mode.label)}</strong>
                <span>${escapeHtml(mode.copy)}</span>
              </button>`;
            })
            .join("")}
        </div>
        <div class="shared-candidate-directory-summary">
          <span>${renderIcon(isOfficialsMode ? "file" : "candidate")} ${escapeHtml(activeFeedLabel)}</span>
          <strong>${escapeHtml(formatCount(list.items.length))}</strong>
          <small>${escapeHtml(candidateDirectoryFeedTitle(feedMode))} loaded in this view.</small>
        </div>
      </section>
      ${renderCandidateDirectoryFilters(list, feedMode, isOfficialsMode)}
      ${
        list.loading
          ? `<div class="shared-page__loading">Loading ${escapeHtml(activeFeedLabel)}...</div>`
          : ""
      }
      ${list.error ? `<div class="shared-page__error">${escapeHtml(list.error)}</div>` : ""}
      <div class="shared-candidate-party-groups">
        ${
          groups.length
            ? groups
                .map((group) => renderCandidatePartyGroup(group, currentPath))
                .join("")
            : list.loaded && !list.loading
              ? `<div class="shared-page__empty">${escapeHtml(candidateDirectoryEmptyMessage(feedMode))}</div>`
              : ""
        }
      </div>
      ${
        list.loadingMore
          ? `<div class="shared-page__hint">Loading more ${escapeHtml(activeFeedLabel)}...</div>`
          : ""
      }
      ${
        list.nextCursor
          ? '<div class="shared-page__pagination-sentinel" data-candidate-list-sentinel aria-hidden="true"></div>'
          : ""
      }
    </div>
  </section>`;
}

function renderCandidateEditorTagPicker(candidate, detail, saving) {
  const selectedTags = candidateEditorCurrentTags(candidate);
  const tagMap = candidateEditorCatalogTagMap();
  const suggestions = candidateEditorSuggestedTags(selectedTags);
  const catalog = detail.tagCatalog || createCandidateTagCatalogState();
  const maxReached = selectedTags.length >= CANDIDATE_EDITOR_MAX_TAGS;
  return `<div class="shared-candidate-tags-editor shared-candidate-editor__wide">
    <input type="hidden" name="priorityTags" value="${escapeHtml(selectedTags.join(", "))}" />
    <div class="shared-candidate-tags-editor__header">
      <span>Priority tags</span>
      <small>${escapeHtml(`${selectedTags.length}/${CANDIDATE_EDITOR_MAX_TAGS} tags selected`)}</small>
    </div>
    ${
      selectedTags.length
        ? `<div class="shared-candidate-tags-editor__chips">
            ${selectedTags
              .map(
                (tag) => `<button class="shared-candidate-tag-chip" type="button" data-action="candidate-tag-remove" data-tag="${escapeHtml(tag)}"${disabledAttr(saving)}>
                  <span>${escapeHtml(candidateEditorTagLabel(tag, tagMap))}</span>
                  <em aria-hidden="true">${renderIcon("close")}</em>
                </button>`,
              )
              .join("")}
          </div>`
        : '<div class="shared-candidate-tags-editor__empty">No tags selected yet.</div>'
    }
    <div class="shared-candidate-tags-editor__add">
      <input name="candidateTagInput" data-candidate-tag-input placeholder="${escapeHtml(maxReached ? "Tag limit reached" : "Add tag")}"${disabledAttr(saving || maxReached)} />
      <button class="shared-feed-chip" type="button" data-action="candidate-tag-add"${disabledAttr(saving || maxReached)}>Add tag</button>
    </div>
    ${
      suggestions.length
        ? `<div class="shared-candidate-tags-editor__suggestions" aria-label="Suggested tags">
            ${suggestions
              .map(
                (tag) => `<button type="button" data-action="candidate-tag-suggest" data-tag="${escapeHtml(tag.value)}"${disabledAttr(saving || maxReached)}>
                  <span>${escapeHtml(tag.label)}</span>
                  ${tag.categoryName ? `<small>${escapeHtml(tag.categoryName)}</small>` : ""}
                </button>`,
              )
              .join("")}
          </div>`
        : catalog.loading
          ? '<div class="shared-candidate-tags-editor__hint">Loading tag catalog...</div>'
          : catalog.error
            ? `<div class="shared-candidate-tags-editor__hint">${escapeHtml("Catalog unavailable. Manual tags still work.")}</div>`
            : ""
    }
  </div>`;
}

function renderCandidateEditForm(candidate, detail, socials = {}) {
  const avatarUpload = detail.avatarUpload || createCandidateAvatarUploadState();
  const avatarUrl = avatarUpload.remoteUrl || candidate.avatarUrl;
  const avatarBusy = avatarUpload.uploading === true;
  const saving = detail.saving === true;
  const identityLock = candidateEditorIdentityLockState(candidate);
  const identityLocked = identityLock.locked === true;
  const identityReadOnlyAttr = identityLocked ? ' readonly aria-readonly="true"' : "";
  const levelLabel = autoCandidateLevelLabel(candidate.levelOfOffice);
  const districtLabel = candidateDisplayDistrictLabel(candidate);
  const candidateId = normalizeString(candidate.candidateId);
  const publicRoute = resolveCandidateOpenRoute(candidate);
  const dashboardRoute = candidateDashboardSectionPath(candidateId);
  const messagingRoute = candidateDashboardSectionPath(candidateId, "messaging");
  const eventsRoute = candidateDashboardSectionPath(candidateId, "events");
  const settingsRoute = isCandidateSettingsEditRoute();
  const workflowItems = [
    {
      icon: "candidate",
      label: "Public profile",
      copy: "Search, follows, donations, and candidate cards.",
      route: publicRoute,
      cta: "View profile",
    },
    {
      icon: "dashboard",
      label: "Campaign dashboard",
      copy: "Staff, voter tools, calendar, missions, and donations.",
      route: dashboardRoute,
      cta: "Open dashboard",
      primary: true,
    },
    {
      icon: "messages",
      label: "Campaign messaging",
      copy: "Candidate, staff, operations, and volunteer rooms.",
      route: messagingRoute,
      cta: "Open messages",
    },
  ];
  return `<form class="shared-form shared-candidate-editor${identityLocked ? " is-identity-locked" : ""}" data-route-form="candidate-edit" aria-busy="${saving ? "true" : "false"}">
    <input type="hidden" name="candidateId" value="${escapeHtml(candidate.candidateId)}" />
    <input type="hidden" name="avatarUploadId" value="${escapeHtml(avatarUpload.uploadId)}" />
    <input type="hidden" name="previousAvatarUploadId" value="${escapeHtml(avatarUpload.uploadId ? avatarUpload.previousAvatarUploadId : "")}" />
    <input type="hidden" name="previousAvatarUrl" value="${escapeHtml(avatarUpload.uploadId ? avatarUpload.previousAvatarUrl : "")}" />
    <div class="shared-candidate-editor__bar">
      <div>
        <span>Edit candidate page</span>
        <h2>Profile details</h2>
        <p>Keep the public campaign profile current across Polis, candidate search, events, donations, and messaging.</p>
      </div>
      <div class="shared-candidate-editor__bar-actions">
        <span class="shared-candidate-editor__status${saving ? " is-saving" : ""}">${saving ? "Saving" : "Ready"}</span>
        <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(saving || avatarBusy)}>${saving ? "Saving..." : "Save changes"}</button>
      </div>
    </div>
    <section class="shared-candidate-editor__context" aria-label="Candidate profile workflow">
      <div class="shared-candidate-editor__context-copy">
        <span>${renderIcon("shield")} ${escapeHtml(settingsRoute ? "Settings editor" : "Profile editor")}</span>
        <h3>Campaign identity hub</h3>
        <p>Saved profile details carry into candidate search, public events, donations, staff workspaces, and campaign conversations.</p>
        <div class="shared-candidate-editor__context-actions">
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(publicRoute)}"${disabledAttr(saving)}>Public profile</button>
          <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="${escapeHtml(dashboardRoute)}"${disabledAttr(saving)}>Candidate dashboard</button>
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(eventsRoute)}"${disabledAttr(saving)}>Events</button>
        </div>
      </div>
      <div class="shared-candidate-editor__workflow" aria-label="Candidate profile destinations">
        ${workflowItems
          .map(
            (item) => `<button class="shared-candidate-editor-workflow${item.primary ? " is-primary" : ""}" type="button" data-action="navigate" data-route="${escapeHtml(item.route)}"${disabledAttr(saving)}>
              <span aria-hidden="true">${renderIcon(item.icon)}</span>
              <strong>${escapeHtml(item.label)}</strong>
              <small>${escapeHtml(item.copy)}</small>
              <em>${escapeHtml(item.cta)}</em>
            </button>`,
          )
          .join("")}
      </div>
    </section>
    <section class="shared-candidate-editor__section shared-candidate-editor__section--profile">
      <div class="shared-candidate-editor__preview">
        ${
          avatarUrl
            ? `<img src="${escapeHtml(avatarUrl)}" alt="${escapeHtml(candidate.displayName)}" />`
            : `<span>${escapeHtml(candidate.displayName.slice(0, 1).toUpperCase() || "C")}</span>`
        }
        <div>
          <strong>${escapeHtml(candidate.displayName)}</strong>
          <span>${escapeHtml(levelLabel || "Candidate")}</span>
          ${districtLabel ? `<span>${escapeHtml(districtLabel)}</span>` : ""}
        </div>
        <input class="shared-candidate-editor__file-input" type="file" accept="${POST_COMPOSER_IMAGE_ACCEPT}" data-candidate-avatar-file />
        <div class="shared-candidate-editor__avatar-actions">
          <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-avatar-pick"${disabledAttr(saving || avatarBusy)}>${avatarBusy ? "Uploading..." : "Upload image"}</button>
          ${
            avatarUpload.uploadId
              ? `<button class="shared-feed-chip" type="button" data-action="candidate-avatar-clear"${disabledAttr(saving || avatarBusy)}>Clear staged</button>`
              : ""
          }
        </div>
        ${
          avatarUpload.fileName
            ? `<small>${escapeHtml(avatarUpload.fileName)}</small>`
            : ""
        }
        ${
          avatarUpload.error
            ? `<small class="shared-candidate-editor__error">${escapeHtml(avatarUpload.error)}</small>`
            : ""
        }
      </div>
      <div class="shared-candidate-editor__grid">
        ${
          identityLocked
            ? `<div class="shared-candidate-editor__lock-note" role="note">
                <span aria-hidden="true">${renderIcon("shield")}</span>
                <div>
                  <strong>${escapeHtml(identityLock.loading ? "Checking approval status" : "Identity locked after approval")}</strong>
                  <small>${escapeHtml(identityLock.loading ? "Display name, office level, and district stay paused while Polis checks approval status." : "Display name, office level, and district now stay fixed. Avatar, bio, tags, and contact links can still be updated.")}</small>
                </div>
              </div>`
            : ""
        }
        <label class="${identityLocked ? "is-identity-locked" : ""}"><span>Display name</span><input name="displayName" value="${escapeHtml(candidate.displayName)}" autocomplete="name" required${identityReadOnlyAttr}${disabledAttr(saving)} /></label>
        <label class="${identityLocked ? "is-identity-locked" : ""}"><span>Office level</span><input name="levelOfOffice" value="${escapeHtml(candidate.levelOfOffice)}"${identityReadOnlyAttr}${disabledAttr(saving)} /></label>
        <label class="${identityLocked ? "is-identity-locked" : ""}"><span>District</span><input name="district" value="${escapeHtml(candidate.district)}"${identityReadOnlyAttr}${disabledAttr(saving)} /></label>
        <label><span>Avatar URL</span><input name="avatarUrl" value="${escapeHtml(avatarUrl)}" inputmode="url"${disabledAttr(saving)} /></label>
        ${renderCandidateEditorTagPicker(candidate, detail, saving)}
      </div>
    </section>
    <section class="shared-candidate-editor__section">
      <h2>Biography</h2>
      <label><span>Bio</span><textarea name="bio" rows="6"${disabledAttr(saving)}>${escapeHtml(candidate.bio)}</textarea></label>
    </section>
    <section class="shared-candidate-editor__section">
      <h2>Connect</h2>
      <div class="shared-candidate-editor__grid">
        <label><span>Phone</span><input name="phone" value="${escapeHtml(socials.phone || "")}" autocomplete="tel" inputmode="tel"${disabledAttr(saving)} /></label>
        <label><span>Email</span><input name="email" value="${escapeHtml(socials.email || "")}" autocomplete="email" inputmode="email"${disabledAttr(saving)} /></label>
        <label><span>Website</span><input name="website" value="${escapeHtml(socials.website || "")}" inputmode="url"${disabledAttr(saving)} /></label>
        <label><span>X</span><input name="x" value="${escapeHtml(socials.x || "")}"${disabledAttr(saving)} /></label>
        <label><span>Instagram</span><input name="instagram" value="${escapeHtml(socials.instagram || "")}"${disabledAttr(saving)} /></label>
        <label><span>Facebook</span><input name="facebook" value="${escapeHtml(socials.facebook || "")}"${disabledAttr(saving)} /></label>
        <label><span>Threads</span><input name="threads" value="${escapeHtml(socials.threads || "")}"${disabledAttr(saving)} /></label>
        <label><span>Bluesky</span><input name="bluesky" value="${escapeHtml(socials.bluesky || "")}"${disabledAttr(saving)} /></label>
        <label><span>TikTok</span><input name="tiktok" value="${escapeHtml(socials.tiktok || "")}"${disabledAttr(saving)} /></label>
      </div>
    </section>
    <div class="shared-candidate-editor__actions">
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(resolveCandidateOpenRoute(candidate))}"${disabledAttr(saving)}>Cancel</button>
      <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(saving || avatarBusy)}>${saving ? "Saving..." : "Save changes"}</button>
    </div>
  </form>`;
}

function candidateDonationFlowStepLabel(step = "") {
  const labels = {
    amount: "Amount",
    profile: "Profile",
    acknowledgements: "Attest",
    review: "Review",
    submitted: "Started",
  };
  return labels[normalizeString(step)] || "Step";
}

function renderCandidateDonationFlowStatus(flow) {
  const error = normalizeString(flow.error);
  const notice = normalizeString(flow.notice);
  return `${error ? `<div class="shared-donation-flow__status shared-donation-flow__status--error">${escapeHtml(error)}</div>` : ""}${notice ? `<div class="shared-donation-flow__status shared-donation-flow__status--notice">${escapeHtml(notice)}</div>` : ""}`;
}

function renderCandidateDonationFlowProgress(flow) {
  const currentStep = normalizeString(flow.step) || "amount";
  const currentIndex =
    currentStep === "submitted"
      ? CANDIDATE_DONATION_FLOW_STEPS.length - 1
      : Math.max(0, CANDIDATE_DONATION_FLOW_STEPS.indexOf(currentStep));
  return `<div class="shared-donation-flow__progress" aria-label="Donation steps">
    ${CANDIDATE_DONATION_FLOW_STEPS.map((step, index) => {
      const active = step === currentStep || (currentStep === "submitted" && step === "review");
      const reached = index <= currentIndex;
      return `<button class="shared-donation-flow__step${active ? " is-active" : ""}${reached ? " is-reached" : ""}" type="button" data-action="candidate-donation-step" data-step="${escapeHtml(step)}"${disabledAttr(!reached || flow.submitting || flow.loading)} aria-current="${active ? "step" : "false"}">
        <span>${escapeHtml(String(index + 1))}</span>
        <strong>${escapeHtml(candidateDonationFlowStepLabel(step))}</strong>
      </button>`;
    }).join("")}
  </div>`;
}

function renderCandidateDonationFlowField(
  flow,
  name,
  label,
  { autocomplete = "", inputmode = "", wide = false } = {},
) {
  const value =
    name === "amount"
      ? normalizeString(flow.amount)
      : normalizeString(flow.fields?.[name]);
  return `<label class="shared-donation-flow__field${wide ? " shared-donation-flow__field--wide" : ""}">
    <span>${escapeHtml(label)}</span>
    <input name="${escapeHtml(name)}" data-donation-flow-field="${escapeHtml(name)}" value="${escapeHtml(value)}"${autocomplete ? ` autocomplete="${escapeHtml(autocomplete)}"` : ""}${inputmode ? ` inputmode="${escapeHtml(inputmode)}"` : ""}${disabledAttr(flow.submitting)} />
  </label>`;
}

function renderCandidateDonationFlowStatusTile({
  icon = "shield",
  title = "",
  subtitle = "",
  statusLabel = "",
  complete = false,
  action = "",
  actionLabel = "",
  pending = false,
}) {
  return `<div class="shared-donation-flow__requirement${complete ? " is-complete" : ""}">
    <span class="shared-donation-flow__requirement-icon">${renderIcon(icon)}</span>
    <div>
      <strong>${escapeHtml(title)}</strong>
      <p>${escapeHtml(subtitle)}</p>
    </div>
    <span class="shared-donation-flow__requirement-status">${escapeHtml(statusLabel)}</span>
    ${
      action && actionLabel
        ? `<button class="shared-feed-chip${complete ? "" : " shared-feed-chip--primary"}" type="button" data-action="${escapeHtml(action)}"${disabledAttr(pending)}>${escapeHtml(pending ? "Opening..." : actionLabel)}</button>`
        : ""
    }
  </div>`;
}

function renderCandidateDonationFlowReviewLine(label, value, actionStep = "") {
  return `<div class="shared-donation-flow__review-line">
    <span>${escapeHtml(label)}</span>
    <strong>${escapeHtml(normalizeString(value) || "Not provided")}</strong>
    ${
      actionStep
        ? `<button class="shared-feed-chip" type="button" data-action="candidate-donation-step" data-step="${escapeHtml(actionStep)}">Edit</button>`
        : ""
    }
  </div>`;
}

function renderCandidateDonationAmountStep(flow) {
  const amountCents = candidateDonationFlowAmountCents(flow);
  const remaining = flow.eligibility?.remainingAllowedCents;
  const remainingLabel =
    remaining !== null && remaining !== undefined
      ? formatDonationAmount(remaining)
      : "the current legal limit";
  const presets = [25, 50, 100, 250].filter((amount) => {
    return remaining === null || remaining === undefined || amount * 100 <= remaining;
  });
  const quickAmounts =
    presets.length > 0
      ? presets
      : remaining && remaining > 0
        ? [Math.max(1, Math.floor(remaining / 100))]
        : [25, 50, 100];
  return `<form class="shared-donation-flow__body" data-route-form="candidate-donation-amount">
    <section class="shared-donation-flow__card shared-donation-flow__amount-card">
      <p class="shared-donation-flow__eyebrow">Step 1</p>
      <h3>Choose how much to give</h3>
      <p>This is a one-time contribution. You can still give ${escapeHtml(remainingLabel)} this cycle.</p>
      <label class="shared-donation-flow__amount-field">
        <span>Donation amount</span>
        <div>
          <em>$</em>
          <input name="amount" data-donation-flow-field="amount" value="${escapeHtml(flow.amount)}" inputmode="decimal" placeholder="25.00"${disabledAttr(flow.submitting)} />
        </div>
      </label>
      ${
        amountCents
          ? `<div class="shared-donation-flow__pill">${renderIcon("heart")} You are giving ${escapeHtml(formatDonationAmount(amountCents))}</div>`
          : ""
      }
    </section>
    <section class="shared-donation-flow__card">
      <div class="shared-donation-flow__section-head">
        <div>
          <h3>Quick amounts</h3>
          <p>Pick once to fill the amount instantly.</p>
        </div>
      </div>
      <div class="shared-donation-flow__amount-presets">
        ${quickAmounts.map((amount) => {
          const selected = amountCents === amount * 100;
          return `<button class="shared-donation-flow__preset${selected ? " is-selected" : ""}" type="button" data-action="candidate-donation-amount-preset" data-amount="${escapeHtml(String(amount))}"${disabledAttr(flow.submitting)}>${escapeHtml(formatDonationAmount(amount * 100))}</button>`;
        }).join("")}
      </div>
    </section>
    <div class="shared-donation-flow__actions">
      <button class="shared-feed-chip" type="button" data-action="candidate-donation-close">Cancel</button>
      <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(flow.loading || flow.submitting)}>${flow.loading ? "Checking..." : "Continue"}</button>
    </div>
  </form>`;
}

function renderCandidateDonationProfileStep(flow) {
  const identityLocked = candidateDonationFlowIdentityLocked(flow);
  const needsIdentity = candidateDonationFlowNeedsIdentity(flow);
  const needsBankLink = candidateDonationFlowNeedsBankLink(flow);
  const pendingIdentity = flow.actionPendingKey === "identity";
  const pendingBank = flow.actionPendingKey === "bank";
  return `<form class="shared-donation-flow__body" data-route-form="candidate-donation-profile">
    <section class="shared-donation-flow__card">
      <p class="shared-donation-flow__eyebrow">Step 2</p>
      <h3>Required verification</h3>
      <p>Stripe uses these checks to confirm donor identity and eligibility before payment.</p>
      <div class="shared-donation-flow__requirements">
        ${renderCandidateDonationFlowStatusTile({
          icon: "shield",
          title: "Identity verification",
          subtitle: identityLocked
            ? "Verified and locked to your Stripe Identity result."
            : "Complete this once so name and home address can be verified.",
          statusLabel: identityLocked ? "Verified" : "Needed",
          complete: identityLocked,
          action: needsIdentity ? "candidate-donation-identity" : "",
          actionLabel: needsIdentity ? "Verify ID" : "",
          pending: pendingIdentity || flow.submitting,
        })}
        ${renderCandidateDonationFlowStatusTile({
          icon: "payments",
          title: "Bank link",
          subtitle: needsBankLink
            ? "Link a U.S. bank account to satisfy the current compliance flow."
            : "Linked and ready to use for donation checks.",
          statusLabel: needsBankLink ? "Needed" : "Linked",
          complete: !needsBankLink,
          action: needsBankLink ? "candidate-donation-bank-link" : "",
          actionLabel: needsBankLink ? "Link bank" : "",
          pending: pendingBank || flow.submitting,
        })}
      </div>
      <button class="shared-feed-chip" type="button" data-action="candidate-donation-refresh"${disabledAttr(flow.loading || flow.submitting)}>Refresh checks</button>
    </section>
    ${
      identityLocked
        ? `<section class="shared-donation-flow__card">
            <h3>Verified identity</h3>
            <p>Name and residential address now come from the verified identity result.</p>
            <div class="shared-donation-flow__review-grid">
              ${renderCandidateDonationFlowReviewLine("Full legal name", flow.fields.fullLegalName)}
              ${renderCandidateDonationFlowReviewLine("Residential address", candidateDonationFlowAddressSummary(flow))}
            </div>
          </section>`
        : `<section class="shared-donation-flow__card">
            <h3>About the donor</h3>
            <p>Use your residential address, not a P.O. Box.</p>
            <div class="shared-donation-flow__field-grid">
              ${renderCandidateDonationFlowField(flow, "fullLegalName", "Full legal name", { autocomplete: "name", wide: true })}
              ${renderCandidateDonationFlowField(flow, "addressLine1", "Residential address line 1", { autocomplete: "address-line1", wide: true })}
              ${renderCandidateDonationFlowField(flow, "addressLine2", "Address line 2 (optional)", { autocomplete: "address-line2", wide: true })}
              ${renderCandidateDonationFlowField(flow, "city", "City", { autocomplete: "address-level2" })}
              ${renderCandidateDonationFlowField(flow, "state", "State", { autocomplete: "address-level1" })}
              ${renderCandidateDonationFlowField(flow, "postalCode", "ZIP", { autocomplete: "postal-code", inputmode: "numeric" })}
            </div>
          </section>`
    }
    <section class="shared-donation-flow__card">
      <h3>Employment details</h3>
      <p>Campaign-finance rules require occupation and employer for this contribution.</p>
      <div class="shared-donation-flow__field-grid">
        ${renderCandidateDonationFlowField(flow, "occupation", "Occupation", { autocomplete: "organization-title" })}
        ${renderCandidateDonationFlowField(flow, "employer", "Employer", { autocomplete: "organization" })}
        ${renderCandidateDonationFlowField(flow, "jobTitle", "Job title (optional)")}
      </div>
    </section>
    <div class="shared-donation-flow__actions">
      <button class="shared-feed-chip" type="button" data-action="candidate-donation-step" data-step="amount"${disabledAttr(flow.submitting)}>Back</button>
      <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(flow.submitting)}>Continue</button>
    </div>
  </form>`;
}

function renderCandidateDonationAcknowledgementsStep(flow) {
  const missingSteps = (flow.eligibility?.missingSteps || []).filter(Boolean);
  const requirements = [
    ["usCitizenOrLpr", "I am a U.S. citizen or lawful permanent resident."],
    ["ownFunds", "This contribution is made from my own funds."],
    [
      "campaignAttribution",
      "My campaign attribution statements are true and complete.",
    ],
  ];
  return `<form class="shared-donation-flow__body" data-route-form="candidate-donation-acknowledgements">
    <section class="shared-donation-flow__card">
      <p class="shared-donation-flow__eyebrow">Step 3</p>
      <h3>Required legal attestations</h3>
      <p>These confirmations are required before you can continue to payment.</p>
      <div class="shared-donation-flow__certifications">
        ${requirements.map(([name, label]) => `<label class="shared-donation-flow__certification${flow.certifications?.[name] ? " is-checked" : ""}">
          <input type="checkbox" name="${escapeHtml(name)}" data-donation-flow-certification="${escapeHtml(name)}"${checkedAttr(flow.certifications?.[name])}${disabledAttr(flow.submitting)} />
          <span>${escapeHtml(label)}</span>
        </label>`).join("")}
      </div>
    </section>
    ${
      missingSteps.length || normalizeString(flow.unavailableReason)
        ? `<section class="shared-donation-flow__card shared-donation-flow__card--warning">
            <h3>Still required before review</h3>
            <p>The items below must be cleared before Stripe payment can start.</p>
            <div class="shared-donation-flow__missing">
              ${
                normalizeString(flow.unavailableReason)
                  ? `<span>${renderIcon("lock")} ${escapeHtml(flow.unavailableReason)}</span>`
                  : ""
              }
              ${missingSteps.map((step) => `<span>${renderIcon("check")} ${escapeHtml(candidateDonationReadableStep(step))}</span>`).join("")}
            </div>
            <div class="shared-card__actions">
              <button class="shared-feed-chip" type="button" data-action="candidate-donation-refresh"${disabledAttr(flow.loading || flow.submitting)}>Refresh</button>
              ${
                candidateDonationFlowNeedsIdentity(flow)
                  ? `<button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-donation-identity"${disabledAttr(flow.submitting || flow.actionPendingKey === "identity")}>Verify ID</button>`
                  : ""
              }
              ${
                candidateDonationFlowNeedsBankLink(flow)
                  ? `<button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-donation-bank-link"${disabledAttr(flow.submitting || flow.actionPendingKey === "bank")}>Link bank</button>`
                  : ""
              }
            </div>
          </section>`
        : ""
    }
    <div class="shared-donation-flow__actions">
      <button class="shared-feed-chip" type="button" data-action="candidate-donation-step" data-step="profile"${disabledAttr(flow.submitting)}>Back</button>
      <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(flow.submitting)}>${flow.submitting ? "Checking..." : "Continue to review"}</button>
    </div>
  </form>`;
}

function renderCandidateDonationReviewStep(flow) {
  const amountCents = candidateDonationFlowAmountCents(flow) || 0;
  return `<form class="shared-donation-flow__body" data-route-form="candidate-donation-review">
    <section class="shared-donation-flow__card">
      <p class="shared-donation-flow__eyebrow">Step 4</p>
      <h3>Review your donation</h3>
      <p>Confirm the summary, then move into secure hosted Stripe payment.</p>
      <div class="shared-donation-flow__review-grid">
        ${renderCandidateDonationFlowReviewLine("Candidate", flow.candidateName)}
        ${renderCandidateDonationFlowReviewLine("Amount", formatDonationAmount(amountCents), "amount")}
        ${renderCandidateDonationFlowReviewLine("Donor", flow.fields.fullLegalName, "profile")}
        ${renderCandidateDonationFlowReviewLine("Address", candidateDonationFlowAddressSummary(flow), "profile")}
        ${renderCandidateDonationFlowReviewLine("Occupation", flow.fields.occupation, "profile")}
        ${renderCandidateDonationFlowReviewLine("Employer", flow.fields.employer, "profile")}
      </div>
    </section>
    <section class="shared-donation-flow__card">
      <h3>Payment handoff</h3>
      <p>You will be sent to hosted Stripe Checkout to finish the payment.</p>
      <div class="shared-donation-flow__missing">
        <span>${renderIcon("shield")} ${candidateDonationFlowNeedsIdentity(flow) ? "Identity check still needs to complete." : "Identity check is complete."}</span>
        <span>${renderIcon("payments")} ${candidateDonationFlowNeedsBankLink(flow) ? "Bank link still needs to complete." : "Bank link is complete."}</span>
      </div>
    </section>
    <div class="shared-donation-flow__actions">
      <button class="shared-feed-chip" type="button" data-action="candidate-donation-step" data-step="acknowledgements"${disabledAttr(flow.submitting)}>Back</button>
      <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(flow.submitting)}>${flow.submitting ? "Opening..." : "Open Stripe Checkout"}</button>
    </div>
  </form>`;
}

function renderCandidateDonationSubmittedStep(flow) {
  const checkoutUrl = normalizeUrl(flow.checkoutSession?.checkoutUrl);
  return `<section class="shared-donation-flow__body shared-donation-flow__submitted">
    <div class="shared-donation-flow__submitted-icon">${renderIcon("check")}</div>
    <h3>Donation flow started</h3>
    <p>${escapeHtml(flow.submittedMessage || "Your donation flow has been started successfully.")}</p>
    <div class="shared-donation-flow__actions">
      ${
        checkoutUrl
          ? `<a class="shared-feed-chip shared-feed-chip--primary" href="${escapeHtml(checkoutUrl)}" target="_blank" rel="noopener noreferrer">Open Stripe Checkout</a>`
          : ""
      }
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-donation-close">Close</button>
    </div>
  </section>`;
}

function renderCandidateDonationFlowBody(flow) {
  if (flow.loading && !flow.eligibility) {
    return `<div class="shared-donation-flow__body"><div class="shared-page__loading">Loading donation checks...</div></div>`;
  }
  if (flow.step === "profile") {
    return renderCandidateDonationProfileStep(flow);
  }
  if (flow.step === "acknowledgements") {
    return renderCandidateDonationAcknowledgementsStep(flow);
  }
  if (flow.step === "review") {
    return renderCandidateDonationReviewStep(flow);
  }
  if (flow.step === "submitted") {
    return renderCandidateDonationSubmittedStep(flow);
  }
  return renderCandidateDonationAmountStep(flow);
}

function renderCandidateDonationFlowModal() {
  const flow = state.pages.candidates.detail.donationFlow;
  if (!flow?.open) {
    return "";
  }
  return `<div class="shared-donation-flow is-open">
    <button class="shared-donation-flow__backdrop" type="button" data-action="candidate-donation-close" aria-label="Close donation flow"></button>
    <section class="shared-donation-flow__dialog" role="dialog" aria-modal="true" aria-labelledby="candidate-donation-flow-title">
      <header class="shared-donation-flow__header">
        <div>
          <p class="shared-donation-flow__eyebrow">Secure donation</p>
          <h2 id="candidate-donation-flow-title">Donate to ${escapeHtml(flow.candidateName)}</h2>
          <p>Complete the same compliance checks and Stripe handoff used in the Polis app.</p>
        </div>
        <button class="shared-comments__close" type="button" data-action="candidate-donation-close" aria-label="Close donation flow">${renderIcon("close")}</button>
      </header>
      ${renderCandidateDonationFlowProgress(flow)}
      ${renderCandidateDonationFlowStatus(flow)}
      ${renderCandidateDonationFlowBody(flow)}
    </section>
  </div>`;
}

function renderCandidateDetailPage() {
  const detail = state.pages.candidates.detail;
  const candidate = detail.item;
  const isEditRoute = getCurrentRoute().routeKey === ROUTE_KEY_CANDIDATE_EDIT;
  const isSettingsEditRoute = isCandidateSettingsEditRoute();
  if (detail.loading && !candidate) {
    return `<section class="shared-page">${renderTopChrome()}<div class="shared-page__content"><div class="shared-page__loading">Loading candidate...</div></div></section>`;
  }
  if (!candidate) {
    return `<section class="shared-page">${renderTopChrome()}<div class="shared-page__content"><div class="shared-page__error">${escapeHtml(detail.error || "Candidate unavailable.")}</div></div></section>`;
  }
  const socials = candidate.socials || {};
  const officialId = resolveCandidateOfficialId(candidate);
  const canDonate = candidateCanReceiveDonations(candidate);
  const levelLabel = autoCandidateLevelLabel(candidate.levelOfOffice);
  const districtLabel = candidateDisplayDistrictLabel(candidate);
  return `<section class="shared-page shared-candidate-page${isEditRoute ? " shared-candidate-page--editing" : ""}">
    ${renderTopChrome()}
    <div class="shared-page__content">
      <div class="shared-page__back-row">
        <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${isSettingsEditRoute ? "/settings" : "/candidates"}">${isSettingsEditRoute ? "Back to settings" : "Back to candidates"}</button>
      </div>
      <div class="shared-page__header shared-page__header--hero">
        <div class="shared-page__hero">
          ${
            candidate.avatarUrl
              ? `<img class="shared-page__hero-avatar" src="${escapeHtml(candidate.avatarUrl)}" alt="${escapeHtml(candidate.displayName)}" />`
              : `<div class="shared-page__hero-avatar shared-page__hero-avatar--placeholder">${escapeHtml(candidate.displayName.slice(0, 1).toUpperCase() || "C")}</div>`
          }
          <div>
            <p class="shared-page__eyebrow">${escapeHtml(levelLabel || "Candidate")}</p>
            <h1>${escapeHtml(candidate.displayName)}</h1>
            <p>${escapeHtml(candidate.bio || "Candidate page")}</p>
            <div class="shared-card__meta">
              ${districtLabel ? `<span>${escapeHtml(districtLabel)}</span>` : ""}
              <span>${escapeHtml(formatCount(candidate.followersCount))} followers</span>
              ${
                candidate.tags.length
                  ? `<span>${escapeHtml(candidate.tags.join(", "))}</span>`
                  : ""
              }
            </div>
          </div>
        </div>
        <div class="shared-card__actions">
          <button class="shared-feed-chip shared-feed-chip--primary" data-action="candidate-follow" data-candidate-id="${escapeHtml(candidate.candidateId)}" data-official-id="${escapeHtml(officialId)}">${candidate.isFollowing ? "Following" : "Follow"}</button>
          ${
            candidate.activeElection?.path
              ? `<button class="shared-feed-chip" data-action="navigate" data-route="${escapeHtml(candidate.activeElection.path)}">${renderIcon("election")} Results</button>`
              : ""
          }
          ${
            candidate.canEdit
              ? `<button class="shared-feed-chip" data-action="navigate" data-route="${escapeHtml(resolveCandidateEditRoute(candidate))}">${isEditRoute ? "Editing" : "Edit page"}</button>`
              : ""
          }
          ${
            canDonate
              ? `<button class="shared-feed-chip shared-feed-chip--primary" data-action="candidate-donation-open" data-candidate-id="${escapeHtml(candidate.candidateId)}">Donate</button>`
              : normalizeString(candidate.donationDisabledReason)
                ? `<button class="shared-feed-chip" type="button" disabled>${escapeHtml(candidate.donationDisabledReason)}</button>`
                : ""
          }
          ${
            normalizeString(socials.website)
              ? `<a class="shared-feed-chip" href="${escapeHtml(socials.website)}" target="_blank" rel="noopener noreferrer">Website</a>`
              : ""
          }
          ${
            officialId
              ? `<button class="shared-feed-chip" data-action="navigate" data-route="${escapeHtml(buildOfficialReportCardRoute(officialId, { returnTo: getCurrentPathWithQuery() }))}">Official Report Card</button>`
              : ""
          }
          <button class="shared-feed-chip" data-action="navigate" data-route="/events?q=${encodeURIComponent(candidate.displayName)}">Related events</button>
        </div>
      </div>
      ${
        isEditRoute
          ? renderCandidateEditForm(candidate, detail, socials)
          : ""
      }
      ${detail.error ? `<div class="shared-page__error">${escapeHtml(detail.error)}</div>` : ""}
      <div class="shared-page__split">
        <div>
          <h2>Posts</h2>
          ${renderMediaThumbnailGrid(detail.posts, {
            emptyMessage: "No posts yet.",
            getRoute: (item) =>
              item.postId ? `/posts/${encodeURIComponent(item.postId)}` : "",
            getMediaUrl: (item) => item.posterUrl || item.imageUrl,
            getAltText: (item) =>
              item.previewTitle ||
              item.caption ||
              item.authorDisplayName ||
              "Post",
            getOverlayText: (item) =>
              `${formatCount(item.likesCount)} like${Number(item.likesCount) === 1 ? "" : "s"}`,
            getPlaceholderLabel: () => "P",
            overlayBare: true,
          })}
        </div>
        <div>
          <h2>Upcoming events</h2>
          ${renderMediaThumbnailGrid(detail.relatedEvents, {
            emptyMessage: "No upcoming events yet.",
            getRoute: (item) =>
              item.eventId ? `/events/${encodeURIComponent(item.eventId)}` : "",
            getMediaUrl: (item) => item.imageUrl,
            getAltText: (item) => item.title || "Event",
            getOverlayText: (item) =>
              `${formatCount(item.attendeeCount)} going`,
            getPlaceholderLabel: () => "E",
          })}
        </div>
      </div>
    </div>
  </section>`;
}

function renderCandidateDashboardAuthGate() {
  const featureSections = candidateDashboardFeatureSections();
  const featureItems = featureSections.map((section) => ({
    key: section.key,
    label: section.label,
    icon: section.icon,
    copy: candidateDashboardFeatureCopy(section),
  }));
  const voterMapPreview = {
    key: "voter-map",
    label: "Voter Map",
    icon: "map",
    copy: {
      eyebrow: "Map tools",
      description:
        "Open mapping, territories, connected voter records, imports, outreach scripts, and field notes.",
    },
  };
  const questIndex = featureItems.findIndex((item) => item.key === "campaign-quest");
  featureItems.splice(questIndex >= 0 ? questIndex : featureItems.length, 0, voterMapPreview);
  const featureByKey = new Map(featureItems.map((item) => [item.key, item]));
  const moduleGroups = [
    {
      label: "Campaign operations",
      icon: "mission",
      copy: "Daily work, event planning, schedules, and approvals.",
      keys: ["overview", "missions", "calendar", "events"],
    },
    {
      label: "People and conversations",
      icon: "messages",
      copy: "Staff access, engagement triage, rooms, and volunteer coordination.",
      keys: ["messaging", "staff", "engagement"],
    },
    {
      label: "Voter field work",
      icon: "map",
      copy: "Registry, turf, field routes, outreach scripts, and prompt controls.",
      keys: ["voter-map", "voter-registry", "campaign-quest", "voter-contact-prompt"],
    },
    {
      label: "Publishing and finance",
      icon: "chart",
      copy: "Performance reporting, petitions, donations, and compliance exports.",
      keys: ["analytics", "petitions", "donations"],
    },
  ].map((group) => ({
    ...group,
    items: group.keys.map((key) => featureByKey.get(key)).filter(Boolean),
  })).filter((group) => group.items.length);
  const commandStats = [
    {
      icon: "calendar",
      label: "Calendar",
      value: "Events + bookings",
      detail: "Office hours, shifts, travel, and public promotion.",
    },
    {
      icon: "messages",
      label: "Messaging",
      value: "Rooms + requests",
      detail: "Campaign rooms, direct requests, and safety review.",
    },
    {
      icon: "mission",
      label: "Missions",
      value: "Claimable work",
      detail: "Assignments, approvals, files, and deadlines.",
    },
  ];
  const commandQueue = [
    ["Today", "Review town hall RSVPs", "Calendar"],
    ["Inbox", "Volunteer route reply", "Messaging"],
    ["Staff", "Confirm field organizer access", "Permissions"],
    ["Missions", "Approve canvass brief", "Due soon"],
  ];
  const moduleMap = moduleGroups
    .map(
      (group) => `<article class="shared-campaign-auth__module" role="listitem">
        <div class="shared-campaign-auth__module-top">
          <span aria-hidden="true">${renderIcon(group.icon)}</span>
          <div>
            <strong>${escapeHtml(group.label)}</strong>
            <small>${escapeHtml(group.copy)}</small>
          </div>
        </div>
        <div class="shared-campaign-auth__module-items">
          ${group.items
            .map(
              (item) => `<span>${renderIcon(item.icon)}${escapeHtml(item.label)}</span>`,
            )
            .join("")}
        </div>
      </article>`,
    )
    .join("");
  return `<section class="shared-page shared-campaign-dashboard">
    ${renderTopChrome()}
    <div class="shared-page__content">
      <section class="shared-campaign-auth shared-campaign-auth--dashboard">
        <div class="shared-campaign-auth__copy">
          <span class="shared-card__meta"><span>Candidate dashboard</span><span>${escapeHtml(formatCount(featureItems.length))} feature areas</span></span>
          <h1>Open every campaign workspace from the web.</h1>
          <p>Sign in to reach the same Polis campaign tools the app uses for operations, staff, voter field work, messaging, donations, petitions, and reporting. Polis will route you to the campaign picker or the exact candidate workspace your role can open.</p>
          <div class="shared-card__actions">
            <button class="shared-feed-chip shared-feed-chip--primary" data-action="auth-login-inline">Sign in</button>
            <button class="shared-feed-chip" data-action="auth-signup-inline">Create account</button>
            <button class="shared-feed-chip" data-action="open-app-shell">Open app</button>
          </div>
        </div>
        <div class="shared-campaign-auth__workspace">
          <aside class="shared-campaign-dashboard-preview" aria-label="Candidate dashboard workspace preview">
            <header>
              <span>${renderIcon("candidate")}</span>
              <div>
                <small>Campaign command center</small>
                <strong>Today in Polis</strong>
              </div>
            </header>
            <div class="shared-campaign-dashboard-preview__metrics" role="list" aria-label="Candidate dashboard priority surfaces">
              ${commandStats
                .map(
                  (item) => `<article role="listitem">
                    <span>${renderIcon(item.icon)}</span>
                    <div>
                      <small>${escapeHtml(item.label)}</small>
                      <strong>${escapeHtml(item.value)}</strong>
                      <p>${escapeHtml(item.detail)}</p>
                    </div>
                  </article>`,
                )
                .join("")}
            </div>
            <div class="shared-campaign-dashboard-preview__queue" aria-label="Campaign work queue">
              ${commandQueue
                .map(
                  ([scope, title, status]) => `<article>
                    <span>${escapeHtml(scope)}</span>
                    <strong>${escapeHtml(title)}</strong>
                    <em>${escapeHtml(status)}</em>
                  </article>`,
                )
                .join("")}
            </div>
            <footer>
              <span>${renderIcon("team")} Owner and staff routes stay permission-aware.</span>
            </footer>
          </aside>
          <div class="shared-campaign-auth__module-map" role="list" aria-label="Candidate dashboard workspace groups">
            ${moduleMap}
          </div>
        </div>
      </section>
    </div>
  </section>`;
}

function renderCandidateVoterMapAuthGate() {
  const mapStats = [
    {
      icon: "map",
      label: "District build",
      value: "Units + territories",
      detail: "Generate geography, rebalance turf, and keep assignments current.",
    },
    {
      icon: "registry",
      label: "Voter registry",
      value: "Imports + records",
      detail: "Add voters, review CSV imports, and preserve contact preferences.",
    },
    {
      icon: "phone",
      label: "Outreach",
      value: "Scripts + notes",
      detail: "Respect opt-outs while staff log calls, texts, visits, and follow-ups.",
    },
  ];
  const mapQueue = [
    ["Build", "Generate precinct and district unit sets", "Admin"],
    ["Turf", "Review territories, splits, merges, and assignment drift", "Map"],
    ["Records", "Import voter rows and resolve duplicate contact data", "Registry"],
    ["Quest", "Send high-priority targets into CampaignQuest", "Field"],
  ];
  const featureTiles = [
    {
      icon: "map",
      eyebrow: "Map",
      label: "District and precinct geography",
      description: "View voter segments, boundaries, support levels, and campaign coverage from the browser.",
    },
    {
      icon: "team",
      eyebrow: "Territories",
      label: "Turf assignment",
      description: "Split, merge, publish, and rebalance staff territories without losing ownership context.",
    },
    {
      icon: "upload",
      eyebrow: "Registry",
      label: "Voter imports",
      description: "Preview uploads, detect invalid rows, and connect records to contact preferences.",
    },
    {
      icon: "phone",
      eyebrow: "Outreach",
      label: "Scripts and outcomes",
      description: "Give staff the right call, text, or canvass script and record what happened next.",
    },
    {
      icon: "file",
      eyebrow: "Notes",
      label: "Field notes",
      description: "Attach local context to voter records while keeping permission-aware audit trails.",
    },
    {
      icon: "mission",
      eyebrow: "Quest",
      label: "CampaignQuest handoff",
      description: "Move priority voters into route-style field work, XP, sign drops, and completion queues.",
    },
  ];
  return `<section class="shared-page shared-campaign-dashboard">
    ${renderTopChrome()}
    <div class="shared-page__content">
      <section class="shared-campaign-auth shared-campaign-auth--dashboard shared-campaign-auth--voter-map">
        <div class="shared-campaign-auth__copy">
          <span class="shared-card__meta"><span>Candidate voter map</span><span>Field operations</span></span>
          <h1>Open the campaign voter map.</h1>
          <p>Sign in with campaign access to review district geography, voter segments, precinct context, outreach scripts, voter imports, territories, contact preferences, and CampaignQuest field handoffs from the Polis web app.</p>
          <div class="shared-card__actions">
            <button class="shared-feed-chip shared-feed-chip--primary" data-action="auth-login-inline">Sign in</button>
            <button class="shared-feed-chip" data-action="auth-signup-inline">Create account</button>
            <button class="shared-feed-chip" data-action="open-app-shell">Open app</button>
          </div>
        </div>
        <div class="shared-campaign-auth__workspace">
          <aside class="shared-campaign-dashboard-preview shared-voter-map-preview" aria-label="Candidate voter map workspace preview">
            <header>
              <span aria-hidden="true">${renderIcon("map")}</span>
              <div>
                <small>Voter map command center</small>
                <strong>District field view</strong>
              </div>
            </header>
            <div class="shared-voter-map-preview__canvas" aria-hidden="true">
              <span class="shared-voter-map-preview__district is-primary"></span>
              <span class="shared-voter-map-preview__district is-secondary"></span>
              <span class="shared-voter-map-preview__district is-tertiary"></span>
              <span class="shared-voter-map-preview__district is-route"></span>
              <span class="shared-voter-map-preview__pin is-one"></span>
              <span class="shared-voter-map-preview__pin is-two"></span>
              <span class="shared-voter-map-preview__pin is-three"></span>
              <span class="shared-voter-map-preview__legend">4 turf lanes ready</span>
            </div>
            <div class="shared-campaign-dashboard-preview__metrics" role="list" aria-label="Candidate voter map priority surfaces">
              ${mapStats
                .map(
                  (item) => `<article role="listitem">
                    <span aria-hidden="true">${renderIcon(item.icon)}</span>
                    <div>
                      <small>${escapeHtml(item.label)}</small>
                      <strong>${escapeHtml(item.value)}</strong>
                      <p>${escapeHtml(item.detail)}</p>
                    </div>
                  </article>`,
                )
                .join("")}
            </div>
            <div class="shared-campaign-dashboard-preview__queue" aria-label="Candidate voter map work queue">
              ${mapQueue
                .map(
                  ([scope, title, status]) => `<article>
                    <span>${escapeHtml(scope)}</span>
                    <strong>${escapeHtml(title)}</strong>
                    <em>${escapeHtml(status)}</em>
                  </article>`,
                )
                .join("")}
            </div>
            <footer>
              <span>${renderIcon("shield")} Contact work stays permission-aware and opt-out aware.</span>
            </footer>
          </aside>
          <div class="shared-campaign-auth__grid shared-campaign-auth__grid--dashboard" role="list" aria-label="Candidate voter map feature areas">
            ${featureTiles
              .map(
                (item) => `<article class="shared-campaign-auth__tile shared-campaign-auth__tile--feature" role="listitem">
                  <span class="shared-campaign-auth__tile-icon" aria-hidden="true">${renderIcon(item.icon)}</span>
                  <span class="shared-campaign-auth__tile-copy">
                    <span class="shared-card__meta"><span>${escapeHtml(item.eyebrow)}</span></span>
                    <strong>${escapeHtml(item.label)}</strong>
                    <small>${escapeHtml(item.description)}</small>
                  </span>
                </article>`,
              )
              .join("")}
          </div>
        </div>
      </section>
    </div>
  </section>`;
}

function candidateDashboardFeatureRank(section) {
  const index = CANDIDATE_DASHBOARD_FEATURE_ORDER.indexOf(section?.key);
  return index >= 0 ? index : CANDIDATE_DASHBOARD_FEATURE_ORDER.length;
}

function candidateDashboardRootFeatureRank(feature) {
  const index = CANDIDATE_DASHBOARD_ROOT_FEATURE_ORDER.indexOf(feature?.key);
  return index >= 0 ? index : CANDIDATE_DASHBOARD_ROOT_FEATURE_ORDER.length;
}

function candidateDashboardFeatureSections({ includeOverview = false } = {}) {
  return CANDIDATE_DASHBOARD_SECTION_CONFIG.filter(
    (section) => includeOverview || section.key !== CANDIDATE_DASHBOARD_DEFAULT_SECTION,
  ).sort((left, right) => candidateDashboardFeatureRank(left) - candidateDashboardFeatureRank(right));
}

function candidateDashboardRootFeatureDescriptor(key) {
  if (key === CANDIDATE_DASHBOARD_VOTER_MAP_FEATURE.key) {
    return CANDIDATE_DASHBOARD_VOTER_MAP_FEATURE;
  }
  return candidateDashboardSectionConfig(key);
}

function candidateDashboardRootFeatureSections() {
  const features = [
    ...candidateDashboardFeatureSections(),
    CANDIDATE_DASHBOARD_VOTER_MAP_FEATURE,
  ];
  return features.sort(
    (left, right) =>
      candidateDashboardRootFeatureRank(left) -
      candidateDashboardRootFeatureRank(right),
  );
}

function candidateDashboardFeatureCopy(section) {
  return (
    CANDIDATE_DASHBOARD_FEATURE_COPY[section?.key] || {
      eyebrow: "Campaign",
      description: `${section?.label || "Campaign feature"} is available from this dashboard when your access includes it.`,
      cta: `Open ${section?.label || "section"}`,
    }
  );
}

function candidateDashboardFeatureStatus(section, access) {
  const enabled = canOpenCandidateDashboardSection(section, access);
  if (enabled) {
    return {
      label: access?.isOwner ? "Owner access" : "Included in your role",
      cta: candidateDashboardFeatureCopy(section).cta,
    };
  }
  if (section?.ownerOnly) {
    return {
      label: "Owner only",
      cta: "Owner access required",
    };
  }
  return {
    label: "Permission required",
    cta: "Ask owner for access",
  };
}

function canOpenCandidateDashboardRootFeature(feature, access) {
  if (feature?.key === CANDIDATE_DASHBOARD_VOTER_MAP_FEATURE.key) {
    return hasCandidateVoterMapAccess(access);
  }
  return canOpenCandidateDashboardSection(feature, access);
}

function candidateDashboardRootFeatureRoute(feature, candidateId) {
  if (feature?.key === CANDIDATE_DASHBOARD_VOTER_MAP_FEATURE.key) {
    return candidateVoterMapPath("", candidateId);
  }
  return candidateDashboardSectionPath(candidateId, feature?.key);
}

function candidateDashboardCommandItems(candidateId, access, candidate = null) {
  const sectionByKey = new Map(
    CANDIDATE_DASHBOARD_SECTION_CONFIG.map((section) => [section.key, section]),
  );
  const makeSectionItem = (key, label, copy, tone = "") => {
    const section = sectionByKey.get(key);
    if (!canOpenCandidateDashboardSection(section, access)) {
      return null;
    }
    return {
      key,
      label,
      copy,
      icon: section.icon,
      route: candidateDashboardSectionPath(candidateId, key),
      tone,
    };
  };
  const items = [
    makeSectionItem(
      "missions",
      "Missions",
      "Assign, claim, approve, and track campaign work.",
      "primary",
    ),
    makeSectionItem(
      "messaging",
      "Messaging",
      "Manage campaign conversations and volunteer room access.",
      "primary",
    ),
    makeSectionItem(
      "engagement",
      "Engagement queue",
      "Triage comments, likes, replies, and posts.",
      "primary",
    ),
    makeSectionItem(
      "calendar",
      "Calendar",
      "Availability, bookings, shifts, travel, and promotion.",
    ),
    makeSectionItem(
      "voter-contact-prompt",
      "Contact prompt",
      "Tune voter-facing outreach choices.",
    ),
    makeSectionItem(
      "voter-registry",
      "Voter registry",
      "Search, add, import, and manage voter records.",
    ),
    canOpenCandidateVoterMap(access, candidate)
      ? {
          key: "voter-map",
          label: "Voter Map",
          copy: "Open mapping, territories, connected voters, scripts, and field notes.",
          icon: "map",
          route: candidateVoterMapPath("", candidateId),
        }
      : null,
    makeSectionItem(
      "campaign-quest",
      "Campaign Quest",
      "Open field map, territories, XP, and sign-drop work.",
    ),
    makeSectionItem(
      "staff",
      "Campaign staff",
      "Invite staff and tune dashboard feature access.",
    ),
    makeSectionItem(
      "donations",
      "Donations",
      "Review setup, transactions, exports, and payout state.",
    ),
    makeSectionItem(
      "analytics",
      "Analytics",
      "Reach, engagement, trends, and event conversion.",
    ),
  ].filter(Boolean);
  if (canManageCandidateMessaging(access)) {
    items.splice(2, 0, {
      key: "room-workspace",
      label: "Room workspace",
      copy: "Open the full Polis messaging workspace for this campaign.",
      icon: "messages",
      route: candidateMessagingServerPath(candidateId),
    });
  }
  return items;
}

function renderCandidateDashboardCommandStrip(candidateId, access, candidate = null) {
  const items = candidateDashboardCommandItems(candidateId, access, candidate);
  if (!items.length) {
    return "";
  }
  return `<section class="shared-campaign-command-strip" aria-label="Campaign work areas">
    ${items
      .map(
        (item) => `<button class="shared-campaign-command${item.tone ? ` shared-campaign-command--${escapeHtml(item.tone)}` : ""}" type="button" data-action="navigate" data-route="${escapeHtml(item.route)}">
          <span>${renderIcon(item.icon)}</span>
          <strong>${escapeHtml(item.label)}</strong>
          <small>${escapeHtml(item.copy)}</small>
        </button>`,
      )
      .join("")}
  </section>`;
}

function candidateDashboardFeatureHighlights(access, limit = 5) {
  const sections = candidateDashboardRootFeatureSections().filter((section) =>
    canOpenCandidateDashboardRootFeature(section, access),
  );
  const visible = sections.slice(0, limit);
  return {
    visible,
    remaining: Math.max(0, sections.length - visible.length),
    total: sections.length,
  };
}

function renderCandidateDashboardFeaturePill(section, candidateId) {
  return `<button class="shared-campaign-feature-pill" type="button" data-action="navigate" data-route="${escapeHtml(candidateDashboardRootFeatureRoute(section, candidateId))}">
    <span>${renderIcon(section.icon)}</span>
    <strong>${escapeHtml(section.label)}</strong>
  </button>`;
}

function renderCandidateDashboardFeatureCard(section, candidateId, access) {
  const copy = candidateDashboardFeatureCopy(section);
  const enabled = canOpenCandidateDashboardSection(section, access);
  const status = candidateDashboardFeatureStatus(section, access);
  const route = candidateDashboardSectionPath(candidateId, section.key);
  const tag = `<span class="shared-campaign-feature-card__status${enabled ? " is-enabled" : " is-locked"}">${escapeHtml(status.label)}</span>`;
  const body = `
    <span class="shared-campaign-feature-card__icon">${renderIcon(enabled ? section.icon : "lock")}</span>
    <span class="shared-campaign-feature-card__body">
      <span class="shared-card__meta"><span>${escapeHtml(copy.eyebrow)}</span>${tag}</span>
      <strong>${escapeHtml(section.label)}</strong>
      <small>${escapeHtml(copy.description)}</small>
      <em>${escapeHtml(status.cta)}</em>
    </span>`;
  if (!enabled) {
    return `<article class="shared-campaign-feature-card is-locked" aria-disabled="true">${body}</article>`;
  }
  return `<button class="shared-campaign-feature-card" type="button" data-action="navigate" data-route="${escapeHtml(route)}">${body}</button>`;
}

function renderCandidateVoterMapFeatureCard(candidateId, access, candidate = null) {
  const enabled = canOpenCandidateVoterMap(access, candidate);
  const disabledBecauseOff = hasCandidateVoterMapAccess(access) && candidate?.voterMapEnabled === false;
  const statusLabel = enabled
    ? access?.isOwner
      ? "Owner access"
      : "Included in your role"
    : disabledBecauseOff
      ? "Not enabled"
      : "Permission required";
  const cta = enabled
    ? "Open Voter Map"
    : disabledBecauseOff
      ? "Voter map disabled"
      : "Ask owner for map access";
  const body = `
    <span class="shared-campaign-feature-card__icon">${renderIcon(enabled ? "map" : "lock")}</span>
    <span class="shared-campaign-feature-card__body">
      <span class="shared-card__meta"><span>Map tools</span><span class="shared-campaign-feature-card__status${enabled ? " is-enabled" : " is-locked"}">${escapeHtml(statusLabel)}</span></span>
      <strong>Voter Map</strong>
      <small>Open mapping, territory access, connected voter records, add/import tools, outreach scripts, and field notes.</small>
      <em>${escapeHtml(cta)}</em>
    </span>`;
  if (!enabled) {
    return `<article class="shared-campaign-feature-card is-locked" aria-disabled="true">${body}</article>`;
  }
  return `<button class="shared-campaign-feature-card" type="button" data-action="navigate" data-route="${escapeHtml(candidateVoterMapPath("", candidateId))}">${body}</button>`;
}

function candidateDashboardAccessRootStats(campaigns = []) {
  const sections = candidateDashboardRootFeatureSections();
  const enabledSections = sections.filter((section) =>
    campaigns.some((access) => canOpenCandidateDashboardRootFeature(section, access)),
  );
  const lockedSections = sections.filter((section) =>
    campaigns.some((access) => !canOpenCandidateDashboardRootFeature(section, access)),
  );
  const fullAccessCount = campaigns.filter((access) =>
    sections.every((section) => canOpenCandidateDashboardRootFeature(section, access)),
  ).length;
  const ownerCount = campaigns.filter((item) => item.isOwner).length;
  return {
    ownerCount,
    staffCount: Math.max(0, campaigns.length - ownerCount),
    enabledSections,
    lockedSections,
    fullAccessCount,
  };
}

function candidateDashboardRootActionItems(campaigns = []) {
  const findAccessForSection = (key, predicate = canOpenCandidateDashboardSection) => {
    const section = candidateDashboardSectionConfig(key);
    return campaigns.find((access) => predicate(section, access));
  };
  const makeAction = ({
    key,
    label,
    copy,
    icon,
    route,
    primary = false,
    shortcuts = [],
  }) => ({
    key,
    label,
    copy,
    icon,
    route,
    primary,
    shortcuts,
  });
  const actions = [];
  const voterMapAccess = campaigns.find((access) => hasCandidateVoterMapAccess(access));
  const actionSpecs = [
    {
      key: "messaging",
      label: "Open messaging",
      copy: "Jump into campaign rooms, requests, and announcements.",
      icon: "messages",
      primary: true,
    },
    {
      key: "engagement",
      label: "Triage engagement",
      copy: "Review public comments, likes, replies, and response mode.",
      icon: "comment",
      primary: true,
    },
    {
      key: "calendar",
      label: "Plan calendar",
      copy: "Manage availability, events, shifts, approvals, and promotion.",
      icon: "calendar",
    },
    {
      key: "missions",
      label: "Open missions",
      copy: "Assign, claim, approve, and track campaign work.",
      icon: "mission",
    },
    {
      key: "staff",
      label: "Tune access",
      copy: "Invite staff and shape feature access.",
      icon: "team",
    },
    {
      key: "donations",
      label: "Check donations",
      copy: "Review finance setup, transactions, payouts, and exports.",
      icon: "heart",
    },
  ];
  actionSpecs.forEach((spec) => {
    const access = findAccessForSection(spec.key);
    if (!access) {
      return;
    }
    actions.push(
      makeAction({
        ...spec,
        route: candidateDashboardSectionPath(access.candidateId, spec.key),
      }),
    );
  });
  if (voterMapAccess) {
    const voterMapPermissions = candidateDashboardPermissionSet(voterMapAccess);
    const voterMapShortcuts = [];
    if (voterMapAccess.isOwner || voterMapPermissions.has("voter_map_manager")) {
      voterMapShortcuts.push({
        label: "Territory wizard",
        icon: "team",
        route: candidateVoterMapPath("territories/admin", voterMapAccess.candidateId),
      });
    }
    if (voterMapAccess.isOwner) {
      voterMapShortcuts.push({
        label: "Outreach scripts",
        icon: "edit",
        route: candidateVoterMapPath("scripts", voterMapAccess.candidateId),
      });
    }
    actions.splice(
      Math.min(actions.length, 2),
      0,
      makeAction({
        key: "voter-map",
        label: "Open voter map",
        copy: "Review territories, voter records, scripts, and field notes.",
        icon: "map",
        route: candidateVoterMapPath("", voterMapAccess.candidateId),
        shortcuts: voterMapShortcuts,
      }),
    );
  }
  return actions.slice(0, 5);
}

function renderCandidateDashboardRootAction(action) {
  const actionButton = `<button class="shared-campaign-access-action${action.primary ? " is-primary" : ""}" type="button" data-action="navigate" data-route="${escapeHtml(action.route)}">
    <span>${renderIcon(action.icon)}</span>
    <strong>${escapeHtml(action.label)}</strong>
    <small>${escapeHtml(action.copy)}</small>
  </button>`;
  const shortcuts = Array.isArray(action.shortcuts) ? action.shortcuts : [];
  if (!shortcuts.length) {
    return actionButton;
  }
  return `<article class="shared-campaign-access-action-shell${action.primary ? " is-primary" : ""}">
    ${actionButton}
    <div class="shared-campaign-access-action__shortcuts" aria-label="${escapeHtml(`${action.label} quick actions`)}">
      ${shortcuts
        .map(
          (shortcut) => `<button class="shared-campaign-access-shortcut" type="button" data-action="navigate" data-route="${escapeHtml(shortcut.route)}">
            <span>${renderIcon(shortcut.icon)}</span>
            <strong>${escapeHtml(shortcut.label)}</strong>
          </button>`,
        )
        .join("")}
    </div>
  </article>`;
}

function candidateDashboardCoverageGroups() {
  return [
    {
      label: "Campaign operations",
      copy: "Reporting, events, calendar, staff, missions, and donations.",
      keys: ["analytics", "events", "calendar", "staff", "missions", "donations"],
    },
    {
      label: "Voter response",
      copy: "Engagement, voter prompts, registry, Voter Map, and Campaign Quest.",
      keys: [
        "engagement",
        "voter-contact-prompt",
        "voter-registry",
        "voter-map",
        "campaign-quest",
      ],
    },
    {
      label: "Communications",
      copy: "Campaign rooms, volunteer coordination, announcements, and follow-up.",
      keys: ["messaging"],
    },
  ];
}

function renderCandidateDashboardCoverageGroup(group, campaigns = []) {
  const sections = group.keys
    .map(candidateDashboardRootFeatureDescriptor)
    .filter(Boolean);
  const availableCount = sections.filter((section) =>
    campaigns.some((access) => canOpenCandidateDashboardRootFeature(section, access)),
  ).length;
  const totalCount = sections.length;
  return `<article class="shared-campaign-access-lane">
    <div class="shared-campaign-access-lane__header">
      <span>
        <strong>${escapeHtml(group.label)}</strong>
        <small>${escapeHtml(group.copy)}</small>
      </span>
      <em>${escapeHtml(`${formatCount(availableCount)}/${formatCount(totalCount)} live`)}</em>
    </div>
    <div class="shared-campaign-access-lane__items">
      ${sections
        .map((section) => {
          const count = campaigns.filter((access) =>
            canOpenCandidateDashboardRootFeature(section, access),
          ).length;
          return `<span class="${count ? "is-live" : "is-locked"}">
            <i>${renderIcon(count ? section.icon : "lock")}</i>
            <strong>${escapeHtml(section.label)}</strong>
            <small>${escapeHtml(count ? `${formatCount(count)} campaign${count === 1 ? "" : "s"}` : "Locked")}</small>
          </span>`;
        })
        .join("")}
    </div>
      </article>`;
}

function renderWorkspaceFallbackAction(action) {
  const route = normalizeString(action.route);
  const actionName = normalizeString(action.action) || "navigate";
  const actionAttrs = route
    ? `data-action="${escapeHtml(actionName)}" data-route="${escapeHtml(route)}"`
    : `data-action="${escapeHtml(actionName)}"`;
  return `<button class="shared-feed-chip${action.primary ? " shared-feed-chip--primary" : ""}" type="button" ${actionAttrs}>${escapeHtml(action.label)}</button>`;
}

function renderWorkspaceFallbackMap({
  eyebrow = "Workspace map",
  title = "Workspace routes are ready.",
  copy = "",
  metrics = [],
  groups = [],
  actions = [],
} = {}) {
  const metricMarkup = metrics
    .map(
      (metric) => `<span>
        <strong>${escapeHtml(metric.value)}</strong>
        <small>${escapeHtml(metric.label)}</small>
      </span>`,
    )
    .join("");
  const groupMarkup = groups
    .map(
      (group) => `<article class="shared-workspace-fallback__group">
        <div class="shared-workspace-fallback__group-top">
          <span aria-hidden="true">${renderIcon(group.icon)}</span>
          <div>
            <strong>${escapeHtml(group.label)}</strong>
            <small>${escapeHtml(group.copy)}</small>
          </div>
        </div>
        <div class="shared-workspace-fallback__items">
          ${(group.items || [])
            .map(
              (item) => `<span>
                ${renderIcon(item.icon)}
                <strong>${escapeHtml(item.label)}</strong>
                <small>${escapeHtml(item.caption || "")}</small>
              </span>`,
            )
            .join("")}
        </div>
      </article>`,
    )
    .join("");
  return `<section class="shared-workspace-fallback">
    <div class="shared-workspace-fallback__intro">
      <span class="shared-settings-eyebrow">${escapeHtml(eyebrow)}</span>
      <h2>${escapeHtml(title)}</h2>
      ${copy ? `<p>${escapeHtml(copy)}</p>` : ""}
      ${
        actions.length
          ? `<div class="shared-workspace-fallback__actions">${actions.map(renderWorkspaceFallbackAction).join("")}</div>`
          : ""
      }
    </div>
    ${metricMarkup ? `<div class="shared-workspace-fallback__metrics">${metricMarkup}</div>` : ""}
    <div class="shared-workspace-fallback__grid">${groupMarkup}</div>
  </section>`;
}

function candidateDashboardFallbackItem(key, fallback = {}) {
  const section = candidateDashboardRootFeatureDescriptor(key);
  const copy = candidateDashboardFeatureCopy(section);
  return {
    icon: fallback.icon || section?.icon || "dashboard",
    label: fallback.label || section?.label || humanizeLabel(key),
    caption: fallback.caption || copy.eyebrow,
  };
}

function renderCandidateDashboardRootFallback() {
  const featureSections = candidateDashboardRootFeatureSections();
  return renderWorkspaceFallbackMap({
    eyebrow: "Campaign command",
    title: "Campaign workspaces stay mapped while access sync is offline.",
    copy:
      "Open candidate access, messages, or the directory now. Once a campaign loads, these same areas become direct dashboard routes.",
    metrics: [
      {
        value: formatCount(featureSections.length),
        label: "work areas",
      },
      { value: "Owner + staff", label: "access model" },
      { value: "Live routes", label: "web surface" },
    ],
    actions: [
      {
        label: "Candidate access",
        route: "/settings/candidate-access",
        primary: true,
      },
      { label: "Candidate directory", route: "/candidates" },
      { label: "Messages", route: "/messages" },
    ],
    groups: [
      {
        label: "Campaign operations",
        icon: "mission",
        copy: "Reporting, events, calendars, staff, missions, and donations.",
        items: [
          candidateDashboardFallbackItem("overview"),
          candidateDashboardFallbackItem("analytics"),
          candidateDashboardFallbackItem("events"),
          candidateDashboardFallbackItem("calendar"),
          candidateDashboardFallbackItem("staff"),
          candidateDashboardFallbackItem("missions"),
          candidateDashboardFallbackItem("donations"),
        ],
      },
      {
        label: "Voter field work",
        icon: "map",
        copy: "Registry, map work, Campaign Quest, and contact prompts.",
        items: [
          candidateDashboardFallbackItem("voter-map"),
          candidateDashboardFallbackItem("voter-registry"),
          candidateDashboardFallbackItem("campaign-quest"),
          candidateDashboardFallbackItem("voter-contact-prompt"),
        ],
      },
      {
        label: "Publishing and response",
        icon: "messages",
        copy: "Messaging, engagement triage, petitions, and public follow-up.",
        items: [
          candidateDashboardFallbackItem("messaging"),
          candidateDashboardFallbackItem("engagement"),
          candidateDashboardFallbackItem("petitions"),
        ],
      },
    ],
  });
}

function renderCandidateDashboardRootSummary(campaigns = []) {
  if (!campaigns.length) {
    return "";
  }
  const stats = candidateDashboardAccessRootStats(campaigns);
  const prioritySections = stats.enabledSections.slice(0, 6);
  const actions = candidateDashboardRootActionItems(campaigns);
  return `<section class="shared-campaign-access-map shared-campaign-access-map--command">
    <div class="shared-campaign-access-map__intro">
      <span class="shared-card__meta"><span>Web command center</span><span>${escapeHtml(formatCount(stats.enabledSections.length))} feature areas</span></span>
      <h2>Start from access, then move directly into campaign work.</h2>
      <p>Each campaign card exposes app-backed dashboard areas, while this map shows which workspaces are ready across every campaign attached to this account.</p>
    </div>
    <div class="shared-campaign-access-map__actions">
      ${actions.map(renderCandidateDashboardRootAction).join("")}
    </div>
    <div class="shared-campaign-access-map__metrics">
      <span><strong>${escapeHtml(formatCount(campaigns.length))}</strong><small>campaign${campaigns.length === 1 ? "" : "s"}</small></span>
      <span><strong>${escapeHtml(formatCount(stats.ownerCount))}</strong><small>owner</small></span>
      <span><strong>${escapeHtml(formatCount(stats.staffCount))}</strong><small>staff</small></span>
      <span><strong>${escapeHtml(formatCount(stats.fullAccessCount))}</strong><small>full access</small></span>
    </div>
    <div class="shared-campaign-access-map__lanes">
      ${candidateDashboardCoverageGroups()
        .map((group) => renderCandidateDashboardCoverageGroup(group, campaigns))
        .join("")}
    </div>
    ${
      prioritySections.length
        ? `<div class="shared-campaign-access-map__features">
            ${prioritySections
              .map((section) => {
                const count = campaigns.filter((access) =>
                  canOpenCandidateDashboardRootFeature(section, access),
                ).length;
                return `<span>
                  <i>${renderIcon(section.icon)}</i>
                  <strong>${escapeHtml(section.label)}</strong>
                  <small>${escapeHtml(`${formatCount(count)} campaign${count === 1 ? "" : "s"}`)}</small>
                </span>`;
              })
              .join("")}
          </div>`
        : ""
    }
  </section>`;
}

function renderCandidateDashboardCampaignCard(access) {
  const profile = access.profile || {};
  const displayName = normalizeString(profile.displayName) || "Campaign";
  const dashboardPath = candidateDashboardSectionPath(access.candidateId);
  const voterMapPath = candidateVoterMapPath("", access.candidateId);
  const permissionCount = access.isOwner
    ? "Owner"
    : `${formatCount(access.permissions.length)} permission${access.permissions.length === 1 ? "" : "s"}`;
  const highlights = candidateDashboardFeatureHighlights(access, 5);
  return `<article class="shared-campaign-card">
    <div class="shared-campaign-card__avatar">
      ${
        profile.avatarUrl
          ? `<img src="${escapeHtml(profile.avatarUrl)}" alt="${escapeHtml(displayName)}" />`
          : `<span>${escapeHtml(displayName.slice(0, 1).toUpperCase() || "C")}</span>`
      }
    </div>
    <div class="shared-campaign-card__body">
      <div class="shared-card__meta">
        <span>${escapeHtml(permissionCount)}</span>
        ${profile.username ? `<span>@${escapeHtml(profile.username)}</span>` : ""}
      </div>
      <h3>${escapeHtml(displayName)}</h3>
      ${
        highlights.visible.length
          ? `<div class="shared-campaign-card__features">
              ${highlights.visible
                .map((section) =>
                  renderCandidateDashboardFeaturePill(section, access.candidateId),
                )
                .join("")}
              ${highlights.remaining ? `<span class="shared-campaign-feature-more">+${escapeHtml(formatCount(highlights.remaining))} more</span>` : ""}
            </div>`
          : `<p class="shared-campaign-card__note">Open the dashboard to review campaign access and request feature access.</p>`
      }
      <div class="shared-card__actions">
        <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="${escapeHtml(dashboardPath)}">Command center</button>
        ${
          hasCandidateVoterMapAccess(access)
            ? `<button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(voterMapPath)}">Voter Map</button>`
            : ""
        }
        ${
          canManageCandidateMessaging(access)
            ? `<button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(candidateMessagingServerPath(access.candidateId))}">Messaging</button>`
            : ""
        }
      </div>
    </div>
  </article>`;
}

function renderCandidateDashboardRootEmpty() {
  const profile = state.pages.profile.me;
  const status = normalizeString(profile?.candidateAccessStatus).toLowerCase();
  const title =
    status === "pending"
      ? "Candidate access is under review."
      : "No campaign dashboard access is attached to this account.";
  const copy =
    status === "pending"
      ? "Your filing review is still pending. The dashboard will open here after approval."
      : "Apply for candidate access or ask a campaign owner to invite you to their staff dashboard.";
  return `<div class="shared-page__empty shared-campaign-empty-access">
    <strong>${escapeHtml(title)}</strong>
    <span>${escapeHtml(copy)}</span>
    <div class="shared-campaign-empty-access__paths">
      <button type="button" data-action="navigate" data-route="/settings/candidate-access">
        <strong>Candidate access</strong>
        <small>Apply for owner access and unlock the campaign command center.</small>
      </button>
      <button type="button" data-action="navigate" data-route="/coalitions">
        <strong>Coalitions</strong>
        <small>Open coalition workspaces if your organizing role lives there.</small>
      </button>
      <button type="button" data-action="navigate" data-route="/messages">
        <strong>Messages</strong>
        <small>Use direct and room messaging while campaign access is being added.</small>
      </button>
    </div>
    <div class="shared-card__actions">
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="/settings/candidate-access">Candidate access</button>
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/candidates">Candidate directory</button>
    </div>
  </div>`;
}

function renderCandidateDashboardRoot() {
  const campaigns = state.pages.candidateDashboard.campaigns;
  return `<section class="shared-page shared-campaign-dashboard">
    ${renderTopChrome()}
    <div class="shared-page__content">
      <div class="shared-page__header">
        <div>
          <h1>Campaigns</h1>
          <p>Open a candidate dashboard to manage reporting, events, calendar, engagement, voter tools, Campaign Quest, donations, staff, missions, and messaging.</p>
        </div>
        <div class="shared-card__actions">
          <button class="shared-feed-chip" data-action="navigate" data-route="/candidates">Candidate directory</button>
          <button class="shared-feed-chip" data-action="open-app-shell">Open app</button>
        </div>
      </div>
      ${renderCandidateCalendarReturnBanner()}
      ${campaigns.loading && !campaigns.items.length ? '<div class="shared-page__loading">Loading campaigns...</div>' : ""}
      ${renderWorkspaceServiceAlert([campaigns.error], {
        title: "Campaign access could not be loaded",
        body: "Campaign dashboards could not sync from Polis services right now.",
        secondaryRoute: "/settings/candidate-access",
        secondaryLabel: "Candidate access",
      })}
      ${campaigns.items.length ? renderCandidateDashboardRootSummary(campaigns.items) : ""}
      ${
        campaigns.error && !campaigns.items.length && !campaigns.loading
          ? renderCandidateDashboardRootFallback()
          : ""
      }
      ${
        campaigns.items.length
          ? `<div class="shared-campaign-grid">${campaigns.items.map(renderCandidateDashboardCampaignCard).join("")}</div>`
          : campaigns.loaded && !campaigns.loading
            ? renderCandidateDashboardRootEmpty()
            : ""
      }
    </div>
  </section>`;
}

function renderCandidateDashboardHero(candidate, access) {
  const candidateId = access?.candidateId || candidate?.candidateId || "";
  const displayName =
    normalizeString(candidate?.displayName || access?.profile?.displayName) ||
    "Campaign";
  const avatarUrl = normalizeUrl(candidate?.avatarUrl || access?.profile?.avatarUrl);
  const officeLine = [
    candidate?.officeTitle,
    candidate?.levelOfOffice,
    candidate?.district,
  ]
    .map(normalizeString)
    .filter(Boolean)
    .join(" - ");
  const sectionByKey = new Map(
    CANDIDATE_DASHBOARD_SECTION_CONFIG.map((section) => [section.key, section]),
  );
  const heroActions = [
    canOpenCandidateDashboardSection(sectionByKey.get("messaging"), access)
      ? {
          label: "Messaging",
          icon: "messages",
          route: candidateDashboardSectionPath(candidateId, "messaging"),
          primary: true,
        }
      : null,
    canOpenCandidateVoterMap(access, candidate)
      ? {
          label: "Voter Map",
          icon: "map",
          route: candidateVoterMapPath("", candidateId),
        }
      : null,
    canOpenCandidateDashboardSection(sectionByKey.get("missions"), access)
      ? {
          label: "Missions",
          icon: "mission",
          route: candidateDashboardSectionPath(candidateId, "missions"),
        }
      : null,
    canOpenCandidateDashboardSection(sectionByKey.get("calendar"), access)
      ? {
          label: "Calendar",
          icon: "calendar",
          route: candidateDashboardSectionPath(candidateId, "calendar"),
        }
      : null,
  ].filter(Boolean);
  return `<section class="shared-campaign-hero">
    <div class="shared-campaign-hero__identity">
      <div class="shared-campaign-hero__avatar">
        ${
          avatarUrl
            ? `<img src="${escapeHtml(avatarUrl)}" alt="${escapeHtml(displayName)}" />`
            : `<span>${escapeHtml(displayName.slice(0, 1).toUpperCase() || "C")}</span>`
        }
      </div>
      <div>
        <div class="shared-card__meta">
          <span>${access?.isOwner ? "Owner access" : "Staff access"}</span>
          ${access?.profile?.username ? `<span>@${escapeHtml(access.profile.username)}</span>` : ""}
        </div>
        <h1>${escapeHtml(displayName)}</h1>
        <p>${escapeHtml(officeLine || candidate?.bio || "Campaign operations")}</p>
      </div>
  </div>
  <div class="shared-campaign-hero__actions">
      ${heroActions
        .map(
          (action) =>
            `<button class="shared-feed-chip${action.primary ? " shared-feed-chip--primary" : ""}" data-action="navigate" data-route="${escapeHtml(action.route)}">${renderIcon(action.icon)} ${escapeHtml(action.label)}</button>`,
        )
        .join("")}
      <button class="shared-feed-chip" data-action="open-app-shell">Open app</button>
    </div>
  </section>`;
}

function renderCandidateDashboardTabs(candidateId, activeSection, access) {
  return `<nav class="shared-campaign-tabs" aria-label="Campaign dashboard sections">
    ${CANDIDATE_DASHBOARD_SECTION_CONFIG.map((section) => {
      const active = section.key === activeSection;
      const enabled = canOpenCandidateDashboardSection(section, access);
      const status = candidateDashboardFeatureStatus(section, access);
      const routeAttr = enabled
        ? ` data-action="navigate" data-route="${escapeHtml(candidateDashboardSectionPath(candidateId, section.key))}"`
        : ` disabled aria-disabled="true" title="${escapeHtml(status.cta)}"`;
      return `<button class="shared-campaign-tab${active ? " is-active" : ""}${enabled ? "" : " is-muted"}" type="button"${routeAttr}>
        <span>${renderIcon(section.icon)}</span>
        <strong>${escapeHtml(section.label)}</strong>
      </button>`;
    }).join("")}
  </nav>`;
}

function renderCandidateDashboardMetric(label, value, tone = "") {
  return `<div class="shared-campaign-metric${tone ? ` shared-campaign-metric--${escapeHtml(tone)}` : ""}">
    <span>${escapeHtml(label)}</span>
    <strong>${escapeHtml(value)}</strong>
  </div>`;
}

function renderCandidateDashboardMiniList(items, renderItem, emptyText) {
  if (!items.length) {
    return `<div class="shared-page__empty">${escapeHtml(emptyText)}</div>`;
  }
  return `<div class="shared-stack">${items.map(renderItem).join("")}</div>`;
}

function candidateDashboardSectionConfig(key) {
  return CANDIDATE_DASHBOARD_SECTION_CONFIG.find((section) => section.key === key);
}

function candidateDashboardCanOpenSectionKey(key, access) {
  return canOpenCandidateDashboardSection(
    candidateDashboardSectionConfig(key),
    access,
  );
}

function candidateDashboardContactOpsCards(detail, candidateId, access) {
  const engagement = detail.engagement || createCandidateDashboardEngagementState();
  const engagementItems = Array.isArray(engagement.items) ? engagement.items : [];
  const needsAttention = engagementItems.filter((item) => !item.handled).length;
  const contactSettings =
    detail.contactPrompt?.settings ||
    normalizeCandidateDashboardContactPromptSettings({}, candidateId);
  const contactChannels = candidateContactPromptEnabledCount(contactSettings);
  const registry =
    detail.voterRegistry || createCandidateDashboardVoterRegistryState();
  const voterRecords = Array.isArray(registry.items) ? registry.items : [];
  const preferredCount = voterRecords.filter(
    (item) => candidateVoterPreferredContactTypes(item).length > 0,
  ).length;
  const voterMap = detail.voterMap || createCandidateDashboardVoterMapState();
  const territoryCount = voterMap.access?.territories?.length || 0;
  const messaging =
    detail.messagingWorkspace || createCandidateDashboardMessagingState();
  const channels = Array.isArray(messaging.item?.channels)
    ? messaging.item.channels
    : [];
  const unreadCount = channels.reduce(
    (total, channel) => total + (Number(channel.unreadCount) || 0),
    0,
  );
  const canOpen = (key) => candidateDashboardCanOpenSectionKey(key, access);
  return [
    {
      key: "engagement",
      label: "Engagement queue",
      metric: needsAttention
        ? `${formatCount(needsAttention)} needs response`
        : engagement.loaded
          ? "Queue clear"
          : "Load queue",
      copy: "Reply as candidate or staff, then clear handled activity.",
      icon: "comment",
      route: candidateDashboardSectionPath(candidateId, "engagement"),
      enabled: canOpen("engagement"),
      urgent: needsAttention > 0,
    },
    {
      key: "voter-contact-prompt",
      label: "Voter contact prompt",
      metric: contactSettings.feedPromptEnabled
        ? `${formatCount(contactChannels)} live channels`
        : "Hidden from voters",
      copy: "Choose which voter outreach requests are shown in feeds and profiles.",
      icon: "candidate",
      route: candidateDashboardSectionPath(candidateId, "voter-contact-prompt"),
      enabled: canOpen("voter-contact-prompt"),
      urgent: !contactSettings.feedPromptEnabled,
    },
    {
      key: "voter-registry",
      label: "Voter registry",
      metric: voterRecords.length
        ? `${formatCount(voterRecords.length)} loaded voters`
        : "No voters loaded",
      copy: preferredCount
        ? `${formatCount(preferredCount)} voters have preferred contact channels.`
        : "Search, import, and capture contact preferences before outreach.",
      icon: "registry",
      route: candidateDashboardSectionPath(candidateId, "voter-registry"),
      enabled: canOpen("voter-registry"),
    },
    {
      key: "voter-map",
      label: "Voter Map",
      metric: territoryCount
        ? `${formatCount(territoryCount)} territories`
        : voterMap.loaded
          ? "Map tools ready"
          : "Open map tools",
      copy: "Use mapping, territory scope, connected voter records, add/import, outreach scripts, and field notes.",
      icon: "map",
      route: candidateVoterMapPath("", candidateId),
      enabled: canOpenCandidateVoterMap(access, detail.candidate),
    },
    {
      key: "messaging",
      label: "Campaign rooms",
      metric: channels.length
        ? `${formatCount(channels.length)} rooms${unreadCount ? `, ${formatCount(unreadCount)} unread` : ""}`
        : "Open room workspace",
      copy: "Coordinate staff, volunteers, announcements, and voter follow-up.",
      icon: "messages",
      route: candidateDashboardSectionPath(candidateId, "messaging"),
      enabled: canOpen("messaging"),
      urgent: unreadCount > 0,
    },
    {
      key: "campaign-quest",
      label: "Field map",
      metric: detail.voterMap?.loaded ? "Map access loaded" : "Check field access",
      copy: "Move voter records into territories, scripts, quests, and sign-drop work.",
      icon: "map",
      route: candidateDashboardSectionPath(candidateId, "campaign-quest"),
      enabled: canOpen("campaign-quest"),
    },
    {
      key: "staff",
      label: "Staff permissions",
      metric: `${formatCount(detail.staff.length)} staff loaded`,
      copy: "Grant engagement, messaging, voter registry, and map access deliberately.",
      icon: "team",
      route: candidateDashboardSectionPath(candidateId, "staff"),
      enabled: canOpen("staff"),
    },
  ];
}

function renderCandidateDashboardContactOpsCard(item) {
  const className = [
    "shared-campaign-contact-ops-card",
    item.urgent ? "is-urgent" : "",
    item.enabled ? "" : "is-locked",
  ]
    .filter(Boolean)
    .join(" ");
  const body = `
    <span class="shared-campaign-contact-ops-card__icon">${renderIcon(item.enabled ? item.icon : "lock")}</span>
    <span class="shared-campaign-contact-ops-card__body">
      <small>${escapeHtml(item.metric)}</small>
      <strong>${escapeHtml(item.label)}</strong>
      <em>${escapeHtml(item.enabled ? item.copy : "Ask the campaign owner for this permission.")}</em>
    </span>`;
  if (!item.enabled) {
    return `<article class="${className}" aria-disabled="true">${body}</article>`;
  }
  return `<button class="${className}" type="button" data-action="navigate" data-route="${escapeHtml(item.route)}">${body}</button>`;
}

function renderCandidateDashboardContactOps(detail, candidateId, access) {
  const cards = candidateDashboardContactOpsCards(detail, candidateId, access);
  const activeCards = cards.filter((item) => item.enabled);
  const urgentCards = cards.filter((item) => item.enabled && item.urgent);
  const engagement = detail.engagement || createCandidateDashboardEngagementState();
  const registry =
    detail.voterRegistry || createCandidateDashboardVoterRegistryState();
  const contactSettings =
    detail.contactPrompt?.settings ||
    normalizeCandidateDashboardContactPromptSettings({}, candidateId);
  return `<article class="shared-campaign-panel shared-campaign-panel--wide shared-campaign-contact-ops">
    <div class="shared-campaign-panel__header">
      <div>
        <span class="shared-card__meta"><span>Voter contact operations</span><span>${escapeHtml(`${formatCount(activeCards.length)} available lanes`)}</span></span>
        <h2>Move from voter signal to campaign response.</h2>
        <p>Use the same app-backed areas from the browser: prompt settings create consent, engagement handles public activity, the registry stores voter preferences, messaging coordinates follow-up, and staff permissions control who can act.</p>
      </div>
      <div class="shared-card__actions">
        <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="${escapeHtml(candidateDashboardSectionPath(candidateId, "engagement"))}"${disabledAttr(!candidateDashboardCanOpenSectionKey("engagement", access))}>Engagement</button>
        <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(candidateDashboardSectionPath(candidateId, "voter-registry"))}"${disabledAttr(!candidateDashboardCanOpenSectionKey("voter-registry", access))}>Voter registry</button>
      </div>
    </div>
    <div class="shared-campaign-contact-ops__summary">
      <span><strong>${escapeHtml(formatCount(urgentCards.length))}</strong><small>attention lanes</small></span>
      <span><strong>${escapeHtml(contactSettings.feedPromptEnabled ? "Live" : "Hidden")}</strong><small>contact prompt</small></span>
      <span><strong>${escapeHtml(formatCount(registry.items?.length || 0))}</strong><small>voters loaded</small></span>
      <span><strong>${escapeHtml(formatCount((engagement.items || []).filter((item) => !item.handled).length))}</strong><small>engagement tasks</small></span>
    </div>
    <div class="shared-campaign-contact-ops__grid">
      ${cards.map(renderCandidateDashboardContactOpsCard).join("")}
    </div>
  </article>`;
}

function renderCandidateDashboardOverview(detail, candidateId, access) {
  const analytics = detail.analytics || {};
  const metrics = [
    renderCandidateDashboardMetric("Reach", formatCount(analytics.reach || 0), "cyan"),
    renderCandidateDashboardMetric(
      "Impressions",
      formatCount(analytics.impressions || 0),
    ),
    renderCandidateDashboardMetric("Staff", formatCount(detail.staff.length)),
    renderCandidateDashboardMetric("Missions", formatCount(detail.missions.length)),
    renderCandidateDashboardMetric("Events", formatCount(detail.events.length)),
    renderCandidateDashboardMetric("Calendar", formatCount(detail.calendar.length)),
  ].join("");
  const featureSections = candidateDashboardFeatureSections({ includeOverview: true });
  return `<div class="shared-campaign-section">
    <div class="shared-campaign-metrics">${metrics}</div>
    <div class="shared-campaign-overview-grid">
      <article class="shared-campaign-panel">
        <div class="shared-campaign-panel__header">
          <h2>Operations</h2>
          <button class="shared-feed-chip" data-action="navigate" data-route="${escapeHtml(candidateDashboardSectionPath(candidateId, "missions"))}">Missions</button>
        </div>
        ${renderCandidateDashboardMiniList(
          detail.missions.slice(0, 3),
          (mission) => `<button class="shared-list-item" data-action="navigate" data-route="/missions/${escapeHtml(encodeURIComponent(mission.missionId))}">
            <strong>${escapeHtml(mission.title)}</strong>
            <span>${escapeHtml(humanizeLabel(mission.status))}${mission.assignedCount ? ` - ${formatCount(mission.assignedCount)} assigned` : ""}</span>
          </button>`,
          "No active missions in this campaign view.",
        )}
      </article>
      <article class="shared-campaign-panel">
        <div class="shared-campaign-panel__header">
          <h2>Calendar</h2>
          <button class="shared-feed-chip" data-action="navigate" data-route="${escapeHtml(candidateDashboardSectionPath(candidateId, "calendar"))}">Open</button>
        </div>
        ${renderCandidateDashboardMiniList(
          detail.calendar.slice(0, 3),
          (item) => `<div class="shared-list-item">
            <strong>${escapeHtml(item.title)}</strong>
            <span>${escapeHtml(item.startAt ? formatAbsoluteDateTime(item.startAt) : humanizeLabel(item.status))}</span>
          </div>`,
          "No upcoming calendar items.",
        )}
      </article>
      <article class="shared-campaign-panel">
        <div class="shared-campaign-panel__header">
          <h2>Access</h2>
          <button class="shared-feed-chip" data-action="navigate" data-route="${escapeHtml(candidateDashboardSectionPath(candidateId, "staff"))}">Staff</button>
        </div>
        ${renderCandidateDashboardMiniList(
          detail.staff.slice(0, 4),
          (member) => `<div class="shared-list-item">
            <strong>${escapeHtml(member.displayName)}</strong>
            <span>${escapeHtml(member.role)} - ${escapeHtml(formatCount(member.permissions.length))} permissions</span>
          </div>`,
          "No staff members loaded.",
        )}
      </article>
      ${renderCandidateDashboardContactOps(detail, candidateId, access)}
      <article class="shared-campaign-panel shared-campaign-panel--wide">
        <div class="shared-campaign-panel__header">
          <div>
            <span class="shared-card__meta"><span>Feature map</span><span>${escapeHtml(access?.isOwner ? "Owner workspace" : "Staff workspace")}</span></span>
            <h2>Campaign command center</h2>
            <p>Open the browser surfaces that match the Polis app dashboard. Locked cards show what exists but needs owner access or a staff permission.</p>
          </div>
        </div>
        <div class="shared-campaign-feature-grid">
          ${featureSections
            .map((section) =>
              renderCandidateDashboardFeatureCard(section, candidateId, access),
            )
            .join("")}
          ${renderCandidateVoterMapFeatureCard(candidateId, access, detail.candidate)}
        </div>
      </article>
    </div>
  </div>`;
}

function formatAnalyticsPercent(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return "0%";
  }
  const percent = numeric <= 1 ? numeric * 100 : numeric;
  return `${percent.toFixed(percent >= 10 ? 1 : 1)}%`;
}

function candidateAnalyticsAudienceLabels(context = {}) {
  if (context.matchMode === "state") {
    return {
      matched: "In-state",
      outside: "Out of state",
      unknown: "Unknown",
    };
  }
  return {
    matched: "Constituents",
    outside: "Outside district",
    unknown: "Unknown",
  };
}

function candidateAnalyticsContextModeLabel(context = {}) {
  if (!context?.available) {
    return "Limited";
  }
  return context.matchMode === "state" ? "State matching" : "District matching";
}

function candidateAnalyticsContextDetail(context = {}) {
  if (!context?.available) {
    const reason = normalizeString(context.reason);
    return reason
      ? `Segmentation limited: ${humanizeLabel(reason)}.`
      : "Segmentation is limited for this campaign configuration.";
  }
  const reference = normalizeString(context.referenceLabel) || "campaign target area";
  return context.matchMode === "state"
    ? `Viewers are matched against ${reference} by state.`
    : `Viewers are matched against ${reference} by district.`;
}

function candidateAnalyticsRangeLabel(analytics = {}) {
  const compactDate = (value, includeYear = false) => {
    const normalized = normalizeString(value);
    if (!normalized) {
      return "";
    }
    const dateOnlyMatch = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    const parsed = dateOnlyMatch
      ? new Date(
          Number(dateOnlyMatch[1]),
          Number(dateOnlyMatch[2]) - 1,
          Number(dateOnlyMatch[3]),
        )
      : new Date(normalized);
    if (Number.isNaN(parsed.getTime())) {
      return formatCalendarDate(normalized);
    }
    return parsed.toLocaleDateString(undefined, {
      month: "short",
      day: "numeric",
      ...(includeYear ? { year: "numeric" } : {}),
    });
  };
  const startRaw = normalizeString(analytics.startDate);
  const endRaw = normalizeString(analytics.endDate);
  const yearFromDate = (value) => {
    const match = normalizeString(value).match(/^(\d{4})-\d{2}-\d{2}$/);
    if (match) {
      return Number(match[1]);
    }
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? 0 : parsed.getFullYear();
  };
  const startYear = yearFromDate(startRaw);
  const endYear = yearFromDate(endRaw);
  const includeYear =
    !startYear || !endYear || startYear !== endYear || startYear !== new Date().getFullYear();
  const start = compactDate(startRaw, includeYear);
  const end = compactDate(endRaw, includeYear);
  if (start && end) {
    return `${start} to ${end}`;
  }
  return `${formatCount(analytics.days || 30)} day window`;
}

function renderCandidateAnalyticsCommand(analytics, resource, labels) {
  const context = analytics.audienceContext || {};
  const loadedAt = Number(resource.loadedAt) || 0;
  const detailRows = [
    ["Matching mode", candidateAnalyticsContextModeLabel(context)],
    ["Target area", normalizeString(context.referenceLabel) || "Not available"],
    ["Range", candidateAnalyticsRangeLabel(analytics)],
    ["Bucket labels", `${labels.matched}, ${labels.outside}, ${labels.unknown}`],
    loadedAt ? ["Last refreshed", formatAbsoluteDateTime(loadedAt)] : null,
  ].filter(Boolean);
  return `<div class="shared-campaign-analytics-command">
    <div class="shared-campaign-analytics-command__summary">
      <span>${renderIcon(context.available ? (context.matchMode === "state" ? "flag" : "map") : "chart")}</span>
      <div>
        <small>${escapeHtml(candidateAnalyticsContextModeLabel(context))}</small>
        <strong>${escapeHtml(candidateAnalyticsRangeLabel(analytics))}</strong>
        <p>${escapeHtml(candidateAnalyticsContextDetail(context))}</p>
      </div>
    </div>
    <div class="shared-campaign-analytics-command__cards" aria-label="Analytics context">
      <div><span>Reach</span><strong>${escapeHtml(formatCount(analytics.reach))}</strong></div>
      <div><span>Engaged</span><strong>${escapeHtml(formatCount(analytics.engagedViewers))}</strong></div>
      <div><span>Reports</span><strong>${escapeHtml(formatAnalyticsPercent(analytics.reportRate))}</strong></div>
    </div>
    <details class="shared-campaign-analytics-details">
      <summary>Details</summary>
      <div>
        ${detailRows
          .map(
            ([label, value]) =>
              `<span><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>`,
          )
          .join("")}
      </div>
    </details>
  </div>`;
}

function renderCandidateAnalyticsRangeControls(resource) {
  return `<div class="shared-campaign-analytics-range" role="group" aria-label="Analytics range">
    ${[7, 30, 90]
      .map((days) => {
        const selected = Number(resource.days) === days;
        return `<button class="shared-feed-chip${selected ? " shared-feed-chip--primary" : ""}" type="button" data-action="candidate-analytics-range" data-days="${escapeHtml(String(days))}"${disabledAttr(resource.loading)}>${escapeHtml(`${days}d`)}</button>`;
      })
      .join("")}
    <button class="shared-feed-chip" type="button" data-action="candidate-analytics-refresh"${disabledAttr(resource.loading)}>Refresh</button>
  </div>`;
}

function renderCandidateAnalyticsAudienceBar(breakdown, labels) {
  if (!breakdown) {
    return `<div class="shared-page__empty">Audience segmentation is unavailable for this range.</div>`;
  }
  const matched = Math.max(0, breakdown.matched?.percent || 0);
  const outside = Math.max(0, breakdown.outside?.percent || 0);
  const unknown = Math.max(0, breakdown.unknown?.percent || 0);
  return `<div class="shared-campaign-analytics-audience">
    <div class="shared-campaign-analytics-bar" aria-label="Audience breakdown">
      <span class="is-matched" style="width: ${escapeHtml(String(matched))}%"></span>
      <span class="is-outside" style="width: ${escapeHtml(String(outside))}%"></span>
      <span class="is-unknown" style="width: ${escapeHtml(String(unknown))}%"></span>
    </div>
    <div class="shared-campaign-analytics-legend">
      <span><em class="is-matched"></em>${escapeHtml(labels.matched)} ${escapeHtml(formatCount(breakdown.matched?.count || 0))}</span>
      <span><em class="is-outside"></em>${escapeHtml(labels.outside)} ${escapeHtml(formatCount(breakdown.outside?.count || 0))}</span>
      <span><em class="is-unknown"></em>${escapeHtml(labels.unknown)} ${escapeHtml(formatCount(breakdown.unknown?.count || 0))}</span>
    </div>
  </div>`;
}

function renderCandidateAnalyticsBreakdownBlock(title, breakdown, labels) {
  if (!breakdown) {
    return "";
  }
  return `<div class="shared-campaign-analytics-breakdown-block">
    <strong>${escapeHtml(title)}</strong>
    <div class="shared-campaign-analytics-bar" aria-label="${escapeHtml(title)} audience breakdown">
      <span class="is-matched" style="width: ${escapeHtml(String(Math.max(0, breakdown.matched?.percent || 0)))}%"></span>
      <span class="is-outside" style="width: ${escapeHtml(String(Math.max(0, breakdown.outside?.percent || 0)))}%"></span>
      <span class="is-unknown" style="width: ${escapeHtml(String(Math.max(0, breakdown.unknown?.percent || 0)))}%"></span>
    </div>
    <p>${escapeHtml(labels.matched)} ${escapeHtml(formatCount(breakdown.matched?.count || 0))} - ${escapeHtml(labels.outside)} ${escapeHtml(formatCount(breakdown.outside?.count || 0))} - ${escapeHtml(labels.unknown)} ${escapeHtml(formatCount(breakdown.unknown?.count || 0))}</p>
  </div>`;
}

function renderCandidateAnalyticsMetricChips(items = []) {
  return `<div class="shared-campaign-analytics-chip-row">
    ${items
      .filter((item) => normalizeString(item?.label))
      .map(
        (item) => `<span><strong>${escapeHtml(item.value)}</strong><em>${escapeHtml(item.label)}</em></span>`,
      )
      .join("")}
  </div>`;
}

function renderCandidateAnalyticsTrend(analytics) {
  const points = analytics.trend || [];
  if (!points.length) {
    return `<div class="shared-page__empty">No daily trend data yet.</div>`;
  }
  const maxReach = Math.max(...points.map((point) => point.reach || 0), 1);
  return `<div class="shared-campaign-analytics-trend">
    ${points
      .slice(-14)
      .map((point) => {
        const height = Math.max(8, Math.round(((point.reach || 0) / maxReach) * 100));
        const breakdown = point.reachBreakdown;
        const total = Math.max(1, breakdown?.total || point.reach || 0);
        const matchedHeight = breakdown
          ? Math.max(0, (breakdown.matched?.count || 0) / total) * 100
          : 100;
        const outsideHeight = breakdown
          ? Math.max(0, (breakdown.outside?.count || 0) / total) * 100
          : 0;
        const unknownHeight = breakdown
          ? Math.max(0, (breakdown.unknown?.count || 0) / total) * 100
          : 0;
        return `<div class="shared-campaign-analytics-trend__day">
          <div class="shared-campaign-analytics-trend__bar" title="${escapeHtml(`${formatCalendarDate(point.date)} - ${formatCount(point.reach || 0)} reach`)}" style="height: ${escapeHtml(String(height))}%">
            <span class="is-matched" style="height: ${escapeHtml(String(matchedHeight))}%"></span>
            <span class="is-outside" style="height: ${escapeHtml(String(outsideHeight))}%"></span>
            <span class="is-unknown" style="height: ${escapeHtml(String(unknownHeight))}%"></span>
          </div>
          <em>${escapeHtml(formatCalendarDate(point.date).replace(/,.*$/u, ""))}</em>
        </div>`;
      })
      .join("")}
  </div>`;
}

function renderCandidateAnalyticsTopPost(post, index, labels) {
  return `<article class="shared-campaign-analytics-post">
    <button class="shared-campaign-analytics-post__button" type="button" data-action="navigate" data-route="/posts/${escapeHtml(encodeURIComponent(post.postId))}">
      <span class="shared-campaign-analytics-rank">${escapeHtml(String(index + 1))}</span>
      <span class="shared-campaign-analytics-post__body">
        <strong>${escapeHtml(post.previewText || "Post")}</strong>
        <span>${escapeHtml(formatCount(post.reach || post.impressions || 0))} reach - ${escapeHtml(formatAnalyticsPercent(post.engagementRate))} engagement</span>
      </span>
    </button>
    ${renderCandidateAnalyticsMetricChips([
      { label: "Impressions", value: formatCount(post.impressions || 0) },
      { label: "Likes", value: formatCount(post.likes || 0) },
      { label: "Comments", value: formatCount(post.comments || 0) },
      { label: "Watches", value: formatCount(post.watches || 0) },
    ])}
    ${renderCandidateAnalyticsBreakdownBlock("Reached viewers", post.reachBreakdown, labels)}
  </article>`;
}

function renderCandidateAnalyticsEventConversion(event, labels) {
  return `<article class="shared-campaign-analytics-event">
    <div>
      <strong>${escapeHtml(event.title)}</strong>
      <span>${escapeHtml(event.startAt ? formatAbsoluteDateTime(event.startAt) : "Event")}</span>
    </div>
    <div class="shared-campaign-analytics-event__metrics">
      <span><strong>${escapeHtml(formatCount(event.reach))}</strong><em>Reach</em></span>
      <span><strong>${escapeHtml(formatCount(event.interestAdds))}</strong><em>Interested</em></span>
      <span><strong>${escapeHtml(formatCount(event.rsvpAdds))}</strong><em>RSVP</em></span>
      <span><strong>${escapeHtml(formatAnalyticsPercent(event.rsvpFromViewRateNet))}</strong><em>RSVP rate</em></span>
    </div>
    ${renderCandidateAnalyticsBreakdownBlock("Reached viewers", event.reachBreakdown, labels)}
    ${renderCandidateAnalyticsBreakdownBlock("Interested adds", event.interestAddsBreakdown, labels)}
    ${renderCandidateAnalyticsBreakdownBlock("RSVP adds", event.rsvpAddsBreakdown, labels)}
  </article>`;
}

function renderCandidateDashboardAnalytics(detail) {
  const resource = detail.analyticsWorkspace;
  const analytics = resource.snapshot || detail.analytics;
  if (resource.loading && !analytics) {
    return `<div class="shared-page__empty">Loading campaign analytics...</div>`;
  }
  if (!analytics) {
    return `<div class="shared-page__empty">Analytics are not available for this campaign session.</div>`;
  }
  const labels = candidateAnalyticsAudienceLabels(analytics.audienceContext);
  const conversions = resource.conversions?.events || [];
  const engagementRate =
    analytics.impressions > 0
      ? (analytics.likes + analytics.comments) / analytics.impressions
      : 0;
  return `<div class="shared-campaign-section shared-campaign-analytics">
    <article class="shared-campaign-panel shared-campaign-analytics-hero">
      <div class="shared-campaign-panel__header">
        <div>
          <h2>Audience analytics</h2>
          <p>${escapeHtml(analytics.audienceContext?.available ? `${analytics.audienceContext.referenceLabel || "Campaign target"} matching is active.` : "Segmentation is limited for this range.")}</p>
        </div>
        ${renderCandidateAnalyticsRangeControls(resource)}
      </div>
      ${resource.error ? `<div class="shared-page__empty">${escapeHtml(resource.error)}</div>` : ""}
      ${renderCandidateAnalyticsCommand(analytics, resource, labels)}
    </article>
    <div class="shared-campaign-metrics">
      ${renderCandidateDashboardMetric("Reach", formatCount(analytics.reach), "cyan")}
      ${renderCandidateDashboardMetric("Engaged viewers", formatCount(analytics.engagedViewers))}
      ${renderCandidateDashboardMetric("Impressions", formatCount(analytics.impressions))}
      ${renderCandidateDashboardMetric("Engagement", formatAnalyticsPercent(engagementRate), "cyan")}
      ${renderCandidateDashboardMetric("Watches", formatCount(analytics.watches))}
      ${renderCandidateDashboardMetric("Completion", formatAnalyticsPercent(analytics.completionRate))}
      ${renderCandidateDashboardMetric("Negative", formatAnalyticsPercent(analytics.negativeRate))}
    </div>
    <div class="shared-campaign-analytics-grid">
      <article class="shared-campaign-panel">
        <div class="shared-campaign-panel__header">
          <div>
            <h2>Audience breakdown</h2>
            <p>Reached viewers grouped by campaign target geography.</p>
          </div>
        </div>
        ${renderCandidateAnalyticsAudienceBar(analytics.reachBreakdown, labels)}
      </article>
      <article class="shared-campaign-panel">
        <div class="shared-campaign-panel__header">
          <div>
            <h2>Daily reach trend</h2>
            <p>Most recent days in the selected range.</p>
          </div>
        </div>
        ${renderCandidateAnalyticsTrend(analytics)}
      </article>
    </div>
    <div class="shared-campaign-analytics-grid">
      <article class="shared-campaign-panel">
        <div class="shared-campaign-panel__header">
          <div>
            <h2>Top posts</h2>
            <p>Ranked by audience reach during this period.</p>
          </div>
        </div>
        ${
          analytics.topPosts.length
            ? `<div class="shared-campaign-analytics-list">${analytics.topPosts.slice(0, 10).map((post, index) => renderCandidateAnalyticsTopPost(post, index, labels)).join("")}</div>`
            : `<div class="shared-page__empty">No top posts in this analytics window.</div>`
        }
      </article>
      <article class="shared-campaign-panel">
        <div class="shared-campaign-panel__header">
          <div>
            <h2>Event conversions</h2>
            <p>Event reach, interest adds, and RSVP adds from campaign exposure.</p>
          </div>
        </div>
        ${
          conversions.length
            ? `<div class="shared-campaign-analytics-list">${conversions.slice(0, 10).map((event) => renderCandidateAnalyticsEventConversion(event, labels)).join("")}</div>`
            : `<div class="shared-page__empty">No event conversions yet.</div>`
        }
      </article>
    </div>
  </div>`;
}

function candidateDashboardEventAllItems(resource) {
  const byId = new Map();
  [
    ...resource.activeItems,
    ...resource.previousItems,
    ...resource.mapItems,
  ].forEach((event) => {
    if (event.eventId && !byId.has(event.eventId)) {
      byId.set(event.eventId, event);
    }
  });
  return Array.from(byId.values());
}

function candidateDashboardEventCommandStats(resource) {
  const allItems = candidateDashboardEventAllItems(resource);
  const mapReadyCount = allItems.filter(candidateDashboardEventMapReady).length;
  return {
    active: resource.activeItems.length,
    previous: resource.previousItems.length,
    total: allItems.length,
    mapReady: mapReadyCount,
    needsMap: Math.max(0, allItems.length - mapReadyCount),
    paid: allItems.filter((event) => event.isFree === false).length,
    routeStops: candidateDashboardRouteStops(resource.route, resource.mapItems)
      .length,
  };
}

function candidateDashboardNextEvent(resource) {
  const now = Date.now();
  return [...resource.activeItems]
    .filter((event) => !event.startAt || event.startAt >= now - 60 * 60 * 1000)
    .sort((left, right) => {
      const leftTime = left.startAt || Number.MAX_SAFE_INTEGER;
      const rightTime = right.startAt || Number.MAX_SAFE_INTEGER;
      if (leftTime !== rightTime) {
        return leftTime - rightTime;
      }
      return left.title.localeCompare(right.title);
    })[0] || null;
}

function candidateDashboardEventsCommandCopy(resource) {
  const nextEvent = candidateDashboardNextEvent(resource);
  const stats = candidateDashboardEventCommandStats(resource);
  if (stats.needsMap > 0) {
    return {
      eyebrow: "Map readiness",
      title: `${formatCount(stats.needsMap)} event${stats.needsMap === 1 ? "" : "s"} need location data`,
      copy:
        "Complete coordinates or place data before building reliable field routes from this workspace.",
      event: nextEvent,
      stats,
    };
  }
  if (nextEvent) {
    return {
      eyebrow: "Next campaign event",
      title: nextEvent.title,
      copy: [
        nextEvent.startAt ? formatAbsoluteDateTime(nextEvent.startAt) : "",
        candidateDashboardEventLocationLabel(nextEvent),
      ].filter(Boolean).join(" - ") || "Open the event to review attendee and location details.",
      event: nextEvent,
      stats,
    };
  }
  if (stats.previous > 0) {
    return {
      eyebrow: "Follow-up queue",
      title: `${formatCount(stats.previous)} previous event${stats.previous === 1 ? "" : "s"} ready for review`,
      copy:
        "Use previous events for turnout follow-up, map cleanup, and future event planning.",
      event: null,
      stats,
    };
  }
  return {
    eyebrow: "Events command",
    title: "No campaign events loaded",
    copy:
      "Create the next campaign event, then keep location and route data complete from the web dashboard.",
    event: null,
    stats,
  };
}

function renderCandidateDashboardEventsCommand(resource) {
  const command = candidateDashboardEventsCommandCopy(resource);
  const stats = command.stats;
  const nextEvent = command.event;
  const routeBuilt = stats.routeStops > 0;
  const openRoute = nextEvent
    ? `/events/${encodeURIComponent(nextEvent.eventId)}`
    : "";
  const commandActions = [
    nextEvent
      ? `<button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="${escapeHtml(openRoute)}">Open next</button>`
      : `<button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-events-create-toggle"${disabledAttr(resource.actionPendingKey === "create")}>Create event</button>`,
    stats.mapReady
      ? `<button class="shared-feed-chip" type="button" data-action="candidate-events-view" data-view="map">Map</button>`
      : "",
    stats.mapReady && !routeBuilt
      ? `<button class="shared-feed-chip" type="button" data-action="candidate-events-build-route"${disabledAttr(resource.actionPendingKey === "route" || !resource.mapItems.length)}>${resource.actionPendingKey === "route" ? "Building..." : "Plan route"}</button>`
      : "",
  ].filter(Boolean);
  return `<section class="shared-campaign-events-command">
    <div class="shared-campaign-events-command__main">
      <span class="shared-campaign-events-command__icon">${renderIcon(stats.needsMap ? "map" : routeBuilt ? "check" : "calendar")}</span>
      <div class="shared-campaign-events-command__copy">
        <small>${escapeHtml(command.eyebrow)}</small>
        <strong>${escapeHtml(command.title)}</strong>
        <p>${escapeHtml(command.copy)}</p>
      </div>
      <div class="shared-campaign-events-command__actions">
        ${commandActions.join("")}
      </div>
    </div>
    <div class="shared-campaign-events-command__metrics">
      <div><span>Active</span><strong>${escapeHtml(formatCount(stats.active))}</strong></div>
      <div><span>Previous</span><strong>${escapeHtml(formatCount(stats.previous))}</strong></div>
      <div><span>Map ready</span><strong>${escapeHtml(formatCount(stats.mapReady))}</strong></div>
      <div><span>Paid</span><strong>${escapeHtml(formatCount(stats.paid))}</strong></div>
    </div>
    <div class="shared-campaign-events-command__nav">
      <button class="shared-campaign-events-command-chip${resource.view === "list" ? " is-active" : ""}" type="button" data-action="candidate-events-view" data-view="list"><span>List view</span><strong>${escapeHtml(formatCount(stats.total))}</strong></button>
      <button class="shared-campaign-events-command-chip${resource.view === "map" ? " is-active" : ""}" type="button" data-action="candidate-events-view" data-view="map"><span>Map view</span><strong>${escapeHtml(formatCount(stats.mapReady))}</strong></button>
      <button class="shared-campaign-events-command-chip${resource.status === "active" && resource.view === "list" ? " is-active" : ""}" type="button" data-action="candidate-events-status" data-status="active"><span>Active list</span><strong>${escapeHtml(formatCount(stats.active))}</strong></button>
      <button class="shared-campaign-events-command-chip${resource.status === "previous" && resource.view === "list" ? " is-active" : ""}" type="button" data-action="candidate-events-status" data-status="previous"><span>Previous list</span><strong>${escapeHtml(formatCount(stats.previous))}</strong></button>
    </div>
  </section>`;
}

function candidateDashboardEventLocationLabel(event) {
  return (
    normalizeString(event.locationName) ||
    normalizeString(event.locationTown) ||
    normalizeString(event.address) ||
    "Location pending"
  );
}

function candidateDashboardEventMapReady(event) {
  return Number.isFinite(event.lat) && Number.isFinite(event.lng);
}

function formatEventCostAmount(amount) {
  const numeric = Number(amount);
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return "$0";
  }
  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: numeric % 1 === 0 ? 0 : 2,
  }).format(numeric);
}

function eventRequiresPayment(event = {}) {
  const costAmount = Number(event.costAmount);
  return event.isFree === false || (Number.isFinite(costAmount) && costAmount > 0);
}

function eventCostLabel(event = {}) {
  return eventRequiresPayment(event)
    ? formatEventCostAmount(event.costAmount || 0)
    : "Free";
}

function eventDetailRoute(eventOrId = "") {
  const eventId =
    typeof eventOrId === "string" ? eventOrId : eventOrId?.eventId || "";
  return eventId ? `/events/${encodeURIComponent(eventId)}` : "/events";
}

function eventSignupRoute(eventOrId = "") {
  const eventId =
    typeof eventOrId === "string" ? eventOrId : eventOrId?.eventId || "";
  return eventId
    ? `/events/${encodeURIComponent(eventId)}/signup`
    : "/events";
}

function eventPaymentRoute(eventOrId = "") {
  const eventId =
    typeof eventOrId === "string" ? eventOrId : eventOrId?.eventId || "";
  return eventId
    ? `/events/${encodeURIComponent(eventId)}/payment`
    : "/events";
}

function eventTransportAvailable(event = {}) {
  return (
    event.transportEnabled === true &&
    event.transportClosedEarly !== true &&
    Number(event.transportRemainingSeats) > 0
  );
}

function eventTransportLabel(event = {}) {
  if (event.transportEnabled !== true) {
    return "None";
  }
  if (event.transportClosedEarly === true) {
    return "Closed";
  }
  const remainingSeats = Math.max(0, Number(event.transportRemainingSeats) || 0);
  if (!remainingSeats) {
    return "Full";
  }
  return `${formatCount(remainingSeats)} seat${remainingSeats === 1 ? "" : "s"} available`;
}

function createEventPaymentReview(formData, event = {}) {
  return {
    eventId: normalizeString(formData.get("eventId")),
    firstName: normalizeString(formData.get("firstName")),
    lastName: normalizeString(formData.get("lastName")),
    address: normalizeString(formData.get("address")),
    isCitizen: formData.get("isCitizen") === "on",
    isOwnFunds: formData.get("isOwnFunds") === "on",
    transportOptIn:
      event.transportEnabled === true
        ? formData.get("transportOptIn") === "on"
        : null,
    createdAt: Date.now(),
  };
}

function eventPaymentReviewFor(event = {}) {
  const review = state.pages.events.detail.pendingPaymentReview;
  if (!review || review.eventId !== normalizeString(event.eventId)) {
    return null;
  }
  return review;
}

function eventPaymentReviewName(review = {}) {
  return [review.firstName, review.lastName].map(normalizeString).filter(Boolean).join(" ");
}

function eventContactOptions(event = {}) {
  const raw = readObjectPayload(event.raw);
  const socials = readObjectPayload(raw.socials);
  return {
    email: normalizeString(socials.email || raw.email || raw.contactEmail),
    website: normalizeUrl(socials.website || raw.website || raw.url),
    link: normalizeUrl(socials.link || socials.other || raw.link),
  };
}

function renderCandidateDashboardEventCard(event, resource, { map = false } = {}) {
  const pendingSave = resource.actionPendingKey === `save:${event.eventId}`;
  const pendingDelete = resource.actionPendingKey === `delete:${event.eventId}`;
  const mapReady = candidateDashboardEventMapReady(event);
  return `<article class="shared-campaign-event-card">
    ${
      event.imageUrl
        ? `<img class="shared-campaign-event-card__image" src="${escapeHtml(event.imageUrl)}" alt="${escapeHtml(event.title)}" />`
        : `<div class="shared-campaign-event-card__image shared-campaign-event-card__image--placeholder">${renderIcon("calendar")}</div>`
    }
    <div class="shared-campaign-event-card__body">
      <div class="shared-card__meta">
        <span>${escapeHtml(event.startAt ? formatAbsoluteDateTime(event.startAt) : "Date pending")}</span>
        <span>${escapeHtml(candidateDashboardEventLocationLabel(event))}</span>
        <span>${escapeHtml(mapReady ? "Map ready" : "Needs coordinates")}</span>
      </div>
      <h3>${escapeHtml(event.title)}</h3>
      <p>${escapeHtml(event.description || event.address || "Campaign event details.")}</p>
      <div class="shared-campaign-event-card__stats">
        <span><strong>${escapeHtml(formatCount(event.attendeeCount))}</strong><em>Going</em></span>
        <span><strong>${escapeHtml(formatCount(event.interestedCount))}</strong><em>Interested</em></span>
        <span><strong>${escapeHtml(event.isFree ? "Free" : formatEventCostAmount(event.costAmount || 0))}</strong><em>Cost</em></span>
      </div>
      ${
        event.tags.length
          ? `<div class="shared-card__tags">${event.tags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}</div>`
          : ""
      }
      ${
        map
          ? `<div class="shared-card__meta">
              <span>${escapeHtml(mapReady ? `${event.lat.toFixed(4)}, ${event.lng.toFixed(4)}` : "No coordinates")}</span>
              ${event.address ? `<span>${escapeHtml(event.address)}</span>` : ""}
            </div>`
          : ""
      }
      <div class="shared-card__actions">
        <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="/events/${escapeHtml(encodeURIComponent(event.eventId))}">Open</button>
        <button class="shared-feed-chip" type="button" data-action="candidate-events-edit" data-event-id="${escapeHtml(event.eventId)}"${disabledAttr(pendingSave || pendingDelete)}>Edit</button>
        <button class="shared-feed-chip" type="button" data-action="candidate-events-delete" data-event-id="${escapeHtml(event.eventId)}"${disabledAttr(pendingDelete)}>${pendingDelete ? "Deleting..." : "Delete"}</button>
      </div>
    </div>
  </article>`;
}

