function renderMissionWorkspaceClaimButton(
  missionId,
  job,
  resource,
  actionName,
) {
  if (!job?.isClaimable) {
    return "";
  }
  const pendingKey = `${missionId}:${job.jobId}:claim`;
  const pending = resource?.actionPendingKey === pendingKey;
  return `<button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="${escapeHtml(actionName)}" data-mission-id="${escapeHtml(missionId)}" data-job-id="${escapeHtml(job.jobId)}"${disabledAttr(pending)}>${pending ? "Claiming..." : "Claim"}</button>`;
}

function renderCandidateMissionStaffCommandAction(entry, resource, options = {}) {
  if (!entry) {
    return "";
  }
  const { mission, job } = entry;
  const jobAction = normalizeString(options.jobAction);
  const route = `/missions/${encodeURIComponent(mission.missionId)}?returnTo=${encodeURIComponent(getCurrentPathWithQuery())}`;
  const detailsButton = (primary = false, label = "Open details") =>
    `<button class="shared-feed-chip${primary ? " shared-feed-chip--primary" : ""}" type="button" data-action="navigate" data-route="${escapeHtml(route)}">${escapeHtml(label)}</button>`;
  if (!jobAction) {
    return detailsButton(true, "Open task");
  }
  const isMine = missionJobIsMine(job);
  const isUnclaimedRoleClaim =
    job.targetMode === "role_claim" && !job.assigneeUserId;
  const canWorkJob =
    !job.isQueued &&
    !isUnclaimedRoleClaim &&
    !job.isClosed &&
    job.status !== "submitted" &&
    !job.isBlocked &&
    isMine;
  const completionBlocker = missionJobCompletionBlocker(job);
  const requiresNote = missionJobHasRequiredNote(job);
  if (job.isClaimable) {
    return `${renderMissionWorkspaceJobActionButton({
      mission,
      job,
      action: "claim",
      actionName: jobAction,
      resource,
      primary: true,
    })}${detailsButton(false)}`;
  }
  if (
    canWorkJob &&
    ["active", "late", "needs_changes"].includes(job.status) &&
    !job.lastStartedAt
  ) {
    return `${renderMissionWorkspaceJobActionButton({
      mission,
      job,
      action: "start",
      actionName: jobAction,
      resource,
      primary: true,
    })}${detailsButton(false)}`;
  }
  if (canWorkJob && !completionBlocker && !requiresNote) {
    return `${renderMissionWorkspaceJobActionButton({
      mission,
      job,
      action: missionJobRequiresApproval(job) ? "submit" : "complete",
      actionName: jobAction,
      resource,
      primary: true,
    })}${detailsButton(false)}`;
  }
  return detailsButton(true, job.isSubmitted ? "View review" : "Open task");
}

function renderMissionWorkspaceJobActionButton({
  mission,
  job,
  action,
  actionName,
  resource,
  label = "",
  primary = false,
  disabled = false,
}) {
  const normalizedAction = normalizeString(action).toLowerCase();
  const config = missionJobActionConfig(normalizedAction, job);
  const pendingKey = missionJobActionPendingKey(
    mission.missionId,
    job.jobId,
    normalizedAction,
  );
  const currentPending = normalizeString(resource?.actionPendingKey);
  const pending = currentPending === pendingKey;
  return `<button class="shared-feed-chip${primary ? " shared-feed-chip--primary" : ""}" type="button" data-action="${escapeHtml(actionName)}" data-mission-id="${escapeHtml(mission.missionId)}" data-job-id="${escapeHtml(job.jobId)}" data-job-action="${escapeHtml(normalizedAction)}"${disabledAttr(disabled || Boolean(currentPending && !pending) || pending)}>${escapeHtml(pending ? "Updating..." : label || config.label)}</button>`;
}

function candidateMissionAdminActionRank(job = {}) {
  if (job.isLate) return 0;
  if (job.isBlocked) return 1;
  if (job.isSubmitted) return 2;
  if (job.status === "needs_changes") return 3;
  if (job.isDueSoon && job.isActive) return 4;
  if (job.isClaimable) return 5;
  if (job.isActive) return 6;
  if (job.isQueued) return 7;
  return 8;
}

function candidateMissionAdminActionItems(items = []) {
  return items
    .flatMap((mission) =>
      candidateMissionSortedJobs(mission.jobs || [])
        .filter((job) => !job.isClosed)
        .map((job) => ({ mission, job })),
    )
    .sort((left, right) => {
      const statusRank =
        candidateMissionAdminActionRank(left.job) -
        candidateMissionAdminActionRank(right.job);
      if (statusRank) {
        return statusRank;
      }
      const leftDue =
        left.job.dueAt || candidateMissionEarliestDue(left.mission) || Number.MAX_SAFE_INTEGER;
      const rightDue =
        right.job.dueAt || candidateMissionEarliestDue(right.mission) || Number.MAX_SAFE_INTEGER;
      if (leftDue !== rightDue) {
        return leftDue - rightDue;
      }
      return (right.mission.attentionCount || 0) - (left.mission.attentionCount || 0);
    });
}

function candidateMissionAdminCommandCopy(entry, counts, noun = "campaign") {
  if (!entry) {
    return {
      eyebrow: "Mission command",
      title: `${formatCount(counts.total)} ${noun} mission${counts.total === 1 ? "" : "s"} visible`,
      copy:
        "Blocked, submitted, claimable, and deadline-driven work will be prioritized here when missions are active.",
    };
  }
  const { mission, job } = entry;
  if (job.isLate) {
    return {
      eyebrow: "Late work",
      title: mission.title,
      copy: `${job.title} is past its deadline and should be handled before lower-risk work.`,
    };
  }
  if (job.isBlocked) {
    return {
      eyebrow: "Blocked",
      title: mission.title,
      copy: `${job.title} is blocking the mission. Move it forward or open the task for context.`,
    };
  }
  if (job.isSubmitted) {
    return {
      eyebrow: "Review ready",
      title: mission.title,
      copy: `${job.title} is waiting for approval before dependent work can continue.`,
    };
  }
  if (job.status === "needs_changes") {
    return {
      eyebrow: "Changes needed",
      title: mission.title,
      copy: `${job.title} needs a follow-up decision before the team can close it out.`,
    };
  }
  if (job.isDueSoon) {
    return {
      eyebrow: "Due soon",
      title: mission.title,
      copy: `${job.title} is the most time-sensitive open task in this workspace.`,
    };
  }
  if (job.isClaimable) {
    return {
      eyebrow: "Claimable role task",
      title: mission.title,
      copy: `${job.title} is waiting for an eligible team member to take ownership.`,
    };
  }
  if (job.isQueued) {
    return {
      eyebrow: "Queued dependency",
      title: mission.title,
      copy: `${job.title} is waiting on its start conditions before it becomes active.`,
    };
  }
  return {
    eyebrow: "Next open task",
    title: mission.title,
    copy: job.title,
  };
}

function renderCandidateMissionAdminCommandAction(entry, resource, options = {}) {
  const toggleAction = normalizeString(options.toggleAction);
  const jobAction = normalizeString(options.jobAction);
  const detailsButton = (route, primary = false, label = "Open mission") =>
    `<button class="shared-feed-chip${primary ? " shared-feed-chip--primary" : ""}" type="button" data-action="navigate" data-route="${escapeHtml(route)}">${escapeHtml(label)}</button>`;

  if (!entry) {
    return toggleAction
      ? `<button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="${escapeHtml(toggleAction)}">Plan mission</button>`
      : "";
  }

  const { mission, job } = entry;
  const route = `/missions/${encodeURIComponent(mission.missionId)}?returnTo=${encodeURIComponent(getCurrentPathWithQuery())}`;
  if (!jobAction) {
    return detailsButton(route, true);
  }
  if (job.isSubmitted) {
    return `${renderMissionWorkspaceJobActionButton({
      mission,
      job,
      action: "approve",
      actionName: jobAction,
      resource,
      primary: true,
    })}${detailsButton(route)}`;
  }
  if (job.isBlocked) {
    return `${renderMissionWorkspaceJobActionButton({
      mission,
      job,
      action: "unblock",
      actionName: jobAction,
      resource,
      primary: true,
    })}${detailsButton(route)}`;
  }
  if (job.isClaimable) {
    return `${renderMissionWorkspaceJobActionButton({
      mission,
      job,
      action: "claim",
      actionName: jobAction,
      resource,
      primary: true,
    })}${detailsButton(route)}`;
  }
  return detailsButton(route, true, job.isQueued ? "View dependency" : "Open task");
}

function renderCandidateMissionAdminQueueChip({
  label,
  count,
  action,
  dataAttr,
  dataValue,
  active,
}) {
  return `<button class="shared-campaign-mission-command-chip${active ? " is-active" : ""}" type="button" data-action="${escapeHtml(action)}" ${escapeHtml(dataAttr)}="${escapeHtml(dataValue)}">
    <span>${escapeHtml(label)}</span>
    <strong>${escapeHtml(formatCount(count))}</strong>
  </button>`;
}

function renderCandidateMissionAdminCommand(resource, items, options = {}) {
  const counts = missionListCounts(items);
  const actionItems = candidateMissionAdminActionItems(items);
  const priority = actionItems[0] || null;
  const command = candidateMissionAdminCommandCopy(priority, counts, options.noun);
  const viewAction = options.viewAction || "candidate-missions-view";
  const filterAction = options.filterAction || "candidate-missions-filter";
  const queuedCount = items.reduce(
    (sum, mission) =>
      sum + (mission.jobs || []).filter((job) => job.isQueued).length,
    0,
  );
  const completedCount = items.reduce(
    (sum, mission) => sum + mission.completedCount,
    0,
  );
  const totalJobs = items.reduce(
    (sum, mission) => sum + (mission.jobs || []).length,
    0,
  );
  const completion = totalJobs
    ? Math.round((completedCount / totalJobs) * 100)
    : 0;
  const queueChips = [
    renderCandidateMissionAdminQueueChip({
      label: "Review queue",
      count: counts.attention,
      action: filterAction,
      dataAttr: "data-filter",
      dataValue: "attention",
      active: resource.view === "attention" && resource.filter === "attention",
    }),
    renderCandidateMissionAdminQueueChip({
      label: "Claimable work",
      count: counts.claimable,
      action: filterAction,
      dataAttr: "data-filter",
      dataValue: "claimable",
      active: resource.view === "attention" && resource.filter === "claimable",
    }),
    renderCandidateMissionAdminQueueChip({
      label: "Due soon",
      count: counts.dueSoon,
      action: filterAction,
      dataAttr: "data-filter",
      dataValue: "soon",
      active: resource.view === "attention" && resource.filter === "soon",
    }),
    renderCandidateMissionAdminQueueChip({
      label: "Board view",
      count: counts.open,
      action: viewAction,
      dataAttr: "data-view",
      dataValue: "board",
      active: resource.view === "board",
    }),
    renderCandidateMissionAdminQueueChip({
      label: "People load",
      count: candidateMissionWorkloads(items).length,
      action: viewAction,
      dataAttr: "data-view",
      dataValue: "people",
      active: resource.view === "people",
    }),
    renderCandidateMissionAdminQueueChip({
      label: "Templates",
      count: resource.templates?.length || 0,
      action: viewAction,
      dataAttr: "data-view",
      dataValue: "templates",
      active: resource.view === "templates",
    }),
  ].join("");
  return `<section class="shared-campaign-mission-admin-command">
    <div class="shared-campaign-mission-admin-command__main">
      <span class="shared-campaign-mission-admin-command__icon">${renderIcon(priority?.job?.isBlocked ? "flag" : priority?.job?.isSubmitted ? "check" : "mission")}</span>
      <div>
        <small>${escapeHtml(command.eyebrow)}</small>
        <strong class="shared-campaign-mission-admin-command__title">${escapeHtml(command.title)}</strong>
        <p>${escapeHtml(command.copy)}</p>
      </div>
      <div class="shared-campaign-mission-admin-command__actions">
        ${renderCandidateMissionAdminCommandAction(priority, resource, options)}
      </div>
    </div>
    <div class="shared-campaign-mission-admin-command__metrics">
      <div><span>Visible</span><strong>${escapeHtml(formatCount(counts.total))}</strong></div>
      <div><span>Open</span><strong>${escapeHtml(formatCount(counts.open))}</strong></div>
      <div><span>Submitted</span><strong>${escapeHtml(formatCount(counts.submitted))}</strong></div>
      <div><span>Queued</span><strong>${escapeHtml(formatCount(queuedCount))}</strong></div>
      <div><span>Complete</span><strong>${escapeHtml(`${completion}%`)}</strong></div>
    </div>
    <div class="shared-campaign-mission-admin-command__queues">
      ${queueChips}
    </div>
  </section>`;
}

function renderMissionWorkspaceJobPanel(mission, job, options = {}) {
  const actionName = normalizeString(options.jobAction);
  if (!job || !actionName) {
    return "";
  }
  const resource =
    options.resource || state.pages.candidateDashboard.detail.missionsWorkspace;
  const canManage = options.canManage === true;
  const isMine = missionJobIsMine(job);
  const isUnclaimedRoleClaim =
    job.targetMode === "role_claim" && !job.assigneeUserId;
  const canWorkJob =
    !job.isQueued &&
    !isUnclaimedRoleClaim &&
    !job.isClosed &&
    (isMine || canManage);
  const completionBlocker = missionJobCompletionBlocker(job);
  const requiresNote = missionJobHasRequiredNote(job);
  const actions = [];
  const route = `/missions/${encodeURIComponent(mission.missionId)}?returnTo=${encodeURIComponent(getCurrentPathWithQuery())}`;

  if (job.isClaimable) {
    actions.push(
      renderMissionWorkspaceJobActionButton({
        mission,
        job,
        action: "claim",
        actionName,
        resource,
        primary: true,
      }),
    );
  }

  if (canWorkJob && job.status !== "submitted" && !job.isBlocked) {
    if (
      ["active", "late", "needs_changes"].includes(job.status) &&
      !job.lastStartedAt
    ) {
      actions.push(
        renderMissionWorkspaceJobActionButton({
          mission,
          job,
          action: "start",
          actionName,
          resource,
        }),
      );
    }
    const completionAction = missionJobRequiresApproval(job)
      ? "submit"
      : "complete";
    if (!completionBlocker && !requiresNote) {
      actions.push(
        renderMissionWorkspaceJobActionButton({
          mission,
          job,
          action: completionAction,
          actionName,
          resource,
          primary: true,
        }),
      );
    }
  }

  if (job.status === "submitted" && canManage) {
    actions.push(
      renderMissionWorkspaceJobActionButton({
        mission,
        job,
        action: "approve",
        actionName,
        resource,
        primary: true,
      }),
    );
  }

  if (job.isBlocked && canManage) {
    actions.push(
      renderMissionWorkspaceJobActionButton({
        mission,
        job,
        action: "unblock",
        actionName,
        resource,
      }),
    );
  }

  actions.push(
    `<button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(route)}">Details</button>`,
  );

  const helper = completionBlocker
    ? completionBlocker
    : requiresNote && canWorkJob
      ? "Open details to submit this task with the required note."
      : job.status === "submitted"
        ? "Submitted and waiting for review."
        : job.isBlocked
          ? "Blocked. Open details for support actions and notes."
          : job.isQueued
            ? "Queued until its start conditions are met."
            : "";
  const meta = [
    missionJobOwnerLabel(job),
    job.dueAt ? `Due ${formatAbsoluteDateTime(job.dueAt)}` : "",
    mission.jobs.length
      ? `${formatCount(mission.completedCount)} of ${formatCount(mission.jobs.length)} tasks`
      : "",
  ].filter(Boolean);

  return `<div class="shared-campaign-mission-card__task">
    <div class="shared-campaign-mission-card__task-top">
      <div>
        <span>Next task</span>
        <strong>${escapeHtml(job.title)}</strong>
      </div>
      ${renderMissionBadge(messagingMissionStatusLabel(job.status), missionStatusTone(job.status))}
    </div>
    ${meta.length ? `<div class="shared-campaign-mission-card__task-meta">${meta.map((item) => `<span>${escapeHtml(item)}</span>`).join("")}</div>` : ""}
    ${actions.length ? `<div class="shared-campaign-mission-card__task-actions">${actions.join("")}</div>` : ""}
    ${helper ? `<p>${escapeHtml(helper)}</p>` : ""}
  </div>`;
}

function renderCandidateMissionCard(mission, options = {}) {
  const nextJob = missionNextJob(mission);
  const progress = missionCompletionPercent(mission);
  const compact = options.compact === true;
  const resource =
    options.resource || state.pages.candidateDashboard.detail.missionsWorkspace;
  const claimAction = options.claimAction || "candidate-mission-job-claim";
  const jobAction = normalizeString(options.jobAction);
  const returnTo = encodeURIComponent(getCurrentPathWithQuery());
  const route = `/missions/${encodeURIComponent(mission.missionId)}?returnTo=${returnTo}`;
  const meta = [
    humanizeLabel(mission.priority),
    mission.dueAt ? `Due ${formatAbsoluteDateTime(mission.dueAt)}` : "",
    nextJob ? `Next: ${nextJob.title}` : "",
  ].filter(Boolean);
  return `<article class="shared-campaign-mission-card${compact ? " is-compact" : ""}">
    <div class="shared-campaign-mission-card__top">
      <button class="shared-campaign-mission-card__open" type="button" data-action="navigate" data-route="${escapeHtml(route)}">
        <span class="shared-campaign-mission-card__icon">${renderIcon("mission")}</span>
        <span class="shared-campaign-mission-card__body">
          <span class="shared-card__meta">${meta.map((item) => `<span>${escapeHtml(item)}</span>`).join("")}</span>
          <strong>${escapeHtml(mission.title)}</strong>
          <span>${escapeHtml(mission.description || (nextJob ? missionJobOwnerLabel(nextJob) : "Mission details and task progress"))}</span>
        </span>
      </button>
      <div class="shared-campaign-mission-card__actions">
        ${renderMissionBadge(humanizeLabel(mission.status), missionStatusTone(mission.status))}
        ${
          jobAction
            ? ""
            : renderMissionWorkspaceClaimButton(
                mission.missionId,
                nextJob,
                resource,
                claimAction,
              )
        }
      </div>
    </div>
    ${renderMissionWorkspaceJobPanel(mission, nextJob, {
      ...options,
      resource,
      jobAction,
    })}
    <div class="shared-mission-progress" aria-label="${escapeHtml(`${progress}% complete`)}"><span style="width: ${Math.max(0, Math.min(100, progress))}%"></span></div>
    <div class="shared-campaign-mission-card__metrics">
      <span>${escapeHtml(formatCount(mission.openCount))} open</span>
      <span>${escapeHtml(formatCount(mission.attentionCount))} attention</span>
      <span>${escapeHtml(formatCount(mission.claimableCount))} claimable</span>
      <span>${escapeHtml(`${progress}% complete`)}</span>
    </div>
  </article>`;
}

function renderCandidateMissionSection(
  title,
  subtitle,
  missions,
  emptyText,
  options = {},
) {
  return `<article class="shared-campaign-panel shared-campaign-mission-section">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>${escapeHtml(title)}</h2>
        ${subtitle ? `<p>${escapeHtml(subtitle)}</p>` : ""}
      </div>
      <span class="shared-mission-badge">${escapeHtml(formatCount(missions.length))}</span>
    </div>
    <div class="shared-campaign-mission-list">
      ${
        missions.length
          ? missions
              .map((mission) => renderCandidateMissionCard(mission, options))
              .join("")
          : `<div class="shared-page__empty">${escapeHtml(emptyText || "No missions in this section.")}</div>`
      }
    </div>
  </article>`;
}

function missionCreateAssigneePeople(scopeType, scopeId) {
  const normalizedScopeType = normalizeMissionScopeType(scopeType);
  const normalizedScopeId = normalizeString(scopeId);
  const seen = new Set();
  const people = [];
  const addPerson = (source = {}, fallbackRole = "") => {
    const userId = normalizeString(source.userId || source.id);
    if (!userId || seen.has(userId)) {
      return;
    }
    seen.add(userId);
    people.push({
      value: userId,
      label:
        normalizeString(source.displayName || source.name || source.username) ||
        "Team member",
      meta:
        normalizeString(source.roleLabel || source.role || fallbackRole) ||
        (source.username
          ? `@${normalizeString(source.username).replace(/^@/u, "")}`
          : "Person"),
    });
  };
  if (normalizedScopeType === "candidate") {
    const detail = state.pages.candidateDashboard.detail;
    if (
      normalizedScopeId &&
      normalizeString(state.auth.user?.userId) === normalizedScopeId
    ) {
      const authDisplayName = normalizeString(state.auth.user?.displayName);
      const authEmail = normalizeString(state.auth.user?.email);
      const authUsername = normalizeString(state.auth.user?.username).replace(
        /^@/u,
        "",
      );
      addPerson(
        {
          userId: normalizedScopeId,
          displayName:
            normalizeString(detail.candidate?.displayName) ||
            (authDisplayName && authDisplayName !== authEmail
              ? authDisplayName
              : "") ||
            (authUsername ? `@${authUsername}` : "") ||
            "Candidate owner",
          username: state.auth.user?.username || detail.candidate?.username,
        },
        "Owner",
      );
    }
    detail.staff.slice(0, 10).forEach((member) => addPerson(member, "Staff"));
    (detail.volunteers?.items || [])
      .slice(0, 8)
      .forEach((volunteer) => addPerson(volunteer, "Volunteer"));
  } else if (normalizedScopeType === "coalition") {
    state.pages.coalitions.detail.members
      .slice(0, 14)
      .forEach((member) => addPerson(member, "Member"));
  }
  return people.slice(0, 14);
}

function missionCreateAssigneeRoles(scopeType) {
  const normalizedScopeType = normalizeMissionScopeType(scopeType);
  const seen = new Set();
  const roles = [];
  const addRole = (role = {}, fallbackCategory = "") => {
    const roleKey = normalizeString(
      role.roleKey || role.key || role.role || role.label,
    );
    if (!roleKey || seen.has(roleKey)) {
      return;
    }
    seen.add(roleKey);
    roles.push({
      value: roleKey,
      label:
        normalizeString(role.label || role.roleLabel || role.name) ||
        humanizeLabel(roleKey),
      meta: normalizeString(role.category || role.roleCategory || fallbackCategory),
    });
  };
  if (normalizedScopeType === "candidate") {
    const detail = state.pages.candidateDashboard.detail;
    const catalog =
      detail.staffAdmin?.catalog || normalizeCandidateStaffAccessCatalog({});
    candidateStaffAssignableRoles(catalog)
      .slice(0, 8)
      .forEach((role) => addRole(role, "Campaign role"));
    const staffRoles = new Map();
    detail.staff.forEach((member) => {
      const roleKey = normalizeCandidateStaffRoleKey(
        member.roleKey || member.role || member.roleLabel,
      );
      if (!roleKey || staffRoles.has(roleKey)) {
        return;
      }
      staffRoles.set(roleKey, {
        roleKey,
        label:
          normalizeString(member.roleLabel || member.role || member.roleKey) ||
          humanizeLabel(roleKey),
        category: normalizeString(member.roleCategory) || "Staff role",
      });
    });
    Array.from(staffRoles.values())
      .slice(0, 8)
      .forEach((role) => addRole(role, "Staff role"));
    const volunteerTags = Array.from(
      new Set(
        (detail.volunteers?.items || [])
          .flatMap((volunteer) => volunteer.roleTags || [])
          .map(normalizeCandidateStaffRoleKey)
          .filter(Boolean),
      ),
    );
    volunteerTags
      .slice(0, 6)
      .forEach((tag) =>
        addRole({ roleKey: tag, label: humanizeLabel(tag) }, "Volunteer group"),
      );
  } else if (normalizedScopeType === "coalition") {
    const detail = state.pages.coalitions.detail;
    const catalog =
      detail.accessWorkspace?.catalog || normalizeCoalitionAccessCatalog({});
    (catalog.roles?.length
      ? catalog.roles
      : COALITION_ROLE_FALLBACKS.map(normalizeCoalitionAccessRole)
    )
      .slice(0, 10)
      .forEach((role) => addRole(role, "Coalition role"));
  }
  if (!roles.length) {
    if (normalizedScopeType === "coalition") {
      COALITION_ROLE_FALLBACKS.slice(0, 4).forEach((role) =>
        addRole(normalizeCoalitionAccessRole(role), "Coalition role"),
      );
    } else {
      CANDIDATE_STAFF_FALLBACK_ROLES.slice(0, 4).forEach((role) =>
        addRole(normalizeCandidateStaffRole(role), "Campaign role"),
      );
    }
  }
  return roles.slice(0, 12);
}

function renderMissionCreateAssigneeOption(option, mode, targetModeKey, assignee) {
  const resolvedMode =
    mode === "role"
      ? targetModeKey === "role_fanout"
        ? "role_fanout"
        : "role_claim"
      : mode;
  const selected =
    normalizeString(option.value) === assignee &&
    (mode === "role" ? targetModeKey !== "user" : targetModeKey === mode);
  return `<button class="shared-campaign-mission-target-option${selected ? " is-active" : ""}" type="button" data-action="mission-create-target-select" data-target-mode="${escapeHtml(mode)}" data-resolved-target-mode="${escapeHtml(resolvedMode)}" data-assignee="${escapeHtml(option.value)}" data-label="${escapeHtml(option.label)}" data-meta="${escapeHtml(option.meta || (resolvedMode === "user" ? "Person" : "Role"))}" aria-pressed="${selected ? "true" : "false"}">
    <span>${renderIcon(resolvedMode === "user" ? "candidate" : "team")}</span>
    <strong>${escapeHtml(option.label)}</strong>
    <small>${escapeHtml(option.meta || (resolvedMode === "user" ? "Person" : "Role"))}</small>
  </button>`;
}

function renderMissionCreateAssigneePicker({
  scopeType,
  scopeId,
  targetModeKey,
  assignee,
  heading = "Lead owner",
  people: peopleOverride = null,
  roles: rolesOverride = null,
}) {
  const people = Array.isArray(peopleOverride)
    ? peopleOverride
    : missionCreateAssigneePeople(scopeType, scopeId);
  const roles = Array.isArray(rolesOverride)
    ? rolesOverride
    : missionCreateAssigneeRoles(scopeType, scopeId);
  const selectedPerson = people.find(
    (person) => targetModeKey === "user" && person.value === assignee,
  );
  const selectedRole = roles.find(
    (role) => targetModeKey !== "user" && role.value === assignee,
  );
  const selectedLabel =
    selectedPerson?.label ||
    selectedRole?.label ||
    (assignee
      ? targetModeKey === "user"
        ? "Manual person"
        : "Manual role"
      : "No target selected");
  const selectedMeta =
    selectedPerson?.meta ||
    selectedRole?.meta ||
    (assignee
      ? targetModeKey === "user"
        ? "The backend will verify this user id or username."
        : "The backend will verify this role key."
      : "Choose a person or role before publishing.");
  const roleModeLabel =
    targetModeKey === "role_fanout" ? "Fan-out role" : "Claimable role";
  return `<section class="shared-campaign-mission-target-picker">
    <div class="shared-campaign-mission-target-picker__header">
      <div>
        <strong>${escapeHtml(heading)}</strong>
        <span data-mission-target-summary>${escapeHtml(`${selectedLabel} - ${selectedMeta}`)}</span>
      </div>
      <button class="shared-feed-chip shared-campaign-mission-target-fanout${targetModeKey === "role_fanout" ? " is-active" : ""}" type="button" data-action="mission-create-target-select" data-target-mode="role_fanout" data-resolved-target-mode="role_fanout" data-assignee="${escapeHtml(roles[0]?.value || "all")}" data-label="${escapeHtml(roles[0]?.label || "All eligible members")}" data-meta="Each eligible person gets a task" aria-pressed="${targetModeKey === "role_fanout" ? "true" : "false"}">Fan out role</button>
    </div>
    <div class="shared-campaign-mission-target-columns">
      <div class="shared-campaign-mission-target-column">
        <div class="shared-card__meta"><span>People</span><span>${escapeHtml(formatCount(people.length))}</span></div>
        <div class="shared-campaign-mission-target-options">
          ${
            people.length
              ? people
                  .map((person) =>
                    renderMissionCreateAssigneeOption(
                      person,
                      "user",
                      targetModeKey,
                      assignee,
                    ),
                  )
                  .join("")
              : '<div class="shared-page__empty">No roster people are loaded yet.</div>'
          }
        </div>
      </div>
      <div class="shared-campaign-mission-target-column">
        <div class="shared-card__meta"><span>${escapeHtml(roleModeLabel)}</span><span>${escapeHtml(formatCount(roles.length))}</span></div>
        <div class="shared-campaign-mission-target-options">
          ${
            roles.length
              ? roles
                  .map((role) =>
                    renderMissionCreateAssigneeOption(
                      role,
                      "role",
                      targetModeKey,
                      assignee,
                    ),
                  )
                  .join("")
              : '<div class="shared-page__empty">No roles are loaded yet.</div>'
          }
        </div>
      </div>
    </div>
  </section>`;
}

function renderCandidateMissionCreateForm(resource, options = {}) {
  const draft = resource.createDraft || {};
  const presetKey = normalizeString(draft.presetKey) || "general";
  const priorityKey = normalizeString(draft.priority).toLowerCase() || "normal";
  const targetModeKey =
    normalizeString(draft.targetMode).toLowerCase() || "user";
  const assignee = normalizeString(draft.assignee);
  const deadlineModeKey =
    normalizeString(draft.deadlineMode).toLowerCase() || "indefinite";
  const timeoutPolicyKey =
    normalizeString(draft.timeoutPolicy).toLowerCase() || "escalate";
  const pending = resource.actionPendingKey === "create";
  const formKind = options.formKind || "candidate-missions-create";
  const toggleAction = options.toggleAction || "candidate-missions-create-toggle";
  const noun = options.noun || "campaign";
  const scopeType = normalizeMissionScopeType(options.scopeType);
  const scopeId = normalizeString(options.scopeId);
  return `<form class="shared-form shared-campaign-mission-create" data-route-form="${escapeHtml(formKind)}">
    <input type="hidden" name="templateId" value="${escapeHtml(draft.templateId || "")}" />
    <input type="hidden" name="templateVersion" value="${escapeHtml(draft.templateVersion || "")}" />
    ${scopeType && scopeId ? `<input type="hidden" name="scopeType" value="${escapeHtml(scopeType)}" /><input type="hidden" name="scopeId" value="${escapeHtml(scopeId)}" />` : ""}
    <input type="hidden" name="assignee" value="${escapeHtml(assignee)}" />
    <input type="hidden" name="targetMode" value="${escapeHtml(targetModeKey)}" />
    <div class="shared-campaign-mission-create__header">
      <div>
        <h2>${draft.templateId ? "Create from template" : "New mission"}</h2>
        <p>Publish a ${escapeHtml(noun)} mission with one lead task. Add follow-up tasks and files from the mission detail after it is created.</p>
      </div>
      <button class="shared-feed-chip" type="button" data-action="${escapeHtml(toggleAction)}"${disabledAttr(pending)}>Cancel</button>
    </div>
    <div class="shared-campaign-mission-form-grid">
      <label>
        <span>Mission objective</span>
        <input name="title" value="${escapeHtml(draft.title || "")}" placeholder="Print GOTV walk cards"${disabledAttr(pending)} required />
      </label>
      <label>
        <span>Preset</span>
        <select name="presetKey"${disabledAttr(pending)}>
          ${MISSION_PRESETS.map(
            (preset) =>
              `<option value="${escapeHtml(preset.key)}"${selectedAttr(preset.key === presetKey)}>${escapeHtml(preset.label)}</option>`,
          ).join("")}
        </select>
      </label>
      <label>
        <span>Priority</span>
        <select name="priority"${disabledAttr(pending)}>
          ${["low", "normal", "high", "urgent"]
            .map(
              (priority) =>
                `<option value="${escapeHtml(priority)}"${selectedAttr(priority === priorityKey)}>${escapeHtml(humanizeLabel(priority))}</option>`,
            )
            .join("")}
        </select>
      </label>
      <label>
        <span>Deadline</span>
        <select name="deadlineMode"${disabledAttr(pending)}>
          <option value="indefinite"${selectedAttr(deadlineModeKey === "indefinite")}>No deadline</option>
          <option value="due_at"${selectedAttr(deadlineModeKey === "due_at")}>Due in hours</option>
          <option value="duration_after_activation"${selectedAttr(deadlineModeKey === "duration_after_activation")}>Hours after activation</option>
        </select>
      </label>
      <label>
        <span>Hours</span>
        <input name="dueHours" type="number" min="0" step="1" value="${escapeHtml(draft.dueHours || "")}" placeholder="48"${disabledAttr(pending)} />
      </label>
      <label>
        <span>Timeout action</span>
        <select name="timeoutPolicy"${disabledAttr(pending)}>
          <option value="escalate"${selectedAttr(timeoutPolicyKey === "escalate")}>Escalate</option>
          <option value="none"${selectedAttr(timeoutPolicyKey === "none")}>None</option>
          <option value="auto_unassign"${selectedAttr(timeoutPolicyKey === "auto_unassign")}>Auto-unassign</option>
          <option value="auto_fail"${selectedAttr(timeoutPolicyKey === "auto_fail")}>Auto-fail</option>
        </select>
      </label>
      <label>
        <span>Timeout grace hours</span>
        <input name="timeoutHours" type="number" min="0" step="1" value="${escapeHtml(draft.timeoutHours || "")}" placeholder="24"${disabledAttr(pending)} />
      </label>
      <label class="shared-campaign-mission-create__description">
        <span>Context for the team</span>
        <textarea name="description" rows="4" placeholder="What should the assignee know before starting?"${disabledAttr(pending)}>${escapeHtml(draft.description || "")}</textarea>
      </label>
    </div>
    ${renderMissionCreateAssigneePicker({
      scopeType,
      scopeId,
      targetModeKey,
      assignee,
    })}
    <div class="shared-campaign-mission-create__preset">
      <strong>${escapeHtml(missionPresetForKey(presetKey).label)}</strong>
      <span>${escapeHtml(missionPresetForKey(presetKey).description)}</span>
    </div>
    <div class="shared-campaign-mission-create__actions">
      <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(pending)}>${pending ? "Publishing..." : "Publish mission"}</button>
    </div>
  </form>`;
}

function missionCreateResourceForFormKind(formKind) {
  const normalizedFormKind = normalizeString(formKind);
  if (normalizedFormKind === "missions-create") {
    return state.pages.missions.list;
  }
  if (normalizedFormKind === "coalition-missions-create") {
    return state.pages.coalitions.detail.missionsWorkspace;
  }
  if (normalizedFormKind === "candidate-missions-create") {
    return state.pages.candidateDashboard.detail.missionsWorkspace;
  }
  return null;
}

function syncMissionCreateDraftFromForm(form) {
  const resource = missionCreateResourceForFormKind(
    form?.getAttribute("data-route-form"),
  );
  if (!resource || !form) {
    return null;
  }
  const formData = new FormData(form);
  resource.createDraft = {
    ...(resource.createDraft || {}),
    templateId: normalizeString(formData.get("templateId")),
    templateVersion: normalizeString(formData.get("templateVersion")),
    title: normalizeString(formData.get("title")),
    presetKey: normalizeString(formData.get("presetKey")),
    priority: normalizeString(formData.get("priority")),
    assignee: normalizeString(formData.get("assignee")),
    targetMode: normalizeString(formData.get("targetMode")),
    deadlineMode: normalizeString(formData.get("deadlineMode")),
    dueHours: normalizeString(formData.get("dueHours")),
    timeoutPolicy: normalizeString(formData.get("timeoutPolicy")),
    timeoutHours: normalizeString(formData.get("timeoutHours")),
    description: normalizeString(formData.get("description")),
  };
  return resource.createDraft;
}

function missionTemplateResourceForFormKind(formKind) {
  const normalizedFormKind = normalizeString(formKind);
  if (normalizedFormKind === "coalition-missions-template-save") {
    return state.pages.coalitions.detail.missionsWorkspace;
  }
  if (normalizedFormKind === "candidate-missions-template-save") {
    return state.pages.candidateDashboard.detail.missionsWorkspace;
  }
  return null;
}

function syncMissionTemplateDraftFromForm(form) {
  const resource = missionTemplateResourceForFormKind(
    form?.getAttribute("data-route-form"),
  );
  if (!resource || !form) {
    return null;
  }
  const formData = new FormData(form);
  const templateId = normalizeString(formData.get("templateId"));
  const targetMode =
    normalizeString(formData.get("targetMode")).toLowerCase() || "user";
  const assignee = normalizeString(formData.get("assignee"));
  const existingConfig =
    resource.templateDraft?.config &&
    typeof resource.templateDraft.config === "object"
      ? resource.templateDraft.config
      : {};
  const remainingConfig = { ...existingConfig };
  delete remainingConfig.assignee;
  delete remainingConfig.target;
  resource.templateDraft = {
    ...(resource.templateDraft || {}),
    templateId,
    title: normalizeString(formData.get("title")),
    description: normalizeString(formData.get("description")),
    presetKey:
      normalizeString(formData.get("presetKey")).toLowerCase() || "general",
    priority:
      normalizeString(formData.get("priority")).toLowerCase() || "normal",
    targetMode,
    assignee,
    deadlineMode:
      normalizeString(formData.get("deadlineMode")).toLowerCase() ||
      "indefinite",
    dueHours: normalizeString(formData.get("dueHours")),
    timeoutPolicy:
      normalizeString(formData.get("timeoutPolicy")).toLowerCase() ||
      "escalate",
    timeoutHours: normalizeString(formData.get("timeoutHours")),
    config: {
      ...remainingConfig,
      presetKey:
        normalizeString(formData.get("presetKey")).toLowerCase() || "general",
      priority:
        normalizeString(formData.get("priority")).toLowerCase() || "normal",
      targetMode,
      ...(assignee ? { assignee } : {}),
      ...(assignee
        ? { target: candidateMissionTargetPayload(targetMode, assignee) }
        : {}),
      deadlineMode:
        normalizeString(formData.get("deadlineMode")).toLowerCase() ||
        "indefinite",
      dueHours: normalizeString(formData.get("dueHours")),
      timeoutPolicy:
        normalizeString(formData.get("timeoutPolicy")).toLowerCase() ||
        "escalate",
      timeoutHours: normalizeString(formData.get("timeoutHours")),
    },
  };
  return resource.templateDraft;
}

