function candidateMissionJobDepth(job, jobsById) {
  let depth = 0;
  let current = job;
  const seen = new Set();
  while (current?.parentJobId && jobsById.has(current.parentJobId) && depth < 4) {
    if (seen.has(current.parentJobId)) break;
    seen.add(current.parentJobId);
    current = jobsById.get(current.parentJobId);
    depth += 1;
  }
  return depth;
}

function renderCandidateMissionTimelineView(items) {
  const sorted = [...items].sort(
    (left, right) =>
      (candidateMissionEarliestDue(left) || Number.MAX_SAFE_INTEGER) -
      (candidateMissionEarliestDue(right) || Number.MAX_SAFE_INTEGER),
  );
  return `<article class="shared-campaign-panel shared-campaign-mission-timeline">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Timeline</h2>
        <p>Dependency-gated work is visible here before staffers receive it.</p>
      </div>
    </div>
    <div class="shared-campaign-mission-timeline__list">
      ${
        sorted.length
          ? sorted
              .map((mission) => {
                const jobs = candidateMissionSortedJobs(mission.jobs || []);
                const jobsById = new Map(jobs.map((job) => [job.jobId, job]));
                return `<article class="shared-campaign-mission-timeline-card">
                  <button type="button" data-action="navigate" data-route="/missions/${escapeHtml(encodeURIComponent(mission.missionId))}?returnTo=${escapeHtml(encodeURIComponent(getCurrentPathWithQuery()))}">
                    <strong>${escapeHtml(mission.title)}</strong>
                    <span>${escapeHtml(`${humanizeLabel(mission.status)} - ${formatCount(jobs.length)} task${jobs.length === 1 ? "" : "s"}`)}</span>
                  </button>
                  <div class="shared-campaign-mission-timeline-jobs">
                    ${
                      jobs.length
                        ? jobs
                            .map((job) => {
                              const parent = job.parentJobId
                                ? jobsById.get(job.parentJobId)
                                : null;
                              const depth = candidateMissionJobDepth(job, jobsById);
                              return `<div class="shared-campaign-mission-timeline-job" style="--mission-depth: ${depth}">
                                <span>${renderMissionBadge(humanizeLabel(job.status), missionStatusTone(job.status))}</span>
                                <div>
                                  <strong>${escapeHtml(job.title)}</strong>
                                  <small>${escapeHtml([
                                    missionJobOwnerLabel(job),
                                    job.dueAt ? `Due ${formatAbsoluteDateTime(job.dueAt)}` : "",
                                  ].filter(Boolean).join(" - "))}</small>
                                  ${parent ? `<small>Starts after ${escapeHtml(parent.title)}</small>` : ""}
                                </div>
                              </div>`;
                            })
                            .join("")
                        : '<div class="shared-page__empty">No tasks have been added yet.</div>'
                    }
                  </div>
                </article>`;
              })
              .join("")
          : '<div class="shared-page__empty">No mission timeline is visible.</div>'
      }
    </div>
  </article>`;
}

function candidateMissionEventDetail(event, key) {
  return normalizeString(event?.details?.[key]);
}

function renderCandidateMissionAuditView(items) {
  const entries = items
    .flatMap((mission) => {
      const jobsById = new Map((mission.jobs || []).map((job) => [job.jobId, job]));
      return (mission.recentEvents || []).map((event) => ({
        mission,
        event,
        job: jobsById.get(candidateMissionEventDetail(event, "jobId")) || null,
      }));
    })
    .sort((left, right) => (right.event.createdAt || 0) - (left.event.createdAt || 0));
  return `<article class="shared-campaign-panel shared-campaign-mission-audit">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Audit</h2>
        <p>Recent assignment, approval, timing, and override activity.</p>
      </div>
    </div>
    <div class="shared-campaign-mission-audit__list">
      ${
        entries.length
          ? entries
              .slice(0, 60)
              .map(
                ({ mission, event, job }) => `<button type="button" data-action="navigate" data-route="/missions/${escapeHtml(encodeURIComponent(mission.missionId))}?returnTo=${escapeHtml(encodeURIComponent(getCurrentPathWithQuery()))}">
                  <span>${renderIcon("mission")}</span>
                  <strong>${escapeHtml(humanizeLabel(event.type))}</strong>
                  <em>${escapeHtml(mission.title)}</em>
                  <small>${escapeHtml([
                    job?.title,
                    event.actorUserId ? `by ${event.actorUserId}` : "",
                    event.createdAt ? formatAbsoluteDateTime(event.createdAt) : "",
                  ].filter(Boolean).join(" - "))}</small>
                </button>`,
              )
              .join("")
          : '<div class="shared-page__empty">No audit activity yet.</div>'
      }
    </div>
  </article>`;
}

function renderCandidateMissionStaffCommand(resource, options = {}) {
  const items = resource.items || [];
  const actionItems = candidateMissionStaffActionItems(items);
  const priority = actionItems[0] || null;
  const command = candidateMissionStaffCommandCopy(priority);
  const openCount = items.reduce((sum, mission) => sum + mission.openCount, 0);
  const claimableCount = actionItems.filter(({ job }) => job.isClaimable).length;
  const dueSoonCount = actionItems.filter(({ job }) => job.isDueSoon).length;
  const submittedCount = actionItems.filter(({ job }) => job.isSubmitted).length;
  return `<section class="shared-campaign-mission-staff-command">
    <div class="shared-campaign-mission-staff-command__main">
      <div class="shared-campaign-mission-staff-command__next">
        <span>${renderIcon(priority?.job?.isClaimable ? "team" : "mission")}</span>
        <div>
          <small>${escapeHtml(command.eyebrow)}</small>
          <h3>${escapeHtml(command.title)}</h3>
          <p>${escapeHtml(command.copy)}</p>
        </div>
      </div>
      <div class="shared-campaign-mission-staff-command__actions">
        ${renderCandidateMissionStaffCommandAction(priority, resource, options)}
      </div>
    </div>
    <div class="shared-campaign-mission-staff-command__metrics">
      <div><span>Visible missions</span><strong>${escapeHtml(formatCount(items.length))}</strong></div>
      <div><span>Open tasks</span><strong>${escapeHtml(formatCount(openCount))}</strong></div>
      <div><span>Claimable</span><strong>${escapeHtml(formatCount(claimableCount))}</strong></div>
      <div><span>Due soon</span><strong>${escapeHtml(formatCount(dueSoonCount))}</strong></div>
      <div><span>In review</span><strong>${escapeHtml(formatCount(submittedCount))}</strong></div>
    </div>
  </section>`;
}

function renderCandidateMissionActiveView(resource, canManage, options = {}) {
  if (!canManage) {
    const groups = candidateMissionStaffGroups(resource.items).filter(
      (group) => group.items.length || group.key !== "other",
    );
    return `<div class="shared-campaign-mission-workspace">
      ${renderCandidateMissionStaffCommand(resource, options)}
      ${
        groups.length
          ? groups
              .map((group) =>
                renderCandidateMissionSection(
                  group.title,
                  group.subtitle,
                  group.items,
                  group.empty,
                  options,
                ),
              )
              .join("")
          : '<div class="shared-page__empty">No active missions are visible.</div>'
      }
    </div>`;
  }
  if (resource.view === "board") {
    return renderCandidateMissionBoardView(resource.items, options);
  }
  if (resource.view === "people") {
    return renderCandidateMissionPeopleView(resource.items);
  }
  if (resource.view === "templates") {
    return renderCandidateMissionTemplatesView(resource, options);
  }
  if (resource.view === "timeline") {
    return renderCandidateMissionTimelineView(resource.items);
  }
  if (resource.view === "audit") {
    return renderCandidateMissionAuditView(resource.items);
  }
  return renderCandidateMissionAttentionView(resource, options);
}

function renderMissionWorkspaceShell({
  resource,
  items,
  canManage,
  scopeType,
  scopeId,
  eyebrow,
  title,
  description,
  loadingLabel,
  refreshAction,
  createToggleAction,
  viewAction,
  filterAction,
  usePresetAction,
  claimAction,
  formKind,
  noun,
}) {
  const openCount = items.reduce((sum, mission) => sum + mission.openCount, 0);
  const attentionCount = items.reduce(
    (sum, mission) => sum + mission.attentionCount,
    0,
  );
  const claimableCount = items.reduce(
    (sum, mission) => sum + mission.claimableCount,
    0,
  );
  const dueSoonCount = items.reduce(
    (sum, mission) =>
      sum + (mission.jobs || []).filter((job) => job.isDueSoon).length,
    0,
  );
  resource.view = normalizeCandidateMissionHubView(resource.view, canManage);
  const resolvedDescription = canManage
    ? description
    : `Review assigned and claimable ${noun} missions, open the next task, and keep blockers or submitted work visible from this web hub.`;
  const templateActionPrefix =
    scopeType === "coalition"
      ? "coalition-missions-template"
      : "candidate-missions-template";
  const actionOptions = {
    resource,
    claimAction,
    filterAction,
    usePresetAction,
    templateToggleAction: `${templateActionPrefix}-toggle`,
    templateEditAction: `${templateActionPrefix}-edit`,
    templateFormKind: `${templateActionPrefix}-save`,
    jobAction:
      scopeType === "coalition"
        ? "coalition-mission-job-action-run"
        : "candidate-mission-job-action-run",
    formKind,
    toggleAction: createToggleAction,
    viewAction,
    noun,
    scopeType,
    scopeId,
    canManage,
  };
  return `<div class="shared-campaign-section shared-campaign-missions">
    <section class="shared-campaign-missions-hero">
      <div>
        <div class="shared-card__meta">
          <span>${escapeHtml(eyebrow)}</span>
          <span>${escapeHtml(canManage ? "Admin" : "My work")}</span>
        </div>
        <h2>${escapeHtml(title)}</h2>
        <p>${escapeHtml(resolvedDescription)}</p>
      </div>
      <div class="shared-campaign-missions-hero__actions">
        <button class="shared-feed-chip" type="button" data-action="${escapeHtml(refreshAction)}"${disabledAttr(resource.loading)}>Refresh</button>
        <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(buildMissionsRoute({ scopeType, scopeId, view: canManage ? "admin" : "mine" }))}">Standalone</button>
        ${
          canManage
            ? `<button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="${escapeHtml(createToggleAction)}"${disabledAttr(resource.actionPendingKey === "create")}>New mission</button>`
            : ""
        }
      </div>
    </section>
    <div class="shared-campaign-metrics">
      ${renderCandidateDashboardMetric("Missions", formatCount(items.length), "cyan")}
      ${renderCandidateDashboardMetric("Open tasks", formatCount(openCount))}
      ${renderCandidateDashboardMetric("Attention", formatCount(attentionCount))}
      ${renderCandidateDashboardMetric("Claimable", formatCount(claimableCount))}
      ${renderCandidateDashboardMetric("Due soon", formatCount(dueSoonCount))}
    </div>
    ${resource.error ? `<div class="shared-page__error">${escapeHtml(resource.error)}</div>` : ""}
    ${resource.loading ? `<div class="shared-page__loading">${escapeHtml(loadingLabel)}</div>` : ""}
    ${canManage && (resource.loaded || items.length || !resource.loading) ? renderCandidateMissionAdminCommand(resource, items, actionOptions) : ""}
    ${renderCandidateMissionTabs(resource, canManage, actionOptions)}
    ${resource.createOpen && canManage ? renderCandidateMissionCreateForm(resource, actionOptions) : ""}
    ${renderCandidateMissionActiveView({ ...resource, items }, canManage, actionOptions)}
  </div>`;
}

function renderCandidateDashboardMissions(detail, candidateId, access) {
  const resource = detail.missionsWorkspace;
  const canManage = canManageCandidateMissions(access);
  const items = resource.loaded ? resource.items : detail.missions;
  return renderMissionWorkspaceShell({
    resource,
    items,
    canManage,
    scopeType: "candidate",
    scopeId: candidateId,
    eyebrow: "Campaign Mission Hub",
    title: "Missions",
    description:
      "Assign work, track blockers, claim role tasks, review progress, and keep campaign operations moving from the web dashboard.",
    loadingLabel: "Loading campaign missions...",
    refreshAction: "candidate-missions-refresh",
    createToggleAction: "candidate-missions-create-toggle",
    viewAction: "candidate-missions-view",
    filterAction: "candidate-missions-filter",
    usePresetAction: "candidate-missions-use-preset",
    claimAction: "candidate-mission-job-claim",
    formKind: "candidate-missions-create",
    noun: "campaign",
  });
}

function candidateVolunteerLabel(volunteer = {}) {
  return (
    normalizeString(volunteer.displayName) ||
    (volunteer.username ? `@${normalizeString(volunteer.username).replace(/^@/u, "")}` : "") ||
    normalizeString(volunteer.userId) ||
    "Volunteer"
  );
}

function renderCandidateVolunteerTags(tags = []) {
  if (!tags.length) {
    return '<span class="shared-campaign-volunteer-muted">Default campaign rooms</span>';
  }
  return `<span class="shared-campaign-volunteer-tags">${tags
    .map((tag) => `<em>${escapeHtml(tag)}</em>`)
    .join("")}</span>`;
}

function candidateVolunteerAccessSummary(volunteer = {}) {
  const tags = Array.isArray(volunteer.roleTags) ? volunteer.roleTags : [];
  if (!tags.length) {
    return "Can join the campaign rooms open to volunteers.";
  }
  return `Routed into ${formatCount(tags.length)} room group${tags.length === 1 ? "" : "s"}.`;
}

function renderCandidateVolunteerRow(volunteer, resource, canManage) {
  const label = candidateVolunteerLabel(volunteer);
  const pendingUpdate = resource.actionPendingKey === `update:${volunteer.userId}`;
  const pendingRemove = resource.actionPendingKey === `remove:${volunteer.userId}`;
  const tagValue = volunteer.roleTags.join(", ");
  return `<article class="shared-campaign-volunteer-row">
    <div class="shared-campaign-volunteer-row__identity">
      <span class="shared-campaign-volunteer-avatar">${
        volunteer.avatarUrl
          ? `<img src="${escapeHtml(volunteer.avatarUrl)}" alt="${escapeHtml(label)}" />`
          : escapeHtml(label.slice(0, 1).toUpperCase() || "V")
      }</span>
      <div>
        <strong>${escapeHtml(label)}</strong>
        <span>${escapeHtml(volunteer.username ? `@${volunteer.username.replace(/^@/u, "")}` : volunteer.userId)}</span>
      </div>
    </div>
    <div class="shared-campaign-volunteer-row__tags">
      ${renderCandidateVolunteerTags(volunteer.roleTags)}
      <small>${escapeHtml(candidateVolunteerAccessSummary(volunteer))}</small>
    </div>
    ${
      canManage
        ? `<form class="shared-campaign-volunteer-edit" data-route-form="candidate-volunteer-update">
            <input type="hidden" name="userId" value="${escapeHtml(volunteer.userId)}" />
            <label>
              <span>Room groups</span>
              <input name="roleTags" value="${escapeHtml(tagValue)}" placeholder="field, canvass, events" autocomplete="off"${disabledAttr(pendingUpdate || pendingRemove)} />
            </label>
            <div class="shared-campaign-volunteer-actions">
              <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(pendingUpdate || pendingRemove)}>${pendingUpdate ? "Saving..." : "Save"}</button>
              <button class="shared-feed-chip" type="button" data-action="candidate-volunteer-remove" data-user-id="${escapeHtml(volunteer.userId)}"${disabledAttr(pendingUpdate || pendingRemove)}>${pendingRemove ? "Removing..." : "Remove"}</button>
            </div>
          </form>`
        : ""
    }
  </article>`;
}

function renderCandidateMessagingRoomCard(candidateId, channel, canManage) {
  const roomRoute = buildMessagingRoomRoute(
    "campaign",
    candidateId,
    channel.conversationId,
  );
  const settingsRoute = buildMessagingRoomRoute(
    "campaign",
    candidateId,
    channel.conversationId,
    "/settings",
  );
  const kind = normalizeString(channel.kind).toLowerCase();
  return `<article class="shared-campaign-room-card">
    <div class="shared-campaign-room-card__top">
          <span class="shared-campaign-room-icon">${renderIcon(kind === "announcement" ? "bell" : "messages")}</span>
      <div>
        <div class="shared-campaign-room-pills">
          <span>${escapeHtml(coalitionRoomKindLabel(channel))}</span>
          ${channel.unreadCount ? `<span class="is-alert">${escapeHtml(formatCount(channel.unreadCount))} unread</span>` : ""}
          ${channel.canManage ? '<span class="is-good">Admin</span>' : ""}
        </div>
        <h3>${escapeHtml(channel.title || "Campaign room")}</h3>
        <p>${escapeHtml(channel.subtitle || channel.lastMessagePreview || "Campaign messaging room")}</p>
      </div>
    </div>
    <div class="shared-campaign-room-card__stats">
      <span><strong>${escapeHtml(formatCount(channel.participantCount || 0))}</strong><small>members</small></span>
      <span><strong>${escapeHtml(coalitionRoomLastActivityLabel(channel))}</strong><small>activity</small></span>
    </div>
    <div class="shared-campaign-room-card__actions">
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="${escapeHtml(roomRoute)}">Open conversation</button>
      ${canManage || channel.canManage ? `<button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(settingsRoute)}">Details</button>` : ""}
    </div>
  </article>`;
}

function renderCandidateMessagingRoomGroup(candidateId, group, canManage) {
  return `<article class="shared-campaign-panel shared-campaign-room-group">
    <div class="shared-campaign-room-group__header">
      <div>
        <h2>${escapeHtml(group.label)}</h2>
        <p>${escapeHtml(group.description || `${formatCount(group.channels.length)} campaign room${group.channels.length === 1 ? "" : "s"}`)}</p>
      </div>
      <span>${escapeHtml(formatCount(group.channels.length))}</span>
    </div>
    ${
      group.channels.length
        ? `<div class="shared-campaign-room-list">${group.channels
            .map((channel) =>
              renderCandidateMessagingRoomCard(candidateId, channel, canManage),
            )
            .join("")}</div>`
        : '<div class="shared-page__empty">No rooms are available in this category yet.</div>'
    }
  </article>`;
}

function candidateMessagingFocusRoom(channels = []) {
  return [...channels]
    .filter((channel) => channel && channel.conversationId)
    .sort((a, b) => {
      const unreadDelta = (Number(b.unreadCount) || 0) - (Number(a.unreadCount) || 0);
      if (unreadDelta) return unreadDelta;
      const activityDelta = (Number(b.updatedAt) || 0) - (Number(a.updatedAt) || 0);
      if (activityDelta) return activityDelta;
      return (Number(b.participantCount) || 0) - (Number(a.participantCount) || 0);
    })[0] || null;
}

function candidateMessagingActivityLabel(channel = {}) {
  const relative = formatRelativeTime(channel.updatedAt);
  if (!relative) {
    return "No recent activity";
  }
  return relative === "now" ? "Active now" : `Active ${relative} ago`;
}

function renderCandidateMessagingFocusRoom(candidateId, channel, canManage) {
  if (!channel?.conversationId) {
    const emptyCopy = canManage
      ? "Create or open the campaign messaging workspace to add candidate, staff, operations, announcement, and volunteer rooms."
      : "Open the campaign messaging workspace to join available campaign rooms when they are shared with you.";
    return `<article class="shared-campaign-messaging-focus is-empty">
      <span class="shared-campaign-room-icon">${renderIcon("messages")}</span>
      <div>
        <h3>No campaign conversations yet</h3>
        <p>${escapeHtml(emptyCopy)}</p>
      </div>
    </article>`;
  }
  const roomRoute = buildMessagingRoomRoute(
    "campaign",
    candidateId,
    channel.conversationId,
  );
  const settingsRoute = buildMessagingRoomRoute(
    "campaign",
    candidateId,
    channel.conversationId,
    "/settings",
  );
  const membersRoute = buildMessagingRoomRoute(
    "campaign",
    candidateId,
    channel.conversationId,
    "/settings/permissions",
  );
  const pinsRoute = buildMessagingRoomRoute(
    "campaign",
    candidateId,
    channel.conversationId,
    "/settings/pinned-messages",
  );
  const invitesRoute = buildMessagingRoomRoute(
    "campaign",
    candidateId,
    channel.conversationId,
    "/settings/invites",
  );
  const notificationsRoute = buildMessagingRoomRoute(
    "campaign",
    candidateId,
    channel.conversationId,
    "/settings/notifications",
  );
  const canManageRoom = canManage || channel.canManage;
  const kind = normalizeString(channel.kind).toLowerCase();
  const roomSubtitle =
    normalizeString(channel.subtitle) ||
    "Open this room to keep the campaign conversation moving.";
  const latestPreview =
    normalizeString(channel.lastMessagePreview) ||
    "No messages have been posted in this room yet.";
  return `<article class="shared-campaign-messaging-focus">
    <div class="shared-campaign-messaging-focus__room">
      <span class="shared-campaign-room-icon">${renderIcon(kind === "announcement" ? "bell" : "messages")}</span>
      <div>
        <div class="shared-campaign-room-pills">
          <span>${escapeHtml(coalitionRoomKindLabel(channel))}</span>
          ${channel.unreadCount ? `<span class="is-alert">${escapeHtml(formatCount(channel.unreadCount))} unread</span>` : '<span class="is-good">Current</span>'}
        </div>
        <h3>${escapeHtml(channel.title || "Campaign conversation")}</h3>
        <p>${escapeHtml(roomSubtitle)}</p>
      </div>
    </div>
    <div class="shared-campaign-messaging-focus__meta">
      <span><strong>${escapeHtml(formatCount(channel.participantCount || 0))}</strong><small>people</small></span>
      <span><strong>${escapeHtml(candidateMessagingActivityLabel(channel))}</strong><small>status</small></span>
    </div>
    <div class="shared-campaign-messaging-focus__latest">
      <small>Latest message</small>
      <p>${escapeHtml(latestPreview)}</p>
    </div>
    <div class="shared-campaign-room-card__actions">
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="${escapeHtml(roomRoute)}">Open conversation</button>
      ${canManageRoom ? `<button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(settingsRoute)}">Details</button>` : ""}
    </div>
    ${
      canManageRoom
        ? `<div class="shared-campaign-messaging-room-links" aria-label="Focused room tools">
            <button type="button" data-action="navigate" data-route="${escapeHtml(membersRoute)}">${renderIcon("team")} <span>Access</span></button>
            <button type="button" data-action="navigate" data-route="${escapeHtml(pinsRoute)}">${renderIcon("saveFilled")} <span>Pins</span></button>
            <button type="button" data-action="navigate" data-route="${escapeHtml(invitesRoute)}">${renderIcon("share")} <span>Invites</span></button>
            <button type="button" data-action="navigate" data-route="${escapeHtml(notificationsRoute)}">${renderIcon("bell")} <span>Alerts</span></button>
          </div>`
        : ""
    }
  </article>`;
}

function renderCandidateMessagingActionCard(action) {
  return `<button class="shared-campaign-messaging-action${action.tone ? ` is-${escapeHtml(action.tone)}` : ""}" type="button" data-action="navigate" data-route="${escapeHtml(action.route)}">
    <span>${renderIcon(action.icon)}</span>
    <strong>${escapeHtml(action.title)}</strong>
    <small>${escapeHtml(action.copy)}</small>
  </button>`;
}

function renderCandidateMessagingCommandCenter({
  candidateId,
  channels,
  groups,
  unreadCount,
  canManage,
  reach,
  workspace,
}) {
  const roomsPath = candidateMessagingServerPath(candidateId);
  const focusRoom = candidateMessagingFocusRoom(channels);
  const composePath = "/messages/compose";
  const inboxPath = "/messages";
  const securityPath = "/messages/security-activity";
  const recoveryPath = "/messages/recovery";
  const commandCopy = canManage
    ? "Open conversations, compose direct outreach, manage room access, review safety, and keep trusted-device recovery close to the campaign workflow."
    : "Open assigned campaign rooms, compose direct outreach, check the inbox, and keep trusted-device recovery close to the campaign workflow.";
  const actions = [
    {
      title: "Compose",
      copy: "Start a direct message or group chat.",
      route: composePath,
      icon: "create",
      tone: "primary",
    },
    {
      title: "Inbox and rooms",
      copy: "Review DMs, requests, and campaign rooms.",
      route: roomsPath,
      icon: "messages",
    },
    ...(canManage
      ? [
          {
            title: "Safety review",
            copy: "Handle reports, restrictions, and message safety.",
            route: `${roomsPath}/moderation`,
            icon: "flag",
            tone: unreadCount ? "attention" : "",
          },
          {
            title: "Team access",
            copy: "Invite staff and assign room groups.",
            route: `${roomsPath}/roles`,
            icon: "shield",
          },
          {
            title: "Room defaults",
            copy: "Set names, visibility, notifications, and access.",
            route: `${roomsPath}/settings`,
            icon: "settings",
          },
          {
            title: "Automations",
            copy: "Configure saved replies and routing.",
            route: `${roomsPath}/workflows`,
            icon: "dashboard",
          },
        ]
      : []),
    {
      title: "Security",
      copy: "Check trusted devices and recovery status.",
      route: securityPath,
      icon: "lock",
    },
  ];
  return `<article class="shared-campaign-panel shared-campaign-panel--accent shared-campaign-messaging-command">
    <div class="shared-campaign-panel__header shared-campaign-messaging-command__header">
      <div>
        <span class="shared-card__meta"><span>Campaign messaging</span><span>${escapeHtml(canManage ? "Manager access" : "Staff access")}</span></span>
        <h2>Campaign messaging workspace</h2>
        <p>${escapeHtml(commandCopy)}</p>
      </div>
      <div class="shared-card__actions">
        <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="${escapeHtml(composePath)}">Compose</button>
        <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(inboxPath)}">Inbox</button>
        <button class="shared-feed-chip" type="button" data-action="candidate-messaging-refresh"${disabledAttr(workspace.loading)}>${workspace.loading ? "Refreshing..." : "Refresh"}</button>
      </div>
    </div>
    <div class="shared-campaign-messaging-signals">
      <span><strong>${escapeHtml(unreadCount ? formatCount(unreadCount) : "Clear")}</strong><small>unread</small></span>
      <span><strong>${escapeHtml(formatCount(channels.length))}</strong><small>active rooms</small></span>
      <span><strong>${escapeHtml(formatCount(groups.length))}</strong><small>room groups</small></span>
      <span><strong>${escapeHtml(formatCount(reach))}</strong><small>people</small></span>
    </div>
    <div class="shared-campaign-messaging-command__body">
      ${renderCandidateMessagingFocusRoom(candidateId, focusRoom, canManage)}
      <div class="shared-campaign-messaging-action-grid">
        ${actions.map(renderCandidateMessagingActionCard).join("")}
      </div>
    </div>
    <div class="shared-campaign-messaging-recovery-strip">
      <span>${renderIcon("shield")}</span>
      <div>
        <strong>Messaging security travels with the campaign workspace.</strong>
        <small>Use trusted devices, recovery codes, and safety activity from web before handing off campaign conversations.</small>
      </div>
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(recoveryPath)}">Recovery</button>
    </div>
  </article>`;
}

function renderCandidateMessagingAdminPanel(
  candidateId,
  directory,
  access,
  canManageOverride = null,
) {
  const serverRoute = candidateMessagingServerPath(candidateId);
  const canManage =
    canManageOverride === null
      ? directory?.canManage || canManageCandidateMessaging(access)
      : canManageOverride === true;
  const actions = canManage
    ? [
        ["Preferences", "Room defaults", `${serverRoute}/settings`, "settings"],
        ["Team access", "Room groups", `${serverRoute}/roles`, "shield"],
        ["Members", "People and rooms", `${serverRoute}/members`, "team"],
        ["Invite links", "Share access", `${serverRoute}/settings/invites`, "share"],
        ["Safety review", "Reports and restrictions", `${serverRoute}/moderation`, "flag"],
        ["Automations", "Saved replies and routing", `${serverRoute}/workflows`, "dashboard"],
        ["Security", "Devices and recovery", "/messages/security-activity", "lock"],
      ]
    : [
        ["Open rooms", "Campaign workspace", serverRoute, "messages"],
        ["Inbox", "Direct messages", "/messages", "messages"],
        ["Compose", "Start a conversation", "/messages/compose", "create"],
        ["Security", "Trusted devices", "/messages/security-activity", "lock"],
      ];
  return `<aside class="shared-campaign-room-admin">
    <div>
      <span class="shared-card__meta"><span>${escapeHtml(canManage ? "Manager controls" : "Room tools")}</span></span>
      <h2>${escapeHtml(canManage ? "Messaging controls" : "Open campaign messaging")}</h2>
      <p>${escapeHtml(canManage ? "Adjust defaults, team access, safety review, and reply routing from the campaign dashboard." : "Open available campaign rooms and review the messaging tools included with your staff access.")}</p>
    </div>
    <div class="shared-campaign-room-admin__actions">
      ${actions
        .map(
          ([label, copy, route, icon]) =>
            `<button class="shared-campaign-room-admin__button" type="button" data-action="navigate" data-route="${escapeHtml(route)}">
              <span>${renderIcon(icon)}</span>
              <strong>${escapeHtml(label)}</strong>
              <small>${escapeHtml(copy)}</small>
            </button>`,
        )
        .join("")}
    </div>
  </aside>`;
}

function renderCandidateMessagingVolunteerPanel(resource, canManage) {
  const tagCount = new Set(
    resource.items.flatMap((volunteer) => volunteer.roleTags || []),
  ).size;
  const emptyTitle = canManage
    ? "No volunteers added to campaign rooms yet."
    : "No volunteer room access has been shared yet.";
  const emptyCopy = canManage
    ? "Add a volunteer by username, then use room groups to route them into field, canvass, event, or operations rooms."
    : "A campaign messaging manager can add volunteers and assign room groups when this workspace is ready.";
  const panelCopy = canManage
    ? "Add volunteers, group them by campaign workstream, and keep room access aligned with field operations."
    : "Review volunteer room access shared by messaging managers, then open the campaign workspace for the rooms available to you.";
  return `<article class="shared-campaign-panel shared-campaign-volunteer-panel">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Volunteer room access</h2>
        <p>${escapeHtml(panelCopy)}</p>
      </div>
      <button class="shared-feed-chip" type="button" data-action="candidate-volunteers-refresh"${disabledAttr(resource.loading)}>Refresh</button>
    </div>
    <div class="shared-campaign-volunteer-summary">
      <span><strong>${escapeHtml(formatCount(resource.items.length))}</strong><small>volunteers</small></span>
      <span><strong>${escapeHtml(formatCount(tagCount))}</strong><small>room groups</small></span>
    </div>
    ${
      canManage
        ? `<form class="shared-campaign-volunteer-form" data-route-form="candidate-volunteer-add">
            <label>
              <span>Volunteer username</span>
              <input name="username" placeholder="@username" autocomplete="off"${disabledAttr(resource.actionPendingKey === "add")} />
            </label>
            <label>
              <span>Room groups</span>
              <input name="roleTags" placeholder="field, canvass, events" autocomplete="off"${disabledAttr(resource.actionPendingKey === "add")} />
            </label>
            <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(resource.actionPendingKey === "add")}>${resource.actionPendingKey === "add" ? "Adding..." : "Add to rooms"}</button>
          </form>`
        : ""
    }
    ${resource.error ? `<div class="shared-page__error">${escapeHtml(resource.error)}</div>` : ""}
    ${resource.loading && !resource.items.length ? '<div class="shared-page__loading">Loading volunteer roster...</div>' : ""}
    ${
      !resource.loading && resource.loaded && !resource.items.length
        ? `<div class="shared-campaign-volunteer-empty">
            <span>${renderIcon("team")}</span>
            <div>
              <strong>${escapeHtml(emptyTitle)}</strong>
              <p>${escapeHtml(emptyCopy)}</p>
            </div>
          </div>`
        : ""
    }
    ${
      resource.items.length
        ? `<div class="shared-campaign-volunteer-list">${resource.items
            .map((volunteer) =>
              renderCandidateVolunteerRow(volunteer, resource, canManage),
            )
            .join("")}</div>`
        : ""
    }
  </article>`;
}

function renderCandidateDashboardMessaging(detail, candidateId, access) {
  const volunteers = detail.volunteers;
  const workspace =
    detail.messagingWorkspace || createCandidateDashboardMessagingState();
  const directory = workspace.item || {
    categories: [],
    channels: [],
    canManage: canManageCandidateMessaging(access),
  };
  const channels = Array.isArray(directory.channels) ? directory.channels : [];
  const groups = coalitionRoomGroups(directory, "Campaign rooms");
  const unreadCount = channels.reduce(
    (total, channel) => total + (Number(channel.unreadCount) || 0),
    0,
  );
  const canManage = workspace.item
    ? directory.canManage === true
    : canManageCandidateMessaging(access);
  const emptyRoomCopy = canManage
    ? "Create or open the campaign messaging workspace to add candidate, staff, operations, announcement, and volunteer rooms."
    : "Open the campaign messaging workspace to see campaign rooms that are available to you.";
  const roomsPath = candidateMessagingServerPath(candidateId);
  const reach = Math.max(
    detail.staff.length,
    volunteers.items.length,
    ...channels.map((channel) => Number(channel.participantCount) || 0),
    0,
  );
  return `<div class="shared-campaign-section shared-campaign-messaging">
    <div class="shared-campaign-metrics">
      ${renderCandidateDashboardMetric("Rooms", formatCount(channels.length), "cyan")}
      ${renderCandidateDashboardMetric("Categories", formatCount(groups.length))}
      ${renderCandidateDashboardMetric("Unread", unreadCount ? formatCount(unreadCount) : "Clear")}
      ${renderCandidateDashboardMetric("Reach", formatCount(reach))}
      ${renderCandidateDashboardMetric("Access", canManage ? "Manage" : "View")}
    </div>
    ${renderCandidateMessagingCommandCenter({
      candidateId,
      channels,
      groups,
      unreadCount,
      canManage,
      reach,
      workspace,
    })}
    ${workspace.error ? `<div class="shared-page__error">${escapeHtml(workspace.error)}</div>` : ""}
    ${workspace.loading && !channels.length ? '<div class="shared-page__loading">Loading campaign rooms...</div>' : ""}
    <div class="shared-campaign-messaging-grid shared-campaign-messaging-grid--rooms">
      <div class="shared-campaign-room-groups">
        ${
          channels.length
            ? groups
                .map((group) =>
                  renderCandidateMessagingRoomGroup(candidateId, group, canManage),
                )
                .join("")
            : `<article class="shared-campaign-panel shared-campaign-room-empty-panel">
                <span>${renderIcon("messages")}</span>
                <div>
                  <h2>No campaign conversations yet.</h2>
                  <p>${escapeHtml(emptyRoomCopy)}</p>
                </div>
                <div class="shared-campaign-room-card__actions">
                  <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-messaging-refresh"${disabledAttr(workspace.loading)}>Refresh</button>
                  <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(roomsPath)}">Open messaging workspace</button>
                </div>
              </article>`
        }
      </div>
      <div class="shared-campaign-messaging-side">
        ${renderCandidateMessagingAdminPanel(candidateId, directory, access, canManage)}
        ${renderCandidateMessagingVolunteerPanel(volunteers, canManage)}
      </div>
    </div>
  </div>`;
}

function candidateEngagementFilteredItems(resource) {
  const filter = normalizeString(resource.filter).toLowerCase() || "all";
  return resource.items.filter((item) => {
    if (filter === "likes") {
      return item.kind === "post_like";
    }
    if (filter === "comments") {
      return item.kind === "post_comment";
    }
    return true;
  });
}

function candidateEngagementTitle(item) {
  const primary = candidateEngagementActorLabel(item.actors[0]);
  const extra = item.additionalCount || Math.max(0, item.count - 1);
  const actorText = extra
    ? `${primary} and ${formatCount(extra)} other${extra === 1 ? "" : "s"}`
    : primary;
  return item.kind === "post_comment"
    ? `${actorText} commented on a campaign post`
    : `${actorText} liked a campaign post`;
}

function candidateEngagementKindLabel(kind) {
  return kind === "post_comment" ? "Comment" : "Like";
}

function candidateEngagementReceivedLabel(item) {
  if (!item.receivedAt) {
    return "Recent activity";
  }
  return formatRelativeTime(item.receivedAt);
}

function candidateEngagementStatusLabel(item) {
  return item.handled ? "Handled" : "Needs response";
}

function candidateEngagementTaskCopy(item, selectedMode) {
  const modeLabel = candidateEngagementResponseModeLabel(selectedMode);
  if (item.handled) {
    return item.handledByDisplayName
      ? `Handled by ${item.handledByDisplayName}`
      : "This item has already been cleared.";
  }
  if (item.kind === "post_comment") {
    return modeLabel
      ? `Reply or react as ${modeLabel}, then clear the item when complete.`
      : "A campaign response mode is required before replying.";
  }
  return "Open the post to review context, then clear the like from the queue.";
}

function renderCandidateEngagementCommandCenter(resource, filteredItems, selectedMode) {
  const selectedModeLabel = candidateEngagementResponseModeLabel(selectedMode);
  const needsAttention = filteredItems.filter((item) => !item.handled);
  const handled = filteredItems.filter((item) => item.handled);
  const commentQueueCount = needsAttention.filter(
    (item) => item.kind === "post_comment",
  ).length;
  const likeQueueCount = needsAttention.filter(
    (item) => item.kind === "post_like",
  ).length;
  const nextAction = commentQueueCount
    ? "Start with unanswered comments, then clear likes after the post context is reviewed."
    : likeQueueCount
      ? "Review like activity, open the post if needed, then mark handled."
      : "The active view is clear. Keep the current response mode ready for new activity.";
  return `<article class="shared-campaign-engagement-command" aria-label="Engagement response center">
    <div class="shared-campaign-engagement-command__copy">
      <span>${renderIcon("reply")} Respond as ${escapeHtml(selectedModeLabel || "Unavailable")}</span>
      <h2>Engagement response center</h2>
      <p>${escapeHtml(nextAction)}</p>
    </div>
    <div class="shared-campaign-engagement-command__metrics" role="list" aria-label="Engagement queue summary">
      <span role="listitem"><strong>${escapeHtml(formatCount(needsAttention.length))}</strong><small>Needs response</small></span>
      <span role="listitem"><strong>${escapeHtml(formatCount(commentQueueCount))}</strong><small>Comment threads</small></span>
      <span role="listitem"><strong>${escapeHtml(formatCount(likeQueueCount))}</strong><small>Like clusters</small></span>
      <span role="listitem"><strong>${escapeHtml(formatCount(handled.length))}</strong><small>Handled</small></span>
    </div>
    <div class="shared-campaign-engagement-command__flow" aria-label="Engagement workflow">
      <span><b>1</b><strong>Review context</strong><small>Open post details only when the preview is not enough.</small></span>
      <span><b>2</b><strong>Respond in mode</strong><small>Use candidate or staff voice before sending a reply.</small></span>
      <span><b>3</b><strong>Clear the queue</strong><small>Mark handled after the voter-facing work is complete.</small></span>
    </div>
  </article>`;
}

function renderCandidateEngagementStatusPill(item) {
  return `<span class="shared-campaign-engagement-status${item.handled ? " is-handled" : " needs-attention"}">
    ${item.handled ? renderIcon("check") : renderIcon("bell")}
    <span>${escapeHtml(candidateEngagementStatusLabel(item))}</span>
  </span>`;
}

function renderCandidateEngagementHandledMeta(item) {
  if (!item.handled) {
    return "";
  }
  const parts = [
    item.handledByDisplayName ? `Handled by ${item.handledByDisplayName}` : "Handled",
    item.handledAt ? formatAbsoluteDateTime(item.handledAt) : "",
  ].filter(Boolean);
  return parts.length
    ? `<div class="shared-campaign-engagement-handled">${renderIcon("check")} <span>${escapeHtml(parts.join(" - "))}</span></div>`
    : "";
}

function renderCandidateEngagementActorStack(actors = []) {
  const visibleActors = actors.slice(0, 3);
  if (!visibleActors.length) {
    return `<span class="shared-campaign-engagement-avatar">?</span>`;
  }
  return `<span class="shared-campaign-engagement-avatars">
    ${visibleActors
      .map((actor) =>
        actor.avatarUrl
          ? `<img src="${escapeHtml(actor.avatarUrl)}" alt="${escapeHtml(candidateEngagementActorLabel(actor))}" />`
          : `<span>${escapeHtml(candidateEngagementActorLabel(actor).slice(0, 1).toUpperCase() || "?")}</span>`,
      )
      .join("")}
  </span>`;
}

function renderCandidateEngagementPreview(item) {
  const preview = item.preview || {};
  const text =
    normalizeString(preview.postText) ||
    normalizeString(preview.commentText) ||
    "Open the post to review the full context.";
  return `<div class="shared-campaign-engagement-preview">
    ${
      preview.postThumbUrl
        ? `<img src="${escapeHtml(preview.postThumbUrl)}" alt="" loading="lazy" />`
        : `<span>${renderIcon(item.kind === "post_comment" ? "comment" : "heart")}</span>`
    }
    <div>
      <strong>${escapeHtml(item.postId ? "Post context" : "Campaign activity")}</strong>
      <p>${escapeHtml(text)}</p>
    </div>
  </div>`;
}

function renderCandidateEngagementComment(comment, resource, selectedMode) {
  const pendingLike = resource.actionPendingKey === `like:${comment.commentId}`;
  const pendingReply = resource.actionPendingKey === `reply:${comment.commentId}`;
  const actor = comment.actor || {};
  const actorLabel = candidateEngagementActorLabel(actor);
  const createdLabel = comment.createdAt
    ? formatAbsoluteDateTime(comment.createdAt)
    : "Comment";
  const likeLabel = comment.likedByMe
    ? "Liked"
    : comment.likeCount
      ? `Like (${formatCount(comment.likeCount)})`
      : "Like";
  const responseClass = comment.badgeLabel || comment.responseMode
    ? " is-campaign-response"
    : "";
  return `<article class="shared-campaign-engagement-comment${comment.likedByMe ? " is-liked" : ""}${responseClass}">
    <div class="shared-campaign-engagement-comment__top">
      ${renderCandidateEngagementActorStack([actor])}
      <div>
        <strong>${escapeHtml(actorLabel)}</strong>
        <span>${escapeHtml(createdLabel)}</span>
      </div>
      ${
        comment.badgeLabel || comment.responseMode
          ? `<em>${escapeHtml(comment.badgeLabel || candidateEngagementResponseModeLabel(comment.responseMode))}</em>`
          : ""
      }
    </div>
    <p class="shared-campaign-engagement-comment__body">${escapeHtml(comment.text || "Comment")}</p>
    <div class="shared-campaign-engagement-comment__actions">
      ${
        comment.commentId
          ? `<button class="shared-feed-chip shared-campaign-engagement-icon-chip" type="button" data-action="candidate-engagement-comment-like" data-comment-id="${escapeHtml(comment.commentId)}" data-liked="${comment.likedByMe ? "true" : "false"}"${disabledAttr(pendingLike || !selectedMode)}>
              ${renderIcon(comment.likedByMe ? "heart" : "heartOutline")}
              <span>${escapeHtml(pendingLike ? "Updating..." : likeLabel)}</span>
            </button>`
          : ""
      }
    </div>
    ${
      comment.commentId && comment.postId
        ? `<form class="shared-campaign-engagement-reply" data-route-form="candidate-engagement-reply">
            <input type="hidden" name="postId" value="${escapeHtml(comment.postId)}" />
            <input type="hidden" name="replyTo" value="${escapeHtml(comment.commentId)}" />
            <label class="shared-campaign-engagement-reply-field">
              <span>Quick reply</span>
              <input name="text" placeholder="${escapeHtml(selectedMode ? `Reply as ${candidateEngagementResponseModeLabel(selectedMode)}` : "No response mode available")}" autocomplete="off"${disabledAttr(pendingReply || !selectedMode)} />
            </label>
            <button class="shared-feed-chip shared-feed-chip--primary shared-campaign-engagement-icon-chip" type="submit"${disabledAttr(pendingReply || !selectedMode)}>
              ${renderIcon("send")}
              <span>${escapeHtml(pendingReply ? "Sending..." : "Reply")}</span>
            </button>
          </form>`
        : ""
    }
  </article>`;
}

function renderCandidateEngagementItem(item, resource, selectedMode) {
  const pendingRead =
    resource.actionPendingKey === `read:${item.postId}:${item.kind === "post_like" ? "likes" : "comments"}` ||
    resource.actionPendingKey === `read:${item.postId}:all`;
  const comments = item.comments.length
    ? item.comments
    : item.children.flatMap((child) => child.comments || []);
  const selectedModeLabel = candidateEngagementResponseModeLabel(selectedMode);
  return `<article class="shared-campaign-engagement-item${item.handled ? " is-handled" : " needs-attention"}">
    <div class="shared-campaign-engagement-item__main">
      <span class="shared-campaign-engagement-kind" aria-hidden="true">${renderIcon(item.kind === "post_comment" ? "comment" : "heart")}</span>
      ${renderCandidateEngagementActorStack(item.actors)}
      <div>
        <div class="shared-card__meta">
          <span>${escapeHtml(candidateEngagementKindLabel(item.kind))}</span>
          <span>${escapeHtml(candidateEngagementReceivedLabel(item))}</span>
          ${item.count > 1 ? `<span>${escapeHtml(`${formatCount(item.count)} events`)}</span>` : ""}
        </div>
        <h3>${escapeHtml(candidateEngagementTitle(item))}</h3>
      </div>
      ${renderCandidateEngagementStatusPill(item)}
    </div>
    <div class="shared-campaign-engagement-item__body">
      ${renderCandidateEngagementPreview(item)}
      <aside class="shared-campaign-engagement-task">
        <span>${escapeHtml(item.handled ? "Queue state" : "Response task")}</span>
        <strong>${escapeHtml(selectedModeLabel ? `Respond as ${selectedModeLabel}` : "Response unavailable")}</strong>
        <p>${escapeHtml(candidateEngagementTaskCopy(item, selectedMode))}</p>
        ${renderCandidateEngagementHandledMeta(item)}
      </aside>
    </div>
    <div class="shared-campaign-engagement-item__actions">
      ${
        item.postId
          ? `<button class="shared-feed-chip shared-campaign-engagement-icon-chip" type="button" data-action="candidate-engagement-mark-read" data-post-id="${escapeHtml(item.postId)}" data-kind="${escapeHtml(item.kind)}"${disabledAttr(pendingRead)}>
              ${renderIcon("check")}
              <span>${escapeHtml(pendingRead ? "Updating..." : item.handled ? "Refresh state" : "Mark handled")}</span>
            </button>`
          : ""
      }
      ${
        item.postId
          ? `<button class="shared-feed-chip shared-campaign-engagement-icon-chip" type="button" data-action="navigate" data-route="/posts/${escapeHtml(encodeURIComponent(item.postId))}">
              ${renderIcon("comment")}
              <span>Open post</span>
            </button>`
          : ""
      }
    </div>
    ${
      comments.length
        ? `<div class="shared-campaign-engagement-comments">
            <div class="shared-campaign-engagement-comments__header">
              <span>Conversation</span>
              <strong>${escapeHtml(`${formatCount(comments.length)} ${comments.length === 1 ? "message" : "messages"}`)}</strong>
            </div>
            ${comments
              .slice(0, 3)
              .map((comment) =>
                renderCandidateEngagementComment(comment, resource, selectedMode),
              )
              .join("")}
          </div>`
        : ""
    }
  </article>`;
}

function renderCandidateEngagementQueueSummary(resource, filteredItems, selectedMode) {
  const selectedModeLabel = candidateEngagementResponseModeLabel(selectedMode);
  const nextCursorLabel = resource.nextCursor ? "Older activity available" : "Loaded through current window";
  return `<div class="shared-campaign-engagement-summary">
    <div>
      <span>Loaded</span>
      <strong>${escapeHtml(formatCount(filteredItems.length))}</strong>
    </div>
    <div>
      <span>Responding</span>
      <strong>${escapeHtml(selectedModeLabel || "Unavailable")}</strong>
    </div>
    <div>
      <span>History</span>
      <strong>${escapeHtml(nextCursorLabel)}</strong>
    </div>
  </div>`;
}

function renderCandidateDashboardEngagement(detail, candidateId, access) {
  const resource = detail.engagement;
  const modes = resource.availableResponseModes.length
    ? resource.availableResponseModes
    : candidateEngagementAvailableModesForAccess(access);
  const selectedMode = candidateDashboardEngagementSelectedMode(resource, access);
  const filteredItems = candidateEngagementFilteredItems(resource);
  const needsAttention = filteredItems.filter((item) => !item.handled);
  const handled = filteredItems.filter((item) => item.handled);
  const commentCount = resource.items.filter(
    (item) => item.kind === "post_comment",
  ).length;
  const likeCount = resource.items.filter((item) => item.kind === "post_like").length;
  const filters = [
    ["all", "All"],
    ["comments", "Comments"],
    ["likes", "Likes"],
  ];
  return `<div class="shared-campaign-section shared-campaign-engagement">
    ${renderCandidateEngagementCommandCenter(resource, filteredItems, selectedMode)}
    <div class="shared-campaign-metrics">
      ${renderCandidateDashboardMetric("Needs attention", formatCount(needsAttention.length), "cyan")}
      ${renderCandidateDashboardMetric("Comments", formatCount(commentCount))}
      ${renderCandidateDashboardMetric("Likes", formatCount(likeCount))}
      ${renderCandidateDashboardMetric("Window", `${formatCount(resource.rangeDays || 90)}d`)}
    </div>
    <article class="shared-campaign-panel shared-campaign-engagement-toolbar">
      <div class="shared-campaign-panel__header">
        <div>
          <h2>Engagement queue</h2>
          <p>Review campaign likes and comments, respond in the correct mode, and clear handled activity.</p>
        </div>
        <button class="shared-feed-chip" type="button" data-action="candidate-engagement-refresh"${disabledAttr(resource.loading)}>Refresh</button>
      </div>
      <div class="shared-campaign-engagement-controls">
        <div>
          <span>Filter</span>
          <div>
            ${filters
              .map(
                ([value, label]) =>
                  `<button class="shared-feed-chip${resource.filter === value ? " shared-feed-chip--primary" : ""}" type="button" data-action="candidate-engagement-filter" data-filter="${escapeHtml(value)}">${escapeHtml(label)}</button>`,
              )
              .join("")}
          </div>
        </div>
        <div>
          <span>Respond as</span>
          <div>
            ${
              modes.length
                ? modes
                    .map(
                      (mode) =>
                        `<button class="shared-feed-chip${selectedMode === mode ? " shared-feed-chip--primary" : ""}" type="button" data-action="candidate-engagement-mode" data-mode="${escapeHtml(mode)}">${escapeHtml(candidateEngagementResponseModeLabel(mode))}</button>`,
                    )
                    .join("")
                : `<span class="shared-campaign-engagement-muted">No response mode available</span>`
            }
          </div>
        </div>
      </div>
      ${renderCandidateEngagementQueueSummary(resource, filteredItems, selectedMode)}
      ${resource.error ? `<div class="shared-page__error">${escapeHtml(resource.error)}</div>` : ""}
    </article>
    ${resource.loading && !resource.items.length ? '<div class="shared-page__loading">Loading engagement...</div>' : ""}
    ${
      !resource.loading && !filteredItems.length && resource.loaded
        ? '<div class="shared-page__empty">No engagement matches this view.</div>'
        : ""
    }
    ${
      needsAttention.length
        ? `<section class="shared-campaign-engagement-group">
            <h2>Needs attention</h2>
            ${needsAttention
              .map((item) =>
                renderCandidateEngagementItem(item, resource, selectedMode),
              )
              .join("")}
          </section>`
        : ""
    }
    ${
      handled.length
        ? `<section class="shared-campaign-engagement-group">
            <h2>Handled</h2>
            ${handled
              .map((item) =>
                renderCandidateEngagementItem(item, resource, selectedMode),
              )
              .join("")}
          </section>`
        : ""
    }
    ${
      resource.nextCursor
        ? `<div class="shared-campaign-engagement-more">
            <button class="shared-feed-chip" type="button" data-action="candidate-engagement-load-more"${disabledAttr(resource.loadingMore)}>${resource.loadingMore ? "Loading..." : "Load more"}</button>
          </div>`
        : ""
    }
  </div>`;
}

function renderCandidateContactTypeControl(type, settings, saving) {
  const enabled = parseBoolean(settings.enabledContactTypes?.[type.key], true);
  return `<label class="shared-campaign-contact-option">
    <input type="checkbox" name="contactType:${escapeHtml(type.key)}"${checkedAttr(enabled)}${disabledAttr(saving)} />
    <span class="shared-campaign-contact-option__mark" aria-hidden="true"></span>
    <span>
      <strong>${escapeHtml(candidateContactTypeLabel(type.key))}</strong>
      <small>${escapeHtml(candidateContactTypeDescription(type.key))}</small>
    </span>
  </label>`;
}

function renderCandidateContactPromptPreview(settings) {
  const enabledTypes = CANDIDATE_CONTACT_TYPE_CONFIG.filter((type) =>
    parseBoolean(settings.enabledContactTypes?.[type.key], true),
  );
  return `<div class="shared-campaign-contact-preview">
    <div class="shared-campaign-contact-preview__phone">
      <div class="shared-campaign-contact-preview__top">
        <span>${renderIcon("candidate")}</span>
        <div>
          <strong>Contact this campaign</strong>
          <small>${escapeHtml(settings.feedPromptEnabled ? "Visible to eligible voters" : "Hidden until enabled")}</small>
        </div>
      </div>
      <p>${
        settings.feedPromptEnabled
          ? "Let the campaign know how you would like to help or hear back."
          : "Turn on feed prompts when this campaign is ready for voter outreach."
      }</p>
      <div class="shared-campaign-contact-preview__chips">
        ${
          enabledTypes.length
            ? enabledTypes
                .map(
                  (type) =>
                    `<span>${escapeHtml(candidateContactTypeLabel(type.key))}</span>`,
                )
                .join("")
            : "<em>No contact channels selected</em>"
        }
      </div>
    </div>
  </div>`;
}

function renderCandidateContactPromptCommandCenter({
  settings,
  savedSettings,
  resource,
  candidateId,
  hasUnsavedChanges,
}) {
  const enabledCount = candidateContactPromptEnabledCount(settings);
  const savedCount = candidateContactPromptEnabledCount(savedSettings);
  const savedLabel = savedSettings.updatedAt
    ? formatAbsoluteDateTime(savedSettings.updatedAt)
    : "Not saved";
  const communityPath = candidateContactPromptCommunityPath(settings, candidateId);
  const cards = [
    {
      label: "Feed placement",
      metric: settings.feedPromptEnabled ? "Visible" : "Hidden",
      copy: settings.feedPromptEnabled
        ? "Eligible voters can see the prompt in feed and candidate profile entry points."
        : "Turn this on before expecting voter request cards to appear.",
      icon: "feed",
      tone: settings.feedPromptEnabled ? "ready" : "urgent",
    },
    {
      label: "Contact menu",
      metric: `${formatCount(enabledCount)} of ${formatCount(CANDIDATE_CONTACT_TYPE_CONFIG.length)} channels`,
      copy:
        enabledCount > 0
          ? "The voter prompt will only show the selected outreach choices."
          : "Select at least one channel before making the prompt live.",
      icon: enabledCount > 0 ? "phone" : "lock",
      tone: enabledCount > 0 ? "ready" : "urgent",
    },
    {
      label: "Community join",
      metric: settings.communityJoinAvailable ? "Ready" : "Needs messaging",
      copy: settings.communityJoinAvailable
        ? "Out-of-district viewers can be sent into the community join path."
        : "Enable Community and Community Invites in campaign messaging first.",
      icon: "messages",
      route: communityPath,
      tone: settings.communityJoinAvailable ? "ready" : "locked",
    },
    {
      label: "Save state",
      metric: hasUnsavedChanges
        ? "Unsaved changes"
        : resource.loading
          ? "Loading"
          : "Saved",
      copy: hasUnsavedChanges
        ? `Draft differs from saved settings (${formatCount(savedCount)} saved channels).`
        : `Last saved: ${savedLabel}.`,
      icon: hasUnsavedChanges ? "edit" : "check",
      tone: hasUnsavedChanges ? "urgent" : "ready",
    },
  ];
  return `<article class="shared-campaign-panel shared-campaign-contact-ops">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Contact prompt command center</h2>
        <p>Review voter-facing readiness before saving changes to the campaign prompt.</p>
      </div>
      <button class="shared-feed-chip" type="button" data-action="candidate-contact-prompt-refresh"${disabledAttr(resource.loading || resource.actionPendingKey === "save")}>Refresh</button>
    </div>
    <div class="shared-campaign-contact-ops__summary">
      <span><strong>${escapeHtml(settings.feedPromptEnabled ? "Live" : "Hidden")}</strong><small>Feed prompt</small></span>
      <span><strong>${escapeHtml(`${formatCount(enabledCount)}/${formatCount(CANDIDATE_CONTACT_TYPE_CONFIG.length)}`)}</strong><small>Channels</small></span>
      <span><strong>${escapeHtml(settings.communityJoinAvailable ? "Ready" : "Setup")}</strong><small>Community join</small></span>
      <span><strong>${escapeHtml(hasUnsavedChanges ? "Draft" : "Saved")}</strong><small>State</small></span>
    </div>
    <div class="shared-campaign-contact-ops__grid">
      ${cards
        .map((card) => {
          const tagName = card.route ? "button" : "div";
          const routeAttrs = card.route
            ? ` type="button" data-action="navigate" data-route="${escapeHtml(card.route)}"`
            : "";
          return `<${tagName} class="shared-campaign-contact-ops-card${card.tone ? ` is-${escapeHtml(card.tone)}` : ""}"${routeAttrs}>
            <span class="shared-campaign-contact-ops-card__icon">${renderIcon(card.icon)}</span>
            <span class="shared-campaign-contact-ops-card__body">
              <small>${escapeHtml(card.metric)}</small>
              <strong>${escapeHtml(card.label)}</strong>
              <em>${escapeHtml(card.copy)}</em>
            </span>
          </${tagName}>`;
        })
        .join("")}
    </div>
  </article>`;
}

function renderCandidateDashboardContactPrompt(detail, candidateId) {
  const resource = detail.contactPrompt;
  const savedSettings =
    resource.settings ||
    normalizeCandidateDashboardContactPromptSettings({}, candidateId);
  const settings = resource.draft || savedSettings;
  const hasUnsavedChanges =
    Boolean(resource.draft) &&
    !candidateContactPromptSettingsEqual(settings, savedSettings);
  const saving = resource.actionPendingKey === "save";
  const enabledCount = candidateContactPromptEnabledCount(settings);
  const lastSaved = settings.updatedAt
    ? formatAbsoluteDateTime(settings.updatedAt)
    : "Not saved";
  const communityPath = candidateContactPromptCommunityPath(settings, candidateId);
  return `<div class="shared-campaign-section shared-campaign-contact">
    <div class="shared-campaign-metrics">
      ${renderCandidateDashboardMetric("Feed prompt", settings.feedPromptEnabled ? "Live" : "Hidden", settings.feedPromptEnabled ? "cyan" : "")}
      ${renderCandidateDashboardMetric("Contact channels", `${formatCount(enabledCount)}/6`)}
      ${renderCandidateDashboardMetric("Community join", settings.communityJoinAvailable ? "Ready" : "Setup")}
      ${renderCandidateDashboardMetric(hasUnsavedChanges ? "Draft state" : "Last saved", hasUnsavedChanges ? "Unsaved" : lastSaved, hasUnsavedChanges ? "pink" : "")}
    </div>
    ${renderCandidateContactPromptCommandCenter({
      settings,
      savedSettings,
      resource,
      candidateId,
      hasUnsavedChanges,
    })}
    <div class="shared-campaign-contact-grid">
      <article class="shared-campaign-panel shared-campaign-contact-settings">
        <div class="shared-campaign-panel__header">
          <div>
            <h2>Voter contact prompt</h2>
            <p>Control whether this campaign appears in voter contact prompts and which outreach choices voters can select.</p>
          </div>
          <span class="shared-campaign-contact-status${settings.feedPromptEnabled ? " is-live" : ""}${hasUnsavedChanges ? " is-draft" : ""}">${escapeHtml(hasUnsavedChanges ? "Unsaved" : settings.feedPromptEnabled ? "Live" : "Hidden")}</span>
        </div>
        ${resource.error ? `<div class="shared-page__error">${escapeHtml(resource.error)}</div>` : ""}
        ${resource.loading && !resource.loaded ? '<div class="shared-page__loading">Loading contact prompt settings...</div>' : ""}
        <form class="shared-campaign-contact-form" data-route-form="candidate-contact-prompt">
          <label class="shared-campaign-contact-toggle">
            <input type="checkbox" name="feedPromptEnabled"${checkedAttr(settings.feedPromptEnabled)}${disabledAttr(saving || resource.loading)} />
            <span class="shared-campaign-contact-switch" aria-hidden="true"></span>
            <span>
              <strong>Show my campaign in voter contact prompts</strong>
              <small>Eligible voters can see this campaign from the For You feed and candidate profile entry points.</small>
            </span>
          </label>
          <div class="shared-campaign-contact-options">
            ${CANDIDATE_CONTACT_TYPE_CONFIG.map((type) =>
              renderCandidateContactTypeControl(type, settings, saving || resource.loading),
            ).join("")}
          </div>
          <div class="shared-campaign-contact-form__actions">
            <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(saving || resource.loading)}>${saving ? "Saving..." : "Save settings"}</button>
            <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(`/candidates/${encodeURIComponent(candidateId)}`)}">Open voter view</button>
          </div>
        </form>
      </article>
      <aside class="shared-campaign-panel shared-campaign-contact-side">
        <div class="shared-campaign-panel__header">
          <div>
            <h2>Prompt preview</h2>
            <p>Use this to check the voter-facing choices before saving.</p>
          </div>
          <span class="shared-campaign-contact-status${settings.feedPromptEnabled ? " is-live" : ""}${hasUnsavedChanges ? " is-draft" : ""}" data-contact-preview-status>${escapeHtml(hasUnsavedChanges ? "Unsaved" : settings.feedPromptEnabled ? "Live" : "Hidden")}</span>
        </div>
        ${renderCandidateContactPromptPreview(settings)}
        <div class="shared-campaign-contact-community">
          <div>
            <strong>Out-of-district community join</strong>
            <span>${escapeHtml(settings.communityJoinAvailable ? "Available for voters outside the district." : "Enable Community and Community Invites in campaign messaging to allow it.")}</span>
          </div>
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(communityPath)}">Messaging settings</button>
        </div>
      </aside>
    </div>
  </div>`;
}

function renderCandidateVoterPreferenceSelect(name, value = "", label = "") {
  const normalizedValue = normalizeString(value).toLowerCase();
  return `<label>
    <span>${escapeHtml(label || candidateContactTypeLabel(name))}</span>
    <select name="${escapeHtml(name)}">
      <option value=""${selectedAttr(!normalizedValue)}>Any</option>
      <option value="yes"${selectedAttr(normalizedValue === "yes")}>Yes</option>
      <option value="no"${selectedAttr(normalizedValue === "no")}>No</option>
      <option value="unset"${selectedAttr(normalizedValue === "unset")}>Unset</option>
    </select>
  </label>`;
}

function candidateVoterRegistryActiveFilterCount(filters = {}) {
  return [
    "q",
    "source",
    "city",
    "state",
    "party",
    ...CANDIDATE_CONTACT_TYPE_CONFIG.map((type) => type.key),
  ].filter((key) => normalizeString(filters[key])).length;
}

function candidateVoterPreferredContactTypes(voter = {}) {
  return CANDIDATE_CONTACT_TYPE_CONFIG.filter(
    (type) =>
      normalizeVoterPreferenceChoice(voter.contactPreferences?.[type.key]) ===
      "yes",
  );
}

function candidateVoterNoContactTypes(voter = {}) {
  return CANDIDATE_CONTACT_TYPE_CONFIG.filter(
    (type) =>
      normalizeVoterPreferenceChoice(voter.contactPreferences?.[type.key]) ===
      "no",
  );
}

function candidateVoterSourceClass(voter = {}) {
  const source = candidateVoterSourceLabel(voter).toLowerCase();
  if (source.includes("polis")) return "polis";
  if (source.includes("manual")) return "manual";
  if (source.includes("import")) return "imported";
  return "other";
}

function candidateVoterRegistryImportState(registryImport = {}) {
  if (registryImport.status?.status) {
    return humanizeLabel(registryImport.status.status);
  }
  if (registryImport.preview) {
    return "Preview ready";
  }
  if (registryImport.fileName) {
    return "File selected";
  }
  return "Ready";
}

function renderCandidateVoterRegistryCommandCenter(resource, counts = {}) {
  const filterCount = candidateVoterRegistryActiveFilterCount(resource.filters);
  const importState = candidateVoterRegistryImportState(resource.import);
  const nextAction = filterCount
    ? "Review the filtered list, clear stale filters when finished, then capture notes from the voter map."
    : resource.import.preview
      ? "Check duplicate handling, start the import, then refresh the list after the job completes."
      : "Use filters for outreach prep, add one voter manually, or preview a CSV before importing records.";
  return `<article class="shared-campaign-registry-command" aria-label="Voter registry command center">
    <div class="shared-campaign-registry-command__copy">
      <span>${renderIcon("registry")} Registry operations</span>
      <h2>Voter registry command center</h2>
      <p>${escapeHtml(nextAction)}</p>
    </div>
    <div class="shared-campaign-registry-command__metrics" role="list" aria-label="Registry summary">
      <span role="listitem"><strong>${escapeHtml(formatCount(counts.loaded || 0))}</strong><small>Loaded voters</small></span>
      <span role="listitem"><strong>${escapeHtml(formatCount(counts.preferred || 0))}</strong><small>Reachable records</small></span>
      <span role="listitem"><strong>${escapeHtml(formatCount(counts.noContact || 0))}</strong><small>Has blocked channel</small></span>
      <span role="listitem"><strong>${escapeHtml(importState)}</strong><small>Import state</small></span>
    </div>
    <div class="shared-campaign-registry-command__actions">
      <a href="#registry-voters">${renderIcon("search")}<span><strong>Review voters</strong><small>${escapeHtml(filterCount ? `${formatCount(filterCount)} filters active` : "Search and segment records")}</small></span></a>
      <a href="#registry-add-voters">${renderIcon("create")}<span><strong>Add one voter</strong><small>Capture consented contact details</small></span></a>
      <a href="#registry-import-voters">${renderIcon("upload")}<span><strong>Import CSV</strong><small>${escapeHtml(importState)}</small></span></a>
    </div>
  </article>`;
}

function renderCandidateVoterRegistryWorkflow(resource) {
  const filterCount = candidateVoterRegistryActiveFilterCount(resource.filters);
  const importStatus = resource.import.status
    ? humanizeLabel(resource.import.status.status)
    : "Ready";
  return `<div class="shared-campaign-registry-workflow" aria-label="Voter registry workflow">
    <a href="#registry-voters">
      ${renderIcon("registry")}
      <span>
        <strong>Voters</strong>
        <small>${escapeHtml(filterCount ? `${formatCount(filterCount)} filters active` : "Review and filter records")}</small>
      </span>
    </a>
    <a href="#registry-add-voters">
      ${renderIcon("create")}
      <span>
        <strong>Add voters</strong>
        <small>Manual entry and duplicate review</small>
      </span>
    </a>
    <a href="#registry-import-voters">
      ${renderIcon("upload")}
      <span>
        <strong>Bulk CSV</strong>
        <small>${escapeHtml(importStatus)}</small>
      </span>
    </a>
  </div>`;
}

function renderCandidateVoterRegistryFilterSummary(filters = {}) {
  const chips = [];
  [
    ["q", "Search"],
    ["source", "Source"],
    ["city", "City"],
    ["state", "State"],
    ["party", "Affiliation"],
  ].forEach(([key, label]) => {
    const value = normalizeString(filters[key]);
    if (value) chips.push([label, value]);
  });
  CANDIDATE_CONTACT_TYPE_CONFIG.forEach((type) => {
    const value = normalizeString(filters[type.key]);
    if (value) chips.push([type.label, voterPreferenceLabel(value)]);
  });
  if (!chips.length) {
    return `<div class="shared-campaign-registry-filter-summary is-empty">Showing all voter records.</div>`;
  }
  return `<div class="shared-campaign-registry-filter-summary">
    ${chips
      .map(
        ([label, value]) =>
          `<span><strong>${escapeHtml(label)}</strong>${escapeHtml(value)}</span>`,
      )
      .join("")}
  </div>`;
}

function renderCandidateVoterRegistryFilters(resource) {
  const filters = resource.filters || {};
  return `<form class="shared-campaign-registry-filters" data-route-form="candidate-voter-registry-filters">
    <div class="shared-campaign-registry-filters__header">
      <div>
        <strong>Find voters</strong>
        <span>Search by identity, location, source, affiliation, or contact preference.</span>
      </div>
      <div class="shared-campaign-registry-filter-actions">
        <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(resource.loading)}>Apply</button>
        <button class="shared-feed-chip" type="button" data-action="candidate-voter-registry-clear"${disabledAttr(resource.loading)}>Clear</button>
      </div>
    </div>
    <label class="is-wide">
      <span>Search</span>
      <input name="q" value="${escapeHtml(filters.q || "")}" placeholder="Name, address, phone, email" autocomplete="off" />
    </label>
    <label>
      <span>Source</span>
      <select name="source">
        <option value=""${selectedAttr(!filters.source)}>All</option>
        <option value="polis"${selectedAttr(filters.source === "polis")}>Polis</option>
        <option value="imported"${selectedAttr(filters.source === "imported")}>Imported</option>
      </select>
    </label>
    <label>
      <span>City</span>
      <input name="city" value="${escapeHtml(filters.city || "")}" autocomplete="address-level2" />
    </label>
    <label>
      <span>State</span>
      <input name="state" value="${escapeHtml(filters.state || "")}" autocomplete="address-level1" maxlength="32" />
    </label>
    <label>
      <span>Affiliation</span>
      <input name="party" value="${escapeHtml(filters.party || "")}" autocomplete="off" />
    </label>
    <div class="shared-campaign-registry-pref-grid">
      ${CANDIDATE_CONTACT_TYPE_CONFIG.map((type) =>
        renderCandidateVoterPreferenceSelect(
          type.key,
          filters[type.key],
          type.label,
        ),
      ).join("")}
    </div>
    ${renderCandidateVoterRegistryFilterSummary(filters)}
  </form>`;
}

function renderCandidateVoterPreferencePills(voter) {
  const yesTypes = candidateVoterPreferredContactTypes(voter);
  const noTypes = candidateVoterNoContactTypes(voter);
  const summary =
    yesTypes.length > 0
      ? `${formatCount(yesTypes.length)} preferred`
      : noTypes.length > 0
        ? `${formatCount(noTypes.length)} no-contact`
        : "Preferences unset";
  return `<div class="shared-campaign-registry-prefs" aria-label="${escapeHtml(summary)}">
    ${CANDIDATE_CONTACT_TYPE_CONFIG.map((type) => {
      const choice = normalizeVoterPreferenceChoice(
        voter.contactPreferences?.[type.key],
      );
      return `<span class="shared-campaign-registry-pref is-${escapeHtml(choice)}">${escapeHtml(type.label)}: ${escapeHtml(voterPreferenceLabel(choice))}</span>`;
    }).join("")}
  </div>`;
}

function renderCandidateVoterRow(voter, options = {}) {
  const address = candidateVoterAddress(voter);
  const sourceLabel = candidateVoterSourceLabel(voter);
  const updated = voter.updatedAt ? formatAbsoluteDateTime(voter.updatedAt) : "";
  const sourceClass = candidateVoterSourceClass(voter);
  const preferred = candidateVoterPreferredContactTypes(voter);
  const noContact = candidateVoterNoContactTypes(voter);
  const preferredSummary = preferred.length
    ? preferred.slice(0, 2).map((type) => type.label).join(", ")
    : "No preferred channels";
  const blockedSummary = noContact.length
    ? noContact.slice(0, 2).map((type) => type.label).join(", ")
    : "No blocked channels";
  const contactRows = [
    ["phone", "Phone", voter.phone || "No phone"],
    ["mail", "Email", voter.email || "No email"],
    ["home", "Address", address || "No address shared"],
  ];
  return `<article class="shared-campaign-registry-row">
    <div class="shared-campaign-registry-row__main">
      <span class="shared-campaign-registry-avatar">${escapeHtml(voter.displayName.slice(0, 1).toUpperCase() || "V")}</span>
      <div>
        <div class="shared-card__meta">
          <span class="shared-campaign-registry-source is-${escapeHtml(sourceClass)}">${escapeHtml(sourceLabel)}</span>
          ${updated ? `<span>${escapeHtml(updated)}</span>` : ""}
        </div>
        <h3>${escapeHtml(voter.displayName)}</h3>
        <p>${escapeHtml([voter.city, voter.state, voter.politicalAffiliation].map(normalizeString).filter(Boolean).join(" - ") || "No district context shared")}</p>
      </div>
      <div class="shared-campaign-registry-row__summary">
        <strong>${escapeHtml(preferred.length ? `${formatCount(preferred.length)} preferred` : "No preferred contact")}</strong>
        <span>${escapeHtml(noContact.length ? `${formatCount(noContact.length)} blocked channels` : "No blocked channels")}</span>
        <div class="shared-campaign-registry-row__summary-plan">
          <em>${escapeHtml(preferredSummary)}</em>
          <em>${escapeHtml(blockedSummary)}</em>
        </div>
      </div>
    </div>
    <div class="shared-campaign-registry-row__contact">
      ${contactRows
        .map(
          ([icon, label, value]) =>
            `<span class="${normalizeString(value).startsWith("No ") ? "is-empty" : ""}">
              ${renderIcon(icon)}
              <span><strong>${escapeHtml(label)}</strong>${escapeHtml(value)}</span>
            </span>`,
        )
        .join("")}
    </div>
    ${renderCandidateVoterPreferencePills(voter)}
    ${
      options.notesRoute
        ? `<div class="shared-campaign-registry-row__actions">
            <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(options.notesRoute)}">${renderIcon("comment")} <span>Notes</span></button>
          </div>`
        : ""
    }
  </article>`;
}

function renderCandidateVoterDuplicate(resource) {
  const duplicate = resource.duplicate;
  if (!duplicate) {
    return "";
  }
  const existing = duplicate.existing || {};
  const pending = normalizeString(resource.actionPendingKey).startsWith("duplicate:");
  return `<div class="shared-campaign-registry-duplicate">
    <span class="shared-campaign-registry-duplicate__icon">${renderIcon("registry")}</span>
    <div>
      <strong>Duplicate voter found</strong>
      <span>${escapeHtml(existing.displayName || "Existing voter")}${existing.city ? ` in ${escapeHtml(existing.city)}` : ""}. Keep the existing record or replace it with this submission.</span>
    </div>
    <div class="shared-card__actions">
      <button class="shared-feed-chip" type="button" data-action="candidate-voter-duplicate-resolve" data-mode="skip"${disabledAttr(pending)}>Keep existing</button>
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-voter-duplicate-resolve" data-mode="replace"${disabledAttr(pending)}>Replace existing</button>
      <button class="shared-feed-chip" type="button" data-action="candidate-voter-duplicate-cancel"${disabledAttr(pending)}>Cancel</button>
    </div>
  </div>`;
}

function renderCandidateVoterManualForm(resource) {
  const saving = resource.actionPendingKey === "manual";
  return `<form class="shared-campaign-registry-manual" data-route-form="candidate-voter-manual">
    <section class="shared-campaign-registry-form-section">
      <div>
        <strong>Identity and location</strong>
        <span>Name plus any address details the campaign is allowed to store.</span>
      </div>
      <div class="shared-campaign-registry-form-grid">
        <label class="is-wide">
          <span>Name</span>
          <input name="name" autocomplete="name"${disabledAttr(saving)} />
        </label>
        <label class="is-wide">
          <span>Address line 1</span>
          <input name="addressLine1" autocomplete="address-line1"${disabledAttr(saving)} />
        </label>
        <label>
          <span>Address line 2</span>
          <input name="addressLine2" autocomplete="address-line2"${disabledAttr(saving)} />
        </label>
        <label>
          <span>City</span>
          <input name="city" autocomplete="address-level2"${disabledAttr(saving)} />
        </label>
        <label>
          <span>State</span>
          <input name="state" autocomplete="address-level1" maxlength="32"${disabledAttr(saving)} />
        </label>
        <label>
          <span>Postal code</span>
          <input name="postalCode" autocomplete="postal-code"${disabledAttr(saving)} />
        </label>
      </div>
    </section>
    <section class="shared-campaign-registry-form-section">
      <div>
        <strong>Contact details</strong>
        <span>Store only channels the voter shared or the campaign is permitted to use.</span>
      </div>
      <div class="shared-campaign-registry-form-grid">
        <label>
          <span>Phone</span>
          <input name="phone" autocomplete="tel"${disabledAttr(saving)} />
        </label>
        <label>
          <span>Email</span>
          <input name="email" type="email" autocomplete="email"${disabledAttr(saving)} />
        </label>
        <label class="is-wide">
          <span>Political affiliation</span>
          <input name="party" autocomplete="off"${disabledAttr(saving)} />
        </label>
      </div>
    </section>
    <section class="shared-campaign-registry-form-section">
      <div>
        <strong>Contact preferences</strong>
        <span>Set whether each outreach channel is wanted, blocked, or not known yet.</span>
      </div>
      <div class="shared-campaign-registry-pref-grid">
        ${CANDIDATE_CONTACT_TYPE_CONFIG.map((type) =>
          renderCandidateVoterPreferenceSelect(type.key, "unset", type.label),
        ).join("")}
      </div>
    </section>
    <div class="shared-campaign-registry-form-actions">
      <button class="shared-feed-chip shared-feed-chip--primary shared-campaign-registry-icon-chip" type="submit"${disabledAttr(saving)}>${renderIcon("create")} <span>${escapeHtml(saving ? "Saving..." : "Save voter")}</span></button>
    </div>
  </form>`;
}

function renderCandidateVoterImportPreview(registryImport) {
  const preview = registryImport.preview;
  if (!preview) {
    return "";
  }
  const summary = preview.summary || {};
  return `<div class="shared-campaign-registry-import-preview">
    <div class="shared-campaign-registry-summary">
      ${renderCandidateDashboardMetric("Total", formatCount(summary.totalRows || 0), "cyan")}
      ${renderCandidateDashboardMetric("Valid", formatCount(summary.validRows || 0))}
      ${renderCandidateDashboardMetric("Invalid", formatCount(summary.invalidRows || 0))}
      ${renderCandidateDashboardMetric("Existing dupes", formatCount(summary.duplicateExistingRows || 0))}
    </div>
    ${
      preview.items?.length
        ? `<div class="shared-campaign-registry-preview-list">
            ${preview.items
              .slice(0, 10)
              .map(
                (item) => `<div class="shared-list-item">
                  <strong>${escapeHtml(item.displayName || `Row ${item.rowNumber}`)}</strong>
                  <span>${escapeHtml([item.city, item.state, item.politicalAffiliation, item.status].map(normalizeString).filter(Boolean).join(" - ") || item.reason || "Preview row")}</span>
                </div>`,
              )
              .join("")}
          </div>`
        : ""
    }
  </div>`;
}

function renderCandidateVoterImportStatus(registryImport) {
  const status = registryImport.status;
  if (!status) {
    return "";
  }
  const pending = registryImport.actionPendingKey === "status";
  return `<div class="shared-campaign-registry-import-status">
    <span class="shared-campaign-registry-import-status__icon">${renderIcon("upload")}</span>
    <div>
      <strong>${escapeHtml(humanizeLabel(status.status || "queued"))}</strong>
      <span>Processed ${escapeHtml(formatCount(status.processedRows))}; imported ${escapeHtml(formatCount(status.successCount))}; skipped ${escapeHtml(formatCount(status.skippedDuplicateCount))}; errors ${escapeHtml(formatCount(status.errorCount))}</span>
      ${status.errorMessage ? `<em>${escapeHtml(status.errorMessage)}</em>` : ""}
    </div>
    <button class="shared-feed-chip" type="button" data-action="candidate-voter-import-status"${disabledAttr(pending)}>${pending ? "Refreshing..." : "Refresh status"}</button>
  </div>`;
}

function renderCandidateVoterImportPanel(resource) {
  const registryImport = resource.import;
  const previewing = registryImport.actionPendingKey === "preview";
  const starting = registryImport.actionPendingKey === "start";
  const canStart = registryImport.uploadId && registryImport.preview && !starting;
  const previewReady = Boolean(registryImport.preview);
  const importStarted = Boolean(registryImport.status);
  return `<article id="registry-import-voters" class="shared-campaign-panel shared-campaign-registry-import">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Bulk CSV import</h2>
        <p>Preview a voter CSV, choose duplicate handling, then start the import.</p>
      </div>
    </div>
    <div class="shared-campaign-registry-import-steps">
      <span class="${previewReady ? "is-complete" : "is-active"}"><em>1</em>Preview</span>
      <span class="${previewReady ? importStarted ? "is-complete" : "is-active" : ""}"><em>2</em>Duplicates</span>
      <span class="${importStarted ? "is-active" : ""}"><em>3</em>Import</span>
    </div>
    <form class="shared-campaign-registry-import-form" data-route-form="candidate-voter-import-preview">
      <label>
        <span>CSV file</span>
        <input name="csvFile" type="file" accept=".csv,text/csv"${disabledAttr(previewing || starting)} />
      </label>
      <button class="shared-feed-chip shared-feed-chip--primary shared-campaign-registry-icon-chip" type="submit"${disabledAttr(previewing || starting)}>${renderIcon("upload")} <span>${escapeHtml(previewing ? "Previewing..." : "Preview CSV")}</span></button>
    </form>
    ${registryImport.error ? `<div class="shared-page__error">${escapeHtml(registryImport.error)}</div>` : ""}
    ${registryImport.fileName ? `<p class="shared-campaign-registry-import-file">Selected: ${escapeHtml(registryImport.fileName)}</p>` : ""}
    ${renderCandidateVoterImportPreview(registryImport)}
    ${
      registryImport.preview
        ? `<div class="shared-campaign-registry-import-start">
            <label>
              <span>Duplicates</span>
              <select data-registry-import-duplicate-mode>
                <option value="replace"${selectedAttr(registryImport.duplicateMode === "replace")}>Replace existing</option>
                <option value="skip"${selectedAttr(registryImport.duplicateMode === "skip")}>Keep existing</option>
              </select>
            </label>
            <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-voter-import-start"${disabledAttr(!canStart)}>${starting ? "Starting..." : "Start import"}</button>
          </div>`
        : ""
    }
    ${renderCandidateVoterImportStatus(registryImport)}
  </article>`;
}

function renderCandidateDashboardVoterRegistry(detail, candidateId = "") {
  const resource = detail.voterRegistry;
  const importedCount = resource.items.filter(
    (item) => candidateVoterSourceLabel(item).toLowerCase() === "imported",
  ).length;
  const polisCount = resource.items.filter(
    (item) => candidateVoterSourceLabel(item).toLowerCase() === "polis",
  ).length;
  const manualCount = resource.items.filter(
    (item) => candidateVoterSourceLabel(item).toLowerCase() === "manual",
  ).length;
  const preferredCount = resource.items.filter(
    (item) => candidateVoterPreferredContactTypes(item).length > 0,
  ).length;
  const noContactCount = resource.items.filter(
    (item) => candidateVoterNoContactTypes(item).length > 0,
  ).length;
  const filterCount = candidateVoterRegistryActiveFilterCount(resource.filters);
  return `<div class="shared-campaign-section shared-campaign-registry">
    ${renderCandidateVoterRegistryCommandCenter(resource, {
      loaded: resource.items.length,
      preferred: preferredCount,
      noContact: noContactCount,
    })}
    <div class="shared-campaign-metrics">
      ${renderCandidateDashboardMetric("Loaded voters", formatCount(resource.items.length), "cyan")}
      ${renderCandidateDashboardMetric("Preferred contact", formatCount(preferredCount))}
      ${renderCandidateDashboardMetric("Sources", `${formatCount(polisCount)} Polis / ${formatCount(importedCount)} import / ${formatCount(manualCount)} manual`)}
      ${renderCandidateDashboardMetric("Filters", filterCount ? `${formatCount(filterCount)} active` : "All voters")}
    </div>
    ${renderCandidateVoterRegistryWorkflow(resource)}
    <div class="shared-campaign-registry-grid">
      <article id="registry-voters" class="shared-campaign-panel shared-campaign-registry-list-panel">
        <div class="shared-campaign-panel__header">
          <div>
            <h2>Connected voters</h2>
            <p>Search, filter, and review campaign voter records from Polis opt-ins, manual adds, and imports.</p>
          </div>
          <button class="shared-feed-chip shared-campaign-registry-icon-chip" type="button" data-action="candidate-voter-registry-refresh"${disabledAttr(resource.loading)}>${renderIcon("registry")} <span>Refresh</span></button>
        </div>
        ${renderCandidateVoterRegistryFilters(resource)}
        ${resource.error ? `<div class="shared-page__error">${escapeHtml(resource.error)}</div>` : ""}
        ${renderCandidateVoterDuplicate(resource)}
        ${resource.loading && !resource.items.length ? '<div class="shared-page__loading">Loading voter registry...</div>' : ""}
        ${
          !resource.loading && resource.loaded && !resource.items.length
            ? '<div class="shared-page__empty">No connected voters match this view.</div>'
            : ""
        }
        ${
          resource.items.length
            ? `<div class="shared-campaign-registry-list">${resource.items
                .map((item) =>
                  renderCandidateVoterRow(item, {
                    notesRoute: candidateId
                      ? candidateVoterMapNotesPath(candidateId, item)
                      : "",
                  }),
                )
                .join("")}</div>`
            : ""
        }
        ${
          resource.nextCursor
            ? `<div class="shared-campaign-engagement-more">
                <button class="shared-feed-chip" type="button" data-action="candidate-voter-registry-load-more"${disabledAttr(resource.loadingMore)}>${resource.loadingMore ? "Loading..." : "Load more"}</button>
              </div>`
            : ""
        }
      </article>
      <div class="shared-campaign-registry-side">
        <article id="registry-add-voters" class="shared-campaign-panel shared-campaign-registry-manual-panel">
          <div class="shared-campaign-panel__header">
            <div>
              <h2>Manual add</h2>
              <p>Add a voter record and capture contact preferences for field follow-up.</p>
            </div>
          </div>
          ${renderCandidateVoterManualForm(resource)}
        </article>
        ${renderCandidateVoterImportPanel(resource)}
      </div>
    </div>
  </div>`;
}

function campaignQuestProgressPercent(progress = {}) {
  const current = Number(progress.currentLevelXp) || 0;
  const next = Number(progress.nextLevelXp) || 100;
  if (next <= 0) {
    return 0;
  }
  return Math.max(0, Math.min(100, Math.round((current / next) * 100)));
}

function campaignQuestGoalProgress(quest = {}) {
  const goals = quest.goals || [];
  const current = goals.reduce((sum, goal) => sum + (Number(goal.current) || 0), 0);
  const target = goals.reduce((sum, goal) => sum + (Number(goal.target) || 0), 0);
  const pct = target
    ? Math.max(0, Math.min(100, Math.round((current / target) * 100)))
    : quest.completed === true
      ? 100
      : 0;
  return { current, target, pct };
}

function campaignQuestGoalSummary(quest = {}) {
  const { current, target } = campaignQuestGoalProgress(quest);
  return target ? `${formatCount(current)}/${formatCount(target)}` : "Ready";
}

function campaignQuestTargetSubtitle(target = {}) {
  const location = [
    target.addressLine1,
    [target.city, target.state, target.postalCode].map(normalizeString).filter(Boolean).join(" "),
  ]
    .map(normalizeString)
    .filter(Boolean)
    .join(", ");
  return location || target.privacyLabel || "Target";
}

function campaignQuestOutreachLabel(value) {
  const normalized = normalizeString(value);
  const labels = {
    doorKnock: "Door",
    yardSign: "Sign",
    phoneCall: "Call",
    phone: "Call",
    sms: "Text",
    text: "Text",
    email: "Email",
    litDrop: "Lit drop",
  };
  return labels[normalized] || humanizeLabel(normalized || "outreach");
}

function campaignQuestOutreachIcon(value) {
  const normalized = normalizeString(value).toLowerCase();
  if (normalized.includes("sign") || normalized.includes("flag")) {
    return "flag";
  }
  if (normalized.includes("phone") || normalized.includes("call")) {
    return "phone";
  }
  if (normalized.includes("sms") || normalized.includes("text")) {
    return "messages";
  }
  if (normalized.includes("email") || normalized.includes("mail")) {
    return "mail";
  }
  return "map";
}

function candidateVoterMapTargetIcon(target = {}) {
  const outreachType = normalizeStringList(target.availableOutreachTypes)[0];
  if (outreachType) {
    return campaignQuestOutreachIcon(outreachType);
  }
  const category = normalizeString(target.targetCategory).toLowerCase();
  if (category.includes("sign")) return "flag";
  if (category.includes("gotv")) return "team";
  if (category.includes("persuasion")) return "comment";
  return "map";
}

function campaignQuestOutcomeChoicesForTarget(config, outreachTypes = []) {
  const normalizedTypes = normalizeStringList(outreachTypes);
  const fields = (config?.outcomeFields || []).filter((field) => {
    if (field.enabled === false) return false;
    if (!normalizedTypes.length || !field.outreachTypes.length) return true;
    return field.outreachTypes.some((type) => normalizedTypes.includes(type));
  });
  return fields.length
    ? fields
    : campaignQuestOutcomesFor(config, normalizedTypes[0] || "");
}

function campaignQuestCategorySummary(targets = []) {
  const counts = targets.reduce((out, target) => {
    const key = normalizeString(target.targetCategory) || "standard_target";
    out[key] = (out[key] || 0) + 1;
    return out;
  }, {});
  const ordered = [
    "high_impact_persuasion",
    "gotv_priority",
    "likely_supporter",
    "sign_delivery",
    "standard_target",
  ];
  return [
    ...ordered.filter((key) => counts[key]).map((key) => [key, counts[key]]),
    ...Object.entries(counts).filter(([key]) => !ordered.includes(key)),
  ];
}

function campaignQuestCategoryOptions(targets = []) {
  const summary = campaignQuestCategorySummary(targets);
  return [
    ["all", targets.length],
    ...summary,
  ].map(([key, count]) => ({
    key,
    count,
    label: key === "all" ? "All" : humanizeLabel(key),
  }));
}

function campaignQuestFilteredTargets(resource = {}) {
  const targets = resource.targets || [];
  const filter = normalizeString(resource.categoryFilter) || "all";
  if (filter === "all") {
    return targets;
  }
  return targets.filter((target) => target.targetCategory === filter);
}

function campaignQuestSelectedTarget(resource = {}, filteredTargets = null) {
  const targets = resource.targets || [];
  const filtered = filteredTargets || campaignQuestFilteredTargets(resource);
  const selectedId = normalizeString(resource.selectedTargetId);
  return (
    targets.find((target) => target.recordId === selectedId) ||
    filtered[0] ||
    targets[0] ||
    null
  );
}

function campaignQuestCoordinateBounds(items = []) {
  const points = items.filter(
    (item) =>
      Number.isFinite(item.lat) &&
      Number.isFinite(item.lng) &&
      (item.lat !== 0 || item.lng !== 0),
  );
  if (!points.length) {
    return null;
  }
  return points.reduce(
    (bounds, item) => ({
      minLat: Math.min(bounds.minLat, item.lat),
      maxLat: Math.max(bounds.maxLat, item.lat),
      minLng: Math.min(bounds.minLng, item.lng),
      maxLng: Math.max(bounds.maxLng, item.lng),
    }),
    {
      minLat: points[0].lat,
      maxLat: points[0].lat,
      minLng: points[0].lng,
      maxLng: points[0].lng,
    },
  );
}

function campaignQuestMapPosition(item, index, total, bounds) {
  if (
    bounds &&
    Number.isFinite(item.lat) &&
    Number.isFinite(item.lng) &&
    (item.lat !== 0 || item.lng !== 0)
  ) {
    const latSpan = Math.max(0.0001, bounds.maxLat - bounds.minLat);
    const lngSpan = Math.max(0.0001, bounds.maxLng - bounds.minLng);
    return {
      x: Math.max(5, Math.min(95, 5 + ((item.lng - bounds.minLng) / lngSpan) * 90)),
      y: Math.max(5, Math.min(95, 95 - ((item.lat - bounds.minLat) / latSpan) * 90)),
    };
  }
  const angle = ((index + 0.35) / Math.max(1, total)) * Math.PI * 2;
  const radius = 31 + ((index % 3) * 7);
  return {
    x: 50 + Math.cos(angle) * radius,
    y: 50 + Math.sin(angle) * radius,
  };
}

function campaignQuestLocationCopy(resource = {}) {
  if (resource.locationPending) {
    return "Checking browser location...";
  }
  if (resource.lastKnownLocation) {
    const accuracy = Number(resource.lastKnownLocation.accuracy);
    return Number.isFinite(accuracy)
      ? `Location ready within ${formatCount(Math.round(accuracy))}m`
      : "Location ready";
  }
  return normalizeString(resource.locationStatus) || "Location not shared";
}

function renderCampaignQuestCommandCenter(resource, progress, config, canManage) {
  const candidateId = currentCandidateDashboardId();
  const targets = resource.targets || [];
  const clusters = resource.clusters || [];
  const enabled = config.enabled !== false;
  const activeQuests = (progress.quests || []).filter((quest) => quest.completed !== true);
  return `<article class="shared-campaign-quest-command">
    <div class="shared-campaign-quest-command__icon">${renderIcon("map")}</div>
    <div class="shared-campaign-quest-command__body">
      <span>${escapeHtml(enabled ? "Campaign Quest active" : "Campaign Quest disabled")}</span>
      <h2>Field map console</h2>
      <p>Run voter-map targets, track XP progress, and keep the browser route aligned with the native Campaign Quest workflow.</p>
      <div class="shared-campaign-quest-command__status">
        <span>${escapeHtml(formatCount(targets.length))} targets</span>
        <span>${escapeHtml(formatCount(clusters.length))} clusters</span>
        <span>${escapeHtml(formatCount(activeQuests.length))} active quests</span>
        <span>${escapeHtml(config.safety.activeShiftRequired ? "Shift required" : "Open shift")}</span>
      </div>
    </div>
    <div class="shared-campaign-quest-command__actions">
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-quest-refresh"${disabledAttr(resource.loading)}>Refresh targets</button>
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(candidateVoterMapPath("map", candidateId))}">Map route</button>
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(candidateDashboardSectionPath(candidateId, "voter-registry"))}">Voter records</button>
      ${canManage ? `<a class="shared-feed-chip shared-campaign-quest-anchor" href="#campaign-quest-settings">Settings</a>` : ""}
    </div>
  </article>`;
}

function renderCampaignQuestProgress(progress) {
  const normalized = progress || normalizeCampaignQuestProgress({});
  const pct = campaignQuestProgressPercent(normalized);
  const streak = normalized.streak || {};
  return `<article class="shared-campaign-panel shared-campaign-quest-progress">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Campaign Quest</h2>
        <p>Track field XP, active quests, badges, and nearby voter-map targets.</p>
      </div>
    </div>
    <div class="shared-campaign-quest-level">
      <div class="shared-campaign-quest-level__top">
        <div class="shared-campaign-quest-level__badge">
          <span>Level</span>
          <strong>${escapeHtml(formatCount(normalized.level))}</strong>
        </div>
        <div class="shared-campaign-quest-level__xp">
          <span>Lifetime XP</span>
          <strong>${escapeHtml(formatCount(normalized.lifetimeXp))}</strong>
        </div>
      </div>
      <div class="shared-campaign-quest-level__bar" aria-hidden="true">
        <span style="width:${escapeHtml(String(pct))}%"></span>
      </div>
      <p><strong>${escapeHtml(String(pct))}%</strong> complete to next level - ${escapeHtml(formatCount(normalized.currentLevelXp))} / ${escapeHtml(formatCount(normalized.nextLevelXp))} XP</p>
    </div>
    <div class="shared-campaign-registry-summary">
      ${renderCandidateDashboardMetric("Today", formatCount(normalized.dailyXp), "cyan")}
      ${renderCandidateDashboardMetric("Week", formatCount(normalized.weeklyXp))}
      ${renderCandidateDashboardMetric("Streak", formatCount(streak.current || 0))}
      ${renderCandidateDashboardMetric("Badges", formatCount(normalized.badges.length))}
    </div>
  </article>`;
}

function renderCampaignQuestQuests(progress) {
  const quests = (progress?.quests || []).slice(0, 6);
  return `<article class="shared-campaign-panel shared-campaign-quest-list-panel">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Active quests</h2>
        <p>Daily and campaign goals that award bonus XP.</p>
      </div>
    </div>
    ${
      quests.length
        ? `<div class="shared-campaign-quest-cards">
            ${quests
              .map((quest) => {
                const summary = campaignQuestGoalSummary(quest);
                const { pct } = campaignQuestGoalProgress(quest);
                const completed = quest.completed === true;
                return `<article class="shared-campaign-quest-card${completed ? " is-complete" : ""}">
                  <div>
                    <span>${escapeHtml(completed ? "Complete" : summary)}</span>
                    <em>+${escapeHtml(formatCount(quest.rewardXp))} XP</em>
                  </div>
                  <strong>${escapeHtml(quest.title)}</strong>
                  <div class="shared-campaign-quest-card__bar" aria-hidden="true"><span style="width:${escapeHtml(String(pct))}%"></span></div>
                </article>`;
              })
              .join("")}
          </div>`
        : `<div class="shared-page__empty">No active quests loaded.</div>`
    }
  </article>`;
}

function renderCampaignQuestBadges(config, progress) {
  const unlocked = new Set((progress?.badges || []).map((badge) => badge.id));
  const badges = (config?.badges || []).slice(0, 8);
  return `<article class="shared-campaign-panel shared-campaign-quest-list-panel">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Badges</h2>
        <p>Recognition rules for canvassing milestones.</p>
      </div>
    </div>
    ${
      badges.length
        ? `<div class="shared-campaign-quest-badges">
            ${badges
              .map(
                (badge) => `<span class="${unlocked.has(badge.id) ? "is-unlocked" : ""}">
                  <strong>${escapeHtml(badge.title)}</strong>
                  <em>${escapeHtml(unlocked.has(badge.id) ? "Unlocked" : `${humanizeLabel(badge.metric || "metric")} ${formatCount(badge.target)}`)}</em>
                </span>`,
              )
              .join("")}
          </div>`
        : `<div class="shared-page__empty">No badge rules loaded.</div>`
    }
  </article>`;
}

function renderCampaignQuestCategoryFilter(resource) {
  const options = campaignQuestCategoryOptions(resource.targets || []);
  const active = normalizeString(resource.categoryFilter) || "all";
  return `<div class="shared-campaign-quest-filter" role="list" aria-label="Campaign Quest target filters">
    ${options
      .map(
        (option) => `<button class="${option.key === active ? "is-active" : ""}" type="button" data-action="candidate-quest-category" data-category="${escapeHtml(option.key)}">
          <strong>${escapeHtml(formatCount(option.count))}</strong>
          <span>${escapeHtml(option.label)}</span>
        </button>`,
      )
      .join("")}
  </div>`;
}

function renderCampaignQuestMapCanvas(resource, selectedTarget, filteredTargets) {
  const targets = (filteredTargets || []).slice(0, 28);
  const clusters = (resource.clusters || []).slice(0, 10);
  const bounds = campaignQuestCoordinateBounds([...targets, ...clusters]);
  return `<div class="shared-campaign-quest-map" aria-label="Campaign Quest target map preview">
    <div class="shared-campaign-quest-map__grid" aria-hidden="true"></div>
    <div class="shared-campaign-quest-map__route" aria-hidden="true"></div>
    ${clusters
      .map((cluster, index) => {
        const position = campaignQuestMapPosition(
          cluster,
          index,
          Math.max(1, clusters.length),
          bounds,
        );
        return `<span class="shared-campaign-quest-cluster" style="--x:${escapeHtml(position.x.toFixed(2))}%;--y:${escapeHtml(position.y.toFixed(2))}%">${escapeHtml(formatCount(cluster.count))}</span>`;
      })
      .join("")}
    ${targets
      .map((target, index) => {
        const position = campaignQuestMapPosition(
          target,
          index + clusters.length,
          Math.max(1, targets.length + clusters.length),
          bounds,
        );
        const selected = selectedTarget?.recordId === target.recordId;
        return `<button class="shared-campaign-quest-pin is-${escapeHtml(target.targetCategory)}${selected ? " is-selected" : ""}" style="--x:${escapeHtml(position.x.toFixed(2))}%;--y:${escapeHtml(position.y.toFixed(2))}%" type="button" data-action="candidate-quest-target-select" data-record-id="${escapeHtml(target.recordId)}" aria-label="${escapeHtml(`Select ${target.displayName || target.privacyLabel || "target"}`)}">
          <span></span>
        </button>`;
      })
      .join("")}
    ${
      resource.lastKnownLocation
        ? `<span class="shared-campaign-quest-avatar" style="--x:50%;--y:50%" title="Your last shared location">Q</span>`
        : ""
    }
    <div class="shared-campaign-quest-map__legend">
      <span><i class="is-high_impact_persuasion"></i>Persuasion</span>
      <span><i class="is-gotv_priority"></i>GOTV</span>
      <span><i class="is-sign_delivery"></i>Signs</span>
    </div>
  </div>`;
}

function renderCampaignQuestSelectedTargetPanel(target, config, resource) {
  if (!target) {
    return `<aside class="shared-campaign-quest-selected">
      <div class="shared-campaign-quest-selected__empty">
        <span>${renderIcon("map")}</span>
        <strong>Select a field target</strong>
        <p>Choose a pin or queue item to claim the next visit, record an outcome, and keep Campaign Quest progress moving.</p>
      </div>
    </aside>`;
  }
  const pendingKey = resource.actionPendingKey;
  const pending =
    pendingKey === `start:${target.recordId}` ||
    pendingKey === `complete:${target.recordId}`;
  const outreachTypes = target.availableOutreachTypes.length
    ? target.availableOutreachTypes
    : ["doorKnock", "yardSign"];
  const defaultOutreach = normalizeString(outreachTypes[0]);
  const outcomes = campaignQuestOutcomeChoicesForTarget(config, outreachTypes);
  const notesRoute = candidateVoterMapNotesPath(currentCandidateDashboardId(), target);
  const targetTitle =
    target.displayName || target.addressLine1 || target.privacyLabel || "Campaign target";
  const targetSubtitle = campaignQuestTargetSubtitle(target);
  const selectedOutcomeId =
    outcomes.find(
      (outcome) =>
        !outcome.outreachTypes.length ||
        outcome.outreachTypes.includes(defaultOutreach),
    )?.id ||
    outcomes[0]?.id ||
    "";
  return `<aside class="shared-campaign-quest-selected" data-quest-target-row="${escapeHtml(target.recordId)}">
    <div class="shared-campaign-quest-selected__header">
      <span class="shared-campaign-quest-dot is-${escapeHtml(target.targetCategory)}"></span>
      <div>
        <small>Selected target</small>
        <strong>${escapeHtml(targetTitle)}</strong>
        <em>${escapeHtml(targetSubtitle)}</em>
      </div>
    </div>
    <div class="shared-campaign-quest-selected__meta">
      <span>${escapeHtml(humanizeLabel(target.targetCategory))}</span>
      <span>${escapeHtml(humanizeLabel(target.pinState))}</span>
      <span>${escapeHtml(target.privacyLabel || "Target")}</span>
    </div>
    <div class="shared-campaign-quest-complete-sheet">
      <div class="shared-campaign-quest-complete-sheet__section">
        <span>Outreach</span>
        <div class="shared-campaign-quest-choice-grid">
          ${outreachTypes
            .map(
              (type, index) => `<label class="shared-campaign-quest-choice">
                <input type="radio" name="quest-outreach-${escapeHtml(target.recordId)}" value="${escapeHtml(type)}" data-quest-outreach${checkedAttr(index === 0)}${disabledAttr(pending)} />
                <span>${renderIcon(campaignQuestOutreachIcon(type))}<strong>${escapeHtml(campaignQuestOutreachLabel(type))}</strong></span>
              </label>`,
            )
            .join("")}
        </div>
      </div>
      <div class="shared-campaign-quest-complete-sheet__section">
        <span>Outcome</span>
        ${
          outcomes.length
            ? `<div class="shared-campaign-quest-outcome-grid" data-quest-outcomes>
                ${outcomes
                  .map((outcome) => {
                    const outreachMatch =
                      !outcome.outreachTypes.length ||
                      outcome.outreachTypes.includes(defaultOutreach);
                    const outreachLabel = outcome.outreachTypes.length
                      ? outcome.outreachTypes.map(campaignQuestOutreachLabel).join(", ")
                      : "Any outreach";
                    return `<label class="shared-campaign-quest-outcome-choice${outreachMatch ? "" : " is-hidden"}" data-quest-outcome-choice data-outreach-types="${escapeHtml(outcome.outreachTypes.join(","))}"${outreachMatch ? "" : " hidden"}>
                      <input type="radio" name="quest-outcome-${escapeHtml(target.recordId)}" value="${escapeHtml(outcome.id)}" data-quest-outcome${checkedAttr(outcome.id === selectedOutcomeId)}${disabledAttr(pending)} />
                      <span>
                        <strong>${escapeHtml(outcome.label)}</strong>
                        <small>${escapeHtml(outreachLabel)}</small>
                      </span>
                    </label>`;
                  })
                  .join("")}
              </div>`
            : '<div class="shared-page__empty">No completion outcomes are configured for this target.</div>'
        }
      </div>
      <label class="shared-campaign-quest-note">
        <span>Field note</span>
        <textarea data-quest-note rows="3" placeholder="Add context for the field team"${disabledAttr(pending)}></textarea>
      </label>
    </div>
    <div class="shared-campaign-quest-selected__actions">
      <button class="shared-feed-chip" type="button" data-action="candidate-quest-target-start" data-record-id="${escapeHtml(target.recordId)}"${disabledAttr(pending)}>${pendingKey === `start:${target.recordId}` ? "Claiming..." : "Claim"}</button>
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-quest-target-complete" data-record-id="${escapeHtml(target.recordId)}"${disabledAttr(pending || !outcomes.length)}>${pendingKey === `complete:${target.recordId}` ? "Completing..." : "Complete"}</button>
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(notesRoute)}">Notes</button>
    </div>
  </aside>`;
}

function renderCampaignQuestFieldBoard(resource, progress, config) {
  const filteredTargets = campaignQuestFilteredTargets(resource);
  const selectedTarget = campaignQuestSelectedTarget(resource, filteredTargets);
  const activeQuests = (progress?.quests || []).filter((quest) => quest.completed !== true);
  return `<article class="shared-campaign-panel shared-campaign-quest-field">
    <div class="shared-campaign-panel__header shared-campaign-quest-field__header">
      <div>
        <h2>Field map board</h2>
        <p>Start a shift, filter nearby targets, and finish the same claim/complete flow used by the app.</p>
      </div>
      <div class="shared-campaign-quest-shift">
        <span class="${resource.shiftActive ? "is-active" : ""}">${escapeHtml(resource.shiftActive ? "Shift active" : "Shift off")}</span>
        <small>${escapeHtml(campaignQuestLocationCopy(resource))}</small>
      </div>
    </div>
    <div class="shared-campaign-quest-field__toolbar">
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="candidate-quest-shift-start"${disabledAttr(resource.locationPending || resource.shiftActive)}>${resource.locationPending ? "Checking..." : resource.shiftActive ? "Shift running" : "Start shift"}</button>
      <button class="shared-feed-chip" type="button" data-action="candidate-quest-follow-location"${disabledAttr(resource.locationPending)}>${resource.locationPending ? "Checking..." : "Use location"}</button>
      <button class="shared-feed-chip" type="button" data-action="candidate-quest-shift-stop"${disabledAttr(!resource.shiftActive)}>End shift</button>
      <span>${escapeHtml(`${formatCount(filteredTargets.length)} visible targets - ${formatCount(activeQuests.length)} active quests`)}</span>
    </div>
    ${renderCampaignQuestCategoryFilter(resource)}
    <div class="shared-campaign-quest-field__layout">
      ${renderCampaignQuestMapCanvas(resource, selectedTarget, filteredTargets)}
      ${renderCampaignQuestSelectedTargetPanel(selectedTarget, config, resource)}
    </div>
  </article>`;
}

function renderCampaignQuestTargetQueueItem(target, selected) {
  return `<button class="shared-campaign-quest-queue-item${selected ? " is-selected" : ""}" type="button" data-action="candidate-quest-target-select" data-record-id="${escapeHtml(target.recordId)}">
    <span class="shared-campaign-quest-dot is-${escapeHtml(target.targetCategory)}"></span>
    <span>
      <strong>${escapeHtml(target.displayName || target.addressLine1 || target.privacyLabel || "Campaign target")}</strong>
      <small>${escapeHtml(campaignQuestTargetSubtitle(target))}</small>
    </span>
    <em>${escapeHtml(humanizeLabel(target.pinState))}</em>
  </button>`;
}

function renderCampaignQuestTargets(resource) {
  const targets = campaignQuestFilteredTargets(resource);
  const selectedTarget = campaignQuestSelectedTarget(resource, targets);
  const clusterTotal = (resource.clusters || []).reduce(
    (sum, cluster) => sum + (Number(cluster.count) || 0),
    0,
  );
  return `<article class="shared-campaign-panel shared-campaign-quest-targets">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Target queue</h2>
        <p>Pick the next voter-map target, then complete the action from the field board.</p>
      </div>
      <button class="shared-feed-chip" type="button" data-action="candidate-quest-refresh"${disabledAttr(resource.loading)}>Refresh</button>
    </div>
    <div class="shared-campaign-quest-clusters">
      <span>${escapeHtml(formatCount(targets.length))} visible targets</span>
      <span>${escapeHtml(formatCount(resource.clusters.length))} clusters</span>
      <span>${escapeHtml(formatCount(clusterTotal))} voters in clusters</span>
    </div>
    ${
      targets.length
        ? `<div class="shared-campaign-quest-queue">
            ${targets
              .slice(0, 20)
              .map((target) =>
                renderCampaignQuestTargetQueueItem(
                  target,
                  selectedTarget?.recordId === target.recordId,
                ),
              )
              .join("")}
          </div>`
        : `<div class="shared-page__empty">No Campaign Quest targets loaded for this area.</div>`
    }
  </article>`;
}

function campaignQuestJsonTextareaValue(value = {}) {
  try {
    return JSON.stringify(
      value && typeof value === "object" && !Array.isArray(value) ? value : {},
      null,
      2,
    );
  } catch {
    return "{}";
  }
}

function renderCampaignQuestConfigBlockHeader(title, description, count = null) {
  return `<div class="shared-campaign-quest-config-block__header">
    <div>
      <strong>${escapeHtml(title)}</strong>
      <p>${escapeHtml(description)}</p>
    </div>
    ${count === null ? "" : `<span>${escapeHtml(formatCount(count))}</span>`}
  </div>`;
}

function renderCampaignQuestConfigEmpty(message) {
  return `<div class="shared-campaign-quest-config-empty">${escapeHtml(message)}</div>`;
}

function renderCampaignQuestNumberMapEditor(section, values = {}, saving) {
  const source =
    values && typeof values === "object" && !Array.isArray(values) ? values : {};
  const entries = Object.entries(source).sort((a, b) =>
    a[0].localeCompare(b[0]),
  );
  return `<section class="shared-campaign-quest-config-block">
    ${renderCampaignQuestConfigBlockHeader(section.title, section.description, entries.length)}
    ${
      entries.length
        ? `<div class="shared-campaign-quest-config-list shared-campaign-quest-config-list--compact">
            ${entries
              .map(
                ([key, value], index) => `<label class="shared-campaign-quest-config-row">
                  <span>${escapeHtml(humanizeLabel(key))}<em>${escapeHtml(key)}</em></span>
                  <input type="hidden" name="xp:${escapeHtml(section.key)}:${index}:key" value="${escapeHtml(key)}" />
                  <input name="xp:${escapeHtml(section.key)}:${index}:value" type="number" step="0.05" value="${escapeHtml(String(Number(value) || 0))}"${disabledAttr(saving)} />
                </label>`,
              )
              .join("")}
          </div>`
        : renderCampaignQuestConfigEmpty("No XP rules are configured for this section.")
    }
  </section>`;
}

function renderCampaignQuestOutcomeEditor(outcome, index, saving) {
  return `<article class="shared-campaign-quest-config-card">
    <div class="shared-campaign-quest-config-card__top">
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="outcome:${index}:enabled"${checkedAttr(outcome.enabled)}${disabledAttr(saving)} />
        <span>${escapeHtml(outcome.label || outcome.id || "Outcome")}</span>
      </label>
      <em>${escapeHtml(outcome.id)}</em>
    </div>
    <label>
      <span>Label</span>
      <input name="outcome:${index}:label" value="${escapeHtml(outcome.label)}"${disabledAttr(saving)} />
    </label>
    <label>
      <span>Outreach types</span>
      <input name="outcome:${index}:outreachTypes" value="${escapeHtml((outcome.outreachTypes || []).join(", "))}"${disabledAttr(saving)} />
    </label>
    <label class="shared-campaign-quest-config-wide">
      <span>Contact outcome JSON</span>
      <textarea name="outcome:${index}:contactOutcome" rows="5"${disabledAttr(saving)}>${escapeHtml(campaignQuestJsonTextareaValue(outcome.contactOutcome))}</textarea>
    </label>
  </article>`;
}

function renderCampaignQuestTemplateEditor(template, index, saving) {
  const period = normalizeString(template.period) || "daily";
  return `<article class="shared-campaign-quest-config-card">
    <div class="shared-campaign-quest-config-card__top">
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="quest:${index}:enabled"${checkedAttr(template.enabled)}${disabledAttr(saving)} />
        <span>${escapeHtml(template.title || template.id || "Quest")}</span>
      </label>
      <em>${escapeHtml(template.id)}</em>
    </div>
    <label class="shared-campaign-quest-config-wide">
      <span>Title</span>
      <input name="quest:${index}:title" value="${escapeHtml(template.title)}"${disabledAttr(saving)} />
    </label>
    <label>
      <span>Period</span>
      <select name="quest:${index}:period"${disabledAttr(saving)}>
        ${["daily", "weekly"]
          .map(
            (value) => `<option value="${escapeHtml(value)}"${selectedAttr(period === value)}>${escapeHtml(humanizeLabel(value))}</option>`,
          )
          .join("")}
        ${["daily", "weekly"].includes(period) ? "" : `<option value="${escapeHtml(period)}" selected>${escapeHtml(humanizeLabel(period))}</option>`}
      </select>
    </label>
    <label>
      <span>Reward XP</span>
      <input name="quest:${index}:rewardXp" type="number" min="0" step="1" value="${escapeHtml(String(template.rewardXp))}"${disabledAttr(saving)} />
    </label>
    <div class="shared-campaign-quest-config-goals">
      ${(template.goals || [])
        .map(
          (goal, goalIndex) => `<label>
            <span>${escapeHtml(humanizeLabel(goal.type))}<em>${escapeHtml(goal.type)}</em></span>
            <input name="quest:${index}:goal:${goalIndex}:target" type="number" min="1" step="1" value="${escapeHtml(String(goal.target))}"${disabledAttr(saving)} />
          </label>`,
        )
        .join("")}
    </div>
  </article>`;
}

function renderCampaignQuestBadgeEditor(badge, index, saving) {
  return `<article class="shared-campaign-quest-config-card">
    <div class="shared-campaign-quest-config-card__top">
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="badge:${index}:enabled"${checkedAttr(badge.enabled)}${disabledAttr(saving)} />
        <span>${escapeHtml(badge.title || badge.id || "Badge")}</span>
      </label>
      <em>${escapeHtml(badge.id)}</em>
    </div>
    <label class="shared-campaign-quest-config-wide">
      <span>Title</span>
      <input name="badge:${index}:title" value="${escapeHtml(badge.title)}"${disabledAttr(saving)} />
    </label>
    <label>
      <span>Metric</span>
      <input name="badge:${index}:metric" value="${escapeHtml(badge.metric)}"${disabledAttr(saving)} />
    </label>
    <label>
      <span>Target</span>
      <input name="badge:${index}:target" type="number" min="1" step="1" value="${escapeHtml(String(badge.target))}"${disabledAttr(saving)} />
    </label>
  </article>`;
}

function renderCampaignQuestConfigBriefing(config) {
  const safety = config.safety || {};
  const verification = config.verification || {};
  const privacy = config.privacy || {};
  const xpRules =
    config.xpRules && typeof config.xpRules === "object" ? config.xpRules : {};
  const scoringRuleCount = [
    "baseXp",
    "outcomeMultipliers",
    "verificationMultipliers",
    "caps",
  ].reduce((total, key) => {
    const section = xpRules[key];
    return total + (section && typeof section === "object" ? Object.keys(section).length : 0);
  }, 0);
  const fieldWindow = safety.canvassingHoursEnabled
    ? `${normalizeString(safety.canvassingHoursStart) || "start unset"} to ${
        normalizeString(safety.canvassingHoursEnd) || "end unset"
      }`
    : "No canvassing window";
  const cards = [
    {
      icon: "bolt",
      label: "Launch state",
      title: config.enabled ? "Field teams can use Campaign Quest" : "Campaign Quest is paused",
      copy: safety.activeShiftRequired
        ? "Volunteers must start a shift before claiming and completing targets."
        : "Volunteers can claim targets without a required shift gate.",
      meta: [
        fieldWindow,
        safety.allowSkipUnsafeAddress ? "Unsafe skip allowed" : "Unsafe skip locked",
      ],
    },
    {
      icon: "shield",
      label: "Trust checks",
      title: verification.gpsSoftCheckEnabled ? "Location confidence is on" : "Manual completions allowed",
      copy: "GPS, photo, and unverified XP settings decide how much trust each field action carries.",
      meta: [
        verification.gpsSoftCheckEnabled
          ? `${formatCount(verification.gpsNearbyMeters)}m GPS check`
          : "GPS check off",
        verification.photoRequiredForYardSigns ? "Sign photos required" : "Sign photos optional",
      ],
    },
    {
      icon: "chart",
      label: "Progress rules",
      title: `${formatCount(scoringRuleCount)} scoring rules`,
      copy: "XP values, multipliers, caps, outcomes, and quest templates shape volunteer progress.",
      meta: [
        `${formatCount(config.outcomeFields.length)} outcomes`,
        `${formatCount(config.questTemplates.length)} templates`,
      ],
    },
    {
      icon: "star",
      label: "Recognition",
      title: `${formatCount(config.badges.length)} badge rules`,
      copy: "Badge and leaderboard settings control how Campaign Quest achievements appear to teams.",
      meta: [
        `${humanizeLabel(privacy.publicBadgeVisibility)} visibility`,
        privacy.individualLeaderboardsEnabled ? "Individual leaderboard on" : "Team leaderboard only",
      ],
    },
  ];
  return `<div class="shared-campaign-quest-config-briefing" aria-label="Campaign Quest settings overview">
    ${cards
      .map(
        (card) => `<article>
          <span class="shared-campaign-quest-config-briefing__icon">${renderIcon(card.icon)}</span>
          <div>
            <small>${escapeHtml(card.label)}</small>
            <strong>${escapeHtml(card.title)}</strong>
            <p>${escapeHtml(card.copy)}</p>
            <div class="shared-campaign-quest-config-briefing__meta">
              ${card.meta.map((item) => `<span>${escapeHtml(item)}</span>`).join("")}
            </div>
          </div>
        </article>`,
      )
      .join("")}
  </div>`;
}

function renderCampaignQuestAdvancedConfig(config, saving) {
  const xpRules =
    config.xpRules && typeof config.xpRules === "object" ? config.xpRules : {};
  return `<section class="shared-campaign-quest-config-advanced">
    ${renderCampaignQuestConfigBlockHeader(
      "Scoring system",
      "Set the XP values, multipliers, and caps that decide how field work turns into progress.",
    )}
    <div class="shared-campaign-quest-config-stack">
      ${CAMPAIGN_QUEST_XP_SECTION_CONFIG.map((section) =>
        renderCampaignQuestNumberMapEditor(section, xpRules[section.key], saving),
      ).join("")}
    </div>
    <section class="shared-campaign-quest-config-block">
      ${renderCampaignQuestConfigBlockHeader(
        "Completion outcomes",
        "Choose the result labels volunteers see and how each result updates voter records.",
        config.outcomeFields.length,
      )}
      ${
        config.outcomeFields.length
          ? `<div class="shared-campaign-quest-config-list">${config.outcomeFields
              .map((outcome, index) =>
                renderCampaignQuestOutcomeEditor(outcome, index, saving),
              )
              .join("")}</div>`
          : renderCampaignQuestConfigEmpty("No completion outcomes are configured.")
      }
    </section>
    <section class="shared-campaign-quest-config-block">
      ${renderCampaignQuestConfigBlockHeader(
        "Quest templates",
        "Edit recurring goals, periods, and rewards before they appear for volunteers.",
        config.questTemplates.length,
      )}
      ${
        config.questTemplates.length
          ? `<div class="shared-campaign-quest-config-list">${config.questTemplates
              .map((template, index) =>
                renderCampaignQuestTemplateEditor(template, index, saving),
              )
              .join("")}</div>`
          : renderCampaignQuestConfigEmpty("No quest templates are configured.")
      }
    </section>
    <section class="shared-campaign-quest-config-block">
      ${renderCampaignQuestConfigBlockHeader(
        "Badges",
        "Set the visible milestones volunteers can earn from doors, conversations, and sign delivery.",
        config.badges.length,
      )}
      ${
        config.badges.length
          ? `<div class="shared-campaign-quest-config-list">${config.badges
              .map((badge, index) =>
                renderCampaignQuestBadgeEditor(badge, index, saving),
              )
              .join("")}</div>`
          : renderCampaignQuestConfigEmpty("No badge rules are configured.")
      }
    </section>
  </section>`;
}

function renderCampaignQuestConfigForm(config, resource, canManage) {
  if (!canManage) {
    return "";
  }
  const saving = resource.actionPendingKey === "config";
  return `<article id="campaign-quest-settings" class="shared-campaign-panel shared-campaign-quest-config">
    <div class="shared-campaign-panel__header">
      <div>
        <h2>Settings</h2>
        <p>Control how field teams claim targets, earn XP, and unlock Campaign Quest milestones from the web dashboard.</p>
      </div>
      <div class="shared-card__actions shared-campaign-quest-config-header-actions">
        <button class="shared-feed-chip shared-feed-chip--primary" type="submit" form="candidate-quest-config-form"${disabledAttr(saving)}>${saving ? "Saving..." : "Save settings"}</button>
      </div>
    </div>
    ${renderCampaignQuestConfigBriefing(config)}
    <div class="shared-campaign-quest-config-summary">
      <span>${renderIcon("settings")} ${escapeHtml(config.enabled ? "Enabled" : "Disabled")}</span>
      <span>${renderIcon("shield")} ${escapeHtml(config.verification.gpsSoftCheckEnabled ? `${formatCount(config.verification.gpsNearbyMeters)}m GPS check` : "GPS check off")}</span>
      <span>${renderIcon("check")} ${escapeHtml(config.privacy.publicBadgeVisibility)} badges</span>
    </div>
    <form id="candidate-quest-config-form" data-route-form="candidate-quest-config" class="shared-campaign-quest-config-form">
      <div class="shared-campaign-quest-config-group">
        <strong>Availability</strong>
        <p>Control when field teams can use Campaign Quest actions.</p>
      </div>
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="enabled"${checkedAttr(config.enabled)}${disabledAttr(saving)} />
        <span>Enabled</span>
      </label>
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="activeShiftRequired"${checkedAttr(config.safety.activeShiftRequired)}${disabledAttr(saving)} />
        <span>Require active shift</span>
      </label>
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="canvassingHoursEnabled"${checkedAttr(config.safety.canvassingHoursEnabled)}${disabledAttr(saving)} />
        <span>Canvassing hours</span>
      </label>
      <label>
        <span>Start</span>
        <input name="canvassingHoursStart" type="time" value="${escapeHtml(config.safety.canvassingHoursStart)}"${disabledAttr(saving)} />
      </label>
      <label>
        <span>End</span>
        <input name="canvassingHoursEnd" type="time" value="${escapeHtml(config.safety.canvassingHoursEnd)}"${disabledAttr(saving)} />
      </label>
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="allowSkipUnsafeAddress"${checkedAttr(config.safety.allowSkipUnsafeAddress)}${disabledAttr(saving)} />
        <span>Allow unsafe skip</span>
      </label>
      <div class="shared-campaign-quest-config-group">
        <strong>Verification</strong>
        <p>Set GPS/photo requirements and unverified XP behavior.</p>
      </div>
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="gpsSoftCheckEnabled"${checkedAttr(config.verification.gpsSoftCheckEnabled)}${disabledAttr(saving)} />
        <span>GPS soft check</span>
      </label>
      <label>
        <span>GPS meters</span>
        <input name="gpsNearbyMeters" type="number" min="10" step="10" value="${escapeHtml(String(config.verification.gpsNearbyMeters))}"${disabledAttr(saving)} />
      </label>
      <label>
        <span>Unverified XP</span>
        <input name="unverifiedXpMultiplier" type="number" min="0" max="1" step="0.05" value="${escapeHtml(String(config.verification.unverifiedXpMultiplier))}"${disabledAttr(saving)} />
      </label>
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="photoRequiredForYardSigns"${checkedAttr(config.verification.photoRequiredForYardSigns)}${disabledAttr(saving)} />
        <span>Photo for signs</span>
      </label>
      <div class="shared-campaign-quest-config-group">
        <strong>Privacy</strong>
        <p>Choose what volunteers can see in scores, badges, and leaderboards.</p>
      </div>
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="exposeRawScoresToVolunteers"${checkedAttr(config.privacy.exposeRawScoresToVolunteers)}${disabledAttr(saving)} />
        <span>Expose raw scores</span>
      </label>
      <label class="shared-campaign-quest-toggle">
        <input type="checkbox" name="individualLeaderboardsEnabled"${checkedAttr(config.privacy.individualLeaderboardsEnabled)}${disabledAttr(saving)} />
        <span>Leaderboards</span>
      </label>
      <label>
        <span>Badge visibility</span>
        <select name="publicBadgeVisibility"${disabledAttr(saving)}>
          ${["campaign", "private", "public"]
            .map(
              (value) => `<option value="${escapeHtml(value)}"${selectedAttr(config.privacy.publicBadgeVisibility === value)}>${escapeHtml(humanizeLabel(value))}</option>`,
            )
            .join("")}
        </select>
      </label>
      ${renderCampaignQuestAdvancedConfig(config, saving)}
      <div class="shared-campaign-registry-form-actions">
        <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(saving)}>${saving ? "Saving..." : "Save settings"}</button>
      </div>
    </form>
  </article>`;
}

function renderCandidateDashboardCampaignQuest(detail, access) {
  const resource = detail.campaignQuest;
  const config = resource.config || normalizeCampaignQuestConfig({});
  const progress = resource.progress || normalizeCampaignQuestProgress({});
  const permissions = candidateDashboardPermissionSet(access);
  const canManage = access?.isOwner || permissions.has("voter_map_manager");
  if (resource.loading && !resource.loaded) {
    return `<div class="shared-campaign-section"><div class="shared-page__loading">Loading Campaign Quest...</div></div>`;
  }
  return `<div class="shared-campaign-section shared-campaign-quest">
    ${renderCampaignQuestCommandCenter(resource, progress, config, canManage)}
    ${resource.error ? `<div class="shared-page__error">${escapeHtml(resource.error)}</div>` : ""}
    ${
      resource.lastCompletion
        ? `<div class="shared-campaign-quest-completion">
            <strong>Last completion</strong>
            <span>+${escapeHtml(formatCount(resource.lastCompletion.xp.totalAwarded))} XP${resource.lastCompletion.badgesUnlocked.length ? ` - ${escapeHtml(formatCount(resource.lastCompletion.badgesUnlocked.length))} badge unlocked` : ""}</span>
          </div>`
        : ""
    }
    ${renderCampaignQuestFieldBoard(resource, progress, config)}
    <div class="shared-campaign-quest-grid">
      <div class="shared-campaign-quest-main">
        ${renderCampaignQuestProgress(progress)}
        ${renderCampaignQuestTargets(resource)}
      </div>
      <div class="shared-campaign-quest-side">
        ${renderCampaignQuestQuests(progress)}
        ${renderCampaignQuestBadges(config, progress)}
        ${renderCampaignQuestConfigForm(config, resource, canManage)}
      </div>
    </div>
  </div>`;
}

function candidateVoterMapAccessLabel(voterMapAccess, dashboardAccess) {
  if (voterMapAccess?.canManageTerritories || dashboardAccess?.isOwner) {
    return "Territory admin";
  }
  if (voterMapAccess?.scope === "territories") {
    return "Territory assigned";
  }
  const permissions = candidateDashboardPermissionSet(dashboardAccess);
  if (permissions.has("voter_map_manager")) {
    return "Map manager";
  }
  if (permissions.has("voter_map_territory")) {
    return "Territory access";
  }
  return "Campaign access";
}

