function coalitionSectionByKey(key) {
  const normalizedKey = normalizeString(key);
  return (
    COALITION_SECTION_CONFIG.find((section) => section.key === normalizedKey) ||
    null
  );
}

function coalitionsRootVisibleItems(items = []) {
  return items.filter((item) => !item.hidden && item.coalition && item.membership);
}

function coalitionsRootAccessStats(items = []) {
  const visibleItems = coalitionsRootVisibleItems(items);
  const activeItems = visibleItems.filter((item) => item.membership.isActive);
  const pendingItems = visibleItems.filter((item) => item.membership.isPending);
  const leaderItems = visibleItems.filter(
    (item) => item.membership.isLeader || item.membership.isAdmin,
  );
  const enabledSections = coalitionFeatureSections().filter((section) =>
    visibleItems.some((item) =>
      canOpenCoalitionSection(section, item.coalition, item.membership),
    ),
  );
  return {
    visibleItems,
    activeItems,
    pendingItems,
    leaderItems,
    enabledSections,
  };
}

function coalitionsRootActionItems(items = []) {
  const visibleItems = coalitionsRootVisibleItems(items);
  const findItemForSection = (key) => {
    const section = coalitionSectionByKey(key);
    return visibleItems.find((item) =>
      canOpenCoalitionSection(section, item.coalition, item.membership),
    );
  };
  const actionSpecs = [
    {
      key: "rooms",
      label: "Open rooms",
      copy: "Jump into coalition room messaging and workstreams.",
      icon: "messages",
      primary: true,
      route: (item) =>
        `/messages/servers/coalition/${encodeURIComponent(item.coalition.coalitionId)}`,
    },
    {
      key: "members",
      label: "Manage access",
      copy: "Review members, approvals, roles, and feature access.",
      icon: "team",
      primary: true,
      route: (item) =>
        coalitionMembersCommandPath(item.coalition.coalitionId, item.membership),
    },
    {
      key: "missions",
      label: "Open missions",
      copy: "Assign, claim, approve, and track coalition work.",
      icon: "mission",
    },
    {
      key: "petitions",
      label: "Open petitions",
      copy: "Create public forms, review responses, and share results.",
      icon: "file",
    },
    {
      key: "voter-map",
      label: "Open voter map",
      copy: "Review districts, voter records, CTA events, and scripts.",
      icon: "map",
      shortcuts: (item) => {
        const coalitionId = item.coalition.coalitionId;
        const shortcuts = [
          {
            label: "District search",
            icon: "search",
            route: coalitionSectionPath(coalitionId, "voter-map/federal-districts"),
          },
          {
            label: "Connected voters",
            icon: "registry",
            route: coalitionSectionPath(coalitionId, "voter-map/connected"),
          },
          {
            label: "Add voters",
            icon: "create",
            route: coalitionSectionPath(coalitionId, "voter-map/add"),
          },
          {
            label: "CTA transport",
            icon: "map",
            route: coalitionSectionPath(coalitionId, "voter-map/cta/transport"),
          },
        ];
        if (item.membership.isAdmin) {
          shortcuts.push(
            {
              label: "Territory wizard",
              icon: "team",
              route: coalitionSectionPath(
                coalitionId,
                "voter-map/territories/admin",
              ),
            },
            {
              label: "Outreach scripts",
              icon: "edit",
              route: coalitionSectionPath(
                coalitionId,
                "voter-map/outreach-scripts",
              ),
            },
          );
        }
        return shortcuts;
      },
    },
    {
      key: "amplify",
      label: "Open amplify",
      copy: "Create requests and collect platform-response links.",
      icon: "share",
    },
    {
      key: "calendar",
      label: "Plan calendar",
      copy: "Coordinate events, shifts, availability, and promotion.",
      icon: "calendar",
    },
    {
      key: "governance",
      label: "Open governance",
      copy: "Review constitution, proposals, ballots, and results.",
      icon: "election",
    },
  ];
  const actions = [];
  actionSpecs.forEach((spec) => {
    const item = findItemForSection(spec.key);
    if (!item) {
      return;
    }
    actions.push({
      key: spec.key,
      label: spec.label,
      copy: spec.copy,
      icon: spec.icon,
      primary: spec.primary === true,
      route: spec.route
        ? spec.route(item)
        : coalitionSectionPath(item.coalition.coalitionId, spec.key),
      shortcuts: spec.shortcuts ? spec.shortcuts(item) : [],
    });
  });
  return actions.slice(0, 5);
}

function renderCoalitionsRootAction(action) {
  const actionButton = `<button class="shared-coalition-access-action${action.primary ? " is-primary" : ""}" type="button" data-action="navigate" data-route="${escapeHtml(action.route)}">
    <span>${renderIcon(action.icon)}</span>
    <strong>${escapeHtml(action.label)}</strong>
    <small>${escapeHtml(action.copy)}</small>
  </button>`;
  const shortcuts = Array.isArray(action.shortcuts) ? action.shortcuts : [];
  if (!shortcuts.length) {
    return actionButton;
  }
  return `<article class="shared-coalition-access-action-shell${action.primary ? " is-primary" : ""}">
    ${actionButton}
    <div class="shared-coalition-access-action__shortcuts" aria-label="${escapeHtml(`${action.label} quick actions`)}">
      ${shortcuts
        .map(
          (shortcut) => `<button class="shared-coalition-access-shortcut" type="button" data-action="navigate" data-route="${escapeHtml(shortcut.route)}">
            <span>${renderIcon(shortcut.icon)}</span>
            <strong>${escapeHtml(shortcut.label)}</strong>
          </button>`,
        )
        .join("")}
    </div>
  </article>`;
}

