        <label><span>CTA type</span><select name="ctaType"${disabledAttr(pending)}><option value="protest_rally">Protest or rally</option><option value="canvass">Canvass</option><option value="phone_bank">Phone bank</option><option value="meeting">Meeting</option></select></label>
