function missionStatusTone(status) {
  const normalized = normalizeString(status).toLowerCase();
  if (["late", "blocked", "submitted", "needs_changes"].includes(normalized)) {
    return "attention";
  }
  if (["completed", "approved"].includes(normalized)) {
    return "complete";
  }
  if (["queued", "paused"].includes(normalized)) {
    return "queued";
  }
  if (["failed", "canceled", "unassigned"].includes(normalized)) {
    return "closed";
  }
  return "active";
}

function renderMissionBadge(label, tone = "") {
  const normalizedTone = normalizeString(tone);
  return `<span class="shared-mission-badge${normalizedTone ? ` shared-mission-badge--${escapeHtml(normalizedTone)}` : ""}">${escapeHtml(label)}</span>`;
}

function missionJobOwnerLabel(job) {
  if (job.assigneeDisplayName) {
    return job.assigneeDisplayName;
  }
  if (job.assigneeUsername) {
    return `@${job.assigneeUsername}`;
  }
  if (job.targetMode === "role_claim") {
    return job.targetRoleLabel
      ? `Claimable by ${job.targetRoleLabel}`
      : "Claimable by eligible role";
  }
  if (job.targetRoleLabel) {
    return job.targetRoleLabel;
  }
  return "Unassigned";
}

function missionNextJob(mission) {
  const jobs = [...(mission?.jobs || [])];
  if (!jobs.length) {
    return null;
  }
  const rank = (job) => {
    if (job.isClaimable) return 0;
    if (job.status === "late" || job.status === "blocked") return 1;
    if (job.status === "submitted" || job.status === "needs_changes") return 2;
    if (job.status === "active") return 3;
    if (job.status === "queued") return 4;
    return 9;
  };
  jobs.sort((left, right) => {
    const ranked = rank(left) - rank(right);
    if (ranked) return ranked;
    return (left.dueAt || Number.MAX_SAFE_INTEGER) - (right.dueAt || Number.MAX_SAFE_INTEGER);
  });
  return jobs[0];
}

function missionCompletionPercent(mission) {
  const total = mission?.jobs?.length || 0;
  if (!total) {
    return 0;
  }
  return Math.round((mission.completedCount / total) * 100);
}

