function renderSettingsReturnBanner() {
  const params = readCurrentSearchParams();
  const socialFallbackStatus = connectedAccountReturnPathStatus();
  const calendarFallbackStatus =
    calendarReturnTargetPathFromLocation() === "/settings/connected-accounts"
      ? calendarReturnPathStatus()
      : "";
  const fallbackStatus = socialFallbackStatus || calendarFallbackStatus;
  const isCalendarReturn = Boolean(
    calendarFallbackStatus ||
      normalizeString(params.get("calendar_status")) ||
      normalizeString(params.get("calendar_message")),
  );
  const status = normalizeString(
    params.get("social_status") ||
      params.get("calendar_status") ||
      params.get("status") ||
      fallbackStatus,
  ).toLowerCase();
  const provider = isCalendarReturn
    ? normalizeCalendarProvider(params.get("provider"))
    : normalizeSettingsProvider(params.get("provider"));
  const message =
    normalizeString(
      params.get("social_message") ||
        params.get("calendar_message") ||
        params.get("message"),
    ) ||
    (fallbackStatus === "error" || (isCalendarReturn && status === "error")
      ? CALENDAR_CONNECTION_INCOMPLETE_MESSAGE
      : "");
  const fallbackKind = calendarFallbackStatus ? "calendar" : "social";
  if (!status && !message) {
    return "";
  }
  const ok = status === "success" || status === "connected";
  return `<div class="shared-settings-return${ok ? " is-success" : " is-error"}">
    <strong>${escapeHtml(ok ? "Connection updated" : "Connection needs attention")}</strong>
    <span>${escapeHtml(
      message ||
        (provider
          ? `${isCalendarReturn ? calendarProviderLabel(provider) : providerLabel(provider)} returned to Polis.`
          : `The ${fallbackKind} connection flow returned to Polis.`),
    )}</span>
  </div>`;
}

