function renderVoterIntelProfileTab(profile, snapshot) {
  return `
    <div class="shared-voter-intel-metrics">
      ${renderVoterIntelMetric({
        label: "Engagement",
        value: formatVoterIntelPercent(voterIntelScore(profile, "civicEngagement")),
        copy: "Signal from issue answers, vote opinions, and election interactions.",
      })}
      ${renderVoterIntelMetric({
        label: "Profile",
        value: formatVoterIntelPercent(voterIntelScore(profile, "profileCompletion")),
        copy: "Address, district, and issue context available to Polis.",
      })}
      ${renderVoterIntelMetric({
        label: "Guide",
        value: formatVoterIntelPercent(voterIntelScore(profile, "ballotGuideReadiness")),
        copy: `${formatCount(profile.ballotGame.completedContestCount)} ranked contest${profile.ballotGame.completedContestCount === 1 ? "" : "s"}.`,
      })}
    </div>
    ${renderVoterIntelReadiness(profile)}
    ${renderVoterIntelMatrix(profile)}
    ${
      profile.explanations.length
        ? `<section class="shared-voter-intel-panel"><h2>Why this looks this way</h2><div class="shared-voter-intel-explanations">${profile.explanations
            .map((entry) => `<p>${escapeHtml(entry)}</p>`)
            .join("")}</div></section>`
        : ""
    }
    ${renderVoterIntelCapability(snapshot)}
    ${renderVoterIntelQuestions()}
  `;
}

function voterIntelRaceCardRoute(districts) {
  return settingsDistrictElectionRoute(districts) || "/election-day";
}

function voterIntelElectionRelativeLabel(electionDay) {
  const dateKey = voterIntelDateKey(electionDay);
  if (!dateKey) return "";
  const timestamp = Date.parse(`${dateKey}T00:00:00`);
  if (Number.isNaN(timestamp)) return "";
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const target = new Date(timestamp);
  const diffDays = Math.round((target.getTime() - today.getTime()) / 86400000);
  if (diffDays === 0) return "Today";
  if (diffDays === 1) return "Tomorrow";
  if (diffDays === -1) return "Yesterday";
  if (diffDays > 1) return `In ${formatCount(diffDays)} days`;
  return `${formatCount(Math.abs(diffDays))} days ago`;
}

function voterIntelElectionGroupFallbackLabel(race = {}) {
  return (
    formatCalendarDate(race.electionDay) ||
    normalizeString(race.electionName) ||
    "Election date pending"
  );
}

function voterIntelElectionRaceGroups(raceItems = []) {
  const groups = new Map();
  raceItems.forEach((item) => {
    const race = item.race || {};
    const dateKey = voterIntelDateKey(race.electionDay);
    const key = dateKey || normalizeString(race.electionName) || "unknown";
    const existing = groups.get(key) || {
      key,
      dateKey,
      label: voterIntelElectionGroupFallbackLabel(race),
      relative: voterIntelElectionRelativeLabel(race.electionDay),
      items: [],
    };
    existing.items.push(item);
    groups.set(key, existing);
  });
  return Array.from(groups.values())
    .map((group) => ({
      ...group,
      items: group.items.slice().sort((left, right) =>
        normalizeString(left.race?.title || left.race?.officeTitle).localeCompare(
          normalizeString(right.race?.title || right.race?.officeTitle),
        ),
      ),
    }))
    .sort((left, right) => {
      if (left.dateKey && right.dateKey) {
        return left.dateKey.localeCompare(right.dateKey);
      }
      if (left.dateKey) return -1;
      if (right.dateKey) return 1;
      return left.label.localeCompare(right.label);
    });
}

function renderVoterIntelElectionGroup(group, districts, index) {
  const selectedContestId = voterIntelRankingsState().selectedContestId;
  const selected = group.items.some(
    (item) => voterIntelRaceContestId(item.race) === selectedContestId,
  );
  const open = index === 0 || selected;
  return `<details class="shared-voter-intel-election-group${selected ? " is-selected" : ""}"${open ? " open" : ""}>
    <summary class="shared-voter-intel-election-group__summary">
      <span class="shared-voter-intel-election-group__icon">${renderIcon("election")}</span>
      <span class="shared-voter-intel-election-group__main">
        <small>Election date</small>
        <strong>${escapeHtml(group.label)}</strong>
        <em>${escapeHtml(`${formatCount(group.items.length)} rankable race${group.items.length === 1 ? "" : "s"}`)}</em>
      </span>
      ${group.relative ? `<span class="shared-voter-intel-election-group__relative">${escapeHtml(group.relative)}</span>` : ""}
      <span class="shared-voter-intel-election-group__chevron" aria-hidden="true">${renderIcon("chevronDown")}</span>
    </summary>
    <div class="shared-voter-intel-election-group__races">
      ${group.items.map((item) => renderVoterIntelRaceCard(districts, item.entry, item.race)).join("")}
    </div>
  </details>`;
}

function voterIntelCandidateInitials(candidate = {}) {
  const explicit = normalizeString(candidate.initials);
  if (explicit) return explicit.slice(0, 3).toUpperCase();
  return (
    normalizeString(candidate.displayName || candidate.name)
      .split(/\s+/u)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part.slice(0, 1).toUpperCase())
      .join("") || "?"
  );
}

function voterIntelRankingPreferencesForContest(contestId) {
  return normalizeContestRankingPreferences(
    voterIntelRankingsState().preferencesByContestId[contestId] || [],
  );
}

function voterIntelHydratedRankingCandidate(race, preference) {
  const candidatesById = new Map(
    voterIntelRaceCandidates(race).map((candidate) => [
      candidate.candidateId,
      candidate,
    ]),
  );
  const candidate = candidatesById.get(preference.candidateId) || {};
  return {
    ...candidate,
    ...preference,
    displayName:
      normalizeString(preference.displayName || candidate.displayName) ||
      preference.candidateId,
    partyLabel: normalizeString(candidate.partyLabel || preference.partyLabel),
    partyToken: normalizeString(candidate.partyToken || preference.partyToken),
    avatarUrl: normalizeUrl(candidate.avatarUrl || preference.avatarUrl),
    initials: normalizeString(candidate.initials || preference.initials),
  };
}

function renderVoterIntelCandidateIdentity(candidate = {}) {
  const imageUrl = normalizeUrl(candidate.avatarUrl);
  const subtitle =
    normalizeString(candidate.partyLabel || candidate.partyToken) || "Candidate";
  return `<span class="shared-voter-intel-ranking__avatar">
      ${imageUrl ? `<img src="${escapeHtml(imageUrl)}" alt="" loading="lazy" />` : `<strong>${escapeHtml(voterIntelCandidateInitials(candidate))}</strong>`}
    </span>
    <span class="shared-voter-intel-ranking__candidate-main">
      <strong>${escapeHtml(candidate.displayName || candidate.name || "Candidate")}</strong>
      <small>${escapeHtml(subtitle)}</small>
    </span>`;
}

function renderVoterIntelRankedCandidate(candidate, index, count, saving) {
  const candidateId = normalizeString(candidate.candidateId);
  return `<li class="shared-voter-intel-ranking__candidate">
    <span class="shared-voter-intel-ranking__rank">${escapeHtml(String(index + 1))}</span>
    ${renderVoterIntelCandidateIdentity(candidate)}
    <span class="shared-voter-intel-ranking__tools">
      <button class="shared-voter-intel-icon-button" type="button" data-action="voter-intel-rank-move" data-contest-id="${escapeHtml(candidate.contestId || "")}" data-candidate-id="${escapeHtml(candidateId)}" data-direction="-1" aria-label="${escapeHtml(`Move ${candidate.displayName} up`)}"${disabledAttr(saving || index === 0)}>${renderIcon("chevronUp")}</button>
      <button class="shared-voter-intel-icon-button" type="button" data-action="voter-intel-rank-move" data-contest-id="${escapeHtml(candidate.contestId || "")}" data-candidate-id="${escapeHtml(candidateId)}" data-direction="1" aria-label="${escapeHtml(`Move ${candidate.displayName} down`)}"${disabledAttr(saving || index >= count - 1)}>${renderIcon("chevronDown")}</button>
      <button class="shared-voter-intel-icon-button" type="button" data-action="voter-intel-rank-remove" data-contest-id="${escapeHtml(candidate.contestId || "")}" data-candidate-id="${escapeHtml(candidateId)}" aria-label="${escapeHtml(`Remove ${candidate.displayName}`)}"${disabledAttr(saving)}>${renderIcon("trash")}</button>
    </span>
  </li>`;
}

function renderVoterIntelUnrankedCandidate(candidate, contestId, saving) {
  return `<li class="shared-voter-intel-ranking__candidate">
    <span class="shared-voter-intel-ranking__rank">${renderIcon("create")}</span>
    ${renderVoterIntelCandidateIdentity(candidate)}
    <button class="shared-feed-chip" type="button" data-action="voter-intel-rank-add" data-contest-id="${escapeHtml(contestId)}" data-candidate-id="${escapeHtml(candidate.candidateId)}"${disabledAttr(saving)}>Add</button>
  </li>`;
}

function renderVoterIntelRankingAggregate(race, aggregate, loading) {
  const contestId = voterIntelRaceContestId(race);
  const candidatesById = new Map(
    voterIntelRaceCandidates(race).map((candidate) => [
      candidate.candidateId,
      candidate,
    ]),
  );
  if (loading && !aggregate) {
    return `<div class="shared-page__loading">Loading community ranking...</div>`;
  }
  if (!aggregate) {
    return `<div class="shared-settings-empty">Community ranking has not been loaded for this race yet.</div>
      <button class="shared-feed-chip" type="button" data-action="voter-intel-rank-refresh" data-contest-id="${escapeHtml(contestId)}">Load consensus</button>`;
  }
  if (!aggregate.available || aggregate.privacySuppressed) {
    return `<div class="shared-voter-intel-ranking__privacy">
      <strong>${escapeHtml(formatCount(aggregate.totalRankings))} ranking${aggregate.totalRankings === 1 ? "" : "s"} submitted</strong>
      <p>Consensus unlocks after ${escapeHtml(formatCount(aggregate.minTotalRankings))} rankings, with enough support per candidate segment to preserve voter privacy.</p>
    </div>`;
  }
  const rows = aggregate.candidates.slice(0, 6);
  if (!rows.length) {
    return `<div class="shared-settings-empty">Consensus is available, but no candidate has enough ranked support to display yet.</div>`;
  }
  return `<ol class="shared-voter-intel-ranking__aggregate-list">
    ${rows
      .map((entry) => {
        const candidate = candidatesById.get(entry.candidateId) || {
          candidateId: entry.candidateId,
          displayName: entry.candidateId,
        };
        const percent = Math.max(
          0,
          Math.min(100, Number(entry.firstChoicePct) || 0),
        );
        return `<li class="shared-voter-intel-ranking__aggregate-item">
          <div>
            <strong>${escapeHtml(candidate.displayName || candidate.name || entry.candidateId)}</strong>
            <small>${escapeHtml(`${formatCount(entry.firstChoiceCount)} first-choice - avg rank ${entry.avgRank ? Number(entry.avgRank).toFixed(1) : "n/a"}`)}</small>
          </div>
          <span>${escapeHtml(`${percent.toFixed(percent % 1 === 0 ? 0 : 1)}%`)}</span>
          <i style="width: ${escapeHtml(String(percent))}%"></i>
        </li>`;
      })
      .join("")}
  </ol>
  <button class="shared-feed-chip" type="button" data-action="voter-intel-rank-refresh" data-contest-id="${escapeHtml(contestId)}"${disabledAttr(loading)}>${loading ? "Refreshing..." : "Refresh consensus"}</button>`;
}

function renderVoterIntelRankingWorkspace(race) {
  const contestId = voterIntelRaceContestId(race);
  const rankingState = voterIntelRankingsState();
  const candidates = voterIntelRaceCandidates(race);
  const candidateIds = new Set(candidates.map((candidate) => candidate.candidateId));
  const saving = rankingState.savingContestId === contestId;
  const loading = rankingState.loadingContestId === contestId;
  const ranked = voterIntelRankingPreferencesForContest(contestId).map(
    (preference) =>
      voterIntelHydratedRankingCandidate(race, {
        ...preference,
        contestId,
      }),
  );
  const rankedIds = new Set(ranked.map((candidate) => candidate.candidateId));
  const unranked = candidates.filter(
    (candidate) =>
      !rankedIds.has(candidate.candidateId) && candidateIds.has(candidate.candidateId),
  );
  const aggregate = rankingState.aggregateByContestId[contestId];
  const error = normalizeString(rankingState.errorByContestId[contestId]);
  const electionLabel = [
    race.electionDay ? formatCalendarDate(race.electionDay) : "",
    race.jurisdiction,
  ]
    .map(normalizeString)
    .filter(Boolean)
    .join(" - ");
  return `<section class="shared-voter-intel-ranking" aria-label="${escapeHtml(`${race.title || race.officeTitle} ranking workspace`)}">
    <div class="shared-voter-intel-ranking__header">
      <div>
        <span class="shared-settings-eyebrow">Ballot ranking</span>
        <h3>${escapeHtml(race.title || race.officeTitle || "Election race")}</h3>
        <p>${escapeHtml(electionLabel || "Rank candidates in the order you would prefer them on your ballot guide.")}</p>
      </div>
      <div class="shared-voter-intel-ranking__actions">
        <button class="shared-feed-chip" type="button" data-action="voter-intel-rank-close">Close</button>
        <button class="shared-feed-chip" type="button" data-action="voter-intel-rank-refresh" data-contest-id="${escapeHtml(contestId)}"${disabledAttr(loading)}>${loading ? "Refreshing..." : "Refresh"}</button>
        <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="voter-intel-rank-save" data-contest-id="${escapeHtml(contestId)}"${disabledAttr(saving || !ranked.length)}>${saving ? "Saving..." : "Save ranking"}</button>
      </div>
    </div>
    ${error ? `<div class="shared-page__error">${escapeHtml(error)}</div>` : ""}
    <div class="shared-voter-intel-ranking__layout">
      <section class="shared-voter-intel-ranking__panel">
        <div class="shared-voter-intel-ranking__panel-title">
          <strong>Your ranking</strong>
          <span>${escapeHtml(`${formatCount(ranked.length)} selected`)}</span>
        </div>
        ${
          ranked.length
            ? `<ol class="shared-voter-intel-ranking__list">${ranked
                .map((candidate, index) =>
                  renderVoterIntelRankedCandidate(
                    candidate,
                    index,
                    ranked.length,
                    saving,
                  ),
                )
                .join("")}</ol>`
            : `<div class="shared-settings-empty">Add candidates from the pool to start your ballot order.</div>`
        }
      </section>
      <section class="shared-voter-intel-ranking__panel">
        <div class="shared-voter-intel-ranking__panel-title">
          <strong>Candidate pool</strong>
          <span>${escapeHtml(`${formatCount(unranked.length)} remaining`)}</span>
        </div>
        ${
          unranked.length
            ? `<ul class="shared-voter-intel-ranking__list">${unranked
                .map((candidate) =>
                  renderVoterIntelUnrankedCandidate(candidate, contestId, saving),
                )
                .join("")}</ul>`
            : `<div class="shared-settings-empty">Every listed candidate is already in your ranking.</div>`
        }
      </section>
      <section class="shared-voter-intel-ranking__panel">
        <div class="shared-voter-intel-ranking__panel-title">
          <strong>Community consensus</strong>
          <span>${escapeHtml(aggregate ? `${formatCount(aggregate.totalRankings)} rankings` : "Not loaded")}</span>
        </div>
        ${renderVoterIntelRankingAggregate(race, aggregate, loading)}
      </section>
    </div>
  </section>`;
}

function renderVoterIntelRaceCard(districts, entry, rankableRace = null) {
  const { office, index } = entry;
  const level = settingsDistrictLevelConfig(
    settingsDistrictOfficeLevelKey(office?.level),
  );
  const reelection = settingsDistrictOfficeReelection(office);
  const candidateGroups = settingsDistrictCandidateGroups(reelection);
  const race = rankableRace || voterIntelRankableRaceFromDistrictEntry(districts, entry);
  const contestId = voterIntelRaceContestId(race);
  const selected =
    contestId && voterIntelRankingsState().selectedContestId === contestId;
  const candidateCount = candidateGroups.reduce(
    (sum, group) => sum + group.candidates.length,
    0,
  );
  const incumbents = settingsDistrictOfficeIncumbents(office);
  const status = normalizeString(reelection.status);
  const electionDay = normalizeString(reelection.electionDay);
  const title =
    normalizeString(office?.office || office?.title || office?.officeTitle) ||
    `Race ${index + 1}`;
  const district = [
    office?.jurisdiction,
    office?.district,
    office?.state,
  ]
    .map(normalizeString)
    .filter(Boolean)
    .join(" - ");
  return `<article class="shared-voter-intel-race-card${selected ? " is-selected" : ""}">
    <div class="shared-voter-intel-race-card__top">
      <span>${renderIcon(level.icon || "election")}</span>
      <div>
        <small>${escapeHtml(level.label)}</small>
        <h3>${escapeHtml(title)}</h3>
        <p>${escapeHtml(district || level.description)}</p>
      </div>
      ${renderSettingsStatusPill(status ? humanizeLabel(status) : "Election data", settingsDistrictReelectionTone(status))}
    </div>
    <div class="shared-voter-intel-race-card__meta">
      <span><strong>${escapeHtml(formatCount(candidateCount))}</strong><small>Candidates</small></span>
      <span><strong>${escapeHtml(formatCount(incumbents.length))}</strong><small>Incumbents</small></span>
      <span><strong>${escapeHtml(electionDay ? formatCalendarDate(electionDay) : "Pending")}</strong><small>Election day</small></span>
    </div>
    ${
      candidateGroups.length
        ? `<div class="shared-voter-intel-race-card__candidates">
            ${candidateGroups
              .slice(0, 4)
              .map((group) => `<span>${escapeHtml(group.partyLabel || "Candidates")} ${escapeHtml(formatCount(group.candidates.length))}</span>`)
              .join("")}
          </div>`
        : `<div class="shared-settings-empty">Candidate roster is not available for this race yet.</div>`
    }
    <div class="shared-voter-intel-race-card__actions">
      ${
        race.candidates.length
          ? `<button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="voter-intel-rank-open" data-contest-id="${escapeHtml(contestId)}">${selected ? "Ranking open" : "Rank race"}</button>`
          : ""
      }
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="${escapeHtml(voterIntelRaceCardRoute(districts))}">Election Day</button>
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/preferences/my-districts">District details</button>
    </div>
  </article>`;
}

function renderVoterIntelElectionsTab(profile, guidedMode) {
  const voterProfile = state.pages.settings.voterProfile;
  const districtsResource = voterProfile.districts;
  const districts = districtsResource.item;
  const offices = settingsDistrictOffices(districts);
  const grouped = settingsDistrictGroupedOffices(offices);
  const districtId = settingsDistrictFederalId(districts, voterProfile.profile.item || normalizeMyProfile());
  const electionRoute = settingsDistrictElectionRoute(districts) || "/election-day";
  const raceEntries = SETTINGS_DISTRICT_LEVELS.flatMap((level) => grouped[level.key] || []);
  const raceItems = raceEntries.map((entry) => ({
    entry,
    race: voterIntelRankableRaceFromDistrictEntry(districts, entry),
  }));
  const rankableRaceItems = raceItems.filter((item) =>
    voterIntelRaceIsRankable(item.race),
  );
  const electionGroups = voterIntelElectionRaceGroups(rankableRaceItems);
  const selectedContestId = voterIntelRankingsState().selectedContestId;
  const selectedRace =
    rankableRaceItems.find(
      (item) => voterIntelRaceContestId(item.race) === selectedContestId,
    )?.race || null;
  return `<div class="shared-voter-intel-tab-body shared-voter-intel-elections">
    ${
      guidedMode
        ? `<section class="shared-voter-intel-guided">
            <span>${renderIcon("election")}</span>
            <div>
              <strong>Ballot ranking</strong>
              <p>Pick a candidate-backed race, rank the choices inline, and continue through each election date when you are ready.</p>
            </div>
          </section>`
        : ""
    }
    <section class="shared-voter-intel-election-hero">
      <div>
        <span class="shared-settings-eyebrow">Elections</span>
        <h2>${escapeHtml(districtId || "District election workspace")}</h2>
        <p>${escapeHtml(profile.ballotGame.nextAction || "Review district races, candidate rosters, and ballot-guide readiness from the browser.")}</p>
      </div>
      <div class="shared-voter-intel-election-hero__actions">
        <button class="shared-feed-chip" type="button" data-action="settings-voter-profile-refresh-districts"${disabledAttr(districtsResource.loading)}>${districtsResource.loading ? "Refreshing..." : "Refresh races"}</button>
        <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="${escapeHtml(electionRoute)}">Election Day</button>
      </div>
    </section>
    ${renderSettingsResourceStatus(districtsResource, "district election data")}
    <div class="shared-voter-intel-metrics">
      ${renderVoterIntelMetric({
        label: "Rankable",
        value: formatCount(rankableRaceItems.length),
        copy: "Candidate-backed races ready for ballot ranking.",
      })}
      ${renderVoterIntelMetric({
        label: "Election dates",
        value: formatCount(electionGroups.length),
        copy: "Races grouped by the election day returned for your district.",
      })}
      ${renderVoterIntelMetric({
        label: "Ranked",
        value: formatCount(profile.ballotGame.completedContestCount),
        copy: "Contests already saved into your ballot guide.",
      })}
    </div>
    ${selectedRace ? renderVoterIntelRankingWorkspace(selectedRace) : ""}
    ${
      electionGroups.length
        ? `<section class="shared-voter-intel-election-list">
            ${electionGroups.map((group, index) => renderVoterIntelElectionGroup(group, districts, index)).join("")}
          </section>`
        : `<section class="shared-voter-intel-panel">
            <div class="shared-settings-empty">${
              raceEntries.length
                ? "No candidate-backed races are ready for ballot ranking yet. Review all district offices in My Districts, then refresh when candidate data is available."
                : "No upcoming races were returned yet. Add or verify your home location, then refresh district election data."
            }</div>
            <div class="shared-settings-form-actions">
              <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="${raceEntries.length ? "/settings/preferences/my-districts" : "/settings/preferences/home-location"}">${raceEntries.length ? "My districts" : "Home location"}</button>
              <button class="shared-feed-chip" type="button" data-action="settings-voter-profile-refresh-districts">Retry</button>
            </div>
          </section>`
    }
  </div>`;
}

function renderVoterIntelGuideTab() {
  return `<div class="shared-voter-intel-tab-body">
    ${renderVoterIntelGuide()}
  </div>`;
}

function renderVoterIntelActiveTab(activeTab, profile, snapshot, guidedMode) {
  if (activeTab === "elections") {
    return renderVoterIntelElectionsTab(profile, guidedMode);
  }
  if (activeTab === "guide") {
    return renderVoterIntelGuideTab();
  }
  return `<div class="shared-voter-intel-tab-body">${renderVoterIntelProfileTab(profile, snapshot)}</div>`;
}

function renderSettingsVoterIntelligence() {
  const voterIntel = state.pages.settings.voterIntel;
  const snapshot = voterIntel.snapshot.item;
  const profile = snapshot?.profile || normalizeVoterIntelProfile();
  const activeTab = getVoterIntelActiveTab();
  const guidedMode = isVoterIntelGuidedMode();
  const activeConfig =
    VOTER_INTEL_TAB_CONFIG.find((item) => item.key === activeTab) ||
    VOTER_INTEL_TAB_CONFIG[0];
  return `<div class="shared-settings-main shared-voter-intel">
    <section class="shared-voter-intel-hero">
      <div>
        <span class="shared-settings-eyebrow">Voter intelligence</span>
        <h2>${escapeHtml(activeConfig.label === "Profile" ? "Turn your civic signals into a working ballot profile." : activeConfig.label)}</h2>
        <p>${escapeHtml(
          activeTab === "elections"
            ? "Review district races and continue the ballot-ranking workflow from the website."
            : activeTab === "guide"
              ? "Build, review, and email the ballot guide generated from saved race rankings."
              : "Track profile readiness, matrix confidence, jurisdiction coverage, and reviewed policy questions from the web app.",
        )}</p>
      </div>
      <div class="shared-settings-header__actions">
        <button class="shared-feed-chip" data-action="settings-refresh">Refresh</button>
        <button class="shared-feed-chip" data-action="navigate" data-route="${escapeHtml(voterIntelTabRoute("elections", guidedMode))}">Elections</button>
      </div>
    </section>
    ${renderVoterIntelTabNav(activeTab, guidedMode)}
    ${renderSettingsResourceStatus(voterIntel.snapshot, "voter intelligence")}
    ${renderVoterIntelActiveTab(activeTab, profile, snapshot, guidedMode)}
  </div>`;
}

function renderSettingsAudienceMemberChips(
  memberUserIds = [],
  { emptyText = "No members selected", limit = 12 } = {},
) {
  const ids = normalizeAudienceGroupMemberIds(memberUserIds);
  return `<div class="shared-settings-audience-members" aria-label="Audience group members">
    ${
      ids.length
        ? ids
            .slice(0, limit)
            .map((memberId) => `<span>${escapeHtml(memberId)}</span>`)
            .join("")
        : `<span>${escapeHtml(emptyText)}</span>`
    }
    ${
      ids.length > limit
        ? `<span>${escapeHtml(`+${formatCount(ids.length - limit)} more`)}</span>`
        : ""
    }
  </div>`;
}

function renderSettingsAudienceSearchResult(user, memberUserIds = [], groupId = "") {
  const existingIds = new Set(normalizeAudienceGroupMemberIds(memberUserIds));
  const alreadyAdded = existingIds.has(user.userId);
  return `<button class="shared-campaign-staff-search-result${alreadyAdded ? " is-disabled" : ""}" type="button" data-action="settings-audience-search-add"
    data-group-id="${escapeHtml(settingsAudienceGroupDraftKey(groupId))}"
    data-user-id="${escapeHtml(user.userId)}"
    data-username="${escapeHtml(user.username)}"
    data-display-name="${escapeHtml(user.displayName)}"
    data-avatar-url="${escapeHtml(user.avatarUrl)}"${disabledAttr(alreadyAdded)}>
    ${renderCandidateStaffAvatar(user)}
    <span>
      <strong>${escapeHtml(user.displayName)}</strong>
      <small>@${escapeHtml(user.username)}${user.subtitle ? ` - ${escapeHtml(user.subtitle.replace(/^@/u, ""))}` : ""}</small>
    </span>
    <em>${alreadyAdded ? "Added" : "Add"}</em>
  </button>`;
}

function renderSettingsAudienceMemberSearch(groupId, memberUserIds, disabled = false) {
  const resource = state.pages.settings.audienceGroups;
  const search = settingsAudienceGroupSearch(resource);
  const key = settingsAudienceGroupDraftKey(groupId);
  const active = search.groupId === key;
  const query = active ? search.query : "";
  const normalizedQuery = normalizeString(query).replace(/^@/u, "");
  const showSuggestions =
    active && (search.loading || search.loaded || normalizedQuery.length >= 2);
  return `<div class="shared-campaign-staff-search shared-settings-audience-search">
    <label class="shared-campaign-staff-search-field">
      <span>Find members</span>
      <input type="search" data-settings-audience-search-input data-group-id="${escapeHtml(key)}" value="${escapeHtml(query)}" placeholder="Search username or name" autocomplete="off"${disabledAttr(disabled)} />
    </label>
    ${
      showSuggestions
        ? `<div class="shared-campaign-staff-search-results">
            ${
              search.loading
                ? '<div class="shared-campaign-staff-search-message">Searching people...</div>'
                : search.error
                  ? `<div class="shared-campaign-staff-search-message is-error">${escapeHtml(search.error)}</div>`
                  : search.items.length
                    ? search.items
                        .map((user) =>
                          renderSettingsAudienceSearchResult(
                            user,
                            memberUserIds,
                            key,
                          ),
                        )
                        .join("")
                    : '<div class="shared-campaign-staff-search-message">No matching people.</div>'
            }
          </div>`
        : `<div class="shared-campaign-staff-search-hint">Type at least two characters or paste user IDs below.</div>`
    }
  </div>`;
}

function renderSettingsAudienceGroups() {
  const settings = state.pages.settings;
  const resource = settings.audienceGroups;
  const publishing =
    settings.publishing.item || normalizePublishingDefaults(settings.publishing.item);
  const defaultGroupIds = new Set(publishing.defaultAudienceGroupIds);
  const uniqueMemberCount = new Set(
    resource.items.flatMap((group) => group.memberUserIds),
  ).size;
  const defaultGroupCount = resource.items.filter((group) =>
    defaultGroupIds.has(group.groupId),
  ).length;
  const savingKey = resource.savingKey;
  const createDraft = settingsAudienceGroupDraft(resource, "", {
    name: "",
    memberUserIds: [],
  });
  const createMemberIds = normalizeAudienceGroupMemberIds(
    createDraft.memberUserIds,
  );
  return `<div class="shared-settings-main shared-settings-audience">
    <section class="shared-settings-audience-hero">
      <div>
        <span class="shared-settings-eyebrow">Custom visibility</span>
        <h2>Build private posting groups without leaving settings.</h2>
        <p>Search for Polis accounts, add members as chips, and keep saved groups ready for custom visibility in the post composer and publishing defaults.</p>
      </div>
      <div class="shared-settings-audience-flow" aria-label="Audience group workflow">
        <span><strong>1</strong><small>Search or paste</small></span>
        <span><strong>2</strong><small>Review members</small></span>
        <span><strong>3</strong><small>Use in composer</small></span>
      </div>
    </section>
    <div class="shared-settings-audience-metrics">
      <article><strong>${escapeHtml(formatCount(resource.items.length))}</strong><span>Groups</span></article>
      <article><strong>${escapeHtml(formatCount(uniqueMemberCount))}</strong><span>Unique member IDs</span></article>
      <article><strong>${escapeHtml(formatCount(defaultGroupCount))}</strong><span>Publishing defaults</span></article>
    </div>
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Create audience group</h2>
          <p>Build private lists that can be selected when a post uses custom visibility.</p>
        </div>
      </div>
      <form class="shared-settings-form shared-settings-audience-editor" data-route-form="settings-audience-group">
        <input type="hidden" name="groupId" value="" />
        <div class="shared-settings-form-grid">
          <label>
            <span>Name</span>
            <input name="name" value="${escapeHtml(createDraft.name)}" data-settings-audience-field="name" data-group-id="create" placeholder="Campaign field team" required />
          </label>
          <label>
            <span>Members</span>
            <textarea name="memberUserIds" rows="4" data-settings-audience-field="memberUserIds" data-group-id="create" placeholder="Search above or paste user IDs, one per line">${escapeHtml(createDraft.memberUserIds)}</textarea>
          </label>
        </div>
        ${renderSettingsAudienceMemberSearch("create", createMemberIds, savingKey === "create")}
        ${renderSettingsAudienceMemberChips(createMemberIds, {
          emptyText: "No members selected",
        })}
        ${renderSettingsResourceStatus(resource, "audience groups")}
        <div class="shared-settings-form-actions">
          <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(savingKey === "create")}>${savingKey === "create" ? "Creating..." : "Create group"}</button>
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/publishing-social">Publishing defaults</button>
        </div>
      </form>
    </section>
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Saved groups</h2>
          <p>Edit membership lists without leaving the browser.</p>
        </div>
        <button class="shared-feed-chip" data-action="settings-refresh">Refresh</button>
      </div>
      ${
        resource.loading && !resource.items.length
          ? '<div class="shared-page__loading">Loading audience groups...</div>'
          : ""
      }
      ${
        !resource.loading && !resource.items.length
          ? '<div class="shared-settings-empty">No audience groups yet. Create one to use custom post visibility without typing raw IDs every time.</div>'
          : ""
      }
      <div class="shared-settings-audience-list">
        ${resource.items
          .map((group) => {
            const isDefault = defaultGroupIds.has(group.groupId);
            const saving = savingKey === `save:${group.groupId}`;
            const deleting = savingKey === `delete:${group.groupId}`;
            const draft = settingsAudienceGroupDraft(resource, group.groupId, group);
            const draftMemberIds = normalizeAudienceGroupMemberIds(
              draft.memberUserIds,
            );
            return `<article class="shared-settings-audience-card${isDefault ? " is-default" : ""}">
              <div class="shared-settings-audience-card__header">
                <div>
                  <h3>${escapeHtml(group.name)}</h3>
                  <p>${escapeHtml(`${formatCount(draftMemberIds.length)} member${draftMemberIds.length === 1 ? "" : "s"}`)}</p>
                </div>
                ${isDefault ? '<span>Default</span>' : ""}
              </div>
              <form class="shared-settings-form shared-settings-audience-editor" data-route-form="settings-audience-group">
                <input type="hidden" name="groupId" value="${escapeHtml(group.groupId)}" />
                <div class="shared-settings-form-grid">
                  <label>
                    <span>Name</span>
                    <input name="name" value="${escapeHtml(draft.name)}" data-settings-audience-field="name" data-group-id="${escapeHtml(group.groupId)}" required />
                  </label>
                  <label>
                    <span>Members</span>
                    <textarea name="memberUserIds" rows="5" data-settings-audience-field="memberUserIds" data-group-id="${escapeHtml(group.groupId)}">${escapeHtml(draft.memberUserIds)}</textarea>
                  </label>
                </div>
                ${renderSettingsAudienceMemberSearch(group.groupId, draftMemberIds, Boolean(savingKey))}
                ${renderSettingsAudienceMemberChips(draftMemberIds, {
                  emptyText: "No members yet",
                })}
                <div class="shared-settings-form-actions">
                  <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(Boolean(savingKey))}>${saving ? "Saving..." : "Save"}</button>
                  <button class="shared-feed-chip" type="button" data-action="settings-audience-group-delete" data-group-id="${escapeHtml(group.groupId)}"${disabledAttr(Boolean(savingKey))}>${deleting ? "Deleting..." : "Delete"}</button>
                </div>
              </form>
            </article>`;
          })
          .join("")}
      </div>
    </section>
  </div>`;
}

function renderSettingsSecurityStatus({ error = "", notice = "" } = {}) {
  if (error) {
    return `<div class="shared-page__error">${escapeHtml(error)}</div>`;
  }
  if (notice) {
    return `<div class="shared-settings-return is-success">${escapeHtml(notice)}</div>`;
  }
  return "";
}

function renderSettingsAccountUsername() {
  const resource = state.pages.settings.voterProfile.profile;
  const profile = resource.item || {};
  const currentUsername = normalizeSettingsAccountUsername(
    profile.username || state.auth.user?.username,
  );
  const displayName =
    normalizeString(profile.displayName || profile.fullName || state.auth.user?.name) ||
    "Your Polis account";
  const handleLabel = currentUsername ? `@${currentUsername}` : "No username set";
  const cooldownText = settingsAccountUsernameCooldownText(profile);
  const updatedLabel = profile.usernameUpdatedAt
    ? `Last changed ${formatSettingsDate(profile.usernameUpdatedAt)}`
    : currentUsername
      ? "No recent change recorded"
      : "Ready to claim";
  const inputDisabled = resource.loading || resource.saving || Boolean(cooldownText);
  return `<div class="shared-settings-main shared-settings-username">
    <section class="shared-settings-panel shared-settings-username-hero">
      <div class="shared-settings-username-hero__main">
        <span class="shared-settings-eyebrow">Account handle</span>
        <h2>${escapeHtml(handleLabel)}</h2>
        <p>${escapeHtml(
          currentUsername
            ? `${displayName} is currently shown around posts, messages, coalitions, and campaign workspaces with this handle.`
            : "Claim a unique handle so people can recognize you across posts, messages, coalitions, and campaign workspaces.",
        )}</p>
      </div>
      <div class="shared-settings-username-hero__status">
        ${renderSettingsStatusPill(cooldownText ? "Locked" : "Editable", cooldownText ? "pending" : "good")}
        <strong>${escapeHtml(updatedLabel)}</strong>
        <span>${escapeHtml(cooldownText || "Username changes are limited to once every 90 days after the first claim.")}</span>
      </div>
    </section>

    <section class="shared-settings-panel shared-settings-username-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Change username</h2>
          <p>Use the same 3-20 character handle rules as the mobile app. Polis will check availability when you save.</p>
        </div>
        <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/profile/edit">Edit profile</button>
      </div>
      ${renderSettingsResourceStatus(resource, "profile")}
      ${renderSettingsSecurityStatus({ notice: resource.notice })}
      <form class="shared-settings-form shared-settings-username-form" data-route-form="settings-account-username">
        <label class="shared-settings-username-field">
          <span>New username</span>
          <div class="shared-settings-username-input">
            <em>@</em>
            <input name="username" value="${escapeHtml(currentUsername)}" autocomplete="username" autocapitalize="none" spellcheck="false" maxlength="20" pattern="[a-z0-9_]{3,20}" placeholder="polis_user" required${disabledAttr(inputDisabled)} />
          </div>
        </label>
        <div class="shared-settings-username-rules">
          <span>${renderIcon("check")} 3-20 characters</span>
          <span>${renderIcon("check")} Lowercase letters, numbers, underscores</span>
          <span>${renderIcon("check")} Unique across Polis</span>
        </div>
        <div class="shared-settings-form-actions">
          <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(inputDisabled)}>${resource.saving ? "Saving..." : currentUsername ? "Save username" : "Claim username"}</button>
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/account-security">Account security</button>
        </div>
      </form>
    </section>

    <section class="shared-settings-panel shared-settings-username-support">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Where this appears</h2>
          <p>The web app now treats this as a real account setting, not an app-only placeholder.</p>
        </div>
      </div>
      <div class="shared-settings-username-map">
        <article>
          <span>${renderIcon("profile")}</span>
          <strong>Profile and posts</strong>
          <p>Your handle travels with public profile cards, comments, and feed attribution.</p>
        </article>
        <article>
          <span>${renderIcon("messages")}</span>
          <strong>Messaging</strong>
          <p>People can find and recognize you when starting direct messages or joining rooms.</p>
        </article>
        <article>
          <span>${renderIcon("team")}</span>
          <strong>Campaigns and coalitions</strong>
          <p>Candidate dashboards and coalition workspaces can invite staff by username.</p>
        </article>
      </div>
    </section>
  </div>`;
}

function renderSettingsAccountSecurityHub() {
  const account = settingsAccountSecurity();
  const reset = account.reset;
  const identifier = defaultSettingsSecurityIdentifier();
  const requestDisabled = reset.requesting || reset.confirming;
  const confirmDisabled = reset.confirming || reset.requesting;
  return `<div class="shared-settings-main shared-settings-security">
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Sign in protection</h2>
          <p>Reset account passwords, add authenticator-app verification, and review security activity from the browser.</p>
        </div>
      </div>
      <div class="shared-settings-security-grid">
        <article class="shared-settings-security-card">
          <span>${renderIcon("profile")}</span>
          <div>
            <h3>Username</h3>
            <p>Claim or change the public handle used across posts, messages, campaign staff, and coalition invites.</p>
          </div>
          <button class="shared-feed-chip shared-feed-chip--primary" data-action="navigate" data-route="/settings/account-username">Manage username</button>
        </article>
        <article class="shared-settings-security-card">
          <span>${renderIcon("settings")}</span>
          <div>
            <h3>Add or reset password</h3>
            <p>Send a reset code to the email or username on the Polis account.</p>
          </div>
        </article>
        <article class="shared-settings-security-card">
          <span>${renderIcon("mission")}</span>
          <div>
            <h3>Authenticator app MFA</h3>
            <p>Generate an authenticator setup URI and verify the one-time code.</p>
          </div>
          <button class="shared-feed-chip shared-feed-chip--primary" data-action="navigate" data-route="/settings/account-security/totp">Set up MFA</button>
        </article>
        <article class="shared-settings-security-card">
          <span>${renderIcon("messages")}</span>
          <div>
            <h3>Messaging Security Center</h3>
            <p>Open device, recovery, and encrypted-history security activity.</p>
          </div>
          <button class="shared-feed-chip" data-action="navigate" data-route="/messages/security-activity">Security activity</button>
        </article>
      </div>
    </section>
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Password reset</h2>
          <p>Request a reset code, then confirm the code with a new password.</p>
        </div>
      </div>
      ${renderSettingsSecurityStatus(reset)}
      <div class="shared-settings-security-forms">
        <form class="shared-settings-form" data-route-form="settings-password-reset-request">
          <label>
            <span>Email or username</span>
            <input name="identifier" autocomplete="username" value="${escapeHtml(identifier)}" placeholder="you@example.com" required />
          </label>
          <div class="shared-settings-form-actions">
            <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(requestDisabled)}>${reset.requesting ? "Sending..." : "Send reset code"}</button>
          </div>
        </form>
        <form class="shared-settings-form" data-route-form="settings-password-reset-confirm">
          <input type="hidden" name="identifier" value="${escapeHtml(reset.username || reset.identifier || identifier)}" />
          <div class="shared-settings-form-grid">
            <label>
              <span>Reset code</span>
              <input name="code" inputmode="numeric" autocomplete="one-time-code" placeholder="123456" required />
            </label>
            <label>
              <span>New password</span>
              <input name="password" type="password" autocomplete="new-password" placeholder="Use at least 8 characters" required />
            </label>
          </div>
          <div class="shared-settings-form-actions">
            <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(confirmDisabled)}>${reset.confirming ? "Updating..." : "Update password"}</button>
          </div>
        </form>
      </div>
    </section>
  </div>`;
}

function renderSettingsAccountSecurityTotp() {
  const account = settingsAccountSecurity();
  const totp = account.totp;
  const busy = totp.starting || totp.verifying;
  return `<div class="shared-settings-main shared-settings-security">
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Authenticator app</h2>
          <p>Use a time-based one-time password app for stronger Polis sign-in verification.</p>
        </div>
        <button class="shared-feed-chip" data-action="navigate" data-route="/settings/account-security">Account security</button>
      </div>
      ${renderSettingsSecurityStatus(totp)}
      <div class="shared-settings-security-step">
        <strong>1</strong>
        <div>
          <h3>Start setup</h3>
          <p>Polis generates a private setup URI for your authenticator app.</p>
        </div>
        <button class="shared-feed-chip shared-feed-chip--primary" data-action="settings-totp-start"${disabledAttr(totp.starting)}>${totp.starting ? "Starting..." : "Start setup"}</button>
      </div>
      ${
        totp.setupUri
          ? `<div class="shared-settings-security-secret">
              <div>
                <h3>Setup URI</h3>
                <p>Add this URI to your authenticator app, then enter the generated code below.</p>
              </div>
              <textarea readonly rows="4">${escapeHtml(totp.setupUri)}</textarea>
              <div class="shared-settings-form-actions">
                <button class="shared-feed-chip" type="button" data-action="settings-totp-copy">${totp.copied ? "Copied" : "Copy URI"}</button>
                <button class="shared-feed-chip" type="button" data-action="settings-totp-open">Open authenticator</button>
              </div>
            </div>
            <form class="shared-settings-form" data-route-form="settings-totp-verify">
              <label>
                <span>6-digit code</span>
                <input name="code" inputmode="numeric" autocomplete="one-time-code" placeholder="123456" required />
              </label>
              <div class="shared-settings-form-actions">
                <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(busy)}>${totp.verifying ? "Verifying..." : "Verify setup"}</button>
              </div>
            </form>`
          : `<div class="shared-settings-empty">Start setup to generate an authenticator URI for this signed-in account.</div>`
      }
    </section>
  </div>`;
}

function renderSettingsAccountSecurity() {
  const pathname =
    typeof window !== "undefined" ? normalizePathname(window.location.pathname) : "";
  return getSettingsSubpath() === "totp" ||
    pathname === "/settings/account-security/totp"
    ? renderSettingsAccountSecurityTotp()
    : renderSettingsAccountSecurityHub();
}

function renderSettingsStatusPill(label, tone = "") {
  return `<span class="shared-settings-status-pill${tone ? ` is-${escapeHtml(tone)}` : ""}">${escapeHtml(label)}</span>`;
}

function renderSettingsPrivacySafetyHub() {
  const settings = state.pages.settings;
  const privacy = settings.privacySafety;
  const blocked = privacy.safetyLists.blocked;
  const muted = privacy.safetyLists.muted;
  const profile = settings.voterProfile.profile.item;
  const audienceCount = settings.audienceGroups.items.length;
  const campaignShareCount = privacy.campaignSharing.items.length;
  const safetyCount = blocked.items.length + muted.items.length;
  const gpsLabel = profile?.gpsEnabled === true ? "GPS on" : "GPS off";
  const activityLabel = privacy.activitySharingEnabled ? "Sharing on" : "Sharing off";
  const commandMetrics = [
    {
      label: "Messaging privacy",
      value: "DMs",
      detail: "Requests, receipts, presence, and app lock.",
    },
    {
      label: "Safety lists",
      value: formatCount(safetyCount),
      detail: `${formatCount(blocked.items.length)} blocked, ${formatCount(muted.items.length)} muted.`,
    },
    {
      label: "Campaign sharing",
      value: `${formatCount(campaignShareCount)} campaign${campaignShareCount === 1 ? "" : "s"}`,
      detail: "Campaign voter-contact permissions.",
    },
    {
      label: "Friend activity",
      value: activityLabel,
      detail: "Events, prompts, and civic posts.",
    },
  ];
  const privacyActions = [
    {
      icon: "messages",
      title: "Messaging privacy",
      copy: "DM requests, presence, read receipts, and app lock.",
      route: "/messages/settings",
      status: "Open",
      primary: true,
    },
    {
      icon: "map",
      title: "Location",
      copy: `${gpsLabel}; manage district home location and foreground GPS.`,
      route: "/settings/location",
      status: gpsLabel,
    },
    {
      icon: "bell",
      title: "App permissions",
      copy: "Notifications, location, camera, microphone, and file picker access.",
      route: "/settings/permissions",
      status: "Browser",
    },
    {
      icon: "candidate",
      title: "Campaign data sharing",
      copy: "Review and revoke campaign access to voter contact preferences.",
      route: "/settings/campaign-data-sharing",
      status: `${formatCount(campaignShareCount)} campaigns`,
    },
    {
      icon: "team",
      title: "Audience groups",
      copy: "Private custom audiences for post visibility.",
      route: "/settings/audience-groups",
      status: `${formatCount(audienceCount)} groups`,
    },
    {
      icon: "search",
      title: "Search and personalization",
      copy: "Clear browser history caches or reset account feed recommendations.",
      route: "/settings/data-storage",
      status: "Utilities",
    },
  ];
  const safetyActions = [
    {
      icon: "shield",
      title: "Blocked users",
      copy: "Accounts blocked from messaging, following, or interacting with you.",
      route: "/settings/blocked-users",
      status: formatCount(blocked.items.length),
      primary: true,
    },
    {
      icon: "soundOff",
      title: "Muted users",
      copy: "Accounts hidden from your experience without notifying them.",
      route: "/settings/muted-users",
      status: formatCount(muted.items.length),
    },
    {
      icon: "lock",
      title: "Security center",
      copy: "Trusted devices, recovery, app lock, and recent messaging security activity.",
      route: "/settings/security",
      status: "Review",
    },
  ];
  const renderHubAction = (item) =>
    `<button class="shared-settings-privacy-action${item.primary ? " is-primary" : ""}" type="button" data-action="navigate" data-route="${escapeHtml(item.route)}">
      <span aria-hidden="true">${renderIcon(item.icon)}</span>
      <strong>${escapeHtml(item.title)}</strong>
      <small>${escapeHtml(item.copy)}</small>
      <em>${escapeHtml(item.status)}</em>
    </button>`;
  return `<div class="shared-settings-main shared-settings-privacy">
    <section class="shared-settings-privacy-command">
      <div class="shared-settings-privacy-command__copy">
        <span>${renderIcon("shield")} Privacy & safety</span>
        <h2>Control who can reach you and what campaign data stays shared.</h2>
        <p>Open the same Polis privacy areas from the web: messaging privacy, location, permissions, friend activity, campaign data sharing, blocked users, and muted users.</p>
      </div>
      <div class="shared-settings-privacy-command__metrics" aria-label="Privacy and safety summary">
        ${commandMetrics
          .map(
            (item) => `<span>
              <small>${escapeHtml(item.label)}</small>
              <strong>${escapeHtml(item.value)}</strong>
              <em>${escapeHtml(item.detail)}</em>
            </span>`,
          )
          .join("")}
      </div>
      <div class="shared-settings-privacy-command__actions">
        <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="/messages/settings">Messaging privacy</button>
        <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/campaign-data-sharing">Campaign sharing</button>
        <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/blocked-users">Blocked users</button>
      </div>
    </section>
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Privacy controls</h2>
          <p>Choose the exact settings surface you want to review without leaving the web app.</p>
        </div>
      </div>
      <div class="shared-settings-privacy-lanes">
        <div class="shared-settings-privacy-lane">
          <span>Privacy</span>
          <div>${privacyActions.map(renderHubAction).join("")}</div>
        </div>
        <div class="shared-settings-privacy-lane">
          <span>Safety</span>
          <div>${safetyActions.map(renderHubAction).join("")}</div>
        </div>
      </div>
    </section>
    <section id="settings-friend-activity" class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Friend activity</h2>
          <p>Match the app preference for showing friends when you attend events, answer prompts, or post civic content.</p>
        </div>
      </div>
      <form class="shared-settings-form" data-route-form="settings-activity-sharing">
        <label class="shared-settings-toggle">
          <input type="checkbox" name="enabled" value="true"${checkedAttr(privacy.activitySharingEnabled)} />
          <span>Share activity with friends from this browser</span>
        </label>
        <div class="shared-settings-form-actions">
          <button class="shared-feed-chip shared-feed-chip--primary" type="submit">Save preference</button>
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/campaign-data-sharing">Campaign sharing</button>
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/security">Security center</button>
        </div>
      </form>
    </section>
    ${renderSettingsResourceStatus(settings.voterProfile.profile, "location profile")}
    ${renderSettingsResourceStatus(settings.audienceGroups, "audience groups")}
    ${renderSettingsResourceStatus(privacy.campaignSharing, "campaign data sharing")}
    ${renderSettingsResourceStatus(blocked, "blocked users")}
    ${renderSettingsResourceStatus(muted, "muted users")}
  </div>`;
}

function renderSettingsLocation() {
  const profileResource = state.pages.settings.voterProfile.profile;
  const districtResource = state.pages.settings.voterProfile.districts;
  const profile = profileResource.item;
  const saving = profileResource.saving;
  return `<div class="shared-settings-main shared-settings-privacy">
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>GPS</h2>
          <p>Foreground GPS updates district context while Polis is open. Background tracking is not used.</p>
        </div>
        ${renderSettingsStatusPill(profile?.gpsEnabled === true ? "On" : "Off", profile?.gpsEnabled === true ? "good" : "pending")}
      </div>
      ${renderSettingsResourceStatus(profileResource, "profile")}
      <form class="shared-settings-form" data-route-form="settings-location-gps">
        <label class="shared-settings-toggle">
          <input type="checkbox" name="gpsEnabled" value="true"${checkedAttr(profile?.gpsEnabled === true)}${disabledAttr(saving)} />
          <span>Use foreground GPS updates in the browser</span>
        </label>
        <div class="shared-settings-form-actions">
          <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(saving)}>${saving ? "Saving..." : "Save GPS"}</button>
          <button class="shared-feed-chip" type="button" data-action="settings-permission-request" data-permission-key="location">Request location permission</button>
        </div>
      </form>
    </section>
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Home location</h2>
          <p>Manage the address used for districts and voter intelligence context.</p>
        </div>
      </div>
      ${renderSettingsResourceStatus(districtResource, "district context")}
      <div class="shared-settings-resource-grid">
        <button class="shared-settings-resource-card" type="button" data-action="navigate" data-route="/settings/preferences/home-location">
          <div><h3>Home location</h3><p>${escapeHtml(profile?.homeLocation?.formattedAddress || profile?.addressLine1 || "Add a home location to resolve district context.")}</p></div><span>Open</span>
        </button>
        <button class="shared-settings-resource-card" type="button" data-action="navigate" data-route="/settings/voter-profile">
          <div><h3>Voter profile</h3><p>Review district, phone, email, party, and voter intelligence settings.</p></div><span>Open</span>
        </button>
      </div>
    </section>
  </div>`;
}

function settingsPermissionLabel(status = {}) {
  const stateLabel = normalizeString(status.state).toLowerCase();
  if (stateLabel === "granted") return ["Granted", "good"];
  if (stateLabel === "denied") return ["Denied", "bad"];
  if (stateLabel === "picker") return ["File picker", "good"];
  if (stateLabel === "unsupported") return ["Unsupported", "bad"];
  return ["Ask first", "pending"];
}

function renderSettingsPermissions() {
  const resource = state.pages.settings.privacySafety.permissions;
  return `<div class="shared-settings-main shared-settings-privacy">
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Browser permissions</h2>
          <p>Request or review the browser permissions Polis web can use.</p>
        </div>
        <button class="shared-feed-chip" type="button" data-action="settings-permissions-refresh"${disabledAttr(resource.loading)}>Refresh</button>
      </div>
      ${renderSettingsResourceStatus(resource, "browser permissions")}
      <div class="shared-settings-permission-grid">
        ${SETTINGS_BROWSER_PERMISSIONS.map((permission) => {
          const status = resource.statuses[permission.key] || { state: "prompt", supported: true };
          const [label, tone] = settingsPermissionLabel(status);
          const pending = resource.actionPendingKey === permission.key;
          return `<article class="shared-settings-permission-card">
            <div>
              <h3>${escapeHtml(permission.label)}</h3>
              <p>${escapeHtml(permission.description)}</p>
            </div>
            <div class="shared-settings-permission-card__footer">
              ${renderSettingsStatusPill(label, tone)}
              <button class="shared-feed-chip" type="button" data-action="settings-permission-request" data-permission-key="${escapeHtml(permission.key)}"${disabledAttr(pending || status.supported === false)}>${pending ? "Requesting..." : permission.key === "photos" ? "How it works" : "Request"}</button>
            </div>
          </article>`;
        }).join("")}
      </div>
    </section>
  </div>`;
}

function renderSettingsSafetyList(kind) {
  const normalizedKind = kind === "muted" ? "muted" : "blocked";
  const resource = settingsSafetyResource(normalizedKind);
  const muted = normalizedKind === "muted";
  const title = muted ? "Muted users" : "Blocked users";
  const actionLabel = muted ? "Unmute" : "Unblock";
  const statusLabel = muted ? "Muted" : "Blocked";
  const copy = muted
    ? "Muted accounts stay out of your experience without notifying the other person."
    : "Blocked accounts cannot message, follow, or interact with you through Polis surfaces.";
  const emptyCopy = muted
    ? "Muted accounts will appear here after you mute someone from a profile, message, or moderation flow."
    : "Blocked accounts will appear here after you block someone from a profile, message, or moderation flow.";
  return `<div class="shared-settings-main shared-settings-privacy shared-settings-safety-list">
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>${escapeHtml(title)}</h2>
          <p>${escapeHtml(copy)}</p>
        </div>
        <div class="shared-settings-safety-actions">
          ${renderSettingsStatusPill(`${formatCount(resource.items.length)} listed`, resource.items.length ? "good" : "pending")}
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/privacy-safety">Safety home</button>
          <button class="shared-feed-chip" type="button" data-action="settings-safety-refresh" data-safety-kind="${escapeHtml(normalizedKind)}"${disabledAttr(resource.loading)}>${resource.loading ? "Refreshing..." : "Refresh"}</button>
        </div>
      </div>
      ${renderSettingsResourceStatus(resource, title.toLowerCase())}
      ${resource.loading && !resource.items.length ? '<div class="shared-page__loading">Loading users...</div>' : ""}
      ${!resource.loading && !resource.items.length ? `<div class="shared-settings-empty shared-settings-safety-empty"><strong>No ${escapeHtml(title.toLowerCase())}</strong><span>${escapeHtml(emptyCopy)}</span></div>` : ""}
      <div class="shared-settings-list">
        ${resource.items.map((entry) => {
          const displayName = entry.displayName || (entry.username ? `@${entry.username}` : "Unknown user");
          const timeLabel = formatSettingsRelativeTime(entry.createdAt);
          const subtitle = [entry.username ? `@${entry.username}` : "", timeLabel || "Added date unavailable"].filter(Boolean).join(" - ");
          const pending = resource.actionPendingKey === entry.userId;
          return `<article class="shared-settings-list-row shared-settings-safety-row is-${escapeHtml(normalizedKind)}">
            <span class="shared-settings-list-row__avatar">${entry.avatarUrl ? `<img src="${escapeHtml(entry.avatarUrl)}" alt="" loading="lazy" />` : escapeHtml(displayName.slice(0, 1).toUpperCase() || "U")}</span>
            <span class="shared-settings-safety-row__body">
              <span class="shared-settings-safety-row__title">
                <strong>${escapeHtml(displayName)}</strong>
                <em>${escapeHtml(statusLabel)}</em>
              </span>
              <small>${escapeHtml(subtitle || entry.userId)}</small>
            </span>
            <button class="shared-feed-chip" type="button" data-action="settings-safety-remove" data-safety-kind="${escapeHtml(normalizedKind)}" data-user-id="${escapeHtml(entry.userId)}" aria-label="${escapeHtml(`${actionLabel} ${displayName}`)}"${disabledAttr(pending)}>${pending ? "Saving..." : actionLabel}</button>
          </article>`;
        }).join("")}
      </div>
      ${resource.nextCursor ? `<div class="shared-settings-form-actions shared-settings-safety-footer"><span>${escapeHtml(formatCount(resource.items.length))} loaded</span><button class="shared-feed-chip" type="button" data-action="settings-safety-load-more" data-safety-kind="${escapeHtml(normalizedKind)}"${disabledAttr(resource.loadingMore)}>${resource.loadingMore ? "Loading..." : "Load more"}</button></div>` : ""}
    </section>
  </div>`;
}

function renderSettingsDataStorage() {
  const storage = state.pages.settings.privacySafety.storage;
  const action = storage.actionPendingKey;
  return `<div class="shared-settings-main shared-settings-privacy">
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Storage</h2>
          <p>Clear browser-side caches used by Polis web.</p>
        </div>
      </div>
      ${storage.error ? `<div class="shared-page__error">${escapeHtml(storage.error)}</div>` : ""}
      ${storage.notice ? `<div class="shared-settings-return is-success">${escapeHtml(storage.notice)}</div>` : ""}
      <div class="shared-settings-resource-grid">
        <button class="shared-settings-resource-card" type="button" data-action="settings-storage-action" data-storage-action="clear-browser-cache"${disabledAttr(Boolean(action))}>
          <div><h3>Clear browser cache</h3><p>Clears Polis cache-storage entries used for browser media and feed resources.</p></div><span>${action === "clear-browser-cache" ? "Clearing..." : "Clear"}</span>
        </button>
        <button class="shared-settings-resource-card" type="button" data-action="settings-storage-action" data-storage-action="clear-search"${disabledAttr(Boolean(action))}>
          <div><h3>Clear local search history</h3><p>Removes search history stored in this browser.</p></div><span>${action === "clear-search" ? "Clearing..." : "Clear"}</span>
        </button>
        <button class="shared-settings-resource-card" type="button" data-action="settings-storage-action" data-storage-action="reset-feed"${disabledAttr(Boolean(action))}>
          <div><h3>Reset feed personalization</h3><p>Clears recommendation state for your Polis account.</p></div><span>${action === "reset-feed" ? "Resetting..." : "Reset"}</span>
        </button>
        <button class="shared-settings-resource-card" type="button" data-action="navigate" data-route="/settings/activity-history">
          <div><h3>Activity history</h3><p>Private view of recent saved, liked, watched, and comment activity.</p></div><span>Open</span>
        </button>
      </div>
    </section>
  </div>`;
}

function renderSettingsActivityHistory() {
  const resource = state.pages.settings.privacySafety.activityHistory;
  return `<div class="shared-settings-main shared-settings-privacy">
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Activity history</h2>
          <p>Review private saved, liked, watched, and comment activity.</p>
        </div>
        <button class="shared-feed-chip" type="button" data-action="settings-activity-refresh"${disabledAttr(resource.loading)}>Refresh</button>
      </div>
      <form class="shared-settings-form shared-settings-activity-filter" data-route-form="settings-activity-history-filter">
        <label><span>Activity type</span><select name="type">${SETTINGS_ACTIVITY_TYPES.map(([value, label]) => `<option value="${escapeHtml(value)}"${selectedAttr(resource.type === value)}>${escapeHtml(label)}</option>`).join("")}</select></label>
        <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(resource.loading)}>Apply</button>
      </form>
      ${renderSettingsResourceStatus(resource, "activity history")}
      ${resource.loading && !resource.items.length ? '<div class="shared-page__loading">Loading activity...</div>' : ""}
      ${!resource.loading && !resource.items.length ? '<div class="shared-settings-empty">No activity found.</div>' : ""}
      <div class="shared-settings-list">
        ${resource.items.map((item) => `<div class="shared-settings-list-row">
          <span class="shared-settings-list-row__avatar">${escapeHtml((item.type || "A").slice(0, 1).toUpperCase())}</span>
          <span><strong>${escapeHtml(settingsActivityTitle(item))}</strong><small>${escapeHtml(formatSettingsDate(item.createdAt))}</small></span>
          ${item.postId ? `<button class="shared-feed-chip" type="button" data-action="navigate" data-route="/posts/${escapeHtml(encodeURIComponent(item.postId))}">Post</button>` : ""}
        </div>`).join("")}
      </div>
      ${resource.nextCursor ? `<div class="shared-settings-form-actions"><button class="shared-feed-chip" type="button" data-action="settings-activity-load-more"${disabledAttr(resource.loadingMore)}>${resource.loadingMore ? "Loading..." : "Load more"}</button></div>` : ""}
    </section>
  </div>`;
}

function campaignShareDisplayName(share) {
  return share?.candidateName || share?.candidateId || "Unknown campaign";
}

function campaignShareChannels(share) {
  return [
    ["Address", share?.sharedAddress === true],
    ["Phone", share?.sharedPhone === true],
    ["Email", share?.sharedEmail === true],
  ];
}

function campaignSharePreferenceCounts(items = []) {
  return items.reduce(
    (counts, share) => {
      VOTER_CONTACT_PREFERENCE_KEYS.forEach(([key]) => {
        const choice = normalizeVoterContactChoice(share?.contactPreferences?.[key]);
        counts[choice] = (counts[choice] || 0) + 1;
      });
      return counts;
    },
    { yes: 0, no: 0, unset: 0 },
  );
}

function campaignShareContactFieldCount(items = []) {
  return items.reduce(
    (total, share) =>
      total +
      campaignShareChannels(share).filter(([, isShared]) => isShared).length,
    0,
  );
}

function campaignShareChoiceLabel(choice) {
  const normalized = normalizeVoterContactChoice(choice);
  if (normalized === "yes") return "Allowed";
  if (normalized === "no") return "No contact";
  return "Unset";
}

function campaignShareChoiceTone(choice) {
  const normalized = normalizeVoterContactChoice(choice);
  if (normalized === "yes") return "good";
  if (normalized === "no") return "bad";
  return "pending";
}

function renderCampaignSharingMetric({ label, value, detail = "" }) {
  return `<div class="shared-settings-campaign-metric">
    <strong>${escapeHtml(value)}</strong>
    <span>${escapeHtml(label)}</span>
    ${detail ? `<small>${escapeHtml(detail)}</small>` : ""}
  </div>`;
}

function renderCampaignShareChannels(share) {
  const channels = campaignShareChannels(share);
  return `<div class="shared-settings-campaign-channels" aria-label="Shared contact fields">
    ${channels.map(([label, isShared]) => `<span class="${isShared ? "is-shared" : ""}">${escapeHtml(label)}</span>`).join("")}
  </div>`;
}

function renderCampaignSharePreferenceReadout(share) {
  return `<div class="shared-settings-campaign-pref-list">
    ${VOTER_CONTACT_PREFERENCE_KEYS.map(([key, label]) => {
      const choice = normalizeVoterContactChoice(share?.contactPreferences?.[key]);
      return `<div class="shared-settings-campaign-pref-row">
        <span>${escapeHtml(label)}</span>
        ${renderSettingsStatusPill(campaignShareChoiceLabel(choice), campaignShareChoiceTone(choice))}
      </div>`;
    }).join("")}
  </div>`;
}

function renderCampaignSharePreferences(share) {
  return `<div class="shared-settings-campaign-editor-grid">
    ${VOTER_CONTACT_PREFERENCE_KEYS.map(([key, label]) => {
      const selected = normalizeVoterContactChoice(share?.contactPreferences?.[key]);
      return `<fieldset class="shared-settings-campaign-choice">
        <legend>${escapeHtml(label)}</legend>
        <div class="shared-settings-segmented-control">
          ${[
            ["yes", "Yes"],
            ["unset", "Unset"],
            ["no", "No"],
          ]
            .map(
              ([value, optionLabel]) => `<label class="${selected === value ? "is-selected" : ""}">
                <input type="radio" name="contact:${escapeHtml(key)}" value="${escapeHtml(value)}"${checkedAttr(selected === value)} />
                <span>${escapeHtml(optionLabel)}</span>
              </label>`,
            )
            .join("")}
        </div>
      </fieldset>`;
    }).join("")}
  </div>`;
}

function renderCampaignShareCard(share, resource) {
  const candidateName = campaignShareDisplayName(share);
  const busy = Boolean(resource.actionPendingKey);
  const saving = resource.actionPendingKey === `save:${share.candidateId}`;
  const deleting = resource.actionPendingKey === `delete:${share.candidateId}`;
  const isEditing = resource.editingCandidateId === share.candidateId;
  const isConfirmingDelete = resource.confirmingDeleteId === share.candidateId;
  const updatedLabel = share.updatedAt
    ? `Updated ${formatSettingsDate(share.updatedAt)}`
    : share.consentedAt
      ? `Shared ${formatSettingsDate(share.consentedAt)}`
      : "Active";

  return `<article class="shared-settings-sharing-card${isEditing ? " is-editing" : ""}">
    <div class="shared-settings-sharing-card__header">
      <div>
        <h3>${escapeHtml(candidateName)}</h3>
        <p>${escapeHtml(updatedLabel)}</p>
      </div>
      ${renderSettingsStatusPill("Sharing", "good")}
    </div>
    ${renderCampaignShareChannels(share)}
    ${
      isEditing
        ? `<form class="shared-settings-form shared-settings-campaign-edit-form" data-route-form="settings-campaign-sharing">
            <input type="hidden" name="candidateId" value="${escapeHtml(share.candidateId)}" />
            ${renderCampaignSharePreferences(share)}
            <div class="shared-settings-form-actions">
              <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(busy)}>${saving ? "Saving..." : "Save preferences"}</button>
              <button class="shared-feed-chip" type="button" data-action="settings-campaign-sharing-cancel-edit"${disabledAttr(busy)}>Cancel</button>
            </div>
          </form>`
        : renderCampaignSharePreferenceReadout(share)
    }
    ${
      isConfirmingDelete
        ? `<div class="shared-settings-campaign-confirm">
            <div>
              <strong>${escapeHtml(`Remove ${candidateName}?`)}</strong>
              <span>This campaign will lose your shared voter contact preferences.</span>
            </div>
            <button class="shared-feed-chip is-danger" type="button" data-action="settings-campaign-sharing-delete" data-candidate-id="${escapeHtml(share.candidateId)}"${disabledAttr(busy)}>${deleting ? "Removing..." : "Remove"}</button>
            <button class="shared-feed-chip" type="button" data-action="settings-campaign-sharing-cancel-delete"${disabledAttr(busy)}>Cancel</button>
          </div>`
        : `<div class="shared-settings-sharing-card__actions">
            <button class="shared-feed-chip" type="button" data-action="settings-campaign-sharing-edit" data-candidate-id="${escapeHtml(share.candidateId)}"${disabledAttr(busy)}>Edit</button>
            <button class="shared-feed-chip" type="button" data-action="settings-campaign-sharing-delete-confirm" data-candidate-id="${escapeHtml(share.candidateId)}"${disabledAttr(busy)}>Remove</button>
          </div>`
    }
  </article>`;
}

function renderSettingsCampaignDataSharing() {
  const resource = state.pages.settings.privacySafety.campaignSharing;
  const busy = Boolean(resource.actionPendingKey);
  const counts = campaignSharePreferenceCounts(resource.items);
  const contactFieldCount = campaignShareContactFieldCount(resource.items);
  return `<div class="shared-settings-main shared-settings-privacy shared-settings-campaign-sharing">
    <section class="shared-settings-panel shared-settings-campaign-hero">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Campaign data sharing</h2>
          <p>Review campaign access to your voter contact preferences and shared contact fields.</p>
        </div>
        <div class="shared-settings-header__actions">
          <button class="shared-feed-chip" type="button" data-action="settings-campaign-sharing-refresh"${disabledAttr(resource.loading)}>Refresh</button>
          ${resource.items.length ? `<button class="shared-feed-chip" type="button" data-action="settings-campaign-sharing-delete-confirm" data-delete-scope="all"${disabledAttr(busy || resource.confirmingDeleteAll)}>${resource.confirmingDeleteAll ? "Confirm below" : "Remove all"}</button>` : ""}
        </div>
      </div>
      <div class="shared-settings-campaign-metrics">
        ${renderCampaignSharingMetric({
          label: "Campaigns",
          value: formatCount(resource.items.length),
          detail: resource.items.length === 1 ? "active share" : "active shares",
        })}
        ${renderCampaignSharingMetric({
          label: "Contact fields",
          value: formatCount(contactFieldCount),
          detail: "address, phone, or email",
        })}
        ${renderCampaignSharingMetric({
          label: "Allowed",
          value: formatCount(counts.yes),
          detail: "preference choices",
        })}
        ${renderCampaignSharingMetric({
          label: "No contact",
          value: formatCount(counts.no),
          detail: "preference choices",
        })}
      </div>
      ${
        resource.confirmingDeleteAll
          ? `<div class="shared-settings-campaign-confirm shared-settings-campaign-confirm--all">
              <div>
                <strong>Remove all campaign sharing?</strong>
                <span>Every campaign listed here will lose access to your shared contact preferences.</span>
              </div>
              <button class="shared-feed-chip is-danger" type="button" data-action="settings-campaign-sharing-delete-all"${disabledAttr(busy)}>${resource.actionPendingKey === "delete-all" ? "Removing..." : "Remove all"}</button>
              <button class="shared-feed-chip" type="button" data-action="settings-campaign-sharing-cancel-delete"${disabledAttr(busy)}>Cancel</button>
            </div>`
          : ""
      }
      ${renderSettingsResourceStatus(resource, "campaign data sharing")}
    </section>
    <section class="shared-settings-panel">
      ${resource.loading && !resource.items.length ? '<div class="shared-page__loading">Loading campaign sharing...</div>' : ""}
      ${!resource.loading && !resource.items.length ? '<div class="shared-settings-empty">No campaign data sharing. Campaigns you allow to use your voter contact preferences will appear here.</div>' : ""}
      <div class="shared-settings-sharing-list">
        ${resource.items.map((share) => renderCampaignShareCard(share, resource)).join("")}
      </div>
    </section>
  </div>`;
}

function settingsSecurityRecoveryStatusLabel(recovery) {
  const status = normalizeString(recovery?.status?.status);
  if (status) {
    return humanizeLabel(status);
  }
  return recovery?.status?.backupVersion ? "Configured" : "Not enrolled";
}

function settingsSecurityRecoveryTone(recovery) {
  const status = normalizeString(recovery?.status?.status).toLowerCase();
  if (status.includes("verified") || status.includes("active")) {
    return "good";
  }
  if (recovery?.status?.backupVersion) {
    return "good";
  }
  if (status.includes("fail") || status.includes("error")) {
    return "bad";
  }
  return "pending";
}

function settingsSecurityBackupLabel(recovery) {
  const backupVersion = Number(recovery?.status?.backupVersion) || 0;
  if (!backupVersion) {
    return "No backup";
  }
  return `v${backupVersion}`;
}

function settingsSecurityCurrentDeviceLabel(messaging) {
  return messagingCurrentDeviceDisplayLabel(messaging, "Not linked");
}

function settingsSecurityActivityIcon(item = {}) {
  const type = normalizeString(item.type || item.title).toLowerCase();
  if (type.includes("recovery") || type.includes("backup")) {
    return "lock";
  }
  if (type.includes("device") || type.includes("link")) {
    return "phone";
  }
  if (type.includes("approve") || type.includes("verify") || type.includes("enroll")) {
    return "check";
  }
  if (type.includes("revoke") || type.includes("deny") || type.includes("fail")) {
    return "shield";
  }
  return "bell";
}

function settingsSecurityActivityTone(item = {}) {
  const type = normalizeString(item.type || item.title || item.status).toLowerCase();
  if (type.includes("revoke") || type.includes("deny") || type.includes("fail")) {
    return "bad";
  }
  if (
    type.includes("approve") ||
    type.includes("verify") ||
    type.includes("enroll") ||
    type.includes("rotate")
  ) {
    return "good";
  }
  return "pending";
}

function settingsSecurityActivityMeta(item = {}) {
  return [
    normalizeString(item.description || item.deviceLabel || item.actorLabel),
    item.createdAt ? formatAbsoluteDateTime(item.createdAt) : "",
    normalizeString(item.ipAddress || item.ip || item.location),
  ]
    .filter(Boolean)
    .join(" - ");
}

function renderSettingsSecurityMetric({ value, label, detail = "", tone = "" }) {
  return `<span class="${tone ? `is-${escapeHtml(tone)}` : ""}">
    <strong>${escapeHtml(value)}</strong>
    <small>${escapeHtml(label)}</small>
    ${detail ? `<em>${escapeHtml(detail)}</em>` : ""}
  </span>`;
}

function renderSettingsSecurityActivityList(limit = 5) {
  const security = state.pages.messaging.security;
  const items = (security.items || []).slice(0, limit);
  return `<div class="shared-settings-security-list">
    ${renderSettingsResourceStatus(security, "security activity")}
    ${
      items.length
        ? items
            .map(
              (item) => `<article class="shared-settings-security-row">
                <span>${renderIcon(settingsSecurityActivityIcon(item))}</span>
                <div>
                  <span class="shared-settings-security-row__title">
                    <strong>${escapeHtml(humanizeLabel(item.type || item.title || "Security event"))}</strong>
                    ${renderSettingsStatusPill(humanizeLabel(item.status || settingsSecurityActivityTone(item)), settingsSecurityActivityTone(item))}
                  </span>
                  <small>${escapeHtml(settingsSecurityActivityMeta(item) || "Security event recorded for this account.")}</small>
                </div>
              </article>`,
            )
            .join("")
        : `<div class="shared-settings-security-empty">
            <span>${renderIcon("shield")}</span>
            <div><strong>No security activity yet.</strong><small>Device approvals and recovery changes will appear here.</small></div>
          </div>`
    }
  </div>`;
}

function renderSettingsSecurityDeviceList({ compact = false } = {}) {
  const messaging = state.pages.messaging;
  const devices = messaging.devices;
  const currentDeviceId = normalizeString(messaging.device.currentDeviceId);
  const items = devices.items || [];
  return `<div class="shared-settings-security-list">
    ${renderSettingsResourceStatus(devices, "trusted devices")}
    ${
      items.length
        ? items
            .map((device) => {
              const isCurrent = messagingDeviceIsCurrent(device, currentDeviceId);
              const lastSeen = device.lastSeenAt
                ? `Last seen ${formatAbsoluteDateTime(device.lastSeenAt)}`
                : "No recent activity";
              const created = device.createdAt
                ? `Added ${formatAbsoluteDateTime(device.createdAt)}`
                : "";
              return `<article class="shared-settings-security-row">
                <span>${renderIcon(isCurrent ? "check" : "phone")}</span>
                <div>
                  <span class="shared-settings-security-row__title">
                    <strong>${escapeHtml(device.deviceLabel || (isCurrent ? "This browser" : "Trusted device"))}</strong>
                    ${renderSettingsStatusPill(isCurrent ? "Current" : "Trusted", isCurrent ? "good" : "")}
                  </span>
                  <small>${escapeHtml([device.platform || "device", lastSeen, created].filter(Boolean).join(" - "))}</small>
                  ${compact ? "" : `<em>${escapeHtml(messagingTrustedDeviceDescription(device, isCurrent))}</em>`}
                </div>
                ${
                  device.deviceId && !isCurrent
                    ? `<button class="shared-feed-chip" type="button" data-action="messaging-device-revoke" data-device-id="${escapeHtml(device.deviceId)}">Revoke</button>`
                    : ""
                }
              </article>`;
            })
            .join("")
        : `<div class="shared-settings-security-empty">
            <span>${renderIcon("phone")}</span>
            <div><strong>No trusted devices found.</strong><small>Start device link to prepare this browser for encrypted messages.</small></div>
          </div>`
    }
  </div>`;
}

function renderSettingsSecurityHub() {
  const messaging = state.pages.messaging;
  const deviceCount = (messaging.devices.items || []).length;
  const recoveryLabel = settingsSecurityRecoveryStatusLabel(messaging.recovery);
  const activityCount = (messaging.security.items || []).length;
  const latestActivity = (messaging.security.items || [])[0];
  return `<div class="shared-settings-main shared-settings-security">
    <section class="shared-settings-panel shared-settings-security-hero">
      <div>
        <span class="shared-settings-eyebrow">Encrypted messaging</span>
        <h2>Security center</h2>
        <p>Manage the browser trust, recovery, and security history that protect encrypted Polis messages.</p>
      </div>
      <div class="shared-settings-security-metrics">
        ${renderSettingsSecurityMetric({
          value: formatCount(deviceCount),
          label: "trusted devices",
          detail: settingsSecurityCurrentDeviceLabel(messaging),
          tone: deviceCount ? "good" : "pending",
        })}
        ${renderSettingsSecurityMetric({
          value: recoveryLabel,
          label: "recovery",
          detail: settingsSecurityBackupLabel(messaging.recovery),
          tone: settingsSecurityRecoveryTone(messaging.recovery),
        })}
        ${renderSettingsSecurityMetric({
          value: formatCount(activityCount),
          label: "events loaded",
          detail: latestActivity?.createdAt ? formatAbsoluteDateTime(latestActivity.createdAt) : "No events yet",
        })}
      </div>
    </section>
    <div class="shared-settings-security-grid">
      <article class="shared-settings-security-card">
        <div class="shared-settings-security-card__top">
          <span>${renderIcon("phone")}</span>
          ${renderSettingsStatusPill(deviceCount ? "Ready" : "Setup needed", deviceCount ? "good" : "pending")}
        </div>
        <div>
          <h3>Device link</h3>
          <p>Set up this browser or approve a short code from another trusted device.</p>
        </div>
        <small>${escapeHtml(deviceCount ? `${formatCount(deviceCount)} device${deviceCount === 1 ? "" : "s"} can unlock messages.` : "No trusted browser is loaded yet.")}</small>
        <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="/settings/security/device-link">Open device link</button>
      </article>
      <article class="shared-settings-security-card">
        <div class="shared-settings-security-card__top">
          <span>${renderIcon("lock")}</span>
          ${renderSettingsStatusPill(recoveryLabel, settingsSecurityRecoveryTone(messaging.recovery))}
        </div>
        <div>
          <h3>Recovery</h3>
          <p>Enroll, rotate, verify, or restore encrypted message history from a saved key.</p>
        </div>
        <small>${escapeHtml(`Encrypted backup ${settingsSecurityBackupLabel(messaging.recovery)}.`)}</small>
        <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/security/restore">Open recovery</button>
      </article>
      <article class="shared-settings-security-card">
        <div class="shared-settings-security-card__top">
          <span>${renderIcon("shield")}</span>
          ${renderSettingsStatusPill("Account")}
        </div>
        <div>
          <h3>Account security</h3>
          <p>Password reset and authenticator MFA remain under Account Security.</p>
        </div>
        <small>Identity and sign-in controls stay separate from message encryption.</small>
        <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/account-security">Account security</button>
      </article>
    </div>
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Recent security activity</h2>
          <p>Device, recovery, and encrypted-history events tied to your account.</p>
        </div>
      </div>
      ${renderSettingsSecurityActivityList()}
    </section>
  </div>`;
}

function renderSettingsSecurityDeviceLink() {
  const messaging = state.pages.messaging;
  const deviceLink = messaging.deviceLink;
  const hasManualLookup = Boolean(normalizeString(deviceLink.lookupCode));
  const displayLink =
    deviceLink.displayLink || (!hasManualLookup ? deviceLink.link : null);
  const lookupLink =
    deviceLink.lookupLink || (hasManualLookup ? deviceLink.link : null);
  const linkStatus = normalizeString(displayLink?.status) || "Idle";
  const linkCode = normalizeString(displayLink?.linkCode);
  const canApproveLookup = Boolean(
    hasManualLookup &&
      lookupLink?.linkId &&
      lookupLink?.targetDeviceId &&
      normalizeString(lookupLink?.linkCode),
  );
  const deviceCount = (messaging.devices.items || []).length;
  const isApproved = normalizeString(displayLink?.status).toLowerCase() === "approved";
  return `<div class="shared-settings-main shared-settings-security">
    <section class="shared-settings-panel shared-settings-security-hero">
      <div>
        <span class="shared-settings-eyebrow">Trusted devices</span>
        <h2>Device link</h2>
        <p>Use a short approval code to make a browser trusted for encrypted Polis messages.</p>
      </div>
      <div class="shared-settings-security-metrics">
        ${renderSettingsSecurityMetric({
          value: formatCount(deviceCount),
          label: "trusted",
          detail: settingsSecurityCurrentDeviceLabel(messaging),
          tone: deviceCount ? "good" : "pending",
        })}
        ${renderSettingsSecurityMetric({
          value: humanizeLabel(linkStatus),
          label: "link status",
          detail: displayLink?.expiresAt ? `Expires ${formatAbsoluteDateTime(displayLink.expiresAt)}` : "No active code",
          tone: isApproved ? "good" : linkCode ? "pending" : "",
        })}
      </div>
    </section>
    <div class="shared-settings-security-actions">
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/security">Security center</button>
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/security/restore">Recovery</button>
    </div>
    <div class="shared-settings-security-flow">
      <article class="shared-settings-security-step">
        <strong>1</strong><div><h3>Start a code</h3><p>Create a time-limited code on the browser you want to trust.</p></div>
      </article>
      <article class="shared-settings-security-step">
        <strong>2</strong><div><h3>Approve it</h3><p>Enter that code on a device that already has access.</p></div>
      </article>
      <article class="shared-settings-security-step">
        <strong>3</strong><div><h3>Check approval</h3><p>Return here to finish encrypted messaging setup.</p></div>
      </article>
    </div>
    <div class="shared-settings-security-forms">
      <section class="shared-settings-panel shared-settings-security-display">
        <div class="shared-settings-panel__header">
          <div>
            <h2>Set up this browser</h2>
            <p>Generate a short code, approve it from a trusted Polis device, then check approval here.</p>
          </div>
          ${renderSettingsStatusPill(humanizeLabel(linkStatus), normalizeString(displayLink?.status).toLowerCase() === "approved" ? "good" : "pending")}
        </div>
        <div class="shared-settings-security-code${linkCode ? "" : " is-empty"}">
          <small>Link code</small>
          <strong>${escapeHtml(linkCode || "Not started")}</strong>
          <span>${escapeHtml(displayLink?.expiresAt ? `Expires ${formatAbsoluteDateTime(displayLink.expiresAt)}` : "Start a link to create a time-limited setup code.")}</span>
        </div>
        <div class="shared-settings-form-actions">
          <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="messaging-device-link-start"${disabledAttr(deviceLink.pending)}>${deviceLink.pending ? "Working..." : linkCode ? "Restart link" : "Start link"}</button>
          ${displayLink?.linkId ? `<button class="shared-feed-chip" type="button" data-action="messaging-device-link-refresh" data-link-id="${escapeHtml(displayLink.linkId)}"${disabledAttr(deviceLink.pending)}>Check approval</button>` : ""}
        </div>
        ${deviceLink.error ? `<div class="shared-page__error">${escapeHtml(deviceLink.error)}</div>` : ""}
      </section>
      <section class="shared-settings-panel">
        <div class="shared-settings-panel__header">
          <div>
            <h2>Approve by code</h2>
            <p>Use a short code shown by another device to approve that device from this browser.</p>
          </div>
        </div>
        <form class="shared-settings-form shared-settings-security-lookup" data-route-form="messaging-device-link-lookup">
          <label><span>Link code</span><input name="linkCode" value="${escapeHtml(deviceLink.lookupCode || "")}" autocomplete="off" /></label>
          <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(deviceLink.pending)}>${deviceLink.pending ? "Working..." : "Lookup"}</button>
        </form>
        ${
          hasManualLookup
            ? `<div class="shared-settings-security-lookup-result">
                <span>${renderIcon(canApproveLookup ? "check" : "shield")}</span>
                <div>
                  <strong>${escapeHtml(canApproveLookup ? "Device ready to approve" : "Lookup incomplete")}</strong>
                  <small>${escapeHtml(messagingDeviceLinkTargetCopy(lookupLink))}</small>
                </div>
                ${canApproveLookup ? `<button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="messaging-device-link-approve"${disabledAttr(deviceLink.pending)}>Approve</button>` : ""}
              </div>`
            : ""
        }
      </section>
    </div>
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Trusted devices</h2>
          <p>Devices allowed to unlock encrypted messaging for this account.</p>
        </div>
      </div>
      ${renderSettingsSecurityDeviceList()}
    </section>
  </div>`;
}

function renderSettingsSecurityRestore() {
  const messaging = state.pages.messaging;
  const recovery = messaging.recovery;
  const recoveryLabel = settingsSecurityRecoveryStatusLabel(recovery);
  const hasBundle = Boolean(recovery.bundle);
  const hasLocalCode = Boolean(normalizeString(recovery.localCode));
  return `<div class="shared-settings-main shared-settings-security">
    <section class="shared-settings-panel shared-settings-security-hero">
      <div>
        <span class="shared-settings-eyebrow">Encrypted history</span>
        <h2>Recovery</h2>
        <p>Keep encrypted message history recoverable when you add a new browser or reset this one.</p>
      </div>
      <div class="shared-settings-security-metrics">
        ${renderSettingsSecurityMetric({
          value: recoveryLabel,
          label: "recovery",
          detail: settingsSecurityBackupLabel(recovery),
          tone: settingsSecurityRecoveryTone(recovery),
        })}
        ${renderSettingsSecurityMetric({
          value: hasBundle ? "Available" : "Missing",
          label: "encrypted backup",
          detail: hasBundle ? "Ready to verify" : "Export a kit first",
          tone: hasBundle ? "good" : "pending",
        })}
        ${renderSettingsSecurityMetric({
          value: hasLocalCode ? "Stored" : "Not stored",
          label: "local key",
          detail: hasLocalCode ? "This browser" : "Enroll to create one",
          tone: hasLocalCode ? "good" : "pending",
        })}
      </div>
    </section>
    <div class="shared-settings-security-actions">
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/security">Security center</button>
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/settings/security/device-link">Device link</button>
    </div>
    <div class="shared-settings-security-forms">
      <section class="shared-settings-panel">
        <div class="shared-settings-panel__header">
          <div>
            <h2>Restore encrypted history</h2>
            <p>Enter your recovery key to restore the encrypted backup on this browser. If you saved a recovery kit, paste it as a fallback.</p>
          </div>
          ${renderSettingsStatusPill(hasBundle ? "Encrypted backup ready" : "Kit required", hasBundle ? "good" : "pending")}
        </div>
        <form class="shared-settings-form" data-route-form="messaging-recovery-restore">
          <label><span>Recovery key</span><input name="recoveryCode" autocomplete="off" placeholder="XXXX-XXXX-XXXX-XXXX"${disabledAttr(recovery.actionPending)} /></label>
          <label><span>Recovery kit JSON optional</span><textarea name="recoveryKit" rows="7" autocomplete="off" placeholder='{"version":"web-v1", ...}'${disabledAttr(recovery.actionPending)}></textarea></label>
          <button class="shared-feed-chip shared-feed-chip--primary" type="submit"${disabledAttr(recovery.actionPending)}>${recovery.actionPending ? "Restoring..." : "Restore encrypted history"}</button>
        </form>
        ${renderSettingsResourceStatus(recovery, "recovery")}
      </section>
      <section class="shared-settings-panel shared-settings-security-secret">
        <div>
          <h3>Recovery status</h3>
          <p>${escapeHtml(hasLocalCode ? "This browser has a local recovery key available." : "Enroll recovery before you need to restore a new browser.")}</p>
        </div>
        <div class="shared-settings-security-secret__code">
          <small>Local recovery key</small>
          <strong>${escapeHtml(recovery.localCode || "Not stored in this browser")}</strong>
        </div>
        <div class="shared-settings-security-recovery-map">
          <span>${renderSettingsStatusPill(recoveryLabel, settingsSecurityRecoveryTone(recovery))} <small>Recovery</small></span>
          <span>${renderSettingsStatusPill(settingsSecurityBackupLabel(recovery), hasBundle ? "good" : "pending")} <small>Backup</small></span>
          <span>${renderSettingsStatusPill(hasLocalCode ? "Local key" : "No key", hasLocalCode ? "good" : "pending")} <small>Browser</small></span>
        </div>
        <div class="shared-settings-form-actions">
          <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="messaging-recovery-enroll"${disabledAttr(recovery.actionPending)}>${recovery.actionPending ? "Working..." : "Enroll"}</button>
          <button class="shared-feed-chip" type="button" data-action="messaging-recovery-rotate"${disabledAttr(recovery.actionPending)}>Rotate</button>
          <button class="shared-feed-chip" type="button" data-action="messaging-recovery-verify"${disabledAttr(recovery.actionPending || !hasBundle)}>Verify</button>
          <button class="shared-feed-chip" type="button" data-action="messaging-recovery-export-kit"${disabledAttr(recovery.actionPending || (!hasBundle && !recovery.localCode))}>Download kit</button>
        </div>
      </section>
    </div>
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Recent recovery activity</h2>
          <p>Recovery and device events loaded from your messaging security log.</p>
        </div>
      </div>
      ${renderSettingsSecurityActivityList()}
    </section>
  </div>`;
}

function renderSettingsSecurityCenter() {
  const securitySubpath = getSettingsSecuritySubpath();
  if (securitySubpath.split("/")[0] === "device-link") {
    return renderSettingsSecurityDeviceLink();
  }
  if (securitySubpath === "restore") {
    return renderSettingsSecurityRestore();
  }
  return renderSettingsSecurityHub();
}

function renderSettingsBalancesPausedPanel() {
  return `<section class="shared-settings-balance-paused" aria-label="Balance-based donations paused">
    <span class="shared-settings-balance-paused__icon" aria-hidden="true">${renderIcon("payments")}</span>
    <div class="shared-settings-balance-paused__body">
      <span class="shared-card__meta"><span>Legacy wallet</span><span>Paused</span></span>
      <h3>Balances coming back later</h3>
      <p>We paused balance-based donations while we roll out direct payments. Existing receipts stay available, and candidates can keep using the direct Stripe-backed donation tools from their dashboards.</p>
      <div class="shared-settings-balance-paused__timeline" aria-label="Payments status">
        <span><strong>Direct donations</strong><small>Active checkout flow</small></span>
        <span><strong>Balance wallet</strong><small>Paused intentionally</small></span>
        <span><strong>Receipts</strong><small>Available below</small></span>
      </div>
    </div>
    <div class="shared-settings-balance-paused__actions">
      <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="/settings/donations">Review receipts</button>
      <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/candidate-dashboard">Candidate donation tools</button>
    </div>
  </section>`;
}

function renderSettingsPayments() {
  const history = state.pages.settings.payments.donationHistory;
  const total = history.items.reduce((sum, item) => sum + (Number(item.amountCents) || 0), 0);
  const receiptCount = history.items.length;
  const commandMetrics = [
    {
      label: "Receipts",
      value: formatCount(receiptCount),
      detail: receiptCount ? "Loaded from donation history." : "No receipts loaded yet.",
    },
    {
      label: "Loaded total",
      value: formatDonationAmount(total),
      detail: "Visible donation ledger amount.",
    },
    {
      label: "Wallet",
      value: "Paused",
      detail: "Balance-based donations are intentionally paused.",
    },
    {
      label: "Candidate tools",
      value: "Dashboard",
      detail: "Setup, payouts, exports, and transaction review.",
    },
  ];
  const paymentActions = [
    {
      icon: "file",
      title: "Donation history",
      copy: "Review receipts, statuses, payment methods, cycles, and compliance certifications.",
      route: "/settings/donations",
      status: `${formatCount(receiptCount)} receipt${receiptCount === 1 ? "" : "s"}`,
      primary: true,
    },
    {
      icon: "dashboard",
      title: "Candidate donation tools",
      copy: "Open campaign donation setup, Stripe connection, transaction exports, and payout workflows.",
      route: "/candidate-dashboard",
      status: "Campaigns",
    },
    {
      icon: "payments",
      title: "Balance wallet status",
      copy: "Legacy balance-based donations stay paused while direct donations remain the active path.",
      route: "/settings/payments",
      status: "Paused",
    },
  ];
  const renderPaymentAction = (item) =>
    `<button class="shared-settings-payment-action${item.primary ? " is-primary" : ""}" type="button" data-action="navigate" data-route="${escapeHtml(item.route)}">
      <span aria-hidden="true">${renderIcon(item.icon)}</span>
      <strong>${escapeHtml(item.title)}</strong>
      <small>${escapeHtml(item.copy)}</small>
      <em>${escapeHtml(item.status)}</em>
    </button>`;
  return `<div class="shared-settings-main shared-settings-payments">
    <section class="shared-settings-payments-command">
      <div class="shared-settings-payments-command__copy">
        <span>${renderIcon("payments")} Payments</span>
        <h2>Donation receipts and campaign finance tools in one place.</h2>
        <p>Use the web payments hub to review your donor receipts, confirm compliance details, and jump to candidate donation dashboards when you manage a campaign.</p>
        <div class="shared-settings-payments-command__actions">
          <button class="shared-feed-chip shared-feed-chip--primary" type="button" data-action="navigate" data-route="/settings/donations">Review receipts</button>
          <button class="shared-feed-chip" type="button" data-action="navigate" data-route="/candidate-dashboard">Candidate tools</button>
        </div>
      </div>
      <div class="shared-settings-payments-command__metrics" aria-label="Payments summary">
        ${commandMetrics
          .map(
            (item) => `<span>
              <small>${escapeHtml(item.label)}</small>
              <strong>${escapeHtml(item.value)}</strong>
              <em>${escapeHtml(item.detail)}</em>
            </span>`,
          )
          .join("")}
      </div>
    </section>
    ${renderSettingsBalancesPausedPanel()}
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Payment workspaces</h2>
          <p>Payments in Polis web focus on direct donations, receipt review, and candidate donation dashboards while balance-based donations remain paused.</p>
        </div>
      </div>
      <div class="shared-settings-payment-actions">
        ${paymentActions.map(renderPaymentAction).join("")}
      </div>
      ${renderSettingsResourceStatus(history, "donation history")}
    </section>
  </div>`;
}

function renderDonationCompliance(item) {
  const compliance = item?.compliance || {};
  return `<div class="shared-settings-disclosure">
    ${renderSettingsStatusPill(`U.S. citizen/LPR: ${compliance.usCitizenOrLpr ? "Yes" : "No"}`, compliance.usCitizenOrLpr ? "good" : "bad")}
    ${renderSettingsStatusPill(`Own funds: ${compliance.ownFunds ? "Yes" : "No"}`, compliance.ownFunds ? "good" : "bad")}
    ${renderSettingsStatusPill(`Campaign attribution: ${compliance.campaignAttribution ? "Yes" : "No"}`, compliance.campaignAttribution ? "good" : "bad")}
  </div>`;
}

function donationStatusTone(status = "") {
  const normalized = normalizeString(status).toLowerCase();
  if (["succeeded", "success", "paid", "completed", "settled"].includes(normalized)) {
    return "good";
  }
  if (["pending", "processing", "requires_action", "requires_capture"].includes(normalized)) {
    return "pending";
  }
  if (["failed", "canceled", "cancelled", "refunded", "disputed"].includes(normalized)) {
    return "bad";
  }
  return "pending";
}

function donationComplianceCount(item = {}) {
  const compliance = item.compliance || {};
  return [
    compliance.usCitizenOrLpr,
    compliance.ownFunds,
    compliance.campaignAttribution,
  ].filter(Boolean).length;
}

function renderSettingsDonationRow(item, resource) {
  const donationId = item.donationId || "";
  const pending = resource.actionPendingKey === `detail:${donationId}`;
  const selected = donationId && resource.selectedDonation?.donationId === donationId;
  const candidateName = item.candidateDisplayName || "Candidate";
  const dateLabel = formatSettingsDate(item.createdAt || item.createdAtIso);
  const statusLabel = humanizeLabel(item.status) || "Unknown";
  const methodLabel = humanizeLabel(item.paymentMethod) || "Unknown method";
  return `<button class="shared-settings-list-row shared-settings-donation-row${selected ? " is-selected" : ""}" type="button" data-action="settings-donation-detail" data-donation-id="${escapeHtml(donationId)}" aria-label="Open donation receipt for ${escapeHtml(candidateName)}"${disabledAttr(pending || !donationId)}>
    <span class="shared-settings-list-row__avatar">${escapeHtml(candidateName.slice(0, 1).toUpperCase() || "D")}</span>
    <span class="shared-settings-donation-row__body">
      <span class="shared-settings-donation-row__title">
        <strong>${escapeHtml(candidateName)}</strong>
        ${renderSettingsStatusPill(statusLabel, donationStatusTone(item.status))}
      </span>
      <small>${escapeHtml([methodLabel, dateLabel].filter(Boolean).join(" - "))}</small>
      <span class="shared-settings-donation-row__meta">
        <em>${escapeHtml(`${donationComplianceCount(item)}/3 certifications`)}</em>
        ${item.electionCycle ? `<em>${escapeHtml(item.electionCycle)}</em>` : ""}
      </span>
    </span>
    <span class="shared-settings-donation-row__amount">
      <strong>${escapeHtml(formatDonationAmount(item.amountCents, item.currency))}</strong>
      <small>${escapeHtml(dateLabel || "No date")}</small>
    </span>
  </button>`;
}

function renderSettingsDonationDetail(selected, resource) {
  if (resource.detailLoading) {
    return `<article class="shared-settings-donation-detail shared-settings-donation-detail--empty">
      <span class="shared-settings-list-row__avatar">${renderIcon("payments")}</span>
      <div>
        <h3>Loading receipt</h3>
        <p>Pulling amount, method, election cycle, and certifications.</p>
      </div>
    </article>`;
  }
  if (resource.detailError && !selected) {
    return `<article class="shared-settings-donation-detail shared-settings-donation-detail--empty">
      <span class="shared-settings-list-row__avatar">${renderIcon("payments")}</span>
      <div>
        <h3>Receipt unavailable</h3>
        <p>${escapeHtml(resource.detailError)}</p>
      </div>
    </article>`;
  }
  if (!selected) {
    return `<article class="shared-settings-donation-detail shared-settings-donation-detail--empty">
      <span class="shared-settings-list-row__avatar">${renderIcon("payments")}</span>
      <div>
        <h3>Donation detail</h3>
        <p>Select a donation to inspect the receipt, payment method, election cycle, and compliance certifications.</p>
      </div>
    </article>`;
  }
  return `<article class="shared-settings-donation-detail">
    <div class="shared-settings-panel__header">
      <div>
        <span class="shared-card__meta"><span>${escapeHtml(humanizeLabel(selected.status) || "Unknown")}</span><span>${escapeHtml(selected.donationId || "Receipt")}</span></span>
        <h3>${escapeHtml(selected.candidateDisplayName || selected.candidateId || "Candidate")}</h3>
        <p>${escapeHtml(formatDonationAmount(selected.amountCents, selected.currency))} on ${escapeHtml(formatSettingsDate(selected.createdAt || selected.createdAtIso) || "unknown date")}</p>
      </div>
      ${renderSettingsStatusPill(humanizeLabel(selected.status) || "Unknown", donationStatusTone(selected.status))}
    </div>
    ${resource.detailError ? `<div class="shared-page__error">${escapeHtml(resource.detailError)}</div>` : ""}
    <div class="shared-settings-donation-detail-grid">
      <div><span>Candidate</span><strong>${escapeHtml(selected.candidateDisplayName || selected.candidateId || "Candidate")}</strong></div>
      <div><span>Amount</span><strong>${escapeHtml(formatDonationAmount(selected.amountCents, selected.currency))}</strong></div>
      <div><span>Status</span><strong>${escapeHtml(humanizeLabel(selected.status))}</strong></div>
      <div><span>Method</span><strong>${escapeHtml(humanizeLabel(selected.paymentMethod))}</strong></div>
      <div><span>Date</span><strong>${escapeHtml(formatSettingsDate(selected.createdAt || selected.createdAtIso))}</strong></div>
      <div><span>Cycle</span><strong>${escapeHtml(selected.electionCycle || "-")}</strong></div>
    </div>
    <h3>Certifications</h3>
    ${renderDonationCompliance(selected)}
  </article>`;
}

function renderSettingsDonationHistory() {
  const resource = state.pages.settings.payments.donationHistory;
  const selected = resource.selectedDonation;
  const loadedTotal = resource.items.reduce((sum, item) => sum + (Number(item.amountCents) || 0), 0);
  return `<div class="shared-settings-main shared-settings-payments">
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Donation history</h2>
          <p>Receipts, statuses, methods, and compliance detail for donations made from your account.</p>
        </div>
        <div class="shared-settings-donation-actions">
          ${renderSettingsStatusPill(`${formatCount(resource.items.length)} receipts`, resource.items.length ? "good" : "pending")}
          ${renderSettingsStatusPill(formatDonationAmount(loadedTotal), resource.items.length ? "good" : "pending")}
          <button class="shared-feed-chip" type="button" data-action="settings-donations-refresh"${disabledAttr(resource.loading)}>${resource.loading ? "Refreshing..." : "Refresh"}</button>
        </div>
      </div>
      ${renderSettingsResourceStatus(resource, "donation history")}
      ${resource.loading && !resource.items.length ? '<div class="shared-page__loading">Loading donations...</div>' : ""}
      ${!resource.loading && !resource.items.length ? '<div class="shared-settings-empty shared-settings-donation-empty"><strong>No donations yet</strong><span>Donation receipts and compliance certifications will appear here after you contribute from Polis.</span></div>' : ""}
      <div class="shared-settings-donation-layout">
        <div class="shared-settings-list">
          ${resource.items.map((item) => renderSettingsDonationRow(item, resource)).join("")}
          ${resource.nextCursor ? `<div class="shared-settings-form-actions shared-settings-donation-footer"><span>${escapeHtml(`${formatCount(resource.items.length)} loaded`)}</span><button class="shared-feed-chip" type="button" data-action="settings-donations-load-more"${disabledAttr(resource.loadingMore)}>${resource.loadingMore ? "Loading..." : "Load more"}</button></div>` : ""}
        </div>
        ${renderSettingsDonationDetail(selected, resource)}
      </div>
    </section>
  </div>`;
}

function renderSettingsHelpLink({ title, copy, href, actionLabel = "Open" }) {
  return `<a class="shared-settings-resource-card" href="${escapeHtml(href)}">
    <div>
      <h3>${escapeHtml(title)}</h3>
      <p>${escapeHtml(copy)}</p>
    </div>
    <span>${escapeHtml(actionLabel)}</span>
  </a>`;
}

function settingsHelpAboutAppInfo() {
  const appInfo =
    runtimeConfig.appInfo && typeof runtimeConfig.appInfo === "object"
      ? runtimeConfig.appInfo
      : {};
  const version = normalizeString(appInfo.version);
  const frontendVersion = normalizeString(appInfo.frontendVersion);
  const buildNumber = normalizeString(appInfo.buildNumber);
  const commit = normalizeString(appInfo.commit);
  const builtAt = normalizeString(appInfo.builtAt);
  const versionLabel =
    version && buildNumber
      ? `${version}+${buildNumber}`
      : version || frontendVersion || "Version unavailable";
  const buildLabel =
    buildNumber ||
    (commit ? `Commit ${commit.slice(0, 7)}` : "Development build");
  return {
    name: normalizeString(appInfo.name) || "polisapp.io",
    displayName: normalizeString(appInfo.displayName) || "polisapp.io",
    frontendName: normalizeString(appInfo.frontendName) || "Web app",
    versionLabel,
    frontendVersion: frontendVersion || version || "",
    buildLabel,
    builtAtLabel: builtAt ? formatAbsoluteDateTime(builtAt) : "",
  };
}

function renderSettingsHelpAboutLicenses() {
  const packages = [
    ["Website package", "polisapp-io", "ISC"],
    ["Frontend package", "polisapp-io-frontend", "ISC"],
    ["Sanitized HTML", "DOMPurify", "Apache-2.0 OR MPL-2.0"],
    ["Markdown rendering", "marked", "MIT"],
    ["Backend framework", "Express", "MIT"],
    ["Database ORM", "Sequelize", "MIT"],
    ["Build tooling", "Webpack and Babel", "MIT"],
  ];
  return `<div class="shared-settings-main shared-settings-help">
    <section class="shared-settings-panel">
      <div class="shared-settings-panel__header">
        <div>
          <h2>Open source licenses</h2>
          <p>Core website packages and license families used by the Polis website bundle.</p>
        </div>
        <button class="shared-feed-chip" data-action="navigate" data-route="/settings/help-about">Help & About</button>
      </div>
      <div class="shared-settings-license-list">
        ${packages
          .map(
            ([scope, name, license]) => `<div class="shared-settings-license-row">
              <span>
                <strong>${escapeHtml(scope)}</strong>
                <small>${escapeHtml(name)}</small>
              </span>
              <em>${escapeHtml(license)}</em>
            </div>`,
          )
          .join("")}
      </div>
    </section>
  </div>`;
}

